# Add Jinja2 filter to split genres on both backslash and comma
@app.template_filter('split_genres')
def split_genres(s):
    """Split string on both backslash and comma separators"""
    if not s:
        return []
    # Split on backslash or comma
    import re
    genres = re.split(r'[\\,]+', str(s))
    return [g.strip() for g in genres if g.strip()]


@app.template_filter('split_artist_collabs')
def split_artist_collabs(s):
    """Split collaboration artist strings into individual artist names."""
    if not s:
        return []

    import re

    # Common collaboration delimiters used in imported metadata.
    # Keep this conservative to avoid splitting legitimate band names.
    parts = re.split(r'\s+(?:w/|feat\.?|ft\.?|featuring)\s+', str(s), flags=re.IGNORECASE)
    cleaned = [p.strip() for p in parts if p and p.strip()]
    return cleaned or [str(s).strip()]

# Add Jinja2 filter for regex replacement
@app.template_filter('regex_replace')
def regex_replace(s, pattern, replacement):
    """Replace pattern in string using regex"""
    import re
    return re.sub(pattern, replacement, str(s))

# Add Jinja2 filter for JavaScript escaping
@app.template_filter('escapejs')
def escapejs(value):
    """Escape strings for use in JavaScript contexts"""
    if value is None:
        return ''
    
    # Convert to string
    value = str(value)
    
    # Define escape mappings for JavaScript
    escapes = {
        '\\': '\\\\',
        "'": "\\'",
        '"': '\\"',
        '\n': '\\n',
        '\r': '\\r',
        '\t': '\\t',
        '\b': '\\b',
        '\f': '\\f',
        '<': '\\u003C',  # Prevent script injection
        '>': '\\u003E',  # Prevent script injection
        '&': '\\u0026',  # Prevent HTML entity issues
    }
    
    # Apply escapes
    for char, escape in escapes.items():
        value = value.replace(char, escape)
    
    return value


def _normalize_slskd_query(value):
    text = str(value or '')
    text = text.replace('\\u0026', ' ')
    text = text.replace('&amp;', ' ')
    text = text.replace('&', ' ')
    text = re.sub(r'\s+', ' ', text)
    return text.strip()


def _clear_stale_slskd_searches(client, context="search", budget_seconds=8):
    """
    Delete any terminal-state (or long-running stuck) searches from slskd
    before starting a new one.

    Delegates to ``client.clear_stale_searches()`` so the logic lives in a
    single place (``SlskdClient``).  ``budget_seconds`` is forwarded as the
    time budget; the default (8 s) is safe for both interactive routes and
    background threads.
    """
    try:
        client.clear_stale_searches(budget_seconds=budget_seconds)
    except Exception as cleanup_err:
        logging.warning(f"[SLSKD] Could not clear stale searches before {context}: {cleanup_err}")

@app.template_filter('format_datetime')
def format_datetime(value):
    """Format ISO datetime string to DD-MM-YY at HH:MM AM/PM"""
    if not value:
        return ''
    
    try:
        # Parse ISO format datetime (e.g., "2026-03-04T17:27:52.671524" or "2026-03-04T17:27:52")
        if 'T' in value:
            # Handle both with and without microseconds
            if '.' in value:
                dt = datetime.strptime(value.split('.')[0], '%Y-%m-%dT%H:%M:%S')
            else:
                dt = datetime.strptime(value, '%Y-%m-%dT%H:%M:%S')
        else:
            # Handle other datetime formats that might exist
            dt = datetime.strptime(value, '%Y-%m-%d %H:%M:%S')
        
        # Format as DD-MM-YY at HH:MM AM/PM
        return dt.strftime('%d-%m-%y at %I:%M %p')
    except (ValueError, AttributeError):
        # If parsing fails, return original value
        return value

# Add cache-control headers to prevent browser caching of HTML templates
@app.after_request
def set_cache_headers(response):
    """Prevent browser caching of HTML templates but allow caching of static assets"""
    if response.content_type and 'text/html' in response.content_type:
        # Don't cache HTML templates
        response.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
        response.headers['Pragma'] = 'no-cache'
        response.headers['Expires'] = '0'
    return response


@app.errorhandler(Exception)
def handle_unhandled_exception(e):
    """
    Global handler for any exception that escapes a route's own try/except block.
    Returns a JSON error response instead of Flask's default HTML 500 page, which
    caused the client-side 'Server returned non-JSON response (HTTP 500)' error.
    """
    # Let Flask handle standard HTTP exceptions (404, 405, etc.) normally so that
    # their correct status codes and messages are preserved.
    if isinstance(e, HTTPException):
        return e
    logging.error(f"Unhandled exception: {type(e).__name__}: {e}")
    logging.error(traceback.format_exc())
    return jsonify({"success": False, "error": "An internal server error occurred. Please try again."}), 500

