@app.route("/api/import_playlist_url", methods=["POST"])
def api_import_playlist_url():
    """Preview tracks from a Spotify or Apple Music playlist URL.

    Body: {"url": "..."}
    Returns track list with artist, title, album, duration_ms, track_number plus
    playlist_name, album_artist, is_compilation, and service fields.

    Spotify playlists are fetched without requiring configured API credentials by
    using Spotify's anonymous web-player access token.  Configured client_id /
    client_secret are used as a fallback only if the anonymous token cannot be
    obtained.
    """
    try:
        data = request.json or {}
        url = (data.get("url") or "").strip()
        if not url:
            return jsonify({"success": False, "error": "url is required"}), 400

        # --- Spotify ---
        spotify_playlist_id = None
        if "open.spotify.com/playlist/" in url:
            # e.g. https://open.spotify.com/playlist/37i9dQZF1DXcBWIGoYBM5M
            _path = url.split("open.spotify.com/playlist/")[1].split("?")[0].split("/")[0]
            spotify_playlist_id = _path
        elif url.startswith("spotify:playlist:"):
            spotify_playlist_id = url.split("spotify:playlist:")[1].split("?")[0]

        if spotify_playlist_id:
            import requests as _req

            # Attempt to get an anonymous Spotify web-player token first so that
            # no developer API credentials are required for public playlist lookups.
            _access_token = None
            try:
                _anon_resp = _req.get(
                    "https://open.spotify.com/get_access_token",
                    params={"reason": "transport", "productType": "web_player"},
                    headers={
                        "User-Agent": (
                            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                            "AppleWebKit/537.36 (KHTML, like Gecko) "
                            "Chrome/124.0.0.0 Safari/537.36"
                        ),
                        "Accept": "application/json",
                    },
                    timeout=(5, 10),
                )
                if _anon_resp.status_code == 200:
                    _access_token = _anon_resp.json().get("accessToken")
            except Exception:
                pass

            # Fall back to configured API credentials if anonymous token unavailable.
            if not _access_token:
                config_data, _ = _read_yaml(CONFIG_PATH)
                spotify_config = config_data.get("api_integrations", {}).get("spotify", {})
                client_id = spotify_config.get("client_id", "")
                client_secret = spotify_config.get("client_secret", "")
                if client_id and client_secret:
                    try:
                        from api_clients.spotify import SpotifyClient
                        _access_token = SpotifyClient(client_id, client_secret)._get_token()
                    except Exception:
                        pass

            if not _access_token:
                return jsonify({
                    "success": False,
                    "error": (
                        "Could not obtain a Spotify access token. "
                        "Optionally add client_id/client_secret to config.yaml as a fallback."
                    ),
                }), 400

            _auth_headers = {
                "Authorization": f"Bearer {_access_token}",
                "Content-Type": "application/json",
            }

            # Fetch playlist metadata (name).
            playlist_name = spotify_playlist_id
            try:
                _meta = _req.get(
                    f"https://api.spotify.com/v1/playlists/{spotify_playlist_id}",
                    headers=_auth_headers,
                    params={"fields": "name"},
                    timeout=(5, 15),
                )
                if _meta.status_code == 200:
                    playlist_name = _meta.json().get("name") or playlist_name
            except Exception:
                pass

            # Fetch all tracks via paginated endpoint.
            tracks = []
            next_url = f"https://api.spotify.com/v1/playlists/{spotify_playlist_id}/tracks"
            params = {"limit": 100}
            while next_url:
                _resp = _req.get(next_url, headers=_auth_headers, params=params, timeout=(5, 30))
                _resp.raise_for_status()
                payload = _resp.json()
                for item in payload.get("items", []):
                    track = item.get("track") or {}
                    if track.get("id"):
                        artist = ", ".join(
                            a.get("name", "") for a in track.get("artists", [])
                        )
                        tracks.append({
                            "track_number": len(tracks) + 1,
                            "artist": artist,
                            "title": track.get("name", ""),
                            "album": (track.get("album") or {}).get("name", ""),
                            "duration_ms": track.get("duration_ms") or 0,
                        })
                next_url = payload.get("next")
                params = None  # next URL already contains query params

            # Determine album_artist.
            artists = [t["artist"] for t in tracks if t["artist"]]
            primary_artists = set(a.split(",")[0].strip() for a in artists)
            album_artist = list(primary_artists)[0] if len(primary_artists) == 1 else "Various Artists"
            is_compilation = album_artist == "Various Artists"

            return jsonify({
                "success": True,
                "service": "spotify",
                "playlist_name": playlist_name,
                "tracks": tracks,
                "album_artist": album_artist,
                "is_compilation": is_compilation,
            })

        # --- Apple Music ---
        try:
            from urllib.parse import urlparse as _urlparse
            _parsed_url = _urlparse(url)
            _is_apple_music = (
                _parsed_url.hostname is not None
                and (
                    _parsed_url.hostname == "music.apple.com"
                    or _parsed_url.hostname.endswith(".music.apple.com")
                )
                and "/playlist/" in (_parsed_url.path or "")
            )
        except Exception:
            _is_apple_music = False
        if _is_apple_music:
            # Apple Music public playlists: https://music.apple.com/us/playlist/name/pl.xxx
            return jsonify({
                "success": False,
                "error": (
                    "Apple Music playlist import requires Apple Music API authentication "
                    "which is not yet configured. Only Spotify playlists are supported."
                ),
            }), 400

        return jsonify({
            "success": False,
            "error": "Unrecognised playlist URL. Provide a Spotify or Apple Music playlist link.",
        }), 400

    except Exception as _e:
        logging.error(f"[import_playlist_url] Error: {_e}", exc_info=True)
        return jsonify({"success": False, "error": "Failed to process playlist URL"}), 500


@app.route("/api/import_playlist_url/queue", methods=["POST"])
def api_import_playlist_url_queue():
    """Add previewed playlist tracks to the download queue.

    Body: {
        "playlist_name": "...",
        "album_artist": "...",
        "is_compilation": true|false,
        "tracks": [{"artist": ..., "title": ..., "duration_ms": ..., "track_number": ...}, ...]
    }
    Returns {"success": true, "queued": N, "skipped": M}
    """
    try:
        data = request.json or {}
        playlist_name = (data.get("playlist_name") or "").strip()
        album_artist = (data.get("album_artist") or "").strip() or "Various Artists"
        tracks = data.get("tracks") or []

        if not tracks:
            return jsonify({"success": False, "error": "No tracks provided"}), 400

        from download_queue_manager import add_to_queue
        queued_count = 0
        skipped_count = 0

        for t in tracks:
            artist = (t.get("artist") or "").strip()
            title = (t.get("title") or "").strip()
            if not artist or not title:
                skipped_count += 1
                continue
            duration_ms = t.get("duration_ms") or 0
            duration_sec = int(duration_ms / 1000) if duration_ms else None
            result = add_to_queue(
                artist=artist,
                title=title,
                album=playlist_name or None,
                album_artist=album_artist or None,
                source="soulseek",
                priority=5,
                import_type="song",
                track_number=t.get("track_number"),
                duration=duration_sec,
            )
            if result:
                queued_count += 1
            else:
                skipped_count += 1

        return jsonify({"success": True, "queued": queued_count, "skipped": skipped_count})

    except Exception as _e:
        logging.error(f"[import_playlist_url/queue] Error: {_e}", exc_info=True)
        return jsonify({"success": False, "error": "Failed to add tracks to queue"}), 500


@app.route("/api/playlist/session", methods=["POST"])
def api_create_playlist_session():
    """
    Create a playlist download session and add tracks to download queue.
    """
    try:
        data = request.json
        
        if not data:
            return jsonify({"success": False, "error": "No data provided"}), 400
        
        session_name = data.get("session_name", "").strip()
        playlist_name = data.get("playlist_name", "").strip()
        playlist_id = data.get("playlist_id", "").strip()
        download_method = data.get("download_method", "soulseek").strip()
        tracks = data.get("tracks", [])
        
        if not session_name or not tracks:
            return jsonify({"success": False, "error": "Missing session_name or tracks"}), 400
        
        if download_method not in ["soulseek", "qbittorrent"]:
            return jsonify({"success": False, "error": "Invalid download_method"}), 400
        
        # Add each track to the download queue
        from download_queue_manager import add_to_queue
        
        queued_tracks = []
        failed_tracks = []
        
        for track in tracks:
            artist = track.get("artist", "").strip()
            title = track.get("title", "").strip()
            album = track.get("album", "").strip()
            
            if not artist or not title:
                failed_tracks.append(track)
                continue
            
            try:
                queue_item = add_to_queue(artist, title, album, download_method, priority=5)
                if queue_item:
                    queued_tracks.append(queue_item)
                else:
                    failed_tracks.append(track)
            except Exception as e:
                logging.error(f"Failed to queue {artist} - {title}: {e}")
                failed_tracks.append(track)
        
        # Log this session
        try:
            conn = get_db()
            cursor = conn.cursor()
            placeholder = "%s"
            
            # Use the correct table name from schema (playlist_download_sessions)
            cursor.execute(f"""
                INSERT INTO playlist_download_sessions 
                (session_name, playlist_name, playlist_id, download_method, total_tracks, queued_count, status, user, created_at, updated_at)
                VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, 'in_progress', {placeholder}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            """, (session_name, playlist_name, playlist_id, download_method, len(tracks), len(queued_tracks), 'unknown'))
            
            conn.commit()
            conn.close()
        except Exception as e:
            logging.warning(f"Failed to log playlist session: {e}")
        
        return jsonify({
            "success": True,
            "session_name": session_name,
            "playlist_name": playlist_name,
            "queued_count": len(queued_tracks),
            "failed_count": len(failed_tracks),
            "total_count": len(tracks),
            "queued_tracks": queued_tracks,
            "failed_tracks": failed_tracks
        })
    
    except Exception as e:
        logging.error(f"Failed to create playlist session: {e}", exc_info=True)
        return jsonify({"success": False, "error": f"Failed to create session: {str(e)}"}), 500

