def convert_row_to_json_serializable(obj):
    """
    Recursively convert database Row objects and other non-JSON-serializable types to JSON-safe formats.
    Handles: Row objects, datetime, Decimal, Jinja2 Undefined, None, etc.
    """
    from jinja2 import Undefined
    
    if obj is None:
        return None
    
    # Handle Jinja2 Undefined objects
    if isinstance(obj, Undefined):
        return None
    
    # Convert Row objects to dicts
    if hasattr(obj, 'keys') and not isinstance(obj, dict):  # row-like mapping object
        obj = dict(obj)
    
    # Recursively process dicts
    if isinstance(obj, dict):
        return {k: convert_row_to_json_serializable(v) for k, v in obj.items()}
    
    # Recursively process lists
    if isinstance(obj, (list, tuple)):
        return [convert_row_to_json_serializable(item) for item in obj]
    
    # Convert datetime to ISO format string
    if isinstance(obj, datetime):
        return obj.isoformat()
    
    # Convert Decimal to float
    try:
        from decimal import Decimal
        if isinstance(obj, Decimal):
            return float(obj)
    except ImportError:
        pass
    
    # Return as-is if it's already JSON-serializable (str, int, float, bool, None)
    return obj


@app.route("/artists")
def artists():
    """List all album artists (not track artists). Only show albums where they are the album artist.
    Exception: Various Artists shows all compilation albums and their tracks.
    Filter: Only show artists with at least 1 album or EP (excludes artists with only 0 albums/EPs)."""
    conn = get_db()
    cursor = conn.cursor()
    placeholder = "%s"
    
    # Get total counts for all tracks (including those without artist info)
    cursor.execute("""
        SELECT 
            COUNT(DISTINCT album) as album_count,
            COUNT(*) as track_count,
            COALESCE(SUM(CASE WHEN stars = 5 THEN 1 ELSE 0 END), 0) as five_star_count
        FROM tracks
    """)
    total_stats = cursor.fetchone()
    
    # Filter artists to show only those with at least one album or EP
    # Derive a canonical album artist per album before aggregating to artist level.
    # This prevents bad per-track album_artist backfills from leaking track artists
    # into the top-level artist browser, especially on Various Artists releases.
    try:
        cursor.execute("""
            WITH normalized_tracks AS (
                SELECT
                    COALESCE(
                        NULLIF(TRIM(musicbrainz_album_mbid), ''),
                        LOWER(TRIM(album)) || '|' || COALESCE(NULLIF(TRIM(CAST(year AS TEXT)), ''), '')
                    ) AS album_key,
                    album,
                    CASE
                        WHEN album_artist IS NOT NULL AND TRIM(album_artist) != '' THEN TRIM(album_artist)
                        WHEN artist IS NOT NULL AND TRIM(artist) != '' THEN TRIM(artist)
                        ELSE NULL
                    END AS candidate_album_artist,
                    last_scanned AS artist_last_updated,
                    stars,
                    CASE
                        WHEN LOWER(TRIM(COALESCE(album_artist, ''))) IN (
                            'various artists', 'various', 'v/a', 'va', 'compilation', 'soundtrack', 'original soundtrack'
                        ) THEN 1
                        ELSE 0
                    END AS is_compilation_artist
                FROM tracks
                WHERE album IS NOT NULL
                  AND TRIM(album) != ''
            ),
            ranked_album_artists AS (
                SELECT
                    album_key,
                    candidate_album_artist,
                    COUNT(*) AS matched_track_count,
                    MAX(artist_last_updated) AS artist_last_updated,
                    MAX(is_compilation_artist) AS is_compilation_artist,
                    ROW_NUMBER() OVER (
                        PARTITION BY album_key
                        ORDER BY
                            MAX(is_compilation_artist) DESC,
                            COUNT(*) DESC,
                            candidate_album_artist ASC
                    ) AS artist_rank
                FROM normalized_tracks
                WHERE candidate_album_artist IS NOT NULL
                  AND candidate_album_artist != ''
                GROUP BY album_key, candidate_album_artist
            ),
            canonical_albums AS (
                SELECT
                    album_key,
                    candidate_album_artist AS canonical_album_artist,
                    artist_last_updated
                FROM ranked_album_artists
                WHERE artist_rank = 1
            ),
            artist_name_counts AS (
                SELECT
                    canonical_album_artist,
                    LOWER(canonical_album_artist) AS artist_key,
                    COUNT(*) AS usage_count
                FROM canonical_albums
                GROUP BY canonical_album_artist
            ),
            best_artist_name AS (
                SELECT DISTINCT ON (artist_key)
                    artist_key,
                    canonical_album_artist AS display_name
                FROM artist_name_counts
                ORDER BY artist_key, usage_count DESC, canonical_album_artist ASC
            )
            SELECT
                ban.display_name AS display_name,
                ban.display_name AS link_artist,
                COUNT(DISTINCT ca.album_key) AS album_count,
                COUNT(nt.album_key) AS track_count,
                COALESCE(SUM(CASE WHEN nt.stars = 5 THEN 1 ELSE 0 END), 0) AS five_star_count,
                MAX(ca.artist_last_updated) AS last_updated
            FROM canonical_albums ca
            JOIN normalized_tracks nt
              ON nt.album_key = ca.album_key
            JOIN best_artist_name ban
              ON LOWER(ca.canonical_album_artist) = ban.artist_key
            GROUP BY ban.display_name
            HAVING COUNT(DISTINCT ca.album_key) > 0
            ORDER BY display_name
        """)
        artists_data = [dict(row) for row in cursor.fetchall()]
    except Exception as _artists_cte_err:
        # Fallback for databases without album_artist column
        logging.debug(f"[artists] CTE query failed (possibly missing album_artist column), using artist-only fallback: {_artists_cte_err}")
        try:
            conn.rollback()
        except Exception:
            pass
        collate_nocase = ""
        cursor.execute(f"""
            SELECT 
                artist as display_name,
                artist as link_artist,
                COUNT(DISTINCT album) as album_count,
                COUNT(*) as track_count,
                COALESCE(SUM(CASE WHEN stars = 5 THEN 1 ELSE 0 END), 0) as five_star_count,
                MAX(last_scanned) as last_updated
            FROM tracks
            WHERE artist IS NOT NULL AND artist != ''
            GROUP BY artist{collate_nocase}
            HAVING album_count > 0
            ORDER BY display_name{collate_nocase}
        """)
        artists_data = [dict(row) for row in cursor.fetchall()]
    
    # Sort by display_name, handling special characters and numbers that should be grouped under '#'
    # Leading articles ("The", "A", "An") are stripped for sort purposes so e.g.
    # "The Pretty Reckless" sorts under "P" not "T".
    _SORT_ARTICLES = ("the ", "a ", "an ")

    def get_sort_key(artist):
        name = artist.get('display_name', '')
        if not name:
            return ('~', '')  # Sort empty names to the end
        sort_name = name
        lower = name.lower()
        for article in _SORT_ARTICLES:
            if lower.startswith(article):
                sort_name = name[len(article):]
                break
        first_char = sort_name[0].upper() if sort_name else name[0].upper()
        # If first character is A-Z, use it; otherwise use '#' for sorting
        if first_char in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
            return (first_char, sort_name.lower())
        else:
            return ('#', sort_name.lower())
    
    artists_data = sorted(artists_data, key=get_sort_key)

    # Annotate each artist with its sort_letter so the template can build correct letter headers
    for _artist in artists_data:
        _sk = get_sort_key(_artist)
        _artist['sort_letter'] = _sk[0] if _sk[0] != '~' else '#'

    conn.close()

    return render_template("artists.html", artists=artists_data, total_stats=total_stats, DB_PATH=DB_PATH)


@app.route("/api/artists/corrections")
def api_artists_corrections():
    """Return per-artist correction indicators asynchronously for the /artists page.

    Runs all diagnostic queries (duplicates, missing metadata, MBID conflicts, etc.)
    and returns a JSON dict keyed by artist display name so the artists page can
    populate the "Needs Correcting" badges after initial load.
    """
    conn = get_db()
    cursor = conn.cursor()

    track_columns = _get_table_columns(cursor, 'tracks')
    has_album_artist = 'album_artist' in track_columns
    artist_expr = "COALESCE(NULLIF(album_artist, ''), artist)" if has_album_artist else "artist"
    candidate_album_artist_expr = (
        "CASE "
        "WHEN album_artist IS NOT NULL AND TRIM(album_artist) != '' THEN TRIM(album_artist) "
        "WHEN artist IS NOT NULL AND TRIM(artist) != '' THEN TRIM(artist) "
        "ELSE NULL END"
        if has_album_artist
        else "CASE WHEN artist IS NOT NULL AND TRIM(artist) != '' THEN TRIM(artist) ELSE NULL END"
    )
    is_compilation_artist_expr = (
        "CASE "
        "WHEN LOWER(TRIM(COALESCE(album_artist, ''))) IN ('various artists', 'various', 'v/a', 'va', 'compilation', 'soundtrack', 'original soundtrack') THEN 1 "
        "ELSE 0 END"
        if has_album_artist
        else "CASE WHEN LOWER(TRIM(COALESCE(artist, ''))) IN ('various artists', 'various', 'v/a', 'va', 'compilation', 'soundtrack', 'original soundtrack') THEN 1 ELSE 0 END"
    )

    duplicate_counts_by_artist = {}
    missing_counts_by_artist = {}
    duplicate_artist_counts_by_artist = {}
    disc_inconsistent_counts_by_artist = {}
    mbid_inconsistent_counts_by_artist = {}
    extra_album_artist_counts_by_artist = {}
    album_tag_inconsistency_counts_by_artist: dict = {}
    missing_tracks_counts_by_artist: dict = {}

    try:
        # Query 1: Find duplicate tracks
        cursor.execute(f"""
            WITH dup_groups AS (
                SELECT
                    {artist_expr} AS display_name,
                    album,
                    LOWER(TRIM(title)) AS norm_title,
                    LOWER(TRIM(COALESCE(artist, ''))) AS norm_artist,
                    TRIM(COALESCE(CAST(track_number AS TEXT), '')) AS norm_track_number,
                    TRIM(COALESCE(CAST(disc_number AS TEXT), '')) AS norm_disc_number,
                    COUNT(*) AS grp_count
                FROM tracks
                WHERE {artist_expr} IS NOT NULL
                  AND TRIM({artist_expr}) != ''
                  AND title IS NOT NULL
                  AND TRIM(title) != ''
                GROUP BY
                    {artist_expr},
                    album,
                    LOWER(TRIM(title)),
                    LOWER(TRIM(COALESCE(artist, ''))),
                    TRIM(COALESCE(CAST(track_number AS TEXT), '')),
                    TRIM(COALESCE(CAST(disc_number AS TEXT), ''))
                HAVING COUNT(*) > 1
            )
            SELECT display_name, COALESCE(SUM(grp_count - 1), 0) AS duplicate_count
            FROM dup_groups
            GROUP BY display_name
        """)
        for row in cursor.fetchall():
            row_dict = dict(row)
            duplicate_counts_by_artist[row_dict.get("display_name", "")] = int(row_dict.get("duplicate_count") or 0)

        # Query 2: Find tracks with missing core metadata
        cursor.execute(f"""
            SELECT
                {artist_expr} AS display_name,
                COUNT(*) AS missing_count
            FROM tracks
            WHERE {artist_expr} IS NOT NULL
              AND TRIM({artist_expr}) != ''
              AND (
                    title IS NULL OR TRIM(title) = '' OR
                    album IS NULL OR TRIM(album) = '' OR
                    track_number IS NULL OR TRIM(CAST(track_number AS TEXT)) = '' OR
                    CAST(COALESCE(NULLIF(TRIM(CAST(track_number AS TEXT)), ''), '0') AS INTEGER) <= 0 OR
                    duration IS NULL OR CAST(duration AS DOUBLE PRECISION) <= 0
                  )
            GROUP BY {artist_expr}
        """)
        for row in cursor.fetchall():
            row_dict = dict(row)
            missing_counts_by_artist[row_dict.get("display_name", "")] = int(row_dict.get("missing_count") or 0)

        # Query 3: Find duplicate artists (same MBID, different names)
        cursor.execute(f"""
            SELECT
                musicbrainz_artist_id,
                COUNT(DISTINCT {artist_expr}) as distinct_artist_names
            FROM tracks
            WHERE musicbrainz_artist_id IS NOT NULL
              AND musicbrainz_artist_id != ''
              AND {artist_expr} IS NOT NULL
              AND TRIM({artist_expr}) != ''
            GROUP BY musicbrainz_artist_id
            HAVING COUNT(DISTINCT {artist_expr}) > 1
        """)
        mbid_to_artists_map = {}
        for row in cursor.fetchall():
            row_dict = dict(row)
            mbid = row_dict.get("musicbrainz_artist_id", "")
            if mbid:
                mbid_to_artists_map[mbid] = row_dict.get("distinct_artist_names", 0)

        cursor.execute(f"""
            SELECT DISTINCT
                {artist_expr} as effective_artist,
                musicbrainz_artist_id
            FROM tracks
            WHERE musicbrainz_artist_id IS NOT NULL
              AND musicbrainz_artist_id != ''
              AND {artist_expr} IS NOT NULL
              AND TRIM({artist_expr}) != ''
        """)
        for row in cursor.fetchall():
            row_dict = dict(row)
            artist_name = row_dict.get("effective_artist", "")
            mbid = row_dict.get("musicbrainz_artist_id", "")
            if artist_name and mbid in mbid_to_artists_map:
                duplicate_artist_counts_by_artist[artist_name] = mbid_to_artists_map[mbid]

        # Query 4: Albums where some tracks have disc_number and others don't
        cursor.execute(f"""
            SELECT
                display_name,
                COUNT(DISTINCT album) AS album_count
            FROM (
                SELECT
                    {artist_expr} AS display_name,
                    album,
                    SUM(CASE WHEN disc_number IS NOT NULL
                                  AND TRIM(CAST(disc_number AS TEXT)) != ''
                                  AND CAST(disc_number AS TEXT) != '0'
                             THEN 1 ELSE 0 END) AS tracks_with_disc,
                    SUM(CASE WHEN disc_number IS NULL
                                  OR TRIM(CAST(disc_number AS TEXT)) = ''
                                  OR CAST(disc_number AS TEXT) = '0'
                             THEN 1 ELSE 0 END) AS tracks_without_disc,
                    COUNT(DISTINCT CASE WHEN disc_number IS NOT NULL
                                             AND TRIM(CAST(disc_number AS TEXT)) != ''
                                             AND CAST(disc_number AS TEXT) != '0'
                                        THEN CAST(disc_number AS TEXT) END) AS distinct_disc_nums
                FROM tracks
                WHERE {artist_expr} IS NOT NULL
                  AND TRIM({artist_expr}) != ''
                  AND album IS NOT NULL
                  AND TRIM(album) != ''
                GROUP BY {artist_expr}, album
            ) sub
            WHERE tracks_with_disc > 0
              AND tracks_without_disc > 0
              AND distinct_disc_nums <= 1
            GROUP BY display_name
        """)
        for row in cursor.fetchall():
            row_dict = dict(row)
            disc_inconsistent_counts_by_artist[row_dict.get("display_name", "")] = int(row_dict.get("album_count") or 0)

        # Query 5: Albums with mixed/competing musicbrainz_album_mbid values
        cursor.execute(f"""
            SELECT
                display_name,
                COUNT(*) AS album_count
            FROM (
                SELECT
                    {artist_expr} AS display_name,
                    album
                FROM tracks
                WHERE {artist_expr} IS NOT NULL
                  AND TRIM({artist_expr}) != ''
                  AND album IS NOT NULL
                  AND TRIM(album) != ''
                  AND musicbrainz_album_mbid IS NOT NULL
                  AND TRIM(musicbrainz_album_mbid) != ''
                GROUP BY {artist_expr}, album
                HAVING COUNT(DISTINCT TRIM(musicbrainz_album_mbid)) > 1
            ) mixed
            GROUP BY display_name
        """)
        for row in cursor.fetchall():
            row_dict = dict(row)
            mbid_inconsistent_counts_by_artist[row_dict.get("display_name", "")] = int(row_dict.get("album_count") or 0)

        # Query 6: Per canonical artist, count extra album-artist variants
        cursor.execute(f"""
            WITH normalized_tracks AS (
                SELECT
                    COALESCE(
                        NULLIF(TRIM(musicbrainz_album_mbid), ''),
                        LOWER(TRIM(album)) || '|' || COALESCE(NULLIF(TRIM(CAST(year AS TEXT)), ''), '')
                    ) AS album_key,
                    {candidate_album_artist_expr} AS candidate_album_artist,
                    {is_compilation_artist_expr} AS is_compilation_artist
                FROM tracks
                WHERE album IS NOT NULL
                  AND TRIM(album) != ''
            ),
            ranked_album_artists AS (
                SELECT
                    album_key,
                    candidate_album_artist,
                    ROW_NUMBER() OVER (
                        PARTITION BY album_key
                        ORDER BY
                            MAX(is_compilation_artist) DESC,
                            COUNT(*) DESC,
                            candidate_album_artist ASC
                    ) AS artist_rank
                FROM normalized_tracks
                WHERE candidate_album_artist IS NOT NULL
                  AND candidate_album_artist != ''
                GROUP BY album_key, candidate_album_artist
            ),
            canonical_albums AS (
                SELECT
                    album_key,
                    candidate_album_artist AS canonical_album_artist
                FROM ranked_album_artists
                WHERE artist_rank = 1
            )
            SELECT
                ca.canonical_album_artist AS display_name,
                COUNT(*) AS extra_album_artist_count
            FROM canonical_albums ca
            JOIN ranked_album_artists ra
              ON ra.album_key = ca.album_key
            WHERE ra.artist_rank > 1
            GROUP BY ca.canonical_album_artist
        """)
        for row in cursor.fetchall():
            row_dict = dict(row)
            extra_album_artist_counts_by_artist[row_dict.get("display_name", "")] = int(row_dict.get("extra_album_artist_count") or 0)

    except Exception as correction_err:
        logging.debug(f"[api_artists_corrections] Could not compute correction indicators: {correction_err}")
        try:
            conn.rollback()
        except Exception:
            pass

    # Album tag inconsistency counts per artist
    try:
        tag_having_parts = [
            f"COUNT(DISTINCT COALESCE(CAST({field} AS TEXT), '')) > 1"
            for field, _ in ALBUM_CONSISTENCY_FIELDS
            if (field != 'album_artist' or has_album_artist) and field in track_columns
        ]
        if tag_having_parts:
            tag_having_sql = " OR ".join(tag_having_parts)
            cursor.execute(f"""
                SELECT
                    effective_artist AS album_artist,
                    COUNT(*) AS inconsistent_album_count
                FROM (
                    SELECT
                        {artist_expr} AS effective_artist,
                        album
                    FROM tracks
                    WHERE album IS NOT NULL
                      AND TRIM(album) != ''
                    GROUP BY {artist_expr}, album
                    HAVING COUNT(*) >= 2
                      AND ({tag_having_sql})
                ) t
                GROUP BY effective_artist
            """)
            for row in cursor.fetchall():
                row_dict = dict(row)
                aa = row_dict.get('album_artist') or ''
                album_tag_inconsistency_counts_by_artist[aa] = int(row_dict.get('inconsistent_album_count') or 0)
    except Exception as tag_inc_err:
        logging.debug(f"[api_artists_corrections] Could not compute album tag inconsistency counts: {tag_inc_err}")
        try:
            conn.rollback()
        except Exception:
            pass

    # Missing-tracks-in-album counts per artist
    try:
        cursor.execute(f"""
            SELECT
                display_name,
                COUNT(DISTINCT album) AS album_count
            FROM (
                SELECT
                    {artist_expr} AS display_name,
                    album,
                    COALESCE(CAST(disc_number AS TEXT), '1') AS disc,
                    MAX(CAST(track_number AS INTEGER)) AS max_track,
                    COUNT(DISTINCT CAST(track_number AS INTEGER)) AS distinct_tracks
                FROM tracks
                WHERE {artist_expr} IS NOT NULL
                  AND TRIM({artist_expr}) != ''
                  AND album IS NOT NULL
                  AND TRIM(album) != ''
                  AND track_number IS NOT NULL
                  AND TRIM(CAST(track_number AS TEXT)) != ''
                  AND CAST(COALESCE(NULLIF(TRIM(CAST(track_number AS TEXT)), ''), '0') AS INTEGER) > 0
                GROUP BY {artist_expr}, album, COALESCE(CAST(disc_number AS TEXT), '1')
                HAVING MAX(CAST(track_number AS INTEGER)) > COUNT(DISTINCT CAST(track_number AS INTEGER))
                   AND COUNT(DISTINCT CAST(track_number AS INTEGER)) >= 3
            ) gap_albums
            GROUP BY display_name
        """)
        for row in cursor.fetchall():
            row_dict = dict(row)
            missing_tracks_counts_by_artist[row_dict.get("display_name", "")] = int(row_dict.get("album_count") or 0)
    except Exception as mt_err:
        logging.debug(f"[api_artists_corrections] Could not compute missing-tracks counts: {mt_err}")
        try:
            conn.rollback()
        except Exception:
            pass

    # Collect all artist names that appear in any diagnostic dict
    all_artists = set()
    for d in [
        duplicate_counts_by_artist,
        missing_counts_by_artist,
        duplicate_artist_counts_by_artist,
        disc_inconsistent_counts_by_artist,
        mbid_inconsistent_counts_by_artist,
        extra_album_artist_counts_by_artist,
        album_tag_inconsistency_counts_by_artist,
        missing_tracks_counts_by_artist,
    ]:
        all_artists.update(d.keys())

    corrections = {}
    for name in all_artists:
        duplicate_count = duplicate_counts_by_artist.get(name, 0)
        disc_inconsistent_count = disc_inconsistent_counts_by_artist.get(name, 0)
        mbid_inconsistent_count = mbid_inconsistent_counts_by_artist.get(name, 0)
        missing_tracks_count = missing_tracks_counts_by_artist.get(name, 0)
        needs_correction = (
            duplicate_count + disc_inconsistent_count + mbid_inconsistent_count + missing_tracks_count
        ) > 0
        corrections[name] = {
            "needs_correction": needs_correction,
            "duplicate_track_count": duplicate_count,
            "missing_track_count": missing_counts_by_artist.get(name, 0),
            "duplicate_artist_count": int(duplicate_artist_counts_by_artist.get(name, 0)),
            "disc_inconsistent_count": disc_inconsistent_count,
            "mbid_inconsistent_count": mbid_inconsistent_count,
            "extra_album_artist_count": extra_album_artist_counts_by_artist.get(name, 0),
            "album_tag_inconsistency_count": album_tag_inconsistency_counts_by_artist.get(name, 0),
            "missing_tracks_count": missing_tracks_count,
            "corrections_url": url_for('artist_corrections', name=name),
        }

    conn.close()
    return jsonify({"corrections": corrections})


@app.route("/artist/<path:name>/corrections")
def artist_corrections(name):
    """Show duplicate-track groups and missing-core-metadata tracks for one artist."""
    from urllib.parse import unquote

    artist_name = unquote(name)
    conn = get_db()
    cursor = conn.cursor()
    placeholder = "%s"
    track_columns = _get_table_columns(cursor, 'tracks')
    has_album_artist = 'album_artist' in track_columns
    artist_expr = "COALESCE(NULLIF(album_artist, ''), artist)" if has_album_artist else "artist"
    album_artist_select = (
        "COALESCE(NULLIF(album_artist, ''), artist) AS album_artist"
        if has_album_artist else
        "artist AS album_artist"
    )

    duplicate_groups = []
    missing_tracks = []
    mbid_inconsistent_albums = []

    try:
        cursor.execute(f"""
            SELECT
                id,
                album,
                title,
                COALESCE(NULLIF(artist, ''), '—') AS track_artist,
                TRIM(COALESCE(CAST(track_number AS TEXT), '')) AS track_number,
                TRIM(COALESCE(CAST(disc_number AS TEXT), '')) AS disc_number,
                file_path,
                duration,
                COALESCE(NULLIF(mbid, ''), '') AS mbid,
                COALESCE(NULLIF(suggested_mbid, ''), '') AS suggested_mbid,
                                {album_artist_select}
            FROM tracks
                        WHERE LOWER({artist_expr}) = LOWER({placeholder})
              AND title IS NOT NULL
              AND TRIM(title) != ''
        """, (artist_name,))
        candidate_rows = [dict(r) for r in cursor.fetchall()]

        def _duration_to_display(raw_duration):
            if raw_duration in (None, ""):
                return "—"
            try:
                duration_seconds = float(raw_duration)
                if duration_seconds > 10000:
                    duration_seconds = duration_seconds / 1000.0
                duration_seconds = int(round(duration_seconds))
                minutes = duration_seconds // 60
                seconds = duration_seconds % 60
                return f"{minutes}:{seconds:02d}"
            except Exception:
                return "—"

        def _normalize_name_component(value):
            return _queue_sanitize_component(str(value or "")).lower()

        def _build_expected_filename(track_row):
            file_name_format = _read_queue_naming_format()
            file_ext = os.path.splitext(str(track_row.get("file_path") or ""))[1] or ".mp3"

            year_value = str(track_row.get("year") or "").strip()[:4] if track_row.get("year") else "Unknown"
            format_vars = {
                "track_number": _queue_safe_track_number(track_row.get("track_number")),
                "artist": _queue_sanitize_component(track_row.get("track_artist") or "Unknown Artist") or "Unknown Artist",
                "album_artist": _queue_sanitize_component(track_row.get("album_artist") or track_row.get("track_artist") or "Unknown Artist") or "Unknown Artist",
                "title": _queue_sanitize_component(track_row.get("title") or "Unknown Title") or "Unknown Title",
                "album": _queue_sanitize_component(track_row.get("album") or "Unknown Album") or "Unknown Album",
                "year": year_value or "Unknown",
            }

            fallback_rel = (
                f"{format_vars['album_artist']}/{format_vars['year']} - {format_vars['album']}/"
                f"{format_vars['track_number']}. {format_vars['artist']} - {format_vars['title']}{file_ext}"
            )

            try:
                rendered = file_name_format.format(**format_vars)
            except Exception:
                rendered = fallback_rel

            if not isinstance(rendered, str) or not rendered.strip():
                rendered = fallback_rel

            rendered = rendered.strip().replace("\\", "/")
            base_name = os.path.basename(rendered)
            if not base_name:
                base_name = os.path.basename(fallback_rel)

            if not os.path.splitext(base_name)[1]:
                base_name = f"{base_name}{file_ext}"

            return base_name

        # Version-variant keywords that indicate a track is a distinct alternate version.
        # If one track's file path contains such a keyword and another's doesn't, they
        # are different versions of the same song and must NOT be flagged as duplicates.
        version_variant_keywords = [
            "instrumental", "karaoke", "a cappella", "acapella",
            "acoustic", "demo", "orchestral", "symphonic",
        ]

        def file_variant_key(file_path):
            """Return a frozenset of version-variant keywords found in the file name."""
            name = os.path.basename(str(file_path or "")).lower()
            return frozenset(
                kw for kw in version_variant_keywords
                if re.search(r"\b" + re.escape(kw) + r"\b", name)
            )

        grouped = {}
        for row in candidate_rows:
            group_key = (
                row.get("album") or "",
                row.get("title") or "",
                row.get("track_artist") or "",
                row.get("track_number") or "",
                row.get("disc_number") or "",
            )
            grouped.setdefault(group_key, []).append(row)

        for (album, title, track_artist, track_number, disc_number), tracks in grouped.items():
            if len(tracks) < 2:
                continue

            # Skip groups where tracks differ in version-variant status (e.g., one
            # has "(Instrumental)" in the file name but another doesn't).  Such tracks
            # are distinct alternate versions, not true duplicates.
            variant_keys = [file_variant_key(t.get("file_path", "")) for t in tracks]
            if len(set(variant_keys)) > 1:
                continue

            mbid_counts = {}
            for track in tracks:
                mbid_value = (track.get("mbid") or "").strip()
                if mbid_value:
                    mbid_counts[mbid_value] = mbid_counts.get(mbid_value, 0) + 1
            consensus_mbid = max(mbid_counts, key=mbid_counts.get) if mbid_counts else ""

            scored_tracks = []
            for track in tracks:
                file_path = str(track.get("file_path") or "")
                file_name = os.path.basename(file_path) if file_path else ""
                expected_name = _build_expected_filename(track)

                actual_name_norm = _normalize_name_component(os.path.splitext(file_name)[0])
                expected_name_norm = _normalize_name_component(os.path.splitext(expected_name)[0])
                filename_similarity = (
                    difflib.SequenceMatcher(None, actual_name_norm, expected_name_norm).ratio()
                    if actual_name_norm and expected_name_norm
                    else 0.0
                )

                mbid_score = 0.0
                if (track.get("mbid") or "").strip():
                    mbid_score += 4.0
                if (track.get("suggested_mbid") or "").strip():
                    mbid_score += 2.0
                if consensus_mbid:
                    if (track.get("mbid") or "").strip() == consensus_mbid:
                        mbid_score += 3.0
                    elif (track.get("mbid") or "").strip():
                        mbid_score -= 2.0

                path_score = 0.0
                lowered_path = file_path.replace("\\", "/").lower()
                if lowered_path.startswith("__queued_for_download__"):
                    path_score -= 2.5
                elif "/downloads/" in lowered_path:
                    path_score -= 1.5
                elif "/music/" in lowered_path:
                    path_score += 1.0

                duration_bonus = 0.3 if track.get("duration") not in (None, "", 0, "0") else 0.0
                keep_score = mbid_score + (filename_similarity * 2.5) + path_score + duration_bonus

                recommendation_notes = []
                if consensus_mbid and (track.get("mbid") or "").strip() == consensus_mbid:
                    recommendation_notes.append("Matches consensus MBID")
                if filename_similarity >= 0.9:
                    recommendation_notes.append("Strong queue filename format match")
                elif filename_similarity >= 0.75:
                    recommendation_notes.append("Good queue filename format match")
                if "/downloads/" in lowered_path or lowered_path.startswith("__queued_for_download__"):
                    recommendation_notes.append("Located in downloads/queued path")

                scored_tracks.append({
                    **track,
                    "file_name": file_name or "—",
                    "duration_display": _duration_to_display(track.get("duration")),
                    "expected_filename": expected_name,
                    "filename_similarity": round(filename_similarity, 3),
                    "mbid_score": round(mbid_score, 2),
                    "keep_score": round(keep_score, 3),
                    "recommendation_notes": recommendation_notes,
                })

            sorted_by_keep = sorted(
                scored_tracks,
                key=lambda t: (
                    t.get("keep_score", 0),
                    -t.get("filename_similarity", 0),
                    str(t.get("id") or ""),
                ),
            )
            recommended_delete_id = sorted_by_keep[0].get("id") if sorted_by_keep else None

            for track in scored_tracks:
                track["recommend_delete"] = str(track.get("id")) == str(recommended_delete_id)

            track_ids = ", ".join(str(t.get("id")) for t in scored_tracks)
            recommendation_basis = "MusicBrainz confidence + queue filename format similarity"
            if consensus_mbid:
                recommendation_basis += f" (consensus MBID: {consensus_mbid})"

            duplicate_groups.append({
                "album": album,
                "title": title,
                "track_artist": track_artist,
                "track_number": track_number,
                "duplicate_count": len(scored_tracks),
                "track_ids": track_ids,
                "tracks": sorted(scored_tracks, key=lambda t: str(t.get("id") or "")),
                "recommended_delete_id": recommended_delete_id,
                "recommendation_basis": recommendation_basis,
            })

        duplicate_groups.sort(
            key=lambda g: (
                -(int(g.get("duplicate_count") or 0)),
                str(g.get("album") or ""),
                str(g.get("title") or ""),
            )
        )

        cursor.execute(f"""
            SELECT
                id,
                title,
                album,
                track_number,
                disc_number,
                year,
                duration,
                COALESCE(NULLIF(mbid, ''), '') AS mbid,
                COALESCE(NULLIF(suggested_mbid, ''), '') AS suggested_mbid,
                file_path,
                 CONCAT_WS(', ',
                    CASE WHEN title IS NULL OR TRIM(title) = '' THEN 'Title' END,
                    CASE WHEN album IS NULL OR TRIM(album) = '' THEN 'Album' END,
                    CASE WHEN track_number IS NULL OR TRIM(CAST(track_number AS TEXT)) = '' THEN 'Track Number' END,
                    CASE WHEN CAST(COALESCE(NULLIF(TRIM(CAST(track_number AS TEXT)), ''), '0') AS INTEGER) <= 0 THEN 'Track Number <= 0' END,
                    CASE WHEN duration IS NULL OR CAST(duration AS DOUBLE PRECISION) <= 0 THEN 'Duration' END,
                    CASE WHEN year IS NOT NULL AND TRIM(CAST(year AS TEXT)) != ''
                          AND (CAST(COALESCE(NULLIF(TRIM(CAST(year AS TEXT)), ''), '0') AS INTEGER) < 1900
                              OR CAST(COALESCE(NULLIF(TRIM(CAST(year AS TEXT)), ''), '0') AS INTEGER) > 2100)
                        THEN 'Suspicious Year' END,
                    CASE WHEN (mbid IS NULL OR TRIM(mbid) = '') AND (suggested_mbid IS NULL OR TRIM(suggested_mbid) = '')
                        THEN 'Recording MBID' END,
                    CASE WHEN writer IS NULL OR TRIM(CAST(writer AS TEXT)) IN ('', '[]', 'null', 'None')
                        THEN 'Writer/Lyricist (optional)' END
                 ) AS metadata_missing_fields,
                CASE
                    WHEN title IS NULL OR TRIM(title) = '' THEN 'Missing track title'
                    WHEN album IS NULL OR TRIM(album) = '' THEN 'Missing album name'
                    WHEN track_number IS NULL OR TRIM(CAST(track_number AS TEXT)) = '' THEN 'Missing track number'
                    WHEN CAST(COALESCE(NULLIF(TRIM(CAST(track_number AS TEXT)), ''), '0') AS INTEGER) <= 0 THEN 'Invalid track number (<= 0)'
                    WHEN duration IS NULL OR CAST(duration AS DOUBLE PRECISION) <= 0 THEN 'Missing or invalid duration'
                    WHEN year IS NOT NULL AND TRIM(CAST(year AS TEXT)) != ''
                         AND (CAST(COALESCE(NULLIF(TRIM(CAST(year AS TEXT)), ''), '0') AS INTEGER) < 1900
                              OR CAST(COALESCE(NULLIF(TRIM(CAST(year AS TEXT)), ''), '0') AS INTEGER) > 2100)
                         THEN 'Suspicious year value'
                    WHEN (mbid IS NULL OR TRIM(mbid) = '') AND (suggested_mbid IS NULL OR TRIM(suggested_mbid) = '') THEN 'Missing recording MBID and suggested MBID'
                    ELSE 'Metadata needs review'
                END AS metadata_issue_reason
            FROM tracks
                        WHERE LOWER({artist_expr}) = LOWER({placeholder})
              AND (
                    title IS NULL OR TRIM(title) = '' OR
                    album IS NULL OR TRIM(album) = '' OR
                    track_number IS NULL OR TRIM(CAST(track_number AS TEXT)) = '' OR
                    CAST(COALESCE(NULLIF(TRIM(CAST(track_number AS TEXT)), ''), '0') AS INTEGER) <= 0 OR
                    duration IS NULL OR CAST(duration AS DOUBLE PRECISION) <= 0 OR
                    (
                        year IS NOT NULL AND TRIM(CAST(year AS TEXT)) != '' AND
                        (
                            CAST(COALESCE(NULLIF(TRIM(CAST(year AS TEXT)), ''), '0') AS INTEGER) < 1900 OR
                            CAST(COALESCE(NULLIF(TRIM(CAST(year AS TEXT)), ''), '0') AS INTEGER) > 2100
                        )
                    ) OR
                    ((mbid IS NULL OR TRIM(mbid) = '') AND (suggested_mbid IS NULL OR TRIM(suggested_mbid) = ''))
                  )
            ORDER BY album, track_number, title
        """, (artist_name,))
        missing_tracks = [dict(r) for r in cursor.fetchall()]

        # Fetch albums that have a MusicBrainz MBID so the corrections page can
        # offer the async "Check for Missing Tracks" feature per album.
        mb_albums = []
        try:
            cursor.execute(f"""
                SELECT album, COUNT(*) as track_count, MAX(musicbrainz_album_mbid) as mb_mbid
                FROM tracks
                                WHERE LOWER({artist_expr}) = LOWER({placeholder})
                  AND musicbrainz_album_mbid IS NOT NULL AND musicbrainz_album_mbid != ''
                GROUP BY album
                ORDER BY album
            """, (artist_name,))
            for row in cursor.fetchall():
                rd = dict(row) if hasattr(row, "keys") else {"album": row[0], "track_count": row[1], "mb_mbid": row[2]}
                mb_albums.append({
                    "album": rd.get("album"),
                    "track_count": int(rd.get("track_count") or 0),
                    "mb_mbid": rd.get("mb_mbid"),
                })
        except Exception as mb_err:
            logging.debug(f"[CORRECTIONS] Could not fetch MB albums: {mb_err}")
            try:
                conn.rollback()
            except Exception:
                pass

        # Albums with mixed album MBIDs. These need manual approval of one
        # canonical MBID across all tracks.
        try:
            cursor.execute(f"""
                SELECT
                    album,
                    COUNT(*) AS track_count,
                    COUNT(DISTINCT TRIM(musicbrainz_album_mbid)) AS mbid_count,
                    STRING_AGG(DISTINCT TRIM(musicbrainz_album_mbid), ',' ORDER BY TRIM(musicbrainz_album_mbid)) AS mbid_values
                FROM tracks
                                WHERE LOWER({artist_expr}) = LOWER({placeholder})
                  AND album IS NOT NULL
                  AND TRIM(album) != ''
                  AND musicbrainz_album_mbid IS NOT NULL
                  AND TRIM(musicbrainz_album_mbid) != ''
                GROUP BY album
                HAVING COUNT(DISTINCT TRIM(musicbrainz_album_mbid)) > 1
                ORDER BY album
            """, (artist_name,))
            for row in cursor.fetchall():
                rd = dict(row) if hasattr(row, "keys") else {}
                mbid_csv = rd.get("mbid_values") or ""
                mbids = [m.strip() for m in str(mbid_csv).split(",") if m and m.strip()]
                mbid_inconsistent_albums.append({
                    "album": rd.get("album"),
                    "track_count": int(rd.get("track_count") or 0),
                    "mbid_count": int(rd.get("mbid_count") or len(mbids)),
                    "mbids": mbids,
                })
        except Exception as mbid_err:
            logging.debug(f"[CORRECTIONS] Could not fetch mixed album MBIDs: {mbid_err}")
            try:
                conn.rollback()
            except Exception:
                pass

        # Fetch albums with disc number inconsistency: some tracks have
        # disc_number set, others don't — on a single-disc album this
        # causes Navidrome to display the album as multiple entries.
        disc_inconsistent_albums = []
        mbid_inconsistent_albums = []
        try:
            cursor.execute(f"""
                SELECT
                    album,
                    COUNT(*) AS track_count,
                    SUM(CASE WHEN disc_number IS NOT NULL
                                  AND TRIM(CAST(disc_number AS TEXT)) != ''
                                  AND CAST(disc_number AS TEXT) != '0'
                             THEN 1 ELSE 0 END) AS tracks_with_disc,
                    SUM(CASE WHEN disc_number IS NULL
                                  OR TRIM(CAST(disc_number AS TEXT)) = ''
                                  OR CAST(disc_number AS TEXT) = '0'
                             THEN 1 ELSE 0 END) AS tracks_without_disc,
                    COUNT(DISTINCT CASE WHEN disc_number IS NOT NULL
                                        AND TRIM(CAST(disc_number AS TEXT)) != ''
                                        AND CAST(disc_number AS TEXT) != '0'
                                    THEN CAST(disc_number AS TEXT) END) AS distinct_disc_values,
                    MAX(CASE WHEN disc_number IS NOT NULL
                                  AND TRIM(CAST(disc_number AS TEXT)) != ''
                                  AND CAST(disc_number AS TEXT) != '0'
                             THEN CAST(disc_number AS TEXT) END) AS disc_value
                FROM tracks
                                WHERE LOWER({artist_expr}) = LOWER({placeholder})
                  AND album IS NOT NULL AND TRIM(album) != ''
                GROUP BY album
                HAVING SUM(CASE WHEN disc_number IS NOT NULL
                                     AND TRIM(CAST(disc_number AS TEXT)) != ''
                                     AND CAST(disc_number AS TEXT) != '0'
                                THEN 1 ELSE 0 END) > 0
                   AND SUM(CASE WHEN disc_number IS NULL
                                     OR TRIM(CAST(disc_number AS TEXT)) = ''
                                     OR CAST(disc_number AS TEXT) = '0'
                                THEN 1 ELSE 0 END) > 0
                ORDER BY album
            """, (artist_name,))
            for row in cursor.fetchall():
                rd = dict(row) if hasattr(row, "keys") else {}
                disc_inconsistent_albums.append({
                    "album": rd.get("album"),
                    "track_count": int(rd.get("track_count") or 0),
                    "tracks_with_disc": int(rd.get("tracks_with_disc") or 0),
                    "tracks_without_disc": int(rd.get("tracks_without_disc") or 0),
                    "distinct_disc_values": int(rd.get("distinct_disc_values") or 0),
                    "disc_value": rd.get("disc_value"),
                })
        except Exception as disc_err:
            logging.debug(f"[CORRECTIONS] Could not fetch disc inconsistency albums: {disc_err}")
            try:
                conn.rollback()
            except Exception:
                pass

        # Fetch albums with mixed MusicBrainz album MBIDs for this artist.
        try:
            cursor.execute(f"""
                SELECT
                    album,
                    COUNT(*) AS track_count,
                    COUNT(DISTINCT TRIM(musicbrainz_album_mbid)) AS distinct_mbid_count,
                    STRING_AGG(DISTINCT TRIM(musicbrainz_album_mbid), ', ') AS mbid_list
                FROM tracks
                                WHERE LOWER({artist_expr}) = LOWER({placeholder})
                  AND album IS NOT NULL
                  AND TRIM(album) != ''
                  AND musicbrainz_album_mbid IS NOT NULL
                  AND TRIM(musicbrainz_album_mbid) != ''
                GROUP BY album
                HAVING COUNT(DISTINCT TRIM(musicbrainz_album_mbid)) > 1
                ORDER BY album
            """, (artist_name,))
            for row in cursor.fetchall():
                rd = dict(row) if hasattr(row, "keys") else {}
                mbids = [m.strip() for m in str(rd.get("mbid_list") or "").split(',') if m.strip()]
                mbid_inconsistent_albums.append({
                    "album": rd.get("album"),
                    "track_count": int(rd.get("track_count") or 0),
                    "distinct_mbid_count": int(rd.get("distinct_mbid_count") or 0),
                    "mbids": mbids,
                })
        except Exception as mbid_err:
            logging.debug(f"[CORRECTIONS] Could not fetch MBID inconsistency albums: {mbid_err}")
            try:
                conn.rollback()
            except Exception:
                pass

        # Detect duplicate album entries for the same artist.
        # Two albums are considered duplicates when either:
        #   (a) they share the same non-null musicbrainz_album_mbid (strongest signal), or
        #   (b) their names normalise to the same string after stripping common edition
        #       suffixes like "(Remastered)", "[Deluxe]", "- Original Soundtrack", etc.
        duplicate_albums = []
        try:
            cursor.execute(f"""
                SELECT
                    album,
                    COUNT(*) AS track_count,
                    MIN(year) AS album_year,
                    MAX(musicbrainz_album_mbid) AS mb_mbid
                FROM tracks
                WHERE LOWER({artist_expr}) = LOWER({placeholder})
                  AND album IS NOT NULL AND TRIM(album) != ''
                GROUP BY album
                ORDER BY album
            """, (artist_name,))
            all_album_rows = []
            for row in cursor.fetchall():
                rd = dict(row) if hasattr(row, "keys") else {
                    "album": row[0], "track_count": row[1],
                    "album_year": row[2], "mb_mbid": row[3],
                }
                all_album_rows.append({
                    "album": rd.get("album") or "",
                    "track_count": int(rd.get("track_count") or 0),
                    "album_year": rd.get("album_year"),
                    "mb_mbid": (rd.get("mb_mbid") or "").strip(),
                })

            from download_queue_manager import _normalize_album_for_dedup

            # Build groups keyed first by MBID, then by normalised name.
            mbid_groups: dict = {}
            for row in all_album_rows:
                mb = row["mb_mbid"]
                if mb:
                    mbid_groups.setdefault(mb, []).append(row)

            # Albums already grouped by MBID don't need a second normalised-name pass.
            mbid_grouped_names = {
                r["album"]
                for rows in mbid_groups.values()
                for r in rows
                if len(rows) > 1
            }

            norm_groups: dict = {}
            for row in all_album_rows:
                if row["album"] in mbid_grouped_names:
                    continue
                norm = _normalize_album_for_dedup(row["album"])
                if norm:
                    norm_groups.setdefault(norm, []).append(row)

            seen_album_sets: set = set()

            def _add_dup_group(albums_in_group: list, signal: str) -> None:
                if len(albums_in_group) < 2:
                    return
                key = tuple(sorted(a["album"] for a in albums_in_group))
                if key in seen_album_sets:
                    return
                seen_album_sets.add(key)
                # Sort so the album with the most tracks is offered as the default
                # canonical name (it is likely the most complete entry).
                sorted_albums = sorted(albums_in_group, key=lambda x: -(x.get("track_count") or 0))
                duplicate_albums.append({
                    "albums": sorted_albums,
                    "canonical_name": sorted_albums[0]["album"],
                    "signal": signal,
                })

            for _mb, rows in mbid_groups.items():
                _add_dup_group(rows, "mbid")
            for _norm, rows in norm_groups.items():
                _add_dup_group(rows, "name")

        except Exception as dup_alb_err:
            logging.debug(f"[CORRECTIONS] Could not detect duplicate albums: {dup_alb_err}")
            try:
                conn.rollback()
            except Exception:
                pass
    finally:
        conn.close()

    return render_template(
        "artist_corrections.html",
        artist_name=artist_name,
        duplicates=duplicate_groups,
        missing_tracks=missing_tracks,
        mb_albums=mb_albums,
        mbid_inconsistent_albums=mbid_inconsistent_albums,
        disc_inconsistent_albums=disc_inconsistent_albums,
        duplicate_albums=duplicate_albums,
        duplicate_count=sum(max(int(d.get("duplicate_count") or 0) - 1, 0) for d in duplicate_groups),
        missing_count=len(missing_tracks),
        mbid_inconsistent_count=len(mbid_inconsistent_albums),
        disc_inconsistent_count=len(disc_inconsistent_albums),
        duplicate_album_count=len(duplicate_albums),
    )


@app.route("/api/artist/corrections/delete-track", methods=["POST"])
def api_artist_corrections_delete_track():
    """Delete one track row (and optionally its file) from Corrections UI."""
    try:
        payload = request.get_json(silent=True) or {}
        track_id = str(payload.get("track_id") or "").strip()
        delete_file = bool(payload.get("delete_file", True))

        if not track_id:
            return jsonify({"success": False, "error": "track_id is required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(
            f"""
            SELECT id, file_path, artist, album, title
            FROM tracks
            WHERE CAST(id AS TEXT) = {placeholder}
            LIMIT 1
            """,
            (track_id,),
        )
        row = cursor.fetchone()

        if not row:
            conn.close()
            return jsonify({"success": False, "error": "Track not found"}), 404

        row_dict = dict(row) if hasattr(row, "keys") else {
            "id": row[0],
            "file_path": row[1],
            "artist": row[2],
            "album": row[3],
            "title": row[4],
        }

        deleted_file = False
        file_path = row_dict.get("file_path")
        if delete_file and file_path:
            normalized_file_path = str(file_path).replace("\\", "/")
            if not normalized_file_path.startswith("__queued_for_download__") and os.path.exists(file_path):
                try:
                    os.remove(file_path)
                    deleted_file = True
                except Exception as file_err:
                    logging.warning(f"[CORRECTIONS] Could not delete file for track {track_id}: {file_err}")

        cursor.execute(
            f"DELETE FROM tracks WHERE CAST(id AS TEXT) = {placeholder}",
            (track_id,),
        )
        conn.commit()
        conn.close()

        logging.info(
            f"[CORRECTIONS] Deleted duplicate track {track_id}: "
            f"{row_dict.get('artist')} - {row_dict.get('title')} "
            f"(file_deleted={deleted_file})"
        )

        return jsonify({
            "success": True,
            "deleted_track_id": track_id,
            "deleted_file": deleted_file,
            "message": "Track deleted successfully",
        })
    except Exception as e:
        logging.error(f"[CORRECTIONS] Failed to delete track: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/artist/corrections/clear-disc-number", methods=["POST"])
def api_artist_corrections_clear_disc_number():
    """Clear disc_number for all tracks in a given album that have it set.

    This fixes the Navidrome "multiple albums" problem caused by a mix of
    tracks with disc_number and tracks without it on a single-disc album.
    """
    try:
        payload = request.get_json(silent=True) or {}
        artist_name = str(payload.get("artist") or "").strip()
        album_name = str(payload.get("album") or "").strip()

        if not artist_name or not album_name:
            return jsonify({"success": False, "error": "artist and album are required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        force_clear = bool(payload.get("force_clear", False))
        cursor.execute(
            f"""
            SELECT
                COUNT(DISTINCT CASE WHEN disc_number IS NOT NULL
                                         AND TRIM(CAST(disc_number AS TEXT)) != ''
                                         AND CAST(disc_number AS TEXT) != '0'
                                    THEN CAST(disc_number AS TEXT) END) AS distinct_disc_values,
                MAX(CASE WHEN disc_number IS NOT NULL
                              AND TRIM(CAST(disc_number AS TEXT)) != ''
                              AND CAST(disc_number AS TEXT) != '0'
                         THEN CAST(disc_number AS TEXT) END) AS max_disc_value
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
              AND album = {placeholder}
            """,
            (artist_name, album_name),
        )
        safety_row = cursor.fetchone()
        safety = dict(safety_row) if hasattr(safety_row, "keys") else {
            "distinct_disc_values": safety_row[0] if safety_row else 0,
            "max_disc_value": safety_row[1] if safety_row else None,
        }
        distinct_disc_values = int(safety.get("distinct_disc_values") or 0)
        max_disc_value = str(safety.get("max_disc_value") or "").strip()
        likely_multi_disc = distinct_disc_values > 1 or (max_disc_value.isdigit() and int(max_disc_value) > 1)
        if likely_multi_disc and not force_clear:
            conn.close()
            return jsonify({
                "success": False,
                "error": "This album appears to be multi-disc. Automatic clear is blocked to avoid damaging correct metadata.",
                "needs_manual_review": True,
                "distinct_disc_values": distinct_disc_values,
                "max_disc_value": max_disc_value or None,
            }), 409

        # Count and collect affected track IDs before clearing
        cursor.execute(
            f"""
            SELECT id, file_path
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
              AND album = {placeholder}
              AND disc_number IS NOT NULL
              AND TRIM(CAST(disc_number AS TEXT)) != ''
              AND CAST(disc_number AS TEXT) != '0'
            """,
            (artist_name, album_name),
        )
        affected_rows = [dict(r) if hasattr(r, "keys") else {"id": r[0], "file_path": r[1]}
                         for r in cursor.fetchall()]

        if not affected_rows:
            conn.close()
            return jsonify({"success": True, "cleared": 0,
                            "message": "No tracks with disc_number found for this album"})

        cursor.execute(
            f"""
            UPDATE tracks
            SET disc_number = NULL
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
              AND album = {placeholder}
              AND disc_number IS NOT NULL
              AND TRIM(CAST(disc_number AS TEXT)) != ''
              AND CAST(disc_number AS TEXT) != '0'
            """,
            (artist_name, album_name),
        )
        conn.commit()
        cleared_count = cursor.rowcount if cursor.rowcount and cursor.rowcount >= 0 else len(affected_rows)
        conn.close()

        # Also clear the tag from the actual audio files
        files_updated = 0
        for row in affected_rows:
            file_path = row.get("file_path")
            if not file_path or not os.path.exists(str(file_path)):
                continue
            try:
                from helpers.tag_manager import update_file_tags
                update_file_tags(str(file_path), {"disc_number": None})
                files_updated += 1
            except Exception as tag_err:
                logging.debug(f"[CORRECTIONS] Could not clear disc_number tag on {file_path}: {tag_err}")

        logging.info(
            f"[CORRECTIONS] Cleared disc_number for {cleared_count} track(s) in "
            f"'{artist_name} — {album_name}' (files updated: {files_updated})"
        )

        return jsonify({
            "success": True,
            "cleared": cleared_count,
            "files_updated": files_updated,
            "message": f"Cleared disc number from {cleared_count} track(s)",
        })
    except Exception as e:
        logging.error(f"[CORRECTIONS] Failed to clear disc numbers: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/artist/corrections/apply-album-mbid", methods=["POST"])
def api_artist_corrections_apply_album_mbid():
    """Apply one canonical album MBID to all tracks in a specific artist/album."""
    try:
        payload = request.get_json(silent=True) or {}
        artist_name = str(payload.get("artist") or "").strip()
        album_name = str(payload.get("album") or "").strip()
        album_mbid = str(payload.get("mbid") or "").strip()
        release_group_mbid = str(payload.get("release_group_mbid") or "").strip()

        if not artist_name or not album_name or not album_mbid:
            return jsonify({"success": False, "error": "artist, album, and mbid are required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        columns = _get_table_columns(cursor, "tracks") or set()
        set_parts = []
        params = []

        if "musicbrainz_album_mbid" in columns:
            set_parts.append(f"musicbrainz_album_mbid = {placeholder}")
            params.append(album_mbid)
            # Keep the canonical alias in sync.
            if "musicbrainz_albumid" in columns:
                set_parts.append(f"musicbrainz_albumid = {placeholder}")
                params.append(album_mbid)
        elif "beets_album_mbid" in columns:
            set_parts.append(f"beets_album_mbid = {placeholder}")
            params.append(album_mbid)
        else:
            conn.close()
            return jsonify({"success": False, "error": "No album MBID column found on tracks table"}), 500

        if release_group_mbid and "musicbrainz_releasegroupid" in columns:
            set_parts.append(f"musicbrainz_releasegroupid = {placeholder}")
            params.append(release_group_mbid)

        cursor.execute(
            f"SELECT id, file_path FROM tracks WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}",
            (artist_name, album_name),
        )
        track_rows = [dict(r) if hasattr(r, "keys") else {"id": r[0], "file_path": r[1]} for r in cursor.fetchall()]

        if not track_rows:
            conn.close()
            return jsonify({"success": False, "error": "No tracks found for this artist/album"}), 404

        params.extend([artist_name, album_name])
        cursor.execute(
            f"UPDATE tracks SET {', '.join(set_parts)} WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}",
            tuple(params),
        )
        rows_updated = cursor.rowcount if cursor.rowcount and cursor.rowcount >= 0 else len(track_rows)
        conn.commit()
        conn.close()

        files_updated = 0
        for row in track_rows:
            file_path = str(row.get("file_path") or "").strip()
            if not file_path or not os.path.exists(file_path):
                continue
            try:
                from helpers.tag_manager import write_tags_to_file

                tags_to_write = {"musicbrainz_album_mbid": album_mbid, "musicbrainz_albumid": album_mbid}
                if release_group_mbid:
                    tags_to_write["musicbrainz_releasegroupid"] = release_group_mbid
                if write_tags_to_file(file_path, tags_to_write):
                    files_updated += 1
            except Exception as file_err:
                logging.debug(f"[CORRECTIONS] Failed to write album MBID tags for {file_path}: {file_err}")

        return jsonify({
            "success": True,
            "rows_updated": rows_updated,
            "files_updated": files_updated,
            "message": f"Applied album MBID to {rows_updated} track(s)",
        })
    except Exception as e:
        logging.error(f"[CORRECTIONS] Failed to apply album MBID correction: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/artist/corrections/merge-albums", methods=["POST"])
def api_artist_corrections_merge_albums():
    """Merge two or more split album entries into one canonical album name.

    Updates every matching track in the database and rewrites the album tag in
    each track's audio file so the fix survives a future Navidrome rescan.
    """
    try:
        payload = request.get_json(silent=True) or {}
        artist_name = str(payload.get("artist") or "").strip()
        source_albums = payload.get("source_albums") or []
        canonical_name = str(payload.get("canonical_name") or "").strip()

        if not artist_name or not source_albums or not canonical_name:
            return jsonify({"success": False, "error": "artist, source_albums, and canonical_name are required"}), 400

        if not isinstance(source_albums, list):
            source_albums = [source_albums]

        # Only rename albums whose current name differs from the target.
        albums_to_rename = [a for a in source_albums if a != canonical_name]
        if not albums_to_rename:
            return jsonify({"success": True, "rows_updated": 0, "files_updated": 0,
                            "message": "Nothing to rename — all albums already use the canonical name"})

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        artist_expr = "COALESCE(NULLIF(album_artist, ''), artist)"
        placeholders_list = ", ".join([placeholder] * len(albums_to_rename))

        # Collect tracks before updating so we have file paths for tag writes.
        cursor.execute(
            f"SELECT id, file_path FROM tracks WHERE LOWER({artist_expr}) = LOWER({placeholder}) AND album IN ({placeholders_list})",
            [artist_name] + albums_to_rename,
        )
        track_rows = [dict(r) if hasattr(r, "keys") else {"id": r[0], "file_path": r[1]}
                      for r in cursor.fetchall()]

        if not track_rows:
            conn.close()
            return jsonify({"success": False, "error": "No tracks found for the specified source albums"}), 404

        cursor.execute(
            f"UPDATE tracks SET album = {placeholder} WHERE LOWER({artist_expr}) = LOWER({placeholder}) AND album IN ({placeholders_list})",
            [canonical_name, artist_name] + albums_to_rename,
        )
        rows_updated = cursor.rowcount if cursor.rowcount and cursor.rowcount >= 0 else len(track_rows)
        conn.commit()
        conn.close()

        # Rewrite the album tag in each audio file so Navidrome won't recreate
        # the split on its next rescan.
        files_updated = 0
        files_skipped = 0
        for row in track_rows:
            file_path = str(row.get("file_path") or "").strip()
            if not file_path or not os.path.exists(file_path):
                files_skipped += 1
                continue
            try:
                from helpers.tag_manager import write_tags_to_file
                if write_tags_to_file(file_path, {"album": canonical_name}):
                    files_updated += 1
            except Exception as file_err:
                logging.debug(f"[CORRECTIONS] Failed to write album tag for {file_path}: {file_err}")

        logging.info(
            f"[CORRECTIONS] merge-albums: artist='{artist_name}' merged {albums_to_rename} → '{canonical_name}' "
            f"rows={rows_updated} files={files_updated} skipped={files_skipped}"
        )
        return jsonify({
            "success": True,
            "rows_updated": rows_updated,
            "files_updated": files_updated,
            "message": (
                f"Merged {len(albums_to_rename)} album name(s) into \"{canonical_name}\" "
                f"({rows_updated} track(s) updated, {files_updated} file(s) retagged)"
            ),
        })
    except Exception as e:
        logging.error(f"[CORRECTIONS] Failed to merge albums: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


