def _search_mb_release_id_for_album(artist: str, album: str, expected_track_count: int = 0) -> str:
    """Search MusicBrainz for a release MBID matching artist+album.

    Returns the release MBID string for the best-scoring match, or an empty
    string when no confident match is found.
    """
    if not artist or not album:
        return ""
    try:
        from difflib import SequenceMatcher

        escaped_artist = _escape_mb_phrase(artist)
        escaped_album = _escape_mb_phrase(album)
        resp = requests.get(
            "https://musicbrainz.org/ws/2/release/",
            params={
                "query": f'artist:"{escaped_artist}" AND release:"{escaped_album}"',
                "fmt": "json",
                "limit": 10,
            },
            headers={"User-Agent": MUSICBRAINZ_USER_AGENT},
            timeout=10,
        )
        resp.raise_for_status()
        releases = resp.json().get("releases", []) or []
        if not releases:
            return ""

        def _score(rel):
            title_sim = SequenceMatcher(None, album.lower(), (rel.get("title") or "").lower()).ratio()
            credits = rel.get("artist-credit") or []
            artist_name = (
                credits[0].get("name", "") if credits and isinstance(credits[0], dict) else ""
            )
            artist_sim = SequenceMatcher(None, artist.lower(), artist_name.lower()).ratio()
            track_count = rel.get("track-count") or 0
            track_bonus = (
                0.1 if expected_track_count and abs(track_count - expected_track_count) <= 2 else 0.0
            )
            return title_sim * 0.5 + artist_sim * 0.3 + track_bonus

        releases.sort(key=_score, reverse=True)
        best = releases[0]
        if _score(best) >= 0.6:
            return best.get("id") or ""
    except Exception as exc:
        logging.debug(f"[MISSING_TRACKS] MB release search fallback failed for {artist}/{album}: {exc}")
    return ""


@app.route("/api/album/missing-tracks")
def api_album_missing_tracks():
    """Check which tracks are in the MusicBrainz release but missing from the library for an album."""
    artist = ""
    album = ""
    try:
        artist = request.args.get("artist", "").strip()
        album = request.args.get("album", "").strip()
        if not artist or not album:
            return jsonify({"error": "artist and album required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # Get library track count and MB MBID for this album
        try:
            cursor.execute(f"""
                SELECT COUNT(*) as track_count, MAX(musicbrainz_album_mbid) as mb_mbid
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
            """, (artist, album))
        except Exception:
            cursor.execute(f"""
                SELECT COUNT(*) as track_count, NULL as mb_mbid
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
            """, (artist, album))

        row = cursor.fetchone()
        if not row:
            conn.close()
            return jsonify({"missing_tracks": [], "missing_count": 0, "library_count": 0})

        row_dict = dict(row) if hasattr(row, "keys") else {"track_count": row[0], "mb_mbid": row[1]}
        library_count = int(row_dict.get("track_count") or 0)
        mb_mbid = row_dict.get("mb_mbid")

        if not mb_mbid:
            # Fallback: search MusicBrainz by artist+album name to find the release MBID.
            fallback_mbid = _search_mb_release_id_for_album(artist, album, library_count)
            if not fallback_mbid:
                conn.close()
                return jsonify({"missing_tracks": [], "missing_count": 0, "library_count": library_count, "reason": "no_mbid"})
            mb_mbid = fallback_mbid
            # Persist the discovered MBID so future calls don't need to search again.
            try:
                cursor.execute(
                    f"UPDATE tracks SET musicbrainz_album_mbid = {placeholder}"
                    f" WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}"
                    f"   AND album = {placeholder}"
                    f"   AND (musicbrainz_album_mbid IS NULL OR TRIM(musicbrainz_album_mbid) = '')",
                    (mb_mbid, artist, album),
                )
                conn.commit()
            except Exception as _save_err:
                logging.debug(f"[MISSING_TRACKS] Could not persist fallback MBID: {_save_err}")

        # Fetch library tracks for this album (include mbid/beets_mbid for MBID-based matching)
        cursor.execute(f"""
            SELECT id, title, track_number, disc_number, mbid, beets_mbid FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
        """, (artist, album))
        library_rows = cursor.fetchall()
        conn.close()

        # Build a consumable local-track pool so one library row cannot satisfy
        # multiple MusicBrainz rows. This matters for duplicate titles and for
        # releases where MusicBrainz flattens a multi-disc set into a single disc.
        library_entries = []
        for t in library_rows:
            if hasattr(t, "keys"):
                t_dict = dict(t)
            else:
                t_dict = {"id": t[0], "title": t[1], "track_number": t[2], "disc_number": t[3], "mbid": t[4], "beets_mbid": t[5]}
            disc = int(t_dict.get("disc_number") or 1)
            track_num = t_dict.get("track_number")
            norm = re.sub(r'\s+', ' ', (t_dict.get("title") or "").lower().strip())
            track_num_int = None
            if track_num is not None:
                try:
                    track_num_int = int(track_num)
                except (TypeError, ValueError):
                    track_num_int = None
            mbids = set()
            for mbid_field in ("beets_mbid", "mbid"):
                val = (t_dict.get(mbid_field) or "").strip()
                if val:
                    mbids.add(val)
            library_entries.append({
                "disc": disc,
                "track_num": track_num_int,
                "norm_title": norm,
                "mbids": mbids,
            })

        # Fetch MusicBrainz release tracklist from shared in-memory cache first.
        from folder_matching_enhancements import get_musicbrainz_release_metadata
        now_ts = time.time()
        cache_entry = _mb_release_metadata_cache.get(mb_mbid)
        if cache_entry and (now_ts - float(cache_entry.get("cached_at", 0.0)) < _MB_RELEASE_CACHE_TTL_SECONDS):
            mb_release = cache_entry.get("data")
        else:
            mb_release = get_musicbrainz_release_metadata(mb_mbid)
            if mb_release:
                _mb_release_metadata_cache[mb_mbid] = {
                    "cached_at": now_ts,
                    "data": mb_release,
                }
        if not mb_release:
            return jsonify({"missing_tracks": [], "missing_count": 0, "library_count": library_count, "reason": "mb_not_found"})

        mb_tracks = mb_release.get("tracks", [])
        mb_total = len(mb_tracks)
        mb_year = mb_release.get("release_year") or ""

        remaining_entries = list(library_entries)

        def _pop_matching_entry(predicate):
            for idx, entry in enumerate(remaining_entries):
                if predicate(entry):
                    return remaining_entries.pop(idx)
            return None

        def _strip_feat_from_title(title):
            """Strip featured-artist notations from a title for fuzzy matching.

            Handles patterns like:
              "Until the End (feat. Elize Ryd)" -> "Until the End"
              "Song feat. Artist"               -> "Song"
              "Song ft. Artist"                 -> "Song"
            """
            t = re.sub(
                r'\s*[\(\[](?:feat\.?|ft\.?|featuring|with)\b[^\)\]]*[\)\]]',
                '', title, flags=re.IGNORECASE,
            )
            t = re.sub(r'\s+(?:feat\.?|ft\.?|featuring)\s+.+$', '', t, flags=re.IGNORECASE)
            return t.strip()

        def _track_matches_title(entry, disc, norm, norm_rec, norm_stripped=None):
            if entry["disc"] == disc and entry["norm_title"] == norm:
                return True
            if norm_rec and entry["disc"] == disc and entry["norm_title"] == norm_rec:
                return True
            if entry["norm_title"] == norm:
                return True
            if norm_rec and entry["norm_title"] == norm_rec:
                return True
            # Try feat-stripped variant of the MB title so that a library entry
            # stored without the featured artist (e.g. "Until the End") still
            # matches an MB title like "Until the End (feat. Elize Ryd)".
            if norm_stripped and norm_stripped != norm:
                if entry["disc"] == disc and entry["norm_title"] == norm_stripped:
                    return True
                if entry["norm_title"] == norm_stripped:
                    return True
            return False

        missing = []
        for mb_track in mb_tracks:
            t_disc = int(mb_track.get("disc_number") or 1)
            t_track_num = mb_track.get("track_number")
            t_title = mb_track.get("title", "")
            t_norm = re.sub(r'\s+', ' ', t_title.lower().strip())
            # Feat-stripped variant for matching against plain library titles.
            t_norm_stripped = re.sub(r'\s+', ' ', _strip_feat_from_title(t_title).lower().strip())
            t_recording_mbid = (mb_track.get("recording_mbid") or "").strip()

            # Normalise the canonical recording title (shorter, no venue suffix)
            # so we can match library entries stored without venue context.
            # e.g. recording_title "Dig" matches library title "Dig" even when
            # the track title is "Dig (live at Candlestick Park, ...)".
            t_recording_title = mb_track.get("recording_title") or ""
            t_norm_recording = re.sub(r'\s+', ' ', t_recording_title.lower().strip())

            matched_entry = None
            if t_recording_mbid:
                matched_entry = _pop_matching_entry(lambda entry: t_recording_mbid in entry["mbids"])

            if matched_entry is None:
                try:
                    t_track_num_int = int(t_track_num) if t_track_num is not None else None
                except (TypeError, ValueError):
                    t_track_num_int = None

                if t_track_num_int is not None:
                    matched_entry = _pop_matching_entry(
                        lambda entry: (
                            entry["disc"] == t_disc
                            and entry["track_num"] == t_track_num_int
                            and _track_matches_title(entry, t_disc, t_norm, t_norm_recording, t_norm_stripped)
                        )
                    )

            if matched_entry is None:
                matched_entry = _pop_matching_entry(
                    lambda entry: _track_matches_title(entry, t_disc, t_norm, t_norm_recording, t_norm_stripped)
                )

            # Final fallback: match by track number alone (same disc + same position).
            # This handles tracks whose titles differ slightly in the library
            # (e.g. "Song" vs "Song (Remastered)") so they are not falsely flagged
            # as missing when the track clearly occupies the correct position.
            if matched_entry is None and t_track_num_int is not None:
                matched_entry = _pop_matching_entry(
                    lambda entry: (
                        entry["disc"] == t_disc
                        and entry["track_num"] == t_track_num_int
                    )
                )

            if matched_entry is None:
                # MusicBrainz returns duration in milliseconds; convert to seconds for UI
                mb_duration_ms = mb_track.get("duration")
                duration_sec = mb_duration_ms // 1000 if mb_duration_ms else None
                missing.append({
                    "title": t_title,
                    "track_number": t_track_num,
                    "disc_number": t_disc,
                    "artist": mb_track.get("artist") or artist,
                    "album": album,
                    "album_artist": artist,
                    "year": mb_year,
                    "release_id": mb_mbid,
                    "recording_mbid": t_recording_mbid,
                    "duration": duration_sec,
                    "is_missing": True,
                })

        return jsonify({
            "missing_tracks": missing,
            "missing_count": len(missing),
            "mb_total": mb_total,
            "library_count": library_count,
        })
    except Exception as e:
        logging.error(f"[MISSING_TRACKS] Error checking missing tracks for {artist}/{album}: {e}")
        return jsonify({"error": str(e), "missing_tracks": [], "missing_count": 0}), 500


@app.route("/api/album/title-mismatches")
def api_album_title_mismatches():
    """Compare library track titles against the full MusicBrainz release tracklist.

    For each library track that can be matched by track number to its MB counterpart:
    - If the title doesn't match the MB title → mismatch_type = 'title'
    - If the title AND the duration both don't match → mismatch_type = 'title_and_length'

    Duration tolerance: tracks whose durations differ by more than 5 seconds are
    considered a length mismatch.
    """
    artist = ""
    album = ""
    try:
        artist = request.args.get("artist", "").strip()
        album = request.args.get("album", "").strip()
        if not artist or not album:
            return jsonify({"error": "artist and album required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # Get MusicBrainz MBID and library tracks for this album
        try:
            cursor.execute(f"""
                SELECT COUNT(*) as track_count, MAX(musicbrainz_album_mbid) as mb_mbid
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
            """, (artist, album))
        except Exception:
            cursor.execute(f"""
                SELECT COUNT(*) as track_count, NULL as mb_mbid
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
            """, (artist, album))

        row = cursor.fetchone()
        if not row:
            conn.close()
            return jsonify({"mismatches": [], "mismatch_count": 0, "library_count": 0})

        row_dict = dict(row) if hasattr(row, "keys") else {"track_count": row[0], "mb_mbid": row[1]}
        library_count = int(row_dict.get("track_count") or 0)
        mb_mbid = row_dict.get("mb_mbid")

        if not mb_mbid:
            conn.close()
            return jsonify({"mismatches": [], "mismatch_count": 0, "library_count": library_count, "reason": "no_mbid"})

        track_columns = _get_table_columns(cursor, "tracks") or set()
        has_is_cover = "is_cover" in track_columns
        has_cover_manual_override = "cover_manual_override" in track_columns
        has_original_cover_artist = "original_cover_artist" in track_columns
        has_is_cover_reason = "is_cover_reason" in track_columns

        extra_cols = []
        if has_is_cover:
            extra_cols.append("is_cover")
        if has_cover_manual_override:
            extra_cols.append("cover_manual_override")
        if has_original_cover_artist:
            extra_cols.append("original_cover_artist")
        if has_is_cover_reason:
            extra_cols.append("is_cover_reason")

        select_cols = "id, title, track_number, disc_number, duration, file_path"
        if extra_cols:
            select_cols += ", " + ", ".join(extra_cols)

        cursor.execute(f"""
            SELECT {select_cols}
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
        """, (artist, album))
        library_rows = cursor.fetchall()
        conn.close()

        def _to_seconds(raw):
            """Convert a raw duration value (seconds or ms) to seconds, or None."""
            if raw is None or raw == "":
                return None
            try:
                val = float(raw)
                if val > 10000:
                    val = val / 1000.0
                return val if val > 0 else None
            except (TypeError, ValueError):
                return None

        # Build a lookup from (disc, track_number) → library track
        lib_by_tracknum = {}

        def _is_cover_track(track_row):
            """Return True if a row is marked/identified as a cover track."""
            def _is_truthy(value):
                if isinstance(value, bool):
                    return value
                if isinstance(value, (int, float)):
                    return value != 0
                return str(value or "").strip().lower() in {"1", "true", "t", "yes", "y", "on"}

            if _is_truthy(track_row.get("is_cover")):
                return True
            if str(track_row.get("original_cover_artist") or "").strip():
                return True
            cover_reason = str(track_row.get("is_cover_reason") or "").lower()
            if "cover" in cover_reason:
                return True
            # Detect covers by title pattern:
            #   bracketed:  "Song (Artist Cover)", "Song [Cover]", "Song (Cover Version)"
            #   bare word:  "Song - cover version", "Song cover", "Imagine (cover by X)"
            title = str(track_row.get("title") or "").strip()
            if re.search(r'\bcover\b', title, re.IGNORECASE):
                return True
            return False

        def _strip_cover_notation(title: str) -> str:
            """Remove cover-version annotations from a track title before comparison.

            Handles patterns such as:
              "Song (Cover Version)"  → "Song"
              "Song [Cover by Artist]" → "Song"
              "Song - cover version"  → "Song"
              "Song (Originally by X)" → "Song"
              "Song (Originally performed by X)" → "Song"
            """
            # Strip bracketed cover annotations, e.g. "(cover)", "(cover version)",
            # "(cover by Artist)", "[cover]", "[originally by X]"
            t = re.sub(r'[\(\[][^\)\]]*\bcover\b[^\)\]]*[\)\]]', '', title, flags=re.IGNORECASE)
            t = re.sub(r'[\(\[][^\)\]]*\boriginally\b[^\)\]]*[\)\]]', '', t, flags=re.IGNORECASE)
            # Strip trailing bare "- cover …" or "- cover version" phrases
            t = re.sub(r'\s*[-–—]\s*cover\b.*$', '', t, flags=re.IGNORECASE)
            # Strip trailing "cover version" / "cover" as a standalone suffix
            t = re.sub(r'\s+cover\s+version\s*$', '', t, flags=re.IGNORECASE)
            t = re.sub(r'\s+cover\s*$', '', t, flags=re.IGNORECASE)
            return re.sub(r'\s+', ' ', t).strip()

        for t in library_rows:
            t_dict = dict(t) if hasattr(t, "keys") else {
                "id": t[0], "title": t[1], "track_number": t[2],
                "disc_number": t[3], "duration": t[4], "file_path": t[5],
            }

            # Covers are intentionally excluded from MB title mismatch checks.
            if _is_cover_track(t_dict):
                continue

            disc = int(t_dict.get("disc_number") or 1)
            track_num = t_dict.get("track_number")
            if track_num is not None:
                try:
                    lib_by_tracknum[(disc, int(track_num))] = t_dict
                except (TypeError, ValueError):
                    pass

        # Fetch MusicBrainz release tracklist from cache first.
        from folder_matching_enhancements import get_musicbrainz_release_metadata
        mb_release = get_musicbrainz_release_metadata(mb_mbid)
        if not mb_release:
            return jsonify({"mismatches": [], "mismatch_count": 0, "library_count": library_count, "reason": "mb_not_found"})

        mb_year = mb_release.get("release_year") or ""
        mismatches = []
        _DURATION_TOLERANCE_SECONDS = 5

        for mb_track in mb_release.get("tracks", []):
            t_disc = int(mb_track.get("disc_number") or 1)
            t_track_num = mb_track.get("track_number")
            if t_track_num is None:
                continue
            try:
                t_track_num_int = int(t_track_num)
            except (TypeError, ValueError):
                continue

            lib_track = lib_by_tracknum.get((t_disc, t_track_num_int))
            if lib_track is None:
                continue

            mb_title = (mb_track.get("title") or "").strip()
            lib_title = (lib_track.get("title") or "").strip()

            # Normalise for comparison: lowercase + collapse whitespace.
            # Strip any cover-version annotations from the library title so that
            # e.g. "Imagine (Cover Version)" is not flagged as a mismatch against
            # the MB title "Imagine".
            mb_title_norm = re.sub(r"\s+", " ", mb_title.lower())
            lib_title_norm = re.sub(r"\s+", " ", _strip_cover_notation(lib_title).lower())

            if mb_title_norm == lib_title_norm:
                continue  # titles match — no mismatch

            # Duration comparison (MB duration is in milliseconds)
            mb_duration_ms = mb_track.get("duration")
            mb_duration_sec = (mb_duration_ms / 1000.0) if mb_duration_ms else None
            lib_duration_sec = _to_seconds(lib_track.get("duration"))

            length_mismatch = False
            if mb_duration_sec is not None and lib_duration_sec is not None:
                if abs(mb_duration_sec - lib_duration_sec) > _DURATION_TOLERANCE_SECONDS:
                    length_mismatch = True

            mismatch_type = "title_and_length" if length_mismatch else "title"

            def _fmt_duration(sec):
                if sec is None:
                    return None
                sec = int(round(sec))
                return f"{sec // 60}:{sec % 60:02d}"

            mismatches.append({
                "track_id": lib_track.get("id"),
                "track_number": t_track_num_int,
                "disc_number": t_disc,
                "library_title": lib_title,
                "mb_title": mb_title,
                "library_duration": _fmt_duration(lib_duration_sec),
                "mb_duration": _fmt_duration(mb_duration_sec),
                "mismatch_type": mismatch_type,
                "file_path": lib_track.get("file_path"),
                # Fields needed to add to queue
                "artist": artist,
                "album": album,
                "album_artist": artist,
                "year": mb_year,
                "release_id": mb_mbid,
            })

        return jsonify({
            "mismatches": mismatches,
            "mismatch_count": len(mismatches),
            "library_count": library_count,
        })
    except Exception as e:
        logging.error(f"[TITLE_MISMATCHES] Error for {artist}/{album}: {e}")
        return jsonify({"error": str(e), "mismatches": [], "mismatch_count": 0}), 500


@app.route("/api/artist/corrections-albums")
def api_artist_corrections_albums():
    """Return albums for an artist that have a MusicBrainz MBID, for the corrections page."""
    try:
        artist_name = request.args.get("artist", "").strip()
        if not artist_name:
            return jsonify({"error": "artist required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        try:
            cursor.execute(f"""
                SELECT album, COUNT(*) as track_count, MAX(musicbrainz_album_mbid) as mb_mbid
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
                  AND musicbrainz_album_mbid IS NOT NULL AND musicbrainz_album_mbid != ''
                GROUP BY album
            """, (artist_name,))
        except Exception:
            conn.close()
            return jsonify({"albums": []})

        albums = []
        for row in cursor.fetchall():
            row_dict = dict(row) if hasattr(row, "keys") else {"album": row[0], "track_count": row[1], "mb_mbid": row[2]}
            albums.append({
                "album": row_dict.get("album"),
                "track_count": int(row_dict.get("track_count") or 0),
                "mb_mbid": row_dict.get("mb_mbid"),
            })
        conn.close()
        return jsonify({"albums": albums})
    except Exception as e:
        logging.error(f"[CORRECTIONS_ALBUMS] Error: {e}")
        return jsonify({"error": str(e), "albums": []}), 500


# ---------------------------------------------------------------------------
# Global Tag Corrections (/correcting)
# ---------------------------------------------------------------------------

ALBUM_CONSISTENCY_FIELDS = [
    # ── Primary Navidrome split causes ────────────────────────────────────────
    # Navidrome groups tracks into albums using ALBUM + ALBUMARTIST. Inconsistencies
    # in these fields are the most common cause of "split album" problems.
    # See: https://www.navidrome.org/docs/usage/library/tagging/
    ('album_artist',         'Album Artist'),
    # When PID.Album="musicbrainz_albumid" is set in Navidrome config, tracks with
    # different MBIDs will always be treated as separate albums.
    ('musicbrainz_album_mbid', 'MusicBrainz Album ID'),
    ('musicbrainz_releasegroupid', 'MusicBrainz Release Group ID'),
    # ── Album classification tags ──────────────────────────────────────────────
    ('releasetype',          'Release Type'),
    ('releasestatus',        'Release Status'),
    ('releasecountry',       'Release Country'),
    # COMPILATION=1 is required for Navidrome to correctly group VA compilations
    # under "Various Artists" rather than splitting them.
    ('compilation',          'Compilation'),
    # ── Standard album-level tags ──────────────────────────────────────────────
    ('genres',               'Genre'),
    ('mood',                 'Mood'),
    ('year',                 'Year'),
    ('label',                'Label'),
    ('recordlabel',          'Record Label'),
    ('tracktotal',           'Track Total'),
    ('disctotal',            'Disc Total'),
    ('grouping',             'Grouping'),
    ('media',                'Media'),
    ('albumversion',         'Album Version'),
    ('discsubtitle',         'Disc Subtitle'),
    ('script',               'Script'),
    ('replaygain_album_gain','ReplayGain Album Gain'),
    ('replaygain_album_peak','ReplayGain Album Peak'),
]


def refresh_needs_correcting_flags(conn):
    """Update the needs_correcting flag on every track in the tracks table.

    Tracks that belong to an album with at least one album-level tag
    inconsistency across its tracks are flagged TRUE; all others are
    cleared to FALSE.

    Navidrome tagging guidelines (https://www.navidrome.org/docs/usage/library/tagging/):
      - ALBUM + ALBUMARTIST must be identical across all tracks on the same album.
      - For compilations/VA albums, ALBUMARTIST should be "Various Artists" and
        COMPILATION=1 must be set on every track.
      - For split releases (Band A / Band B), use a single ALBUMARTIST with both
        artists separated by a semicolon, or ensure MUSICBRAINZ_ALBUMID is the
        same on all tracks (when PID.Album="musicbrainz_albumid" is configured).
      - Inconsistent MUSICBRAINZ_ALBUMID values across tracks will cause Navidrome
        to treat them as separate albums when persistent IDs are enabled.
      - RELEASETYPE/RELEASESTATUS/RELEASECOUNTRY inconsistencies indicate different
        editions are mixed together and should be corrected.
    """
    try:
        cursor = conn.cursor()
        track_columns = _get_table_columns(cursor, 'tracks')
        has_album_artist = 'album_artist' in track_columns
        album_expr_t = "COALESCE(NULLIF(t.album_artist, ''), t.artist)" if has_album_artist else "t.artist"
        album_expr_t2 = "COALESCE(NULLIF(t2.album_artist, ''), t2.artist)" if has_album_artist else "t2.artist"
        effective_consistency_fields = [
            (field, label)
            for field, label in ALBUM_CONSISTENCY_FIELDS
            if field != 'album_artist' or has_album_artist
        ]

        # Build the HAVING clause that detects any album-level inconsistency
        having_parts = []
        for field, _ in effective_consistency_fields:
            having_parts.append(
                f"COUNT(DISTINCT COALESCE(CAST({field} AS TEXT), '')) > 1"
            )
        if not having_parts:
            return
        having_sql = " OR ".join(having_parts)

        # First: clear flag on all tracks that are now consistent
        cursor.execute("""
            UPDATE tracks
            SET needs_correcting = FALSE
            WHERE needs_correcting IS DISTINCT FROM FALSE
        """)

        # Then: set flag on tracks whose album has inconsistencies
        cursor.execute(f"""
            UPDATE tracks t
            SET needs_correcting = TRUE
            WHERE EXISTS (
                SELECT 1
                FROM tracks t2
                WHERE {album_expr_t2} = {album_expr_t}
                  AND t2.album = t.album
                  AND t2.album IS NOT NULL
                  AND TRIM(t2.album) != ''
                GROUP BY {album_expr_t2}, t2.album
                HAVING COUNT(*) >= 2 AND ({having_sql})
            )
        """)

        # Also flag tracks where releasecountry is set but differs from
        # the artist's known country (both values must be non-empty).
        cursor.execute("""
            UPDATE tracks
            SET needs_correcting = TRUE
            WHERE TRIM(COALESCE(releasecountry, '')) != ''
              AND TRIM(COALESCE(artist_country, ''))  != ''
              AND LOWER(TRIM(releasecountry)) != LOWER(TRIM(artist_country))
        """)
        conn.commit()
    except Exception as exc:
        logging.warning(f"[CORRECTING] refresh_needs_correcting_flags failed: {exc}")
        try:
            conn.rollback()
        except Exception:
            pass


def _ensure_correction_ignores_table(conn):
    """Create the correction_ignores table if it does not yet exist.

    Each row records a (album_artist, album, field) tuple that the user
    has chosen to suppress from the corrections page.
    """
    try:
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS correction_ignores (
                id          SERIAL PRIMARY KEY,
                album_artist TEXT NOT NULL DEFAULT '',
                album        TEXT NOT NULL,
                field        TEXT NOT NULL,
                ignored_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE (album_artist, album, field)
            )
        """)
        conn.commit()
    except Exception as e:
        logging.debug(f"[CORRECTION_IGNORES] Could not create table: {e}")
        try:
            conn.rollback()
        except Exception:
            pass


def _get_album_tag_inconsistencies(conn, artist_filter=None):
    """Return albums that have inconsistent album-level tag values across their tracks.

    Returns a list of dicts:
        {album_artist, album, track_count,
         inconsistencies: [{field, field_label, values: [{value, count, track_ids}]}]}
    """
    cursor = conn.cursor()
    track_columns = _get_table_columns(cursor, 'tracks')
    has_album_artist = 'album_artist' in track_columns
    artist_expr = "COALESCE(NULLIF(album_artist, ''), artist)" if has_album_artist else "artist"
    effective_consistency_fields = [
        (field, label)
        for field, label in ALBUM_CONSISTENCY_FIELDS
        if field != 'album_artist' or has_album_artist
    ]

    # Build per-field HAVING clauses
    having_parts = []
    for field, _ in effective_consistency_fields:
        having_parts.append(
            f"COUNT(DISTINCT COALESCE(CAST({field} AS TEXT), '')) > 1"
        )
    if not having_parts:
        return []
    having_sql = " OR ".join(having_parts)

    where_sql = "WHERE album IS NOT NULL AND TRIM(album) != ''"
    params: list = []
    if artist_filter:
        where_sql += f" AND {artist_expr} = %s"
        params.append(artist_filter)

    try:
        cursor.execute(f"""
            SELECT
                {artist_expr} AS album_artist,
                album,
                COUNT(*) AS track_count
            FROM tracks
            {where_sql}
            GROUP BY {artist_expr}, album
            HAVING COUNT(*) >= 2
              AND ({having_sql})
            ORDER BY {artist_expr}, album
        """, params or None)
        flagged_albums = cursor.fetchall()
    except Exception as e:
        logging.warning(f"[CORRECTING] Flagging query failed: {e}")
        return []

    # Load ignore rules once for all albums
    ignored_fields: set = set()  # set of (album_artist, album, field)
    try:
        cursor.execute(
            "SELECT album_artist, album, field FROM correction_ignores"
        )
        for ignore_row in cursor.fetchall():
            if hasattr(ignore_row, 'keys'):
                ignored_fields.add((ignore_row.get('album_artist') or '',
                                    ignore_row.get('album') or '',
                                    ignore_row.get('field') or ''))
            else:
                ignored_fields.add((ignore_row[0] or '', ignore_row[1] or '', ignore_row[2] or ''))
    except Exception:
        pass  # Table may not exist yet on very first run; silently skip

    results = []
    for row in flagged_albums:
        row_dict = dict(row) if hasattr(row, 'keys') else {
            'album_artist': row[0], 'album': row[1], 'track_count': row[2]
        }
        album_artist = row_dict.get('album_artist') or ''
        album = row_dict.get('album') or ''
        track_count = int(row_dict.get('track_count') or 0)

        # Detail query: get per-field value counts and track ids
        try:
            cursor.execute("""
                SELECT id, %s
                FROM tracks
                WHERE %s = %s
                  AND album = %s
            """ % (
                ', '.join(f for f, _ in effective_consistency_fields),
                artist_expr, '%s'
            ), (album_artist, album))
            detail_rows = cursor.fetchall()
        except Exception:
            continue

        col_names = ['id'] + [f for f, _ in effective_consistency_fields]
        inconsistencies = []
        for field, field_label in effective_consistency_fields:
            # Skip fields the user has chosen to ignore for this album
            if (album_artist, album, field) in ignored_fields:
                continue
            col_idx = col_names.index(field)
            value_map: dict = {}  # value → {count, track_ids}
            for dr in detail_rows:
                if hasattr(dr, 'keys'):
                    track_id = dr.get('id') or dr['id']
                    val = dr.get(field)
                else:
                    track_id = dr[0]
                    val = dr[col_idx]
                val_str = str(val).strip() if val is not None else ''
                if val_str not in value_map:
                    value_map[val_str] = {'value': val_str, 'count': 0, 'track_ids': []}
                value_map[val_str]['count'] += 1
                value_map[val_str]['track_ids'].append(track_id)

            # Only flag if there are 2+ distinct non-empty values
            non_empty = {v: d for v, d in value_map.items() if v != ''}
            if len(non_empty) >= 2:
                inconsistencies.append({
                    'field': field,
                    'field_label': field_label,
                    'values': sorted(non_empty.values(), key=lambda x: -x['count']),
                })

        if inconsistencies:
            results.append({
                'album_artist': album_artist,
                'album': album,
                'track_count': track_count,
                'inconsistencies': inconsistencies,
            })

    return results


def _get_country_mismatches(conn):
    """Return albums that have tracks whose releasecountry differs from the artist's country.

    Both releasecountry and artist_country must be non-empty for a mismatch to be
    reported.  Results are grouped by album and ordered by artist then album name.

    Returns a list of dicts:
        {album_artist, album, track_count, artist_country,
         release_countries: [{value, count, track_ids}]}
    """
    cursor = conn.cursor()
    track_columns = _get_table_columns(cursor, 'tracks')
    has_album_artist = 'album_artist' in track_columns
    artist_expr = "COALESCE(NULLIF(album_artist, ''), artist)" if has_album_artist else "artist"
    try:
        cursor.execute("""
            SELECT
                %s AS album_artist,
                album,
                artist_country,
                COUNT(*)                                   AS track_count
            FROM tracks
            WHERE album IS NOT NULL
              AND TRIM(album) != ''
              AND TRIM(COALESCE(releasecountry, ''))  != ''
              AND TRIM(COALESCE(artist_country, ''))  != ''
              AND LOWER(TRIM(releasecountry)) != LOWER(TRIM(artist_country))
            GROUP BY
                %s,
                album,
                artist_country
            ORDER BY
                %s,
                album
        """ % (artist_expr, artist_expr, artist_expr))
        rows = cursor.fetchall()
    except Exception as exc:
        logging.warning(f"[CORRECTING] country-mismatch query failed: {exc}")
        return []

    results = []
    for row in rows:
        row_dict = dict(row) if hasattr(row, 'keys') else {
            'album_artist': row[0], 'album': row[1],
            'artist_country': row[2], 'track_count': row[3],
        }
        album_artist  = row_dict.get('album_artist') or ''
        album         = row_dict.get('album') or ''
        artist_country = row_dict.get('artist_country') or ''
        track_count   = int(row_dict.get('track_count') or 0)

        # Detail: collect the distinct releasecountry values for this album
        try:
            cursor.execute("""
                SELECT id, releasecountry
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s
                  AND album = %s
                  AND TRIM(COALESCE(releasecountry, ''))  != ''
                  AND TRIM(COALESCE(artist_country, ''))  != ''
                  AND LOWER(TRIM(releasecountry)) != LOWER(TRIM(artist_country))
            """, (album_artist, album))
            detail_rows = cursor.fetchall()
        except Exception:
            continue

        value_map: dict = {}
        for dr in detail_rows:
            if hasattr(dr, 'keys'):
                track_id = dr.get('id') or dr['id']
                val = (dr.get('releasecountry') or '').strip()
            else:
                track_id = dr[0]
                val = (dr[1] or '').strip()
            if val not in value_map:
                value_map[val] = {'value': val, 'count': 0, 'track_ids': []}
            value_map[val]['count'] += 1
            value_map[val]['track_ids'].append(track_id)

        if not value_map:
            continue

        results.append({
            'album_artist':    album_artist,
            'album':           album,
            'track_count':     track_count,
            'artist_country':  artist_country,
            'release_countries': sorted(value_map.values(), key=lambda x: -x['count']),
        })

    return results


# Fields in ALBUM_CONSISTENCY_FIELDS that MusicBrainz can supply authoritatively
# from a single release lookup (inc=release-groups+labels).
_MB_SUGGESTION_FIELDS = {
    'year',
    'releasetype',
    'releasestatus',
    'releasecountry',
    'label',
    'recordlabel',
    'tracktotal',
    'disctotal',
    'compilation',
    'media',
    'script',
    'language',
}


def _fetch_mb_release_suggestions(release_mbid: str) -> dict:
    """Query MusicBrainz for a single release and return a dict of field→value
    covering the album-level tags that MB knows about.

    Uses a single API call with inc=release-groups+labels so it respects the
    MusicBrainz 1 req/sec rate limit from the calling thread.

    Returns an empty dict on any error or when the MBID is unknown.
    """
    if not release_mbid or not release_mbid.strip():
        return {}

    release_mbid = release_mbid.strip()
    MB_BASE = "https://musicbrainz.org/ws/2/"
    headers = {"User-Agent": MUSICBRAINZ_USER_AGENT, "Accept": "application/json"}

    def _get(url, params, timeout=12):
        time.sleep(1.0)   # honour MusicBrainz 1 req/sec policy
        r = requests.get(url, params=params, headers=headers, timeout=timeout)
        r.raise_for_status()
        return r.json()

    try:
        data = _get(
            f"{MB_BASE}release/{release_mbid}",
            {"fmt": "json", "inc": "release-groups+labels"},
        )
    except requests.HTTPError as exc:
        if exc.response is not None and exc.response.status_code == 404:
            # Might be a release-group MBID – browse its first release
            try:
                browse = _get(
                    f"{MB_BASE}release",
                    {"fmt": "json", "release-group": release_mbid,
                     "inc": "release-groups+labels", "limit": 1},
                )
                releases = browse.get("releases") or []
                if not releases:
                    return {}
                data = releases[0]
            except Exception:
                return {}
        else:
            return {}
    except Exception:
        return {}

    suggestions: dict = {}

    # Release-group data – needed for original date and release type.
    rg = data.get("release-group") or {}

    # Year – prefer the release-group's first-release-date (the year the album
    # originally came out) over the specific release's date so that a 2020
    # remastered reissue still reports the original release year, not 2020.
    original_date = (rg.get("first-release-date") or "").strip()
    release_date = (data.get("date") or "").strip()
    raw_date = original_date or release_date
    if raw_date:
        suggestions["year"] = raw_date[:4]

    # Release country
    country = (data.get("country") or "").strip()
    if country:
        suggestions["releasecountry"] = country

    # Release status (Official, Bootleg, Promotion, …)
    status = (data.get("status") or "").strip()
    if status:
        suggestions["releasestatus"] = status

    # Barcode / ASIN (not in ALBUM_CONSISTENCY_FIELDS but useful context)
    barcode = (data.get("barcode") or "").strip()
    if barcode:
        suggestions["barcode"] = barcode
    asin = (data.get("asin") or "").strip()
    if asin:
        suggestions["asin"] = asin

    # Language + Script (text-representation)
    text_rep = data.get("text-representation") or {}
    lang = (text_rep.get("language") or "").strip()
    if lang:
        suggestions["language"] = lang
    script = (text_rep.get("script") or "").strip()
    if script:
        suggestions["script"] = script

    # Release type from release-group (rg already extracted above)
    primary_type = (rg.get("primary-type") or "").strip()
    secondary_types = [t for t in (rg.get("secondary-types") or []) if t]
    if primary_type or secondary_types:
        all_types = ([primary_type] if primary_type else []) + secondary_types
        suggestions["releasetype"] = ", ".join(all_types)
        # Mark compilation flag
        if "Compilation" in secondary_types:
            suggestions["compilation"] = "1"

    # Label and catalog number from label-info
    label_info = data.get("label-info") or []
    if label_info:
        first = label_info[0]
        label_obj = first.get("label") or {}
        label_name = (label_obj.get("name") or "").strip()
        if label_name:
            suggestions["label"] = label_name
            suggestions["recordlabel"] = label_name
        cat = (first.get("catalog-number") or "").strip()
        if cat:
            suggestions["catalognumber"] = cat

    # Track and disc totals
    media_list = data.get("media") or []
    if media_list:
        suggestions["disctotal"] = str(len(media_list))
        total_tracks = sum(
            len(m.get("tracks") or []) or int(m.get("track-count") or 0)
            for m in media_list
        )
        if total_tracks:
            suggestions["tracktotal"] = str(total_tracks)
        # Media format – use first (or most common) disc format
        formats = [m.get("format") for m in media_list if m.get("format")]
        if formats:
            suggestions["media"] = formats[0]
        # Disc subtitles, if present
        disc_titles = [m.get("title") for m in media_list if m.get("title")]
        if len(disc_titles) == 1:
            suggestions["discsubtitle"] = disc_titles[0]

    return suggestions


@app.route("/correcting")
def correcting():
    """Global tag corrections page: albums with inconsistent album-level tags."""
    try:
        conn = get_db()
    except Exception as e:
        return render_template("correcting.html", inconsistencies=[], total=0,
                               page=1, per_page=50, total_pages=1, error=str(e))

    _ensure_correction_ignores_table(conn)

    page = max(1, int(request.args.get('page', 1)))
    per_page = 50
    try:
        all_inconsistencies = _get_album_tag_inconsistencies(conn)
    except Exception as e:
        logging.error(f"[CORRECTING] Error: {e}")
        all_inconsistencies = []
    finally:
        conn.close()

    total = len(all_inconsistencies)
    total_pages = max(1, (total + per_page - 1) // per_page)
    page = min(page, total_pages)
    start = (page - 1) * per_page
    paged = all_inconsistencies[start:start + per_page]

    return render_template(
        "correcting.html",
        inconsistencies=paged,
        total=total,
        page=page,
        per_page=per_page,
        total_pages=total_pages,
    )


@app.route("/api/correcting/fix-album-field", methods=["POST"])
def api_correcting_fix_album_field():
    """Apply a single field value to all tracks in an album."""
    try:
        payload = request.get_json(silent=True) or {}
        album_artist = (payload.get('album_artist') or '').strip()
        album = (payload.get('album') or '').strip()
        field = (payload.get('field') or '').strip()
        value = payload.get('value')

        if not album or not field:
            return jsonify({"success": False, "error": "album and field are required"}), 400

        # Validate field is in the allowed list
        allowed_fields = {f for f, _ in ALBUM_CONSISTENCY_FIELDS}
        if field not in allowed_fields:
            return jsonify({"success": False, "error": f"field '{field}' not allowed"}), 400

        conn = get_db()
        cursor = conn.cursor()

        try:
            cursor.execute(f"""
                UPDATE tracks
                SET {field} = %s
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s
                  AND album = %s
                RETURNING id, file_path
            """, (value, album_artist, album))
            affected = cursor.fetchall()
            conn.commit()
        except Exception as e:
            conn.rollback()
            conn.close()
            return jsonify({"success": False, "error": str(e)}), 500

        updated_count = len(affected)

        # Write tags to file for each affected track
        files_updated = 0
        for row in affected:
            row_dict = dict(row) if hasattr(row, 'keys') else {'id': row[0], 'file_path': row[1]}
            file_path = row_dict.get('file_path')
            if not file_path or not os.path.exists(str(file_path)):
                continue
            try:
                from helpers.tag_manager import update_file_tags
                update_file_tags(str(file_path), {field: value})
                files_updated += 1
            except Exception as tag_err:
                logging.debug(f"[CORRECTING] Could not update tag on {file_path}: {tag_err}")

        conn.close()
        return jsonify({
            "success": True,
            "updated_count": updated_count,
            "files_updated": files_updated,
        })
    except Exception as e:
        logging.error(f"[CORRECTING] fix-album-field error: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/correcting/mb-suggestions")
def api_correcting_mb_suggestions():
    """Fetch MusicBrainz authoritative values for a given album.

    Query params:
        album_artist  – album artist name
        album         – album title

    Returns JSON:
        {success: true, suggestions: {field: value, …}, mbid: "…"}
        or
        {success: false, error: "…"}

    Only fields in ALBUM_CONSISTENCY_FIELDS (plus a few extras like
    barcode/asin) are returned in the suggestions object.
    Fields that MB doesn't know are omitted.
    """
    album_artist = (request.args.get("album_artist") or "").strip()
    album        = (request.args.get("album")        or "").strip()

    if not album:
        return jsonify({"success": False, "error": "album is required"}), 400

    try:
        conn = get_db()
        cursor = conn.cursor()

        # Find the most commonly stored musicbrainz_albumid for this album
        cursor.execute("""
            SELECT musicbrainz_albumid
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist,''), artist) = %s
              AND album = %s
              AND musicbrainz_albumid IS NOT NULL
              AND TRIM(musicbrainz_albumid) != ''
            GROUP BY musicbrainz_albumid
            ORDER BY COUNT(*) DESC
            LIMIT 1
        """, (album_artist, album))
        row = cursor.fetchone()
        conn.close()
    except Exception as exc:
        logging.error(f"[CORRECTING] mb-suggestions DB error: {exc}")
        return jsonify({"success": False, "error": str(exc)}), 500

    if not row:
        return jsonify({"success": False, "error": "No MusicBrainz album ID found for this album"}), 404

    mbid = (dict(row) if hasattr(row, "keys") else {"musicbrainz_albumid": row[0]})["musicbrainz_albumid"]

    try:
        suggestions = _fetch_mb_release_suggestions(mbid)
    except Exception as exc:
        logging.error(f"[CORRECTING] _fetch_mb_release_suggestions error: {exc}")
        return jsonify({"success": False, "error": str(exc)}), 500

    if not suggestions:
        return jsonify({"success": False, "error": "MusicBrainz returned no usable data for this release"}), 404

    # Only expose fields that are in ALBUM_CONSISTENCY_FIELDS (or are catalogue
    # fields that the fix endpoint can apply), so the client doesn't receive
    # internal-only keys.
    allowed = {f for f, _ in ALBUM_CONSISTENCY_FIELDS} | {
        "catalognumber", "barcode", "asin", "language", "script",
        "discsubtitle",
    }
    filtered = {k: v for k, v in suggestions.items() if k in allowed}

    return jsonify({"success": True, "suggestions": filtered, "mbid": mbid})


# ---------------------------------------------------------------------------
# Artist Genre Management
# ---------------------------------------------------------------------------

def _parse_genres_string(s):
    """Parse a comma/backslash-separated genres string into a list."""
    if not s:
        return []
    return [g.strip() for g in re.split(r'[,\\]+', s) if g.strip()]


def _parse_json_genres(col):
    """Parse a JSON genre column (list of strings or list of dicts with 'name' key)."""
    if not col:
        return []
    try:
        data = json.loads(col) if isinstance(col, str) else col
        if not isinstance(data, list):
            return []
        result = []
        for item in data:
            if isinstance(item, str):
                result.append(item.strip())
            elif isinstance(item, dict):
                name = item.get("name") or item.get("tag") or ""
                if name:
                    result.append(str(name).strip())
        return [g for g in result if g]
    except Exception:
        return []


@app.route("/api/correcting/ignore", methods=["POST"])
def api_correcting_ignore():
    """Persist an ignore rule for a specific (album_artist, album, field) combination.

    Body JSON: {album_artist, album, field}
    The field entry is excluded from future corrections reports.
    """
    try:
        payload = request.get_json(silent=True) or {}
        album_artist = (payload.get('album_artist') or '').strip()
        album = (payload.get('album') or '').strip()
        field = (payload.get('field') or '').strip()

        if not album or not field:
            return api_fail("album and field are required")

        allowed_fields = {f for f, _ in ALBUM_CONSISTENCY_FIELDS}
        if field not in allowed_fields:
            return api_fail(f"field '{field}' is not a known corrections field")

        conn = get_db()
        _ensure_correction_ignores_table(conn)
        with conn:
            cursor = conn.cursor()
            cursor.execute("""
                INSERT INTO correction_ignores (album_artist, album, field)
                VALUES (%s, %s, %s)
                ON CONFLICT (album_artist, album, field) DO NOTHING
            """, (album_artist, album, field))
        conn.close()
        return api_ok()
    except Exception as e:
        logging.error(f"[CORRECTING] ignore error: {e}")
        return api_fail("Internal server error", status=500)


