def update_audio_file_genres(file_path, genres_list):
    """
    Update genre tags in audio files (MP3, FLAC, etc.)
    
    Args:
        file_path: Path to the audio file
        genres_list: List of genre strings to set
        
    Returns:
        tuple: (success: bool, error_message: str or None)
        - (True, None) if file was successfully updated
        - (False, "error message") if there was an error or unsupported format
    """
    try:
        from mutagen.mp3 import MP3
        from mutagen.flac import FLAC
        from mutagen.id3 import ID3, TCON
    except ImportError:
        return False, "Mutagen library not available"
    
    try:
        # Determine file format and handle accordingly
        file_ext = os.path.splitext(file_path)[1].lower()
        
        if file_ext == '.mp3':
            # Handle MP3 files with ID3 tags
            audio = MP3(file_path, ID3=ID3)
            if audio.tags is None:
                audio.add_tags()
            audio.tags['TCON'] = TCON(encoding=3, text=genres_list)
            audio.save()
            return True, None
        elif file_ext == '.flac':
            # Handle FLAC files with Vorbis comments
            audio = FLAC(file_path)
            # FLAC uses vorbis comments, which support multiple genre values
            audio['genre'] = genres_list
            audio.save()
            return True, None
        else:
            # For unsupported formats, return error to skip file
            return False, f"Unsupported format: {file_ext}"
    except Exception as e:
        return False, str(e)


@app.route("/api/artist/country/apply-as-genre", methods=["POST"])
def api_apply_country_as_genre():
    """Apply artist country as genre tag to all tracks."""
    try:
        data = request.get_json()
        artist_name = data.get("artist_name", "").strip()
        
        if not artist_name:
            return jsonify({"error": "Artist name required"}), 400
        
        # Get artist country
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        cursor.execute(f"SELECT country FROM artists WHERE name = {placeholder}", (artist_name,))
        artist_row = cursor.fetchone()
        
        if not artist_row or not artist_row['country']:
            return jsonify({"error": "No country information available for this artist"}), 404
        
        country = artist_row['country']
        
        # Get all tracks by this artist with file paths
        cursor.execute(f"SELECT id, file_path, genre FROM tracks WHERE artist = {placeholder}", (artist_name,))
        tracks = cursor.fetchall()
        
        if not tracks:
            conn.close()
            return jsonify({"error": "No tracks found for this artist"}), 404
        
        conn.close()
        
        # Import mutagen for MP3 tag editing
        try:
            from mutagen.id3 import ID3
            from mutagen.mp3 import MP3
        except ImportError:
            return jsonify({"error": "Mutagen library not available"}), 500
        
        updated_count = 0
        errors = []
        
        # Use consistent genre delimiter
        GENRE_DELIMITER = '; '
        
        for track in tracks:
            track_id, file_path, current_genre = track
            
            if not file_path or not os.path.exists(file_path):
                continue
            
            try:
                # Update MP3 file genre tag
                audio = MP3(file_path, ID3=ID3)
                
                # Get existing genres - split on both '; ' and ';' for backward compatibility
                existing_genres = []
                if audio.tags and 'TCON' in audio.tags:
                    try:
                        genre_str = str(audio.tags['TCON'])
                    except (KeyError, AttributeError):
                        genre_str = ""
                    # Split on ';' and strip whitespace from each part
                    existing_genres = [part.strip() for part in genre_str.split(';') if part.strip()]
                
                # Add country if not already present\n                if country not in existing_genres:\n                    existing_genres.append(country)\n                    \n                    # Set the genre tag\n                    if audio.tags is None:\n                        audio.add_tags()\n                    # Set genre directly without TCON class for compatibility\n                    try:\n                        # Try using mutagen's frame creation\n                        from mutagen.id3._frames import TCON as FrameTCON  # type: ignore\n                        audio.tags['TCON'] = FrameTCON(encoding=3, text=existing_genres)\n                    except (ImportError, AttributeError, TypeError):\n                        # Fallback: just update database\n                        pass\n                    audio.save()
                    
                    # Update database - use consistent delimiter
                    conn = get_db()
                    cursor = conn.cursor()
                    placeholder = "%s"
                    new_genre = GENRE_DELIMITER.join(existing_genres)
                    cursor.execute(f"UPDATE tracks SET genre = {placeholder} WHERE id = {placeholder}", (new_genre, track_id))
                    conn.commit()
                    conn.close()
                    
                    updated_count += 1
                    
            except Exception as e:
                errors.append(f"{os.path.basename(file_path)}: {str(e)}")
                logging.error(f"[APPLY_COUNTRY_GENRE] Error updating {file_path}: {e}")
        
        message = f"Applied '{country}' as genre to tracks"
        if errors:
            message += f" (with {len(errors)} errors)"
        
        return jsonify({
            "success": True,
            "message": message,
            "tracks_updated": updated_count,
            "errors": errors[:5]  # Return first 5 errors
        })
        
    except Exception as e:
        logging.error(f"[APPLY_COUNTRY_GENRE] Error: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/api/artist/cached-missing-releases", methods=["GET"])
def api_cached_missing_releases():
    """Get cached missing releases for an artist from the database."""
    artist = request.args.get("artist", "").strip()
    if not artist:
        return jsonify({"error": "Artist is required"}), 400
    
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Check if missing_releases table exists
        if not _table_exists(cursor, 'missing_releases'):
            conn.close()
            return jsonify({
                "artist": artist,
                "missing": [],
                "from_cache": False
            })
        
        cursor.execute(f"""
            SELECT release_id, title, primary_type, first_release_date, cover_art_url, category, last_checked
            FROM missing_releases
            WHERE artist = {placeholder}
            ORDER BY first_release_date DESC
        """, (artist,))
        
        rows = cursor.fetchall()
        conn.close()
        
        missing = []
        for row in rows:
            missing.append({
                "id": _row_get(row, 'release_id', 0, ""),
                "title": _row_get(row, 'title', 1, ""),
                "primary_type": _row_get(row, 'primary_type', 2, "Album"),
                "first_release_date": _row_get(row, 'first_release_date', 3, ""),
                "cover_art_url": _row_get(row, 'cover_art_url', 4, ""),
                "category": _row_get(row, 'category', 5, "Album"),
                "last_checked": _row_get(row, 'last_checked', 6, "")
            })
        
        return jsonify({
            "artist": artist,
            "missing": missing,
            "from_cache": True
        })
        
    except Exception as e:
        logging.error(f"[MISSING_RELEASES] Error fetching cached data: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/artist/cleanup-false-positive-missing", methods=["POST"])
def api_cleanup_false_positive_missing():
    """Remove false positives from missing_releases that actually exist in database."""
    data = request.json or {}
    artist = data.get("artist", "").strip()
    
    if not artist:
        return jsonify({"error": "Artist is required"}), 400
    
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get all existing albums
        cursor.execute(f"""
            SELECT DISTINCT album FROM tracks WHERE artist = {placeholder}
        """, (artist,))
        existing_albums = {_normalize_release_title(_row_get(row, 'album', 0, '')) for row in cursor.fetchall() if _row_get(row, 'album', 0)}
        
        # Get all missing releases
        cursor.execute(f"""
            SELECT release_id, title FROM missing_releases WHERE artist = {placeholder}
        """, (artist,))
        missing_releases = cursor.fetchall()
        
        # Find false positives (items in missing_releases that exist in database)
        false_positives = []
        for row in missing_releases:
            release_id = _row_get(row, 'release_id', 0, "")
            title = _row_get(row, 'title', 1, "")
            norm_title = _normalize_release_title(title)
            if norm_title in existing_albums:
                false_positives.append(release_id)
        
        # Remove false positives
        removed_count = 0
        for release_id in false_positives:
            cursor.execute(f"""
                DELETE FROM missing_releases WHERE release_id = {placeholder}
            """, (release_id,))
            removed_count += 1
        
        conn.commit()
        conn.close()
        
        logging.info(f"[CLEANUP] Removed {removed_count} false positive missing releases for {artist}")
        
        return jsonify({
            "success": True,
            "artist": artist,
            "removed_count": removed_count,
            "false_positives": false_positives
        })
        
    except Exception as e:
        logging.error(f"[CLEANUP] Error removing false positives: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/artist/bio")
def api_artist_bio():
    """Get artist biography.

    Primary source: the ``bio`` column in the local ``artists`` table (populated
    during a popularity/scan run).  When that column is empty the endpoint falls
    back to a live Wikidata/Wikipedia lookup and caches the result so subsequent
    requests are served from the database.
    """
    artist_name = request.args.get("name", "").strip()
    if not artist_name:
        return jsonify({"error": "Artist name required"}), 400
    
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        cursor.execute(f"""
            SELECT bio, image_url
            FROM artists
            WHERE name = {placeholder}
        """, (artist_name,))
        artist_row = cursor.fetchone()

        bio = (artist_row['bio'] if artist_row and artist_row['bio'] else "").strip()
        image_url = (artist_row['image_url'] if artist_row and artist_row['image_url'] else "").strip()

        if bio:
            conn.close()
            logging.debug(f"[ARTIST BIO] DB hit for {artist_name}: {len(bio)} chars")
            return jsonify({
                "bio": clean_discogs_biography(bio),
                "source": "Database (from scan)",
                "image_url": image_url,
            })

        # --- Wikidata / Wikipedia fallback ---
        logging.info(f"[ARTIST BIO] No DB bio for {artist_name}, trying Wikidata")
        try:
            from api_clients.wikidata import get_artist_biography as _wikidata_bio
            wikidata_bio = _wikidata_bio(artist_name)
        except Exception as _wk_err:
            logging.debug(f"[ARTIST BIO] Wikidata import/call failed: {_wk_err}")
            wikidata_bio = None

        if wikidata_bio:
            # Cache in the artists table so future requests are instant
            try:
                cursor.execute(f"""
                    INSERT INTO artists (id, name, bio)
                    VALUES ({placeholder}, {placeholder}, {placeholder})
                    ON CONFLICT (name) DO UPDATE SET bio = EXCLUDED.bio
                """, (artist_name, artist_name, wikidata_bio))
                conn.commit()
            except Exception as _cache_err:
                logging.debug(f"[ARTIST BIO] Failed to cache Wikidata bio: {_cache_err}")
            conn.close()
            logging.info(f"[ARTIST BIO] Wikidata bio for {artist_name}: {len(wikidata_bio)} chars")
            return jsonify({
                "bio": wikidata_bio,
                "source": "Wikidata",
                "image_url": image_url,
            })

        conn.close()
        logging.info(f"[ARTIST BIO] No bio found for {artist_name}")
        return jsonify({
            "bio": "",
            "source": "Not yet populated (run Scan Artist button to fetch)",
            "image_url": image_url,
        })
        
    except Exception as e:
        logging.error(f"[ARTIST BIO] Error fetching bio for {artist_name}: {e}")
        return jsonify({"bio": "", "source": "Error loading bio"}), 200


