@app.route("/api/album/search-art")
def api_album_search_art():
    """Search for album art on MusicBrainz, Discogs, Spotify, or Apple Music"""
    artist_name = request.args.get("artist", "").strip()
    album_name = request.args.get("album", "").strip()
    source = request.args.get("source", "musicbrainz").strip()
    
    if not artist_name or not album_name:
        return jsonify({"error": "Artist and album name required"}), 400
    
    logger = logging.getLogger('sptnr')
    try:
        images = []
        
        if source == "musicbrainz":
            import difflib as _difflib_art
            # Search release-groups using the correct field name for the endpoint.
            # Use "releasegroup:" for title matching and "artist:" for artist filtering.
            search_url = "https://musicbrainz.org/ws/2/release-group"
            params = {
                "query": f'releasegroup:"{album_name}" AND artist:"{artist_name}"',
                "fmt": "json",
                "limit": 20,
            }
            headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
            
            resp = requests.get(search_url, params=params, headers=headers, timeout=10)
            resp.raise_for_status()
            data = resp.json()
            
            logger.debug(f"MusicBrainz search returned {len(data.get('release-groups', []))} results")

            # Normalise helper for comparison
            def _norm_title(t):
                return re.sub(r"[^a-z0-9]", "", (t or "").lower())

            norm_album = _norm_title(album_name)

            for rg in data.get("release-groups", [])[:20]:
                rg_id = rg.get("id")
                if not rg_id:
                    continue

                rg_title = rg.get("title", "")
                # Skip results whose title is very dissimilar to the query to avoid
                # returning artwork for a completely different album.
                if norm_album:
                    ratio = _difflib_art.SequenceMatcher(
                        None, norm_album, _norm_title(rg_title)
                    ).ratio()
                    if ratio < 0.40:
                        logger.debug(
                            f"Skipping release-group '{rg_title}' (similarity {ratio:.2f} < 0.40)"
                        )
                        continue

                # The Cover Art Archive stores images per release, not per release-group.
                # Attempt front image for the release-group; if that fails, enumerate
                # individual releases within the group to find a cover.
                found_for_rg = False
                for image_format in ["front-500", "front-250", "front"]:
                    image_url = f"https://coverartarchive.org/release-group/{rg_id}/{image_format}"
                    try:
                        head_resp = requests.head(image_url, timeout=3, allow_redirects=True)
                        if head_resp.status_code == 200:
                            artist_display = (
                                rg.get("artist-credit", [{}])[0].get("name", "")
                                if rg.get("artist-credit")
                                else ""
                            )
                            images.append({
                                "url": image_url,
                                "source": "MusicBrainz CAA",
                                "title": rg_title,
                                "artist": artist_display,
                            })
                            found_for_rg = True
                            break
                    except Exception as e:
                        logger.debug(f"HEAD request failed for {image_url}: {e}")
                        continue

                if not found_for_rg:
                    # Fall back to individual releases within the group
                    try:
                        rg_detail_url = f"https://musicbrainz.org/ws/2/release-group/{rg_id}"
                        rg_detail_resp = requests.get(
                            rg_detail_url,
                            params={"fmt": "json", "inc": "releases"},
                            headers=headers,
                            timeout=5,
                        )
                        if rg_detail_resp.status_code == 200:
                            releases_in_group = rg_detail_resp.json().get("releases", [])
                            for rel in releases_in_group[:5]:
                                rel_id = rel.get("id")
                                if not rel_id:
                                    continue
                                rel_img_url = f"https://coverartarchive.org/release/{rel_id}/front-500"
                                try:
                                    rel_head = requests.head(rel_img_url, timeout=3, allow_redirects=True)
                                    if rel_head.status_code == 200:
                                        artist_display = (
                                            rg.get("artist-credit", [{}])[0].get("name", "")
                                            if rg.get("artist-credit")
                                            else ""
                                        )
                                        images.append({
                                            "url": rel_img_url,
                                            "source": "MusicBrainz CAA",
                                            "title": rg_title,
                                            "artist": artist_display,
                                        })
                                        found_for_rg = True
                                        break
                                except Exception:
                                    continue
                    except Exception as rg_detail_err:
                        logger.debug(f"Release-group detail fetch failed for {rg_id}: {rg_detail_err}")

        
        elif source == "discogs":
            # Search Discogs for release
            import difflib as _difflib_art_discogs
            from popularity import _discogs_search, _get_discogs_session
            
            config_data, _ = _read_yaml(CONFIG_PATH)
            discogs_config = config_data.get("api_integrations", {}).get("discogs", {})
            discogs_token = discogs_config.get("token", "")
            
            session = _get_discogs_session()
            headers = {"User-Agent": "Popularr/1.0"}
            if discogs_token:
                headers["Authorization"] = f"Discogs token={discogs_token}"

            def _norm_title_d(t):
                return re.sub(r"[^a-z0-9]", "", (t or "").lower())

            norm_album_d = _norm_title_d(album_name)

            # Search with album and artist - try different query formats
            for query in [f"{artist_name} {album_name}", f'"{album_name}" {artist_name}', album_name]:
                try:
                    logger.debug(f"Searching Discogs with query: {query}")
                    results = _discogs_search(session, headers, query, kind="release", per_page=15)
                    
                    for result in results[:15]:
                        if result.get("cover_image"):
                            # Filter out results that don't match the album title at all.
                            # Discogs returns a combined "Artist - Title" string in result["title"].
                            result_title_raw = result.get("title", "")
                            # Discogs title is often "Artist - Album"
                            result_album_part = result_title_raw.split(" - ", 1)[-1] if " - " in result_title_raw else result_title_raw
                            if norm_album_d:
                                ratio_d = _difflib_art_discogs.SequenceMatcher(
                                    None, norm_album_d, _norm_title_d(result_album_part)
                                ).ratio()
                                if ratio_d < 0.35:
                                    logger.debug(
                                        f"Skipping Discogs result '{result_title_raw}' "
                                        f"(similarity {ratio_d:.2f} < 0.35)"
                                    )
                                    continue
                            # Verify the image URL is valid
                            try:
                                img_resp = requests.head(result["cover_image"], timeout=3)
                                if img_resp.status_code == 200:
                                    images.append({
                                        "url": result["cover_image"],
                                        "source": "Discogs",
                                        "title": result_album_part,
                                        "artist": ", ".join([a.get("name", "") for a in result.get("artists", [])])
                                    })
                            except Exception as e:
                                logger.debug(f"Image verification failed for Discogs: {e}")
                                continue
                    
                    if images:
                        logger.debug(f"Found {len(images)} images on Discogs")
                        break  # Stop if we found images
                except Exception as e:
                    logger.debug(f"Discogs search with query '{query}' failed: {e}")
                    continue
        
        elif source == "applemusic":
            # Search Apple Music/iTunes for album
            from api_clients.applemusic import AppleMusicClient
            
            apple_music = AppleMusicClient()
            
            try:
                logger.debug(f"Searching Apple Music for album: {artist_name} - {album_name}")
                results = apple_music.search_album(album_name, artist_name, limit=15)
                
                for album in results:
                    artwork_url = album.get("artworkUrl100", "")
                    if artwork_url:
                        # Replace 100x100 with higher resolution
                        # iTunes URLs use /100x100bb. or /100x100. patterns before file extension
                        if "/100x100bb." in artwork_url:
                            artwork_url = artwork_url.replace("/100x100bb.", "/600x600bb.")
                        elif "/100x100." in artwork_url:
                            artwork_url = artwork_url.replace("/100x100.", "/600x600.")
                        
                        images.append({
                            "url": artwork_url,
                            "source": "Apple Music",
                            "title": album.get("collectionName", ""),
                            "artist": album.get("artistName", "")
                        })
                
                if images:
                    logger.debug(f"Found {len(images)} images on Apple Music")
            except Exception as e:
                logger.debug(f"Apple Music search failed: {e}")
        
        logger.info(f"Album art search for '{artist_name} - {album_name}' via {source}: {len(images)} images found")
        return jsonify({"images": images})
        
    except Exception as e:
        logger.error(f"Error searching album art: {e}")
        import traceback
        logger.error(traceback.format_exc())
        return jsonify({"error": str(e), "images": []}), 500


@app.route("/api/album/queue-status", methods=["GET"])
def api_album_queue_status():
    """Return the current download-queue status for every queued track in an album.

    Query params: artist, album
    Returns a mapping of track_id -> {queue_id, status, label, css, icon}
    so the album page can update its "In Queue" badges dynamically.
    """
    artist_name = request.args.get("artist", "").strip()
    album_name = request.args.get("album", "").strip()
    if not artist_name or not album_name:
        return jsonify({"error": "artist and album are required"}), 400

    try:
        from queue_status_constants import STATUS_DISPLAY_CONFIG, ACTIVE_QUEUE_STATUSES

        conn = get_db()
        cursor = conn.cursor()
        placeholder = get_placeholder(conn)

        # Find all track stubs that still carry a __queued_for_download__ marker for
        # this album so we know which queue items to look up.
        cursor.execute(
            f"""
            SELECT id, title, file_path
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
              AND album = {placeholder}
              AND file_path LIKE '__queued_for_download__%%'
            """,
            (artist_name, album_name),
        )
        queued_rows = cursor.fetchall()

        result = {}
        for row in queued_rows:
            is_dict = hasattr(row, 'keys')
            track_id = row['id'] if is_dict else row[0]
            file_path = (row['file_path'] if is_dict else row[2]) or ''

            # Extract queue_id from the file_path marker: __queued_for_download__queue_id_<N>
            queue_id = None
            if 'queue_id_' in file_path:
                try:
                    queue_id = int(file_path.split('queue_id_')[-1])
                except (ValueError, IndexError):
                    pass

            if queue_id is None:
                result[track_id] = {
                    "queue_id": None,
                    "status": "queued",
                    "label": "In Queue",
                    "css": "bg-warning text-dark",
                    "icon": "clock",
                }
                continue

            # Look up current status in download_queue
            cursor.execute(
                f"SELECT status FROM download_queue WHERE id = {placeholder}",
                (queue_id,),
            )
            dq_row = cursor.fetchone()
            if dq_row:
                status = (dq_row['status'] if hasattr(dq_row, 'keys') else dq_row[0]) or 'queued'
            else:
                status = 'queued'

            cfg = STATUS_DISPLAY_CONFIG.get(status, {})
            result[track_id] = {
                "queue_id": queue_id,
                "status": status,
                "label": cfg.get("label", status.capitalize()),
                "css": cfg.get("css", "bg-warning text-dark"),
                "icon": cfg.get("icon", "clock"),
            }

        conn.close()
        return jsonify({"success": True, "tracks": result})

    except Exception as e:
        logging.error(f"[ALBUM_QUEUE_STATUS] Error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/album/set-art", methods=["POST"])
def api_album_set_art():
    """Set custom album art from a URL – downloads the image and stores it in the database"""
    data = request.json or {}
    artist_name = data.get("artist", "").strip()
    album_name = data.get("album", "").strip()
    image_url = data.get("image_url", "").strip()

    if not artist_name or not album_name or not image_url:
        return jsonify({"error": "Artist, album name, and image URL required"}), 400

    # Validate that image_url is a valid HTTP/HTTPS URL, not a data URI or other scheme
    if not image_url.startswith(('http://', 'https://')):
        return jsonify({"error": "Image URL must be a valid HTTP or HTTPS URL"}), 400

    # Block SSRF: reject URLs resolving to private/loopback addresses
    try:
        from urllib.parse import urlparse as _up
        import ipaddress as _ipaddress
        import socket as _socket
        _parsed_url = _up(image_url)
        _hostname = _parsed_url.hostname or ""
        if not _hostname:
            return jsonify({"error": "Invalid URL: no hostname"}), 400
        # Reject obvious internal hostnames
        _lower_host = _hostname.lower()
        if _lower_host in ("localhost", "127.0.0.1", "::1") or _lower_host.endswith(".local"):
            return jsonify({"error": "Image URL hostname is not permitted"}), 400
        # Resolve and block private IP ranges
        try:
            _addr = _socket.getaddrinfo(_hostname, None)[0][4][0]
            _ip = _ipaddress.ip_address(_addr)
            if _ip.is_private or _ip.is_loopback or _ip.is_link_local or _ip.is_reserved:
                return jsonify({"error": "Image URL hostname is not permitted"}), 400
        except Exception:
            pass  # If resolution fails let requests handle the error
        # Reconstruct safe URL from parsed components to avoid tainted-URL attacks
        _safe_image_url = _up(image_url).geturl()
    except Exception:
        return jsonify({"error": "Invalid image URL"}), 400

    logger = logging.getLogger('sptnr')
    try:
        resp = requests.get(_safe_image_url, timeout=10, allow_redirects=True,
                            headers={"User-Agent": "sptnr/1.0 +https://github.com/M0VENTURA/sptnr"})
        if resp.status_code != 200 or not resp.content:
            return jsonify({"error": f"Could not download image: HTTP {resp.status_code}"}), 400

        mime_type = resp.headers.get("Content-Type", "image/jpeg").split(";")[0].strip()
        if not mime_type.startswith("image/"):
            return jsonify({"error": "URL did not return an image"}), 400

        saved = _save_album_art_to_db(artist_name, album_name, resp.content, source="manual", mime_type=mime_type)
        if not saved:
            return jsonify({"error": "Failed to save image to database"}), 500

        logger.info(f"Album art updated for '{artist_name} - {album_name}' from URL")
        return jsonify({"success": True, "message": "Album art updated"})

    except requests.exceptions.RequestException as e:
        logger.warning(f"Error downloading album art: {e}")
        return jsonify({"error": "Failed to download image from the provided URL"}), 400
    except Exception as e:
        logger.error(f"Error setting album art: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


@app.route("/api/album/upload-art", methods=["POST"])
def api_album_upload_art():
    """Set custom album art from a directly uploaded image file"""
    artist_name = request.form.get("artist", "").strip()
    album_name = request.form.get("album", "").strip()
    image_file = request.files.get("image")

    if not artist_name or not album_name:
        return jsonify({"error": "Artist and album name required"}), 400
    if not image_file or not image_file.filename:
        return jsonify({"error": "No image file provided"}), 400

    mime_type = image_file.mimetype or "image/jpeg"
    if not mime_type.startswith("image/"):
        return jsonify({"error": "Uploaded file must be an image"}), 400

    logger = logging.getLogger('sptnr')
    try:
        image_data = image_file.read()
        if not image_data:
            return jsonify({"error": "Uploaded image is empty"}), 400

        saved = _save_album_art_to_db(artist_name, album_name, image_data, source="manual_upload", mime_type=mime_type)
        if not saved:
            return jsonify({"error": "Failed to save image to database"}), 500

        logger.info(f"Album art uploaded for '{artist_name} - {album_name}'")
        return jsonify({"success": True, "message": "Album art uploaded"})

    except Exception as e:
        logger.error(f"Error uploading album art: {e}")
        return jsonify({"error": "An internal error occurred"}), 500


@app.route("/api/album/ignore-missing-track", methods=["POST"])
def api_album_ignore_missing_track():
    """Mark a persisted missing track as ignored so it no longer shows on the album page"""
    data = request.get_json(force=True, silent=True) or {}
    missing_track_id = data.get("id")
    artist = (data.get("artist") or "").strip()
    album_name = (data.get("album") or "").strip()
    title = (data.get("title") or "").strip()
    disc_number = int(data.get("disc_number") or 1)

    if not missing_track_id and not (artist and album_name and title):
        return jsonify({"error": "Provide id or (artist, album, title)"}), 400

    try:
        conn = get_db()
        cursor = conn.cursor()
        _ensure_missing_album_tracks_table(cursor)
        ph = "%s"
        if missing_track_id:
            cursor.execute(
                f"UPDATE missing_album_tracks SET ignored = TRUE WHERE id = {ph}",
                (missing_track_id,),
            )
        else:
            cursor.execute(
                f"UPDATE missing_album_tracks SET ignored = TRUE "
                f"WHERE artist_name = {ph} AND album_name = {ph} AND title = {ph} AND disc_number = {ph}",
                (artist, album_name, title, disc_number),
            )
        conn.commit()
        conn.close()
        return jsonify({"success": True})
    except Exception as e:
        logging.error(f"Error ignoring missing track: {e}")
        return jsonify({"error": str(e)}), 500


