@app.route("/api/artist/add", methods=["POST"])
def api_add_artist():
    """Manually add an artist and fetch all their releases from MusicBrainz."""
    data = request.json or {}
    artist_name = data.get("artist", "").strip()
    
    if not artist_name:
        return jsonify({"error": "Artist name is required"}), 400
    
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        # Check if artist already exists in tracks
        cursor.execute(f"SELECT COUNT(*) FROM tracks WHERE artist = {placeholder}", (artist_name,))
        result = cursor.fetchone()
        existing_count = result[0] if result else 0
        
        # Fetch all releases from MusicBrainz
        logging.info(f"[ADD_ARTIST] Fetching MusicBrainz releases for: {artist_name}")
        mb_releases = _fetch_musicbrainz_releases(artist_name, limit=200)
        
        if not mb_releases:
            conn.close()
            return jsonify({
                "error": f"No releases found on MusicBrainz for artist: {artist_name}",
                "artist": artist_name,
                "releases_found": 0
            }), 404
        
        # Get existing albums if artist exists
        existing_norm = set()
        if existing_count > 0:
            cursor.execute(f"SELECT DISTINCT album FROM tracks WHERE artist = {placeholder}", (artist_name,))
            existing_albums = [_row_get(row, "album", 0) for row in cursor.fetchall()]
            existing_norm = {_normalize_release_title(a) for a in existing_albums if a}
        
        # Add all releases to missing_releases table
        added_count = 0
        for rg in mb_releases:
            # Check if already exists in library
            norm_title = _normalize_release_title(rg.get("title") or "")
            if norm_title and norm_title in existing_norm:
                continue
            
            # Skip compilations
            secondary = [s.lower() for s in rg.get("secondary_types") or []]
            if "compilation" in secondary:
                continue
            
            # Determine category
            primary_type = (rg.get("primary_type") or "").lower()
            category = "Album"
            if primary_type == "ep":
                category = "EP"
            elif primary_type == "single" or "single" in secondary:
                category = "Single"
            
            # Insert into missing_releases with DB-aware upsert
            try:
                cursor.execute(
                    f"DELETE FROM missing_releases WHERE LOWER(artist) = LOWER({placeholder}) AND release_id = {placeholder}",
                    (artist_name, rg.get("id", ""))
                )
                cursor.execute("SELECT COALESCE(MAX(id), 0) + 1 AS next_id FROM missing_releases")
                next_id_row = cursor.fetchone()
                next_missing_release_id = int(next_id_row.get("next_id", 1)) if isinstance(next_id_row, dict) else int(next_id_row[0] if next_id_row else 1)
                cursor.execute(f"""
                    INSERT INTO missing_releases 
                    (id, artist, release_id, title, primary_type, first_release_date, cover_art_url, category, last_checked)
                    VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, CURRENT_TIMESTAMP)
                """, (
                    next_missing_release_id,
                    artist_name,
                    rg.get("id", ""),
                    rg.get("title", ""),
                    rg.get("primary_type", "Album"),
                    rg.get("first_release_date", ""),
                    rg.get("cover_art_url", ""),
                    category
                ))
                added_count += 1
            except Exception as e:
                logging.error(f"[ADD_ARTIST] Error inserting release {rg.get('title')}: {e}")
        
        conn.commit()
        
        # Create artist_stats entry if it doesn't exist (so artist appears on artists page)
        if existing_count == 0:
            cursor.execute(f"""
                INSERT INTO artist_stats 
                (artist_name, last_updated)
                VALUES ({placeholder}, CURRENT_TIMESTAMP)
                ON CONFLICT (artist_name) DO NOTHING
            """, (artist_name,))
            conn.commit()
        
        conn.close()
        
        logging.info(f"[ADD_ARTIST] Added {added_count} missing releases for {artist_name}")
        
        return jsonify({
            "success": True,
            "artist": artist_name,
            "releases_found": len(mb_releases),
            "added_to_missing": added_count,
            "already_in_library": len(existing_norm),
            "artist_exists": existing_count > 0
        })
        
    except Exception as e:
        logging.error(f"[ADD_ARTIST] Error adding artist {artist_name}: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/album/<path:artist>/<path:album>")
def album_detail(artist, album):
    """View album details and tracks"""
    try:
        # URL decode the artist and album names
        from urllib.parse import unquote
        artist = unquote(artist)
        album = unquote(album)
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Query by COALESCE(album_artist, artist) to match how artists are listed
        # Use NULLIF to treat empty strings as NULL for proper COALESCE behavior
        # Try both COALESCE and plain artist for backwards compatibility with old links
        placeholder = "%s"
        collate_nocase = ""
        tracks_data = None
        for artist_clause in ["COALESCE(NULLIF(album_artist, ''), artist)", "artist"]:
            cursor.execute(f"""
                SELECT *
                FROM tracks
                WHERE {artist_clause} = {placeholder}
                  AND LOWER(COALESCE(album, '')) = LOWER({placeholder})
                ORDER BY COALESCE(disc_number, 1), COALESCE(track_number, 999), title{collate_nocase}
            """, (artist, album))
            tracks_data = cursor.fetchall()
            if tracks_data:
                break
        
        if not tracks_data:
            return render_template("album.html",
                                 artist_name=artist,
                                 album_name=album,
                                 tracks=[],
                                 tracks_by_disc={},
                                 album_data=None,
                                 album_genres=[],
                                 qbit_config={"enabled": False, "web_url": "http://localhost:8080"},
                                 slskd_config={"enabled": False},
                                 error="Album not found")
        
        # Check favourite status for this album
        is_album_favourite = False
        try:
            cursor.execute(f"""
                SELECT 1
                FROM bookmarks
                WHERE type = {placeholder}
                  AND LOWER(COALESCE(artist, '')) = LOWER({placeholder})
                  AND LOWER(COALESCE(album, '')) = LOWER({placeholder})
                LIMIT 1
            """, ("album", artist, album))
            is_album_favourite = cursor.fetchone() is not None
        except Exception as fav_err:
            logging.debug(f"Album favourite check failed for {artist} - {album}: {fav_err}")

        # Get album metadata from first track
        try:
            cursor.execute(f"""
                SELECT 
                    COUNT(*) as track_count,
                    AVG(stars) as avg_stars,
                    SUM(COALESCE(duration, 0)) as total_duration,
                    MAX(spotify_release_date) as spotify_release_date,
                    MAX(spotify_album_type) as spotify_album_type,
                    MAX(spotify_album_art_url) as spotify_album_art_url,
                    MAX(last_scanned) as last_scanned,
                    MAX(COALESCE(disc_number, 1)) as total_discs,
                    MAX(musicbrainz_album_mbid) as musicbrainz_album_mbid,
                    COALESCE(MAX(discogs_album_id), MAX(discogs_release_id)) as discogs_album_id,
                    MAX(spotify_album_id) as spotify_album_id,
                    MAX(spotify_artist_id) as spotify_artist_id,
                    MAX(discogs_artist_id) as discogs_artist_id,
                    MAX(COALESCE(NULLIF(recordlabel, ''), NULLIF(label, ''))) as record_label,
                    MAX(catalognumber) as catalog_number
                FROM tracks
                                WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
                                    AND LOWER(COALESCE(album, '')) = LOWER({placeholder})
            """, (artist, album))
        except:
            # Fallback for databases without beets columns or album_artist column
            cursor.execute(f"""
                SELECT 
                    COUNT(*) as track_count,
                    AVG(stars) as avg_stars,
                    SUM(COALESCE(duration, 0)) as total_duration,
                    MAX(spotify_release_date) as spotify_release_date,
                    MAX(spotify_album_type) as spotify_album_type,
                    MAX(spotify_album_art_url) as spotify_album_art_url,
                    MAX(last_scanned) as last_scanned,
                    MAX(COALESCE(disc_number, 1)) as total_discs,
                    NULL as musicbrainz_album_mbid,
                    NULL as discogs_album_id,
                    NULL as spotify_album_id,
                    NULL as spotify_artist_id,
                    NULL as discogs_artist_id,
                    NULL as record_label,
                    NULL as catalog_number
                FROM tracks
                                WHERE COALESCE(album_artist, artist) = {placeholder}
                                    AND LOWER(COALESCE(album, '')) = LOWER({placeholder})
            """, (artist, album))
        album_data = cursor.fetchone()
        
        # Convert to dict if it's a Row object
        if album_data:
            album_data = dict(album_data)
        else:
            album_data = {
                'track_count': 0,
                'avg_stars': 0,
                'total_duration': 0,
                'spotify_release_date': None,
                'spotify_album_type': None,
                'spotify_album_art_url': None,
                'last_scanned': None,
                'total_discs': 1,
                'record_label': None,
                'catalog_number': None,
            }
        
        # Count singles in this album (based on is_single from single detection)
        cursor.execute("""
            SELECT COUNT(*) as singles_count
            FROM tracks
                        WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s
                            AND LOWER(COALESCE(album, '')) = LOWER(%s)
                            AND is_single = TRUE
        """, (artist, album))
        singles_row = cursor.fetchone()
        album_data['singles_count'] = singles_row['singles_count'] if singles_row else 0
        
        # Aggregate genres from tracks in this album - use navidrome_genres which comes from Navidrome
        cursor.execute(f"""
            SELECT DISTINCT navidrome_genres FROM tracks
                        WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
                            AND LOWER(COALESCE(album, '')) = LOWER({placeholder})
                            AND navidrome_genres IS NOT NULL AND navidrome_genres != ''
        """, (artist, album))
        genre_rows = cursor.fetchall()
        album_genres = set()
        for row in genre_rows:
            try:
                genre_value = row['navidrome_genres'] if isinstance(row, dict) else row[0]
                if genre_value:
                    # Split on both backslash (Navidrome) and comma (user-entered)
                    genres = [g.strip() for g in genre_value.replace('\\', ',').split(',') if g.strip()]
                    album_genres.update(genres)
            except (KeyError, IndexError, TypeError) as e:
                logging.debug(f"Error parsing genre row: {e}")
                continue
        
        # Calculate genre fit for each track
        tracks_with_genre_fit = []
        for track in tracks_data:
            try:
                # Convert Row to dict if needed
                if hasattr(track, 'keys'):
                    track_dict = dict(track)
                else:
                    # Already a dict or tuple, try to convert
                    track_dict = track if isinstance(track, dict) else dict(track)
                
                # Parse track's genres - use navidrome_genres which comes from Navidrome
                track_genres = set()
                if track_dict.get('navidrome_genres'):
                    # navidrome_genres uses backslash separator, handle that
                    if isinstance(track_dict['navidrome_genres'], str):
                        # Split on both backslash and comma to handle both formats
                        track_genres.update([g.strip() for g in track_dict['navidrome_genres'].replace('\\', ',').replace('•', ',').split(',') if g.strip()])
                    elif isinstance(track_dict['navidrome_genres'], list):
                        # If it's already a list, just use it
                        track_genres.update(track_dict['navidrome_genres'])
                
                # Calculate how many album genres this track contains
                genre_matches = len(track_genres & album_genres) if album_genres else 0
                genre_fit_percent = int((genre_matches / len(album_genres) * 100) if album_genres else 0)
                
                track_dict['genre_matches'] = genre_matches
                track_dict['genre_fit_percent'] = genre_fit_percent
                track_dict['matching_genres'] = sorted(list(track_genres & album_genres))
                
                tracks_with_genre_fit.append(track_dict)
            except Exception as e:
                logging.debug(f"Error calculating genre fit: {e}")
                track_dict = dict(track) if hasattr(track, 'keys') else track
                if not isinstance(track_dict, dict):
                    track_dict = {'title': str(track)}
                track_dict['genre_matches'] = 0
                track_dict['genre_fit_percent'] = 0
                track_dict['matching_genres'] = []
                tracks_with_genre_fit.append(track_dict)

        # Ensure stable numeric track ordering on album pages.
        # track_number may be stored as TEXT (e.g., "1/12"), so SQL lexical ordering
        # can misorder values like 10 before 2.
        def _album_track_sort_key(track_dict):
            try:
                disc_raw = track_dict.get('disc_number') if isinstance(track_dict, dict) else 1
                disc_num = int(disc_raw) if disc_raw not in (None, "") else 1
            except Exception:
                disc_num = 1

            track_raw = track_dict.get('track_number') if isinstance(track_dict, dict) else None
            track_str = str(track_raw).strip() if track_raw not in (None, "") else ""

            # Parse first numeric component from values like "01", "1/12", "A1".
            track_num = 999999
            if track_str:
                try:
                    match = re.search(r"(\d+)", track_str)
                    if match:
                        track_num = int(match.group(1))
                except Exception:
                    pass

            title = ""
            if isinstance(track_dict, dict):
                title = (track_dict.get('title') or "").lower()

            return (disc_num, track_num, track_str.lower(), title)

        tracks_with_genre_fit = sorted(tracks_with_genre_fit, key=_album_track_sort_key)

        # Load persisted missing tracks from the database and merge them in so they
        # survive page refreshes without requiring another MusicBrainz comparison.
        try:
            conn_mt = get_db()
            cursor_mt = conn_mt.cursor()
            ph_mt = "%s"
            _ensure_missing_album_tracks_table(cursor_mt)
            cursor_mt.execute(
                f"SELECT id, title, track_number, disc_number, track_artist, year, "
                f"release_id, recording_mbid, duration "
                f"FROM missing_album_tracks "
                f"WHERE LOWER(artist_name) = LOWER({ph_mt}) AND LOWER(album_name) = LOWER({ph_mt}) "
                f"AND ignored = FALSE "
                f"ORDER BY disc_number, track_number",
                (artist, album),
            )
            for mt_row in cursor_mt.fetchall():
                mt = dict(mt_row) if hasattr(mt_row, "keys") else {
                    "id": mt_row[0], "title": mt_row[1], "track_number": mt_row[2],
                    "disc_number": mt_row[3], "track_artist": mt_row[4], "year": mt_row[5],
                    "release_id": mt_row[6], "recording_mbid": mt_row[7], "duration": mt_row[8],
                }
                tracks_with_genre_fit.append({
                    "is_missing": True,
                    "missing_track_id": mt.get("id"),
                    "title": mt.get("title", ""),
                    "track_number": mt.get("track_number"),
                    "disc_number": mt.get("disc_number") or 1,
                    "artist": mt.get("track_artist") or artist,
                    "album_artist": artist,
                    "album": album,
                    "year": mt.get("year") or "",
                    "release_id": mt.get("release_id") or "",
                    "recording_mbid": mt.get("recording_mbid") or "",
                    "duration": mt.get("duration"),
                    "_mb_diff_items": [],
                    "_mb_comp_json": "",
                })
            conn_mt.close()
            # Re-sort to interleave missing tracks at the right positions
            tracks_with_genre_fit = sorted(tracks_with_genre_fit, key=_album_track_sort_key)
        except Exception as _mt_err:
            logging.debug(f"Could not load persisted missing tracks: {_mt_err}")


        # Pre-compute MusicBrainz pending update banner data from the stored
        # pending_mb_updates JSON so banners are rendered server-side and survive
        # page refreshes without requiring another round-trip to MusicBrainz.
        import json as _json_local
        import html as _html_mod
        for _td in tracks_with_genre_fit:
            _raw = _td.get('pending_mb_updates')
            if _raw:
                try:
                    _comp = _json_local.loads(_raw)

                    # Track is marked as extra (not part of MB release) — show badge only.
                    if _comp.get('is_extra'):
                        _td['_mb_is_extra'] = True
                        _td['_mb_diff_items'] = []
                        _td['_mb_comp_json'] = ''
                        continue

                    _td['_mb_is_extra'] = False
                    _diff_fields = _comp.get('diff_fields', [])

                    # Filter out permanently-ignored fields for this track
                    _raw_ignored = _td.get('mb_ignored_fields') or '[]'
                    try:
                        _ignored_set = set(_json_local.loads(_raw_ignored))
                    except Exception:
                        _ignored_set = set()
                    _diff_fields = [f for f in _diff_fields if f not in _ignored_set]

                    # Skip title rename if the only difference is a "(Artist Cover)" suffix
                    if 'title' in _diff_fields:
                        _lib_title = _comp.get('library_title', '')
                        _mb_title = _comp.get('mb_title', '')
                        if re.search(r'\([^)]*\bcover\b[^)]*\)', _lib_title, re.IGNORECASE):
                            _stripped = re.sub(r'\s*\([^)]*\bcover\b[^)]*\)', '', _lib_title, flags=re.IGNORECASE).strip()
                            if _stripped.lower() == _mb_title.lower():
                                _diff_fields = [f for f in _diff_fields if f != 'title']

                    # Build per-field items list used to render one row per change
                    _items = []
                    if 'title' in _diff_fields:
                        _items.append({
                            'field': 'title',
                            'html': _html_mod.escape(
                                f"Title: {_comp.get('library_title', '')} \u2192 {_comp.get('mb_title', '')}"
                            ),
                        })
                    if 'track_number' in _diff_fields:
                        _items.append({
                            'field': 'track_number',
                            'html': _html_mod.escape(
                                f"Track#: {_comp.get('library_track_number', '?')} \u2192 {_comp.get('mb_track_number', '?')}"
                            ),
                        })
                    if 'year' in _diff_fields:
                        _items.append({
                            'field': 'year',
                            'html': _html_mod.escape(
                                f"Year: {_comp.get('library_year', '—')} \u2192 {_comp.get('mb_year', '')}"
                            ),
                        })
                    if 'mbid' in _diff_fields:
                        _items.append({
                            'field': 'mbid',
                            'html': _html_mod.escape("MusicBrainz ID: missing \u2192 added"),
                        })
                    if 'duration' in _diff_fields:
                        _items.append({
                            'field': 'duration',
                            'html': _html_mod.escape(
                                f"Length: {_comp.get('library_duration', '—')} \u2192 {_comp.get('mb_duration', '—')}"
                            ),
                        })
                    if 'disc_number' in _diff_fields:
                        if _comp.get('cross_disc_match'):
                            _html_disc = _html_mod.escape(
                                f"Move to Disc {_comp.get('mb_disc_number', '')} (track {_comp.get('mb_track_number', '?')})"
                            )
                        else:
                            _html_disc = _html_mod.escape(
                                f"Disc: {_comp.get('library_disc_number', 1)} \u2192 {_comp.get('mb_disc_number', '')}"
                            )
                        _items.append({
                            'field': 'disc_number',
                            'html': _html_disc,
                        })

                    if _items:
                        _td['_mb_diff_items'] = _items
                        _td['_mb_comp_json'] = _raw
                    else:
                        _td['_mb_diff_items'] = []
                        _td['_mb_comp_json'] = ''
                except Exception:
                    _td['_mb_is_extra'] = False
                    _td['_mb_diff_items'] = []
                    _td['_mb_comp_json'] = ''
            else:
                _td['_mb_is_extra'] = False
                _td['_mb_diff_items'] = []
                _td['_mb_comp_json'] = ''

        # If album-level IDs are missing, infer from track-level IDs in this album.
        def _infer_album_id_from_tracks(rows, key_name):
            counts = {}
            for row in rows:
                if not isinstance(row, dict):
                    continue
                value = str(row.get(key_name) or "").strip()
                if not value:
                    continue
                counts[value] = counts.get(value, 0) + 1
            if not counts:
                return None
            return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[0][0]

        if not album_data.get('musicbrainz_album_mbid'):
            album_data['musicbrainz_album_mbid'] = _infer_album_id_from_tracks(
                tracks_with_genre_fit,
                'musicbrainz_album_mbid'
            )

        if not album_data.get('discogs_album_id'):
            inferred_discogs = _infer_album_id_from_tracks(tracks_with_genre_fit, 'discogs_album_id')
            if not inferred_discogs:
                inferred_discogs = _infer_album_id_from_tracks(tracks_with_genre_fit, 'discogs_release_id')
            album_data['discogs_album_id'] = inferred_discogs

        # Avoid external metadata lookups on album page load.
        # Missing-track enrichment via MusicBrainz should run in background metadata scans.


        tracks_by_disc = {}
        for track_dict in tracks_with_genre_fit:
            try:
                disc_num = track_dict.get('disc_number') if isinstance(track_dict, dict) else (track_dict['disc_number'] if hasattr(track_dict, '__getitem__') else 1)
                disc_num = disc_num or 1
                
                if disc_num not in tracks_by_disc:
                    tracks_by_disc[disc_num] = []
                tracks_by_disc[disc_num].append(track_dict)
            except Exception as e:
                logging.debug(f"Error processing track for disc grouping: {e}")
                # Fallback to disc 1
                if 1 not in tracks_by_disc:
                    tracks_by_disc[1] = []
                tracks_by_disc[1].append(track_dict)
        
        # Get the actual artist name from the database (from first track)
        # This ensures the form is populated with the actual database value, not the URL value
        # which might have encoding issues
        # Note: tracks_with_genre_fit contains dictionaries (converted from Row objects above)
        db_artist_name = artist  # default to URL parameter
        db_album_name = album    # default to URL parameter
        if tracks_with_genre_fit:
            first_track = tracks_with_genre_fit[0]
            # Use album_artist if available, otherwise use artist
            db_artist_name = first_track.get('album_artist') or first_track.get('artist') or artist
            db_album_name = first_track.get('album') or album
        
        conn.close()

        # Fetch artist MBID for the album from tracks (used to pre-fill Edit Album form)
        album_artist_mbid = None
        try:
            conn2 = get_db()
            cursor2 = conn2.cursor()
            placeholder2 = "%s"
            cursor2.execute(
                f"SELECT MAX(COALESCE(NULLIF(musicbrainz_artist_id, ''), NULLIF(musicbrainz_artistid, ''))) AS mbid"
                f" FROM tracks"
                f" WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder2}"
                f" AND LOWER(COALESCE(album, '')) = LOWER({placeholder2})",
                (db_artist_name, db_album_name),
            )
            _mbid_row = cursor2.fetchone()
            if _mbid_row:
                album_artist_mbid = (_mbid_row.get("mbid") if hasattr(_mbid_row, "get") else _mbid_row[0]) or None
            conn2.close()
        except Exception as _mbid_err:
            logging.debug(f"Could not fetch artist MBID for album edit form: {_mbid_err}")
        
        # Compute genre sources for server-side rendering (from DB data populated during scans)
        # Genres are only fetched from external sources (Spotify, Last.fm, etc.) during the
        # popularity/singles scan and saved to the database. Pre-rendering avoids AJAX on page open.
        genre_sources = {}
        try:
            genre_sources = get_album_genres_summary(tracks_with_genre_fit, limit=25)
        except Exception as e:
            logging.debug(f"Error computing genre sources for album page: {e}")
        
        # Get qBittorrent and slskd config
        cfg = get_config()
        qbit_config = cfg.get("qbittorrent", {"enabled": False, "web_url": "http://localhost:8080"})
        slskd_config = cfg.get("slskd", {"enabled": False})
        
        return render_template("album.html",
                             artist_name=db_artist_name,
                             album_name=db_album_name,
                             tracks=tracks_with_genre_fit,
                             tracks_by_disc=tracks_by_disc,
                             album_data=album_data,
                             album_genres=sorted(list(album_genres)),
                             genre_sources=genre_sources,
                             is_album_favourite=is_album_favourite,
                             qbit_config=qbit_config,
                             slskd_config=slskd_config,
                             album_artist_mbid=album_artist_mbid)
    except Exception as e:
        import traceback
        logging.error(f"Error loading album {artist}/{album}: {e}")
        logging.error(traceback.format_exc())
        
        # Get config even for error page
        try:
            cfg = get_config()
            qbit_config = cfg.get("qbittorrent", {"enabled": False, "web_url": "http://localhost:8080"})
            slskd_config = cfg.get("slskd", {"enabled": False})
        except:
            qbit_config = {"enabled": False, "web_url": "http://localhost:8080"}
            slskd_config = {"enabled": False}
        
        return render_template("album.html",
                             artist_name=artist,
                             album_name=album,
                             tracks=[],
                             tracks_by_disc={},
                             album_data=None,
                             album_genres=[],
                             is_album_favourite=False,
                             qbit_config=qbit_config,
                             slskd_config=slskd_config,
                             error=f"Error loading album: {str(e)}")


def _run_artist_scan_pipeline(artist_name: str, force: bool = False):
    """
    Helper function to run the complete scan pipeline for an artist:
    1. Navidrome import (imports metadata from Navidrome)
    2. Popularity detection (Spotify, Last.fm, ListenBrainz) + Singles detection + Star rating
    3. Essentia mood/genre scan (local ML scan for this artist)
    
    All steps log to unified_scan.log and Recent Scans page.
    This is used by artist scan, album rescan, and track rescan routes.
    
    Note: Album-level rescans remain force=True in the album pipeline.
    """
    # Write to file immediately to confirm function is called
    try:
        with open('/tmp/artist_scan_debug.log', 'a') as f:
            f.write(f"{datetime.now()}: _run_artist_scan_pipeline called for {artist_name}\n")
    except:
        pass
    
    log_unified(f"🎤 Artist scan pipeline started for: {artist_name}")
    try:
        log_unified(f"Force rescan: {force}")
        
        # Look up artist_id from cache; rebuild index if missing
        log_unified(f"Looking up artist_id for '{artist_name}' in database...")
        conn = get_db()
        try:
            cursor = conn.cursor()
            placeholder = "%s"
            cursor.execute(f"SELECT artist_id FROM artist_stats WHERE artist_name = {placeholder}", (artist_name,))
            row = cursor.fetchone()
            artist_id = row['artist_id'] if row else None
            log_unified(f"Database lookup result: artist_id={artist_id}")
        finally:
            conn.close()

        if not artist_id:
            log_unified(f"Artist ID not found in cache, rebuilding artist index...")
            idx = build_artist_index()
            artist_data = idx.get(artist_name, {})
            artist_id = artist_data.get("id") if artist_data else None
            log_unified(f"After index rebuild: artist_id={artist_id}")

        # If still no artist_id, check if this is a track artist (not an album artist)
        # Track artists appear in tracks.artist but not in artist_stats (which only has album artists)
        if not artist_id:
            log_unified(f"Artist not found as album artist, checking if track artist exists in database...")
            track_count = 0  # Initialize to avoid NameError if query fails
            conn = get_db()
            try:
                cursor = conn.cursor()
                placeholder = "%s"
                cursor.execute(f"SELECT COUNT(*) as cnt FROM tracks WHERE artist = {placeholder}", (artist_name,))
                result = cursor.fetchone()
                track_count = result['cnt'] if result else 0
                log_unified(f"Found {track_count} tracks for '{artist_name}'")
            finally:
                conn.close()
            
            if track_count == 0:
                log_unified(f"❌ Scan aborted: no tracks found for '{artist_name}' - artist does not exist in library")
                return
            
            # Artist exists as track artist only
            # Skip Navidrome track import (tracks already imported via album artist)
            # But still fetch artist-level metadata (bio, images) from external APIs
            log_unified(f"Artist '{artist_name}' is a track artist (e.g., from Various Artists albums)")
            log_unified(f"Step 1/3: Fetching artist metadata for track artist '{artist_name}'")
            try:
                from helpers.scan_helpers import fetch_artist_metadata
                fetch_artist_metadata(artist_name, verbose=True)
                log_unified(f"Artist metadata fetched successfully")
            except ImportError as e:
                log_unified(f"Warning: Artist metadata fetch not available: {e}")
            except Exception as e:
                log_unified(f"Warning: Failed to fetch artist metadata: {e}")
            log_unified(f"Step 2/3: Running popularity scan for track artist '{artist_name}' (force={force})")
            popularity_scan(verbose=True, force=force, artist_filter=artist_name)
            log_unified(f"Step 2b/3: Running metadata enrichment scan for track artist '{artist_name}'")
            popularity_scan(verbose=True, force=force, artist_filter=artist_name, metadata_only=True)
        else:
            # Normal flow: artist_id found, run both steps
            # Step 1: Import metadata from Navidrome for this artist
            log_unified(f"Step 1/3: Navidrome import for artist '{artist_name}' (force={force})")
            scan_artist_to_db(artist_name, artist_id, verbose=True, force=force)

            # Step 2: Run popularity scan for this artist (includes singles detection and star rating)
            log_unified(f"Step 2/3: Running popularity scan for artist '{artist_name}' (force={force})")
            popularity_scan(verbose=True, force=force, artist_filter=artist_name)
            log_unified(f"Step 2b/3: Running metadata enrichment scan for artist '{artist_name}'")
            popularity_scan(verbose=True, force=force, artist_filter=artist_name, metadata_only=True)

        # Step 3: Run Essentia mood/genre scan for this artist
        log_unified(f"Step 3/3: Running Essentia scan for artist '{artist_name}' (force={force})")
        try:
            from essentia_mood_scan import run_essentia_mood_scan
            from helpers.config_helpers import get_config
            cfg = get_config()
            essentia_cfg = cfg.get("essentia", {}) if isinstance(cfg, dict) else {}
            script_path = essentia_cfg.get("script_path", "")
            if not script_path:
                log_unified(f"Essentia scan skipped: script_path not configured")
            else:
                models_dir = essentia_cfg.get("models_dir", "")
                mood_threshold = float(essentia_cfg.get("mood_threshold", 0.005))
                per_file_timeout = int(essentia_cfg.get("per_file_timeout", 300))
                tag_genres = bool(essentia_cfg.get("tag_genres", False))
                num_genres = int(essentia_cfg.get("num_genres", 3))
                genre_threshold = float(essentia_cfg.get("genre_threshold", 15.0))
                genre_format = essentia_cfg.get("genre_format", "parent_child")
                tag_moods = bool(essentia_cfg.get("tag_moods", True))
                parse_json_features = bool(essentia_cfg.get("parse_json_features", True))
                delete_json_after_import = bool(essentia_cfg.get("delete_json_after_import", True))
                json_output_dir = str(essentia_cfg.get("json_output_dir", "") or "").strip()
                cpu_nice = int(essentia_cfg.get("cpu_nice", 10))
                inter_file_delay = float(essentia_cfg.get("inter_file_delay", 0.0))
                run_essentia_mood_scan(
                    script_path=script_path,
                    models_dir=models_dir,
                    mood_threshold=mood_threshold,
                    per_file_timeout=per_file_timeout,
                    force=force,
                    tag_genres=tag_genres,
                    num_genres=num_genres,
                    genre_threshold=genre_threshold,
                    genre_format=genre_format,
                    tag_moods=tag_moods,
                    parse_json_features=parse_json_features,
                    delete_json_after_import=delete_json_after_import,
                    json_output_dir=json_output_dir,
                    artist_filter=artist_name,
                    cpu_nice=cpu_nice,
                    inter_file_delay=inter_file_delay,
                )
                log_unified(f"Essentia scan complete for artist '{artist_name}'")
        except ImportError:
            log_unified(f"Essentia scan skipped: essentia_mood_scan module not available")
        except Exception as e:
            log_unified(f"Warning: Essentia scan failed for '{artist_name}': {e}")

        log_unified(f"✅ Scan complete for artist '{artist_name}'")
        
        # Save checkpoint for resume functionality
        try:
            checkpoint_path = os.path.join(os.path.dirname(DB_PATH), "navidrome_scan_checkpoint.json")
            with open(checkpoint_path, 'w') as f:
                json.dump({"last_scanned_artist": artist_name}, f)
            log_unified(f"Checkpoint saved: Ready to resume from '{artist_name}'")
        except Exception as e:
            log_unified(f"Warning: Failed to save checkpoint: {e}")
    except Exception as e:
        log_unified(f"❌ Scan failed for {artist_name}: {e}")
        import traceback
        log_unified(f"Traceback: {traceback.format_exc()}")


def _auto_detect_album_type(artist_name: str, album_name: str):
    """
    Auto-detect and update album type based on Discogs format data (primary),
    album name heuristics (secondary), or track count heuristics (fallback).
    
    Priority order:
    1. Discogs format data (most reliable source)
       - If discogs_formats contains "EP" → "ep"
       - If discogs_formats contains "Single" → "single"
       - If discogs_is_single = 1 → "single"
    2. Album name heuristics (compilation / live keywords)
       - Album name contains "greatest hits", "best of", "anthology" etc. → "album+compilation"
       - Album name contains "live at", "in concert", "unplugged" etc. → "album+live"
    3. Metadata & track count heuristics (fallback if above unavailable)
       - If == 1 track → Single
       - If >= 70% singles with < 5 total tracks → Single
       - If >= 50% singles with 3-6 total tracks → EP  
       - If >= 40% singles with 6-10 tracks → EP
       - If 3-6 tracks → EP (even with lower singles percentage)
       - Otherwise → Album
    
    IMPORTANT: Always prioritize Discogs format data when available. This ensures 
    albums like "Stark" (marked as "Album" by Spotify) are correctly classified as "EP"
    when Discogs indicates it's an EP.
    
    Args:
        artist_name: Name of the artist
        album_name: Name of the album
    """
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get current album type, track counts, and Discogs format data
        # Use database-appropriate boolean comparison for the is_single column
        is_single_expr = "CASE WHEN is_single THEN 1 ELSE 0 END"
        cursor.execute(f"""
            SELECT 
                COUNT(*) as total_tracks,
                SUM({is_single_expr}) as singles_count,
                MAX(spotify_album_type) as current_type,
                MAX(discogs_formats) as discogs_formats,
                MAX(discogs_is_single) as discogs_is_single
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
        """, (artist_name, album_name))
        
        result = cursor.fetchone()
        if not result:
            conn.close()
            return
        
        total_tracks = result['total_tracks'] or 0
        singles_count = result['singles_count'] or 0
        current_type = result['current_type']
        discogs_formats_raw = result['discogs_formats']
        discogs_is_single = result['discogs_is_single']
        
        if total_tracks == 0:
            conn.close()
            return
        
        # Determine new type using priority order
        new_type = None
        classification_reason = ""
        new_type_from_discogs = False
        
        # ===== PRIORITY 1: Discogs Format Data (Most Reliable) =====
        if discogs_formats_raw:
            try:
                discogs_formats = json.loads(discogs_formats_raw)
                formats_lower = [str(fmt).lower() for fmt in discogs_formats]
                
                # Check for EP in formats
                if any('ep' in fmt for fmt in formats_lower):
                    new_type = 'ep'
                    new_type_from_discogs = True
                    classification_reason = f"Discogs format contains 'EP'"
                # Check for Single in formats
                elif any('single' in fmt for fmt in formats_lower):
                    new_type = 'single'
                    new_type_from_discogs = True
                    classification_reason = f"Discogs format contains 'Single'"
            except (json.JSONDecodeError, TypeError):
                # If parsing fails, fall through to heuristics
                pass
        
        # Check discogs_is_single flag if format check didn't yield result
        # But sanity check: ignore if album has 6+ tracks (can't be a single)
        if not new_type and discogs_is_single == 1 and total_tracks < 6:
            new_type = 'single'
            new_type_from_discogs = True
            classification_reason = "Discogs confirmed as single"
        
        # ===== PRIORITY 2: Album Name Heuristics (compilation / live) =====
        # These patterns are reliable enough to override track-count heuristics
        # but not Discogs format data (handled above).
        if not new_type:
            album_lower = album_name.lower()
            compilation_keywords = [
                "greatest hits", "best of", "the very best", "anthology",
                "collection", "essential", "retrospective", "hits collection",
                "platinum", "gold edition", "ultimate collection",
            ]
            live_keywords = [
                "live at", "live in", "live from", "live session",
                "live recording", "live tour", "in concert", "unplugged",
                "(live)", "[live]", "- live",
            ]
            if any(kw in album_lower for kw in compilation_keywords):
                new_type = 'album+compilation'
                classification_reason = "Album name indicates compilation"
            elif any(kw in album_lower for kw in live_keywords):
                new_type = 'album+live'
                classification_reason = "Album name indicates live recording"

        # ===== PRIORITY 3: Metadata & Track Count Heuristics =====
        if not new_type:
            # Calculate singles percentage
            singles_percent = (singles_count / total_tracks * 100) if total_tracks > 0 else 0
            
            # Determine type based on track count and singles percentage
            if total_tracks == 1:
                new_type = 'single'
                classification_reason = "Single track"
            elif singles_percent >= 70 and total_tracks < 5:
                new_type = 'single'
                classification_reason = f"{singles_percent:.0f}% singles, {total_tracks} total tracks"
            elif singles_percent >= 50 and 3 <= total_tracks <= 6:
                new_type = 'ep'
                classification_reason = f"{singles_percent:.0f}% singles, {total_tracks} total tracks"
            elif singles_percent >= 40 and 6 < total_tracks <= 10:
                new_type = 'ep'
                classification_reason = f"{singles_percent:.0f}% singles, {total_tracks} total tracks (6-10 track range)"
            elif 3 <= total_tracks <= 6:
                new_type = 'ep'
                classification_reason = f"{total_tracks} total tracks (EP heuristic)"
            else:
                new_type = 'album'
                classification_reason = f"{total_tracks} total tracks"
        
        # Update album type in database if it's different from current.
        # Guard: do not let heuristic-only results strip secondary type info that was
        # previously detected by MusicBrainz (e.g. "album (compilation)", "album+live").
        # Secondary type presence is indicated by a "+" or "(" in the type string.
        # Discogs data (authoritative) is allowed to override in all cases.
        def _has_secondary_type(t):
            return bool(t and ('+' in t or '(' in t))
        
        if (new_type and new_type != current_type
                and _has_secondary_type(current_type)
                and not _has_secondary_type(new_type)
                and not new_type_from_discogs):
            log_unified(f"Preserving secondary type info in '{current_type}' (heuristic would set '{new_type}')")
        elif new_type and new_type != current_type:
            cursor.execute(f"""
                UPDATE tracks 
                SET spotify_album_type = {placeholder}
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
            """, (new_type, artist_name, album_name))
            conn.commit()
            
            change_note = ""
            if current_type:
                change_note = f", changed from '{current_type}'"
            log_unified(f"✓ Album type set to '{new_type}' ({classification_reason}{change_note})")
        
        conn.close()
    except Exception as e:
        log_unified(f"Warning: Failed to auto-detect album type: {e}")


def _run_album_scan_pipeline(artist_name: str, album_name: str, force: bool = False):
    """
    Helper function to run the complete scan pipeline for a specific album:
    1. Navidrome import (imports metadata from Navidrome for the album)
    2. Popularity detection (Spotify, Last.fm, ListenBrainz) + Singles detection + Star rating
    
    All steps log to unified_scan.log and Recent Scans page.
    This is used by the album rescan route.
    
    Args:
        artist_name: Name of the artist
        album_name: Name of the album to scan
    
    Note: Force is optional and controlled by the caller/UI toggle.
    """
    album_display = f"{artist_name} - {album_name}"
    log_unified(f"💿 Album scan pipeline started for: {album_display}")
    try:
        # Look up artist_id from cache; rebuild index if missing
        log_unified(f"Looking up artist_id for '{artist_name}' in database...")
        conn = get_db()
        try:
            cursor = conn.cursor()
            placeholder = "%s"
            cursor.execute(f"SELECT artist_id FROM artist_stats WHERE artist_name = {placeholder}", (artist_name,))
            row = cursor.fetchone()
            artist_id = row['artist_id'] if row else None
            log_unified(f"Database lookup result: artist_id={artist_id}")
        finally:
            conn.close()

        if not artist_id:
            log_unified(f"Artist ID not found in cache, rebuilding artist index...")
            idx = build_artist_index()
            artist_data = idx.get(artist_name, {})
            artist_id = artist_data.get("id") if artist_data else None
            log_unified(f"After index rebuild: artist_id={artist_id}")

        # If still no artist_id, check if this is a track artist (not an album artist)
        if not artist_id:
            log_unified(f"Artist not found as album artist, checking if track artist exists in database...")
            track_count = 0  # Initialize to avoid NameError if query fails
            conn = get_db()
            try:
                cursor = conn.cursor()
                placeholder = "%s"
                cursor.execute(f"SELECT COUNT(*) as cnt FROM tracks WHERE artist = {placeholder} AND album = {placeholder}", (artist_name, album_name))
                result = cursor.fetchone()
                track_count = result['cnt'] if result else 0
                log_unified(f"Found {track_count} tracks for '{album_display}'")
            finally:
                conn.close()
            
            if track_count == 0:
                log_unified(f"❌ Scan aborted: no tracks found for '{album_display}' - album does not exist in library")
                return
            
            # Artist/album exists as track artist only - skip Navidrome import, go straight to popularity scan
            log_unified(f"Album '{album_display}' uses track artist (e.g., from Various Artists compilation)")
            log_unified(f"Skipping Navidrome import (Step 1/2) - album metadata already imported via album artist")
            log_unified(f"Step 2/2: Running popularity scan for album '{album_display}' (force={force})")
            popularity_scan(verbose=True, force=force, artist_filter=artist_name, album_filter=album_name)
            log_unified(f"Step 2b/2: Running metadata enrichment scan for album '{album_display}'")
            popularity_scan(verbose=True, force=force, artist_filter=artist_name, album_filter=album_name, metadata_only=True)
            
            # Step 3: Auto-detect and set album type
            log_unified(f"Step 3/3: Auto-detecting album type for '{album_display}'")
            _auto_detect_album_type(artist_name, album_name)
        else:
            # Normal flow: artist_id found, run both steps
            # Step 1: Import metadata from Navidrome for this specific album
            log_unified(f"Step 1/2: Navidrome import for album '{album_display}' (force={force})")
            scan_artist_to_db(artist_name, artist_id, verbose=True, force=force, album_filter=album_name)

            # Step 2: Run popularity scan for this specific album (includes singles detection and star rating)
            log_unified(f"Step 2/2: Running popularity scan for album '{album_display}' (force={force})")
            popularity_scan(verbose=True, force=force, artist_filter=artist_name, album_filter=album_name)
            log_unified(f"Step 2b/2: Running metadata enrichment scan for album '{album_display}'")
            popularity_scan(verbose=True, force=force, artist_filter=artist_name, album_filter=album_name, metadata_only=True)
        
        # Step 3: Auto-detect and set album type based on singles detection
        log_unified(f"Step 3/3: Auto-detecting album type for '{album_display}'")
        _auto_detect_album_type(artist_name, album_name)
        
        log_unified(f"✅ Scan complete for album '{album_display}'")
    except Exception as e:
        log_unified(f"❌ Scan failed for {album_display}: {e}")
        import traceback
        log_unified(f"Traceback: {traceback.format_exc()}")


@app.route("/album/<path:artist>/<path:album>/edit", methods=["POST"])
def album_edit(artist, album):
    """Update album metadata for all tracks in the album"""
    from urllib.parse import unquote
    artist = unquote(artist)
    album = unquote(album)
    
    # Get form data
    album_title = request.form.get("album_title", "").strip()
    album_artist = request.form.get("album_artist", "").strip()
    track_artist = request.form.get("track_artist", "").strip()
    track_composer = request.form.get("track_composer", "").strip()
    track_comment = request.form.get("track_comment", "").strip()
    release_year = request.form.get("release_year", "").strip() or None
    album_type = request.form.get("album_type", "").strip() or None
    
    # Normalize album type - convert standalone "compilation" to "album+compilation"
    if album_type == "compilation":
        album_type = "album+compilation"
    
    album_mbid = request.form.get("album_mbid", "").strip() or None
    album_discogs_id = request.form.get("album_discogs_id", "").strip() or None
    artist_mbid = request.form.get("artist_mbid", "").strip() or None
    album_genres = request.form.get("album_genres", "").strip()
    cover_art_url = request.form.get("cover_art_url", "").strip() or None
    
    # Debug logging for character encoding issues (use debug level to avoid log noise)
    logging.debug(f"Album edit - URL artist: {repr(artist)}, form album_artist: {repr(album_artist)}")
    logging.debug(f"Album edit - URL album: {repr(album)}, form album_title: {repr(album_title)}")
    logging.debug(f"Album edit - track_artist: {repr(track_artist)}")
    logging.debug(f"Album edit - track_composer: {repr(track_composer)}")
    logging.debug(f"Album edit - track_comment: {repr(track_comment)}")
    
    if not album_title or not album_artist:
        flash("Album title and artist are required", "danger")
        return redirect(url_for("album_detail", artist=artist, album=album))
    
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        track_columns = _get_table_columns(cursor, "tracks") or set()
        discogs_album_column = None
        if "discogs_album_id" in track_columns:
            discogs_album_column = "discogs_album_id"
        elif "discogs_release_id" in track_columns:
            discogs_album_column = "discogs_release_id"
        
        # Update all tracks in this album
        update_fields = []
        update_values = []
        
        # Track if album/artist names changed
        names_changed = (album_artist != artist) or (album_title != album)
        
        # If album title or artist changed, update those
        if names_changed:
            update_fields.extend([f"album = {placeholder}", f"album_artist = {placeholder}"])
            update_values.extend([album_title, album_artist])
        
        # Update year if provided
        if release_year:
            update_fields.append(f"year = {placeholder}")
            update_values.append(int(release_year))

        # Optional per-track fields applied to all tracks in this album
        if track_artist:
            update_fields.append(f"artist = {placeholder}")
            update_values.append(track_artist)
        if track_composer:
            update_fields.append(f"composer = {placeholder}")
            update_values.append(track_composer)
        if track_comment:
            update_fields.append(f"comment = {placeholder}")
            update_values.append(track_comment)
        
        # Update album type if provided
        if album_type:
            update_fields.append(f"spotify_album_type = {placeholder}")
            update_values.append(album_type)
        
        # Update album MBID if provided
        if album_mbid:
            update_fields.append(f"musicbrainz_album_mbid = {placeholder}")
            update_values.append(album_mbid)

        # Update artist MBID if provided
        if artist_mbid:
            update_fields.append(f"musicbrainz_artist_id = {placeholder}")
            update_values.append(artist_mbid)

        # Update album Discogs release ID if provided
        if album_discogs_id and discogs_album_column:
            update_fields.append(f"{discogs_album_column} = {placeholder}")
            update_values.append(album_discogs_id)
        
        # Update genres
        if album_genres:
            update_fields.append(f"genres = {placeholder}")
            update_values.append(album_genres)
        
        # Update cover art URL
        if cover_art_url:
            update_fields.append(f"cover_art_url = {placeholder}")
            update_values.append(cover_art_url)
        
        # Add WHERE clause values
        update_values.extend([artist, album])
        
        # Execute update
        if update_fields:
            # Validate that update_fields only contains safe column assignments
            # All field assignments should be in the format "column_name = <placeholder>"
            allowed_columns = {
                'album', 'artist', 'album_artist', 'year', 'spotify_album_type',
                'musicbrainz_album_mbid', 'musicbrainz_artist_id',
                'discogs_album_id', 'discogs_release_id',
                'genres', 'composer', 'comment', 'cover_art_url'
            }
            for field in update_fields:
                column_name = field.split('=')[0].strip()
                if column_name not in allowed_columns:
                    flash(f"Invalid column name in update: {column_name}", "danger")
                    return redirect(url_for("album_detail", artist=artist, album=album))
            
            sql = (
                f"UPDATE tracks SET {', '.join(update_fields)} "
                f"WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}"
            )
            cursor.execute(sql, update_values)
            rows_updated = cursor.rowcount
            conn.commit()

            try:
                cursor.execute(f"""
                    SELECT id, file_path, title, artist, album, album_artist, genres, year, composer, comment
                    FROM tracks
                    WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
                """, (album_artist, album_title))
                tracks = cursor.fetchall()

                # Commit the read-only SELECT so the connection is idle (not
                # idle-in-transaction) during the cover art HTTP download and
                # per-track file tag writes below.  Without this commit the
                # implicit transaction from the SELECT persists for the full
                # duration of slow network/disk I/O, which can exceed
                # idle_in_transaction_session_timeout.
                try:
                    conn.commit()
                except Exception:
                    pass

                files_updated = 0
                files_failed = 0
                files_missing = 0
                files_with_path = 0
                tracks_without_path = []
                tracks_missing_on_disk = []
                tracks_failed_to_write = []
                tag_writer_unavailable = False

                if tracks:
                    try:
                        from helpers.tag_manager import write_tags_to_file

                        # Download cover art once for all tracks (if a URL was provided)
                        cover_art_bytes = None
                        cover_art_mime = None
                        if cover_art_url:
                            try:
                                from urllib.parse import urlparse as _urlparse, urlunparse as _urlunparse
                                _parsed = _urlparse(cover_art_url)
                                _allowed_hosts = {
                                    "coverartarchive.org",
                                    "musicbrainz.org",
                                    "discogs.com",
                                    "img.discogs.com",
                                    "i.discogs.com",
                                    "images.discogs.com",
                                    "archive.org",
                                    "ia800.us.archive.org",
                                }
                                _hostname = (_parsed.hostname or "").lower().lstrip("www.")
                                _is_trusted = (
                                    _parsed.scheme in ("http", "https")
                                    and any(
                                        _hostname == h or _hostname.endswith("." + h)
                                        for h in _allowed_hosts
                                    )
                                )
                                if not _is_trusted:
                                    logging.warning(f"Rejecting cover art URL from untrusted host: {_parsed.hostname}")
                                    cover_art_url = None
                                else:
                                    # Reconstruct the URL from validated parsed components to avoid tainted-URL SSRF
                                    _safe_url = _urlunparse((
                                        _parsed.scheme,
                                        _parsed.netloc,
                                        _parsed.path,
                                        _parsed.params,
                                        _parsed.query,
                                        "",
                                    ))
                                    import requests as _requests
                                    _resp = _requests.get(_safe_url, timeout=10)
                                    if _resp.status_code == 200 and _resp.content:
                                        cover_art_bytes = _resp.content
                                        cover_art_mime = _resp.headers.get("Content-Type", "image/jpeg").split(";")[0].strip()
                                        # Also persist to album_art table
                                        try:
                                            from popularity import download_and_save_album_art as _save_art
                                            _save_art(album_artist, album_title, _safe_url, source="manual")
                                        except Exception as _art_db_err:
                                            logging.debug(f"Could not save cover art to album_art table: {_art_db_err}")
                                    else:
                                        logging.warning(f"Failed to download cover art from {_safe_url}: HTTP {_resp.status_code}")
                            except Exception as _download_err:
                                logging.warning(f"Could not download cover art: {_download_err}")

                        def _resolve_music_file_path(path_value):
                            if not path_value:
                                return None
                            raw_path = str(path_value).strip()
                            if not raw_path:
                                return None

                            candidates = [raw_path]
                            if not os.path.isabs(raw_path):
                                roots = [
                                    os.environ.get("MUSIC_FOLDER"),
                                    os.environ.get("MUSIC_ROOT"),
                                    os.environ.get("MUSIC_DIR"),
                                    "/music",
                                ]
                                seen = set()
                                for root in roots:
                                    if not root:
                                        continue
                                    root_text = str(root).strip()
                                    if not root_text:
                                        continue
                                    candidate = os.path.join(root_text, raw_path)
                                    if candidate not in seen:
                                        candidates.append(candidate)
                                        seen.add(candidate)

                            for candidate in candidates:
                                if os.path.exists(candidate):
                                    return candidate
                            return None

                        for track in tracks:
                            track_title = track.get('title') if hasattr(track, 'get') else track[2]
                            file_path = track.get('file_path') if hasattr(track, 'get') else track[1]
                            if not file_path:
                                tracks_without_path.append(str(track_title or 'Unknown title'))
                                continue

                            files_with_path += 1
                            resolved_file_path = _resolve_music_file_path(file_path)
                            if not resolved_file_path:
                                files_missing += 1
                                tracks_missing_on_disk.append(f"{track_title} ({file_path})")
                                continue

                            try:
                                tags_to_write = {}

                                if track_artist:
                                    tags_to_write["artist"] = track_artist
                                if album_genres:
                                    tags_to_write["genre"] = album_genres
                                if release_year:
                                    tags_to_write["year"] = release_year
                                if track_composer:
                                    tags_to_write["composer"] = track_composer
                                if track_comment:
                                    tags_to_write["comment"] = track_comment
                                if names_changed:
                                    tags_to_write["album"] = album_title
                                    tags_to_write["album_artist"] = album_artist
                                if album_mbid:
                                    tags_to_write["musicbrainz_album_mbid"] = album_mbid
                                if artist_mbid:
                                    tags_to_write["musicbrainz_artistid"] = artist_mbid
                                if cover_art_bytes:
                                    tags_to_write["cover_art_data"] = cover_art_bytes
                                    tags_to_write["cover_art_mime"] = cover_art_mime

                                if tags_to_write:
                                    if write_tags_to_file(str(resolved_file_path), tags_to_write):
                                        files_updated += 1
                                    else:
                                        files_failed += 1
                                        tracks_failed_to_write.append(f"{track_title} ({resolved_file_path})")
                            except Exception as file_err:
                                logging.warning(f"Failed to write tags to {resolved_file_path}: {file_err}")
                                files_failed += 1
                                tracks_failed_to_write.append(f"{track_title} ({resolved_file_path})")
                    except ImportError:
                        logging.warning("Tag manager not available for file writing")
                        tag_writer_unavailable = True

                result_sections = []
                if tag_writer_unavailable:
                    result_sections.append({
                        "title": "Tag writing unavailable",
                        "body": "The database update completed, but the tag writer could not be loaded for file updates.",
                    })
                if tracks_without_path:
                    result_sections.append({
                        "title": "Tracks without file paths",
                        "items": tracks_without_path,
                    })
                if tracks_missing_on_disk:
                    result_sections.append({
                        "title": "Tracks missing on disk",
                        "items": tracks_missing_on_disk,
                    })
                if tracks_failed_to_write:
                    result_sections.append({
                        "title": "Tracks that failed to update",
                        "items": tracks_failed_to_write,
                    })

                result_stats = [
                    {"label": "DB tracks updated", "value": rows_updated},
                    {"label": "Files written", "value": f"{files_updated}/{files_with_path}" if files_with_path else files_updated},
                ]
                if cover_art_bytes:
                    result_stats.append({"label": "Cover art embedded", "value": "Yes"})
                elif cover_art_url:
                    result_stats.append({"label": "Cover art", "value": "Download failed"})
                if tracks_without_path:
                    result_stats.append({"label": "No file path", "value": len(tracks_without_path)})
                if files_missing:
                    result_stats.append({"label": "Missing on disk", "value": files_missing})
                if files_failed:
                    result_stats.append({"label": "Write failures", "value": files_failed})

                if files_with_path:
                    cover_art_note = " Cover art embedded." if cover_art_bytes else (" Cover art download failed." if cover_art_url else "")
                    result_summary = f"Updated {rows_updated} tracks in the database and wrote tags to {files_updated} of {files_with_path} track files.{cover_art_note}"
                elif tag_writer_unavailable:
                    result_summary = f"Updated {rows_updated} tracks in the database, but file tag writing is unavailable."
                else:
                    result_summary = f"Updated {rows_updated} tracks in the database. No track file paths were available for tag writing."

                result_category = "warning" if result_sections else "success"
                flash_result_panel(
                    "Album metadata update completed",
                    category=result_category,
                    summary=result_summary,
                    stats=result_stats,
                    sections=result_sections,
                )
            except Exception as file_update_err:
                logging.warning(f"Error updating audio files: {file_update_err}")
                flash_result_panel(
                    "Album metadata update completed with file update errors",
                    category="warning",
                    summary=f"Updated {rows_updated} tracks in the database, but file tag updates hit an error.",
                    sections=[{
                        "title": "File update error",
                        "items": [str(file_update_err)],
                    }],
                    stats=[{"label": "DB tracks updated", "value": rows_updated}],
                )
        else:
            flash("No changes to save", "info")
        
        # Redirect to the (potentially new) album page
        # To ensure special characters are preserved, query the database for the actual artist/album names
        # after the update, rather than relying on potentially corrupted form data
        # Reuse existing connection to avoid overhead of creating new connection
        try:
            # Get the actual artist and album names from the database after the update
            # Use the same COALESCE logic as album_detail to get the correct artist
            cursor.execute(f"""
                SELECT 
                    COALESCE(NULLIF(album_artist, ''), artist) as effective_artist,
                    album
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
                    AND album = {placeholder}
                LIMIT 1
            """, (album_artist, album_title))
            db_row = cursor.fetchone()
            
            if db_row:
                redirect_artist = db_row['effective_artist']
                redirect_album = db_row['album']
            else:
                # Fallback: use form data if names changed, otherwise use original URL params
                redirect_artist = album_artist if names_changed else artist
                redirect_album = album_title if names_changed else album
        except Exception as e:
            logging.warning(f"Error querying database for redirect: {e}")
            # Fallback: use form data if names changed, otherwise use original URL params
            redirect_artist = album_artist if names_changed else artist
            redirect_album = album_title if names_changed else album
        finally:
            conn.close()
        
        return redirect(url_for("album_detail", artist=redirect_artist, album=redirect_album))
        
    except Exception as e:
        logging.error(f"Error updating album: {e}")
        flash(f"Error updating album: {str(e)}", "danger")
        return redirect(url_for("album_detail", artist=artist, album=album))


@app.route("/api/album/<path:artist>/<path:album>/rename-files", methods=["POST"])
def api_album_rename_files(artist, album):
    """
    Rename all files in an album based on current metadata.
    
    This endpoint:
    1. Fetches all tracks for the album
    2. Calculates new file paths based on current metadata
    3. Moves files to new paths maintaining disc/track numbering
    4. Updates database file_path columns
    5. Returns status and details of renamed files
    
    URL Parameters:
        artist: Artist name (URL decoded)
        album: Album name (URL decoded)
    
    Returns:
        JSON with:
        - success: bool
        - renamed_count: Number of files successfully renamed
        - updated_db_count: Number of database records updated
        - errors: List of error messages
        - details: List of {track_id, track, old_path, new_path}
    """
    from urllib.parse import unquote
    artist = unquote(artist)
    album = unquote(album)
    
    try:
        from download_queue_manager import rename_album_files
        
        conn = get_db()
        
        # Call the rename function
        result = rename_album_files(artist, album, conn)
        
        conn.close()
        
        return jsonify(result)
        
    except Exception as e:
        logging.error(f"Error renaming album files: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({
            "success": False,
            "renamed_count": 0,
            "updated_db_count": 0,
            "errors": [str(e)],
            "details": []
        }), 500


@app.route("/api/track/<track_id>/rename-file", methods=["POST"])
def api_track_rename_file(track_id):
    """
    Rename/move a single track's file using the configured file_name_format from config.

    Reads downloads.file_name_format (same setting used by Queue Manager organize).
    Moves the file to the new path and updates the database.

    Returns:
        JSON with success, renamed, old_path, new_path, message, error
    """
    try:
        from download_queue_manager import rename_track_file

        conn = get_db()
        cfg = get_config()
        music_dir = cfg.get("navidrome", {}).get("music_folder", "/music")

        result = rename_track_file(track_id, conn, music_dir=music_dir)
        conn.close()

        status_code = 200 if result.get("success") else 400
        return jsonify(result), status_code

    except Exception as e:
        logging.error(f"Error renaming track file {track_id}: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/duplicate-artists/<path:artist>", methods=["GET"])
def api_get_duplicate_artists(artist):
    """
    Get duplicate artists for a specific artist (same MBID, different names).
    
    URL Parameters:
        artist: Artist name (URL decoded)
    
    Returns:
        JSON with:
        - duplicates: List of {mbid, canonical_mb, variations[], track_counts{}}
        - artist_info: Current artist's MBID if available
    """
    from urllib.parse import unquote
    artist = unquote(artist)
    
    try:
        conn = get_db()
        placeholder = "%s"
        cursor = conn.cursor()
        
        # Get the MBID for the current artist (use the same album_artist fallback as Artists page)
        cursor.execute("""
            SELECT DISTINCT musicbrainz_artist_id
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
                AND musicbrainz_artist_id IS NOT NULL
                AND musicbrainz_artist_id != ''
            LIMIT 1
        """.format(placeholder=placeholder), (artist,))
        
        artist_mbid_row = cursor.fetchone()
        artist_mbid = _row_get(artist_mbid_row, 'musicbrainz_artist_id', 0) if artist_mbid_row else None
        
        duplicates = []
        
        if artist_mbid:
            # Get all album_artist name variations for this MBID (not track artist)
            cursor.execute("""
                SELECT 
                    COALESCE(NULLIF(album_artist, ''), artist) as artist,
                    COUNT(*) as track_count
                FROM tracks
                WHERE musicbrainz_artist_id = {placeholder}
                GROUP BY COALESCE(NULLIF(album_artist, ''), artist)
                ORDER BY track_count DESC
            """.format(placeholder=placeholder), (artist_mbid,))
            
            variations_data = cursor.fetchall()
            
            if len(variations_data) > 1:
                # Multiple variations found - this is a duplicate artist scenario
                canonical_mb = fetch_musicbrainz_artist_name(artist_mbid) or _row_get(variations_data[0], 'artist', 0)
                variations = [_row_get(v, 'artist', 0) for v in variations_data]
                track_counts = {
                    _row_get(v, 'artist', 0): _row_get(v, 'track_count', 1)
                    for v in variations_data
                }
                
                duplicates.append({
                    'mbid': artist_mbid,
                    'canonical_mb': canonical_mb,
                    'variations': variations,
                    'track_counts': track_counts,
                    'current_artist': artist
                })
        
        conn.close()
        
        return jsonify({
            "duplicates": duplicates,
            "artist_info": {
                "name": artist,
                "mbid": artist_mbid
            }
        })
        
    except Exception as e:
        logging.error(f"Error getting duplicate artists: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({
            "duplicates": [],
            "error": str(e)
        }), 500


@app.route("/api/duplicate-artists/merge", methods=["POST"])
def api_merge_duplicate_artists():
    """
    Merge duplicate artists by updating all tracks to use canonical name.
    
    Request JSON:
        - old_artist: Current artist name (str)
        - new_artist: Canonical artist name to merge into (str)
        - mbid: MusicBrainz artist ID (str)
        - dry_run: Preview changes without executing (bool, optional)
    
    Returns:
        JSON with:
        - success: bool
        - updated_db: Number of database records updated
        - updated_files: Number of MP3 tags updated
        - moved_files: Number of files reorganized
        - errors: List of error messages
        - message: Summary message
    """
    try:
        data = request.get_json()
        old_artist = data.get('old_artist', '').strip()
        source_artists = data.get('source_artists') or []
        new_artist = data.get('new_artist', '').strip()
        mbid = data.get('mbid', '').strip()
        dry_run = data.get('dry_run', False)
        
        if not new_artist or not mbid:
            return jsonify({
                "success": False,
                "error": "new_artist and mbid are required"
            }), 400

        # Resolve source variants to merge. Prefer explicit list from UI, fallback to old_artist,
        # then discover all non-canonical variants by MBID.
        candidates = []
        if isinstance(source_artists, list):
            candidates.extend([str(name).strip() for name in source_artists if str(name).strip()])
        if old_artist:
            candidates.append(old_artist)

        if not candidates:
            conn = get_db()
            cursor = conn.cursor()
            placeholder = "%s"
            cursor.execute(f"""
                SELECT DISTINCT COALESCE(NULLIF(album_artist, ''), artist) AS variation
                FROM tracks
                WHERE musicbrainz_artist_id = {placeholder}
            """, (mbid,))
            candidates = []
            for row in cursor.fetchall() or []:
                variation = _row_get(row, 'variation', 0)
                if variation:
                    candidates.append(str(variation).strip())
            conn.close()

        merge_sources = []
        seen = set()
        for name in candidates:
            normalized_name = str(name).strip()
            if not normalized_name:
                continue
            # Only skip the exact canonical spelling. Case-only variants like
            # "Babymetal" -> "BABYMETAL" should still be merged.
            if normalized_name == new_artist:
                continue
            if normalized_name in seen:
                continue
            seen.add(normalized_name)
            merge_sources.append(normalized_name)

        if not merge_sources:
            return jsonify({
                "success": True,
                "dry_run": dry_run,
                "updated_db": 0,
                "updated_files": 0,
                "moved_files": 0,
                "errors": [],
                "message": f"No non-canonical variants found to merge into '{new_artist}'"
            })

        aggregate = {
            'updated_db': 0,
            'updated_files': 0,
            'moved_files': 0,
            'errors': []
        }

        for source_name in merge_sources:
            result = update_artist_name(source_name, new_artist, mbid, dry_run=dry_run)
            aggregate['updated_db'] += result.get('updated_db', 0)
            aggregate['updated_files'] += result.get('updated_files', 0)
            aggregate['moved_files'] += result.get('moved_files', 0)
            aggregate['errors'].extend(result.get('errors', []))
        
        return jsonify({
            "success": True,
            "dry_run": dry_run,
            "updated_db": aggregate['updated_db'],
            "updated_files": aggregate['updated_files'],
            "moved_files": aggregate['moved_files'],
            "errors": aggregate['errors'],
            "message": f"{'[DRY RUN] ' if dry_run else ''}Merged {len(merge_sources)} variant(s) into '{new_artist}': {aggregate['updated_db']} tracks updated"
        })
        
    except Exception as e:
        logging.error(f"Error merging duplicate artists: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({
            "success": False,
            "error": str(e)
        }), 500


