@app.route("/api/track/<track_id>/toggle-manual-single", methods=["POST"])
def api_toggle_manual_single(track_id):
    """Toggle single_manual_override flag for a track (prevents auto-detection from overwriting)"""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get current value
        placeholder = "%s"
        cursor.execute(f"SELECT single_manual_override FROM tracks WHERE id = {placeholder}", (track_id,))
        result = cursor.fetchone()
        
        if not result:
            return jsonify({"error": "Track not found"}), 404
        
        current_value = result[0] or 0
        new_value = 1 - current_value  # Toggle between 0 and 1
        
        # Update
        cursor.execute(
            f"UPDATE tracks SET single_manual_override = {placeholder} WHERE id = {placeholder}",
            (new_value, track_id)
        )
        conn.commit()
        conn.close()
        
        return jsonify({
            "success": True,
            "track_id": track_id,
            "single_manual_override": new_value,
            "message": f"Single manual override {'enabled' if new_value else 'disabled'} - single detection scan will {'skip' if new_value else 'process'} this track"
        })
    except Exception as e:
        logging.error(f"Error toggling manual single flag: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/track/<track_id>/rescan-single", methods=["POST"])
def api_rescan_single_track(track_id):
    """Force a fresh single detection scan for one track on the next popularity run.

    Clears single_detection_last_updated so the next popularity scan re-evaluates
    this track regardless of the normal TTL cache.  Optionally accepts a ``source``
    body param for UI display purposes (ignored at runtime — all sources are checked).
    """
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(f"SELECT id, title, artist FROM tracks WHERE id = {placeholder}", (track_id,))
        row = cursor.fetchone()
        if not row:
            conn.close()
            return jsonify({"error": "Track not found"}), 404

        cursor.execute(
            f"UPDATE tracks SET single_detection_last_updated = NULL WHERE id = {placeholder}",
            (track_id,)
        )
        conn.commit()
        conn.close()

        return jsonify({
            "success": True,
            "track_id": track_id,
            "message": "Single detection cache cleared — track will be re-evaluated on next scan"
        })
    except Exception as e:
        logging.error(f"Error resetting single detection for track {track_id}: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/scan/start", methods=["POST"])
def scan_start():
    """Start a library scan"""
    global scan_process
    
    scan_type = request.form.get("scan_type", "full")
    artist = request.form.get("artist")
    force_artist_scan = str(request.form.get("force", "")).strip().lower() in ("1", "true", "yes", "on")
    
    logging.info(f"scan_start called: scan_type={scan_type}, artist={artist}")
    
    # Handle artist-specific scan differently - use threaded worker instead of subprocess
    if scan_type == "artist":
        if artist:
            logging.info(f"Starting artist scan thread for: {artist}")
            threading.Thread(target=_run_artist_scan_pipeline, args=(artist, force_artist_scan), daemon=True).start()
            mode_label = "Forced" if force_artist_scan else "Changes Only"
            flash(f"Scan started for artist: {artist} ({mode_label})", "success")
            return redirect(url_for("artist_detail", name=artist))
        else:
            logging.error("Artist scan requested but no artist name provided")
            flash("Error: No artist name provided", "danger")
            return redirect(url_for("dashboard"))
    
    # For batch/force scans, use subprocess as before
    with scan_lock:
        if scan_process and scan_process.poll() is None:
            flash("A scan is already running", "warning")
            return redirect(url_for("dashboard"))
        
        # Build command
        cmd = ["python", "/app/start.py"]
        
        if scan_type == "full":
            cmd.append("--full-scan")
        elif scan_type == "force":
            cmd.extend(["--full-scan", "--force"])
        
        # Start process
        scan_process = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1
        )
        
        flash(f"Scan started: {scan_type}", "success")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/unified", methods=["POST"])
def scan_unified():
    """Start the unified scan pipeline (popularity + singles)"""
    global scan_process
    
    with scan_lock:
        if scan_process and scan_process.poll() is None:
            flash("A scan is already running", "warning")
            return redirect(url_for("dashboard"))
        
        try:
            # Read force setting from config
            config_data, _ = _read_yaml(CONFIG_PATH)
            force = config_data.get("features", {}).get("force", False)
            
            # Start unified scan process
            cmd = [sys.executable, "unified_scan.py", "--verbose"]
            if force:
                cmd.append("--force")
            scan_process = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1
            )
            flash("✅ Unified scan started (popularity → singles → ratings)", "success")
        except Exception as e:
            flash(f"❌ Error starting unified scan: {str(e)}", "danger")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/popularity", methods=["POST"])
def scan_popularity_route():
    """Run popularity score update from external sources"""
    global scan_process_popularity
    
    # Get scan mode from query parameters (default: "all")
    mode = request.args.get('mode', 'all')  # all, force, missing, metadata, metadata_force, singles, singles_resume, singles_resume_force, singles_detection, singles_detection_force, resume, resume_force
    restart_requested = str(request.args.get('restart', '0')).strip().lower() in ('1', 'true', 'yes', 'on')
    force_start = str(request.args.get('force_start', '0')).strip().lower() in ('1', 'true', 'yes', 'on')
    
    with scan_lock:
        # Check if scan is already running
        if scan_process_popularity is not None:
            scan_already_running = False
            if isinstance(scan_process_popularity, dict):
                thread = scan_process_popularity.get('thread')
                if thread and thread.is_alive():
                    scan_already_running = True
            elif hasattr(scan_process_popularity, 'is_alive') and scan_process_popularity.is_alive():
                scan_already_running = True

            if scan_already_running and not force_start:
                return jsonify({"scan_running": True, "message": "A popularity scan is already running."}), 409

        try:
            db_dir = os.path.dirname(DB_PATH)
            if restart_requested:
                checkpoint_path = os.path.join(db_dir, "popularity_scan_checkpoint.json")
                if os.path.exists(checkpoint_path):
                    try:
                        os.remove(checkpoint_path)
                        logging.info("Restart requested: cleared popularity checkpoint to start from beginning")
                    except Exception as checkpoint_err:
                        logging.warning(f"Restart requested but failed to clear popularity checkpoint: {checkpoint_err}")
            
            # Use different progress files for singles-only / singles-detection modes
            if mode in ('singles', 'singles_resume', 'singles_resume_force', 'singles_detection', 'singles_detection_force'):
                popularity_progress_file = os.path.join(db_dir, "singles_scan_progress.json")
                _write_progress_file(popularity_progress_file, "singles_scan", True, {"status": "starting"})
            elif mode in ('metadata', 'metadata_force'):
                popularity_progress_file = os.path.join(db_dir, "metadata_lookup_scan_progress.json")
                _write_progress_file(popularity_progress_file, "metadata_lookup_scan", True, {"status": "starting"})
            else:
                popularity_progress_file = os.path.join(db_dir, "popularity_scan_progress.json")
                _write_progress_file(popularity_progress_file, "popularity_scan", True, {"status": "starting"})

            # Run popularity scan in background thread instead of subprocess
            from popularity import popularity_scan as scan_popularity_func
            
            # Determine force and filter logic based on mode
            force_rescan = (mode == 'force' or mode == 'resume_force' or mode == 'metadata_force' or mode == 'singles_resume_force' or mode == 'singles_detection_force')
            filter_missing = (mode == 'missing')
            metadata_only = mode in ('metadata', 'metadata_force')
            singles_only = mode in ('singles', 'singles_resume', 'singles_resume_force')
            singles_with_missing_popularity = mode in ('singles_detection', 'singles_detection_force')
            
            # Determine resume artist for resume mode
            resume_from_artist = None
            if mode in ('resume', 'resume_force', 'singles_resume', 'singles_resume_force'):
                from scan_resume import get_last_scanned_artist
                resume_scan_type = "singles" if singles_only else "popularity"
                resume_from_artist = get_last_scanned_artist(scan_type=resume_scan_type, db_path=DB_PATH)
                if resume_from_artist:
                    logging.info(f"Resume mode: Found last scanned artist '{resume_from_artist}'")
                else:
                    logging.warning("Resume mode: No last scanned artist found, starting from beginning")
            
            def run_popularity_scan_bg():
                _pop_cycle = 0
                _cycle_resume = resume_from_artist
                try:
                    while True:
                        _pop_cycle += 1

                        cfg = get_config()
                        perpetual_enabled = bool((cfg.get("features") or {}).get("perpetual", False))

                        _stopped = False

                        if singles_only:
                            logging.info(f"Starting singles-only scan in background (cycle {_pop_cycle})")
                            completed = scan_popularity_func(
                                verbose=False,
                                force=force_rescan,
                                singles_only=True,
                                resume_from=_cycle_resume,
                                stop_progress_file=popularity_progress_file
                            )
                            if completed is False:
                                _write_progress_with_current_artist(popularity_progress_file, "singles_scan", False, {"status": "stopped", "exit_code": 0})
                                logging.info("Singles scan stopped by user request")
                                break
                            logging.info("Singles scan cycle %d completed successfully", _pop_cycle)
                            _log_scan_session_complete("singles")
                        elif metadata_only:
                            logging.info(f"Starting metadata-only lookup scan in background (force={force_rescan}, cycle {_pop_cycle})")
                            completed = scan_popularity_func(
                                verbose=False,
                                force=force_rescan,
                                metadata_only=True,
                                stop_progress_file=popularity_progress_file
                            )
                            if completed is False:
                                _write_progress_with_current_artist(popularity_progress_file, "metadata_lookup_scan", False, {"status": "stopped", "exit_code": 0})
                                logging.info("Metadata lookup scan stopped by user request")
                                break
                            logging.info("Metadata lookup scan cycle %d completed successfully", _pop_cycle)
                            try:
                                logging.info("Metadata lookup scan complete; starting missing releases refresh")
                                _run_daily_missing_releases_scan()
                            except Exception as missing_release_err:
                                logging.warning(f"Metadata lookup post-step failed (missing releases refresh): {missing_release_err}")
                            _log_scan_session_complete("metadata")
                        elif singles_with_missing_popularity:
                            logging.info(f"Starting singles scan (with popularity fetch for new albums) in background (force={force_rescan}, cycle {_pop_cycle})")
                            completed = scan_popularity_func(
                                verbose=False,
                                force=force_rescan,
                                singles_with_missing_popularity=True,
                                stop_progress_file=popularity_progress_file
                            )
                            if completed is False:
                                _write_progress_with_current_artist(popularity_progress_file, "singles_scan", False, {"status": "stopped", "exit_code": 0})
                                logging.info("Singles scan stopped by user request")
                                break
                            logging.info("Singles scan cycle %d completed successfully", _pop_cycle)
                            _log_scan_session_complete("singles")
                        else:
                            # Popularity and Singles Scan — three sequential phases, each with
                            # its own 2-week cooldown (when not forced).  If a phase ran recently
                            # it is skipped but the next phase still runs.
                            _PHASE_COOLDOWN_DAYS = 14

                            # Phase 1: metadata lookup
                            run_meta = force_rescan or not _scan_phase_ran_recently("metadata", _PHASE_COOLDOWN_DAYS)
                            if run_meta:
                                logging.info(f"Phase 1/3: metadata lookup (force={force_rescan})")
                                meta_completed = scan_popularity_func(
                                    verbose=False,
                                    force=force_rescan,
                                    metadata_only=True,
                                    # Pass the same resume checkpoint used by Phase 2/3 so
                                    # that a restart after a mid-Phase-1 crash (or any
                                    # crash that happened before Phase 1 finished) does not
                                    # restart from the very beginning of the library (e.g.
                                    # "Various Artists") but instead skips to the last
                                    # completed artist, just like the other phases do.
                                    resume_from=_cycle_resume,
                                    stop_progress_file=popularity_progress_file
                                )
                                if meta_completed is False:
                                    _write_progress_with_current_artist(popularity_progress_file, "popularity_scan", False, {"status": "stopped", "exit_code": 0})
                                    logging.info("Popularity scan stopped during metadata phase")
                                    _stopped = True
                                else:
                                    _log_scan_session_complete("metadata")
                                    try:
                                        _run_daily_missing_releases_scan()
                                    except Exception as _mre:
                                        logging.warning(f"Missing releases refresh failed after metadata phase: {_mre}")
                            else:
                                logging.info(f"Phase 1/3: metadata lookup skipped (ran within last {_PHASE_COOLDOWN_DAYS} days)")

                            if not _stopped:
                                # Phase 2: popularity scoring
                                run_pop = force_rescan or not _scan_phase_ran_recently("popularity", _PHASE_COOLDOWN_DAYS)
                                if run_pop:
                                    logging.info(f"Phase 2/3: popularity scoring (force={force_rescan})")
                                    pop_completed = scan_popularity_func(
                                        verbose=False,
                                        force=force_rescan,
                                        filter_missing=filter_missing,
                                        popularity_only=True,
                                        resume_from=_cycle_resume,
                                        stop_progress_file=popularity_progress_file
                                    )
                                    if pop_completed is False:
                                        _write_progress_with_current_artist(popularity_progress_file, "popularity_scan", False, {"status": "stopped", "exit_code": 0})
                                        logging.info("Popularity scan stopped during popularity phase")
                                        _stopped = True
                                    else:
                                        _log_scan_session_complete("popularity")
                                else:
                                    logging.info(f"Phase 2/3: popularity scoring skipped (ran within last {_PHASE_COOLDOWN_DAYS} days)")

                            if not _stopped:
                                # Phase 3: singles detection + star assignment
                                run_singles = force_rescan or not _scan_phase_ran_recently("singles", _PHASE_COOLDOWN_DAYS)
                                if run_singles:
                                    logging.info(f"Phase 3/3: singles detection (force={force_rescan})")
                                    singles_completed = scan_popularity_func(
                                        verbose=False,
                                        force=force_rescan,
                                        singles_only=True,
                                        resume_from=_cycle_resume,
                                        stop_progress_file=popularity_progress_file
                                    )
                                    if singles_completed is False:
                                        _write_progress_with_current_artist(popularity_progress_file, "popularity_scan", False, {"status": "stopped", "exit_code": 0})
                                        logging.info("Popularity scan stopped during singles phase")
                                        _stopped = True
                                    else:
                                        _log_scan_session_complete("singles")
                                else:
                                    logging.info(f"Phase 3/3: singles detection skipped (ran within last {_PHASE_COOLDOWN_DAYS} days)")

                            if _stopped:
                                break

                            logging.info("Popularity and Singles scan cycle %d (all phases) completed", _pop_cycle)

                        if metadata_only:
                            _scan_type_label = "metadata_lookup_scan"
                        elif singles_only or singles_with_missing_popularity:
                            _scan_type_label = "singles_scan"
                        else:
                            _scan_type_label = "popularity_scan"

                        if not perpetual_enabled:
                            _write_progress_with_current_artist(popularity_progress_file, _scan_type_label, False, {"status": "complete", "exit_code": 0})
                            break

                        # Perpetual: check for stop before looping.
                        with scan_lock:
                            if scan_process_popularity is None or _is_stop_requested_from_progress(popularity_progress_file):
                                _write_progress_with_current_artist(popularity_progress_file, _scan_type_label, False, {"status": "stopped", "exit_code": 0})
                                logging.info("Popularity scan perpetual loop: stop requested after cycle %d", _pop_cycle)
                                break

                        logging.info(
                            "[POPULARITY_PERPETUAL] Cycle %d complete; perpetual mode enabled – restarting from beginning",
                            _pop_cycle,
                        )

                        # Subsequent perpetual cycles always start from the beginning.
                        _cycle_resume = None

                except Exception as e:
                    logging.error(f"Error in popularity scan: {e}", exc_info=True)
                    if metadata_only:
                        scan_type_label = "metadata_lookup_scan"
                    elif singles_only or singles_with_missing_popularity:
                        scan_type_label = "singles_scan"
                    else:
                        scan_type_label = "popularity_scan"
                    _write_progress_with_current_artist(popularity_progress_file, scan_type_label, False, {"status": "error", "error": str(e), "exit_code": 1})
            
            scan_thread = threading.Thread(target=run_popularity_scan_bg, daemon=False)
            scan_thread.start()
            scan_process_popularity = {'thread': scan_thread, 'type': 'popularity'}
            
            if singles_with_missing_popularity:
                flash("✅ Singles scan started (fetches popularity only for new albums)", "success")
            elif singles_only:
                flash("✅ Singles detection scan started (single detection only)", "success")
            elif metadata_only:
                flash("✅ Metadata lookup scan started (metadata + cover detection only)", "success")
            else:
                mode_desc = {
                    'all': 'Metadata + Popularity + Singles',
                    'force': 'Metadata + Popularity + Singles (Forced)',
                    'missing': 'Missing Only',
                    'metadata': 'Metadata + Cover Detection Only',
                    'metadata_force': 'Metadata + Cover Detection (Forced)',
                    'singles': 'Singles Detection Only',
                    'singles_resume': 'Singles Resume from Last',
                    'singles_resume_force': 'Singles Resume (Forced)',
                    'resume': 'Resume from Last',
                    'resume_force': 'Resume (Forced)'
                }.get(mode, 'Metadata + Popularity + Singles')
                flash(f"✅ Popularity scan started ({mode_desc} scan)", "success")
            logging.info("Popularity scan thread started successfully")
        except Exception as e:
            logging.error(f"Error starting popularity scan: {e}", exc_info=True)
            flash(f"❌ Error starting popularity scan: {str(e)}", "danger")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/singles", methods=["POST"])
def scan_singles():
    """Run single detection"""
    global scan_process_singles

    with scan_lock:
        if scan_process_singles is not None:
            if isinstance(scan_process_singles, dict):
                thread = scan_process_singles.get('thread')
                if thread and thread.is_alive():
                    flash("Single detection scan is already running", "warning")
                    return redirect(url_for("dashboard"))
            elif hasattr(scan_process_singles, 'is_alive') and scan_process_singles.is_alive():
                flash("Single detection scan is already running", "warning")
                return redirect(url_for("dashboard"))

        try:
            from popularity import popularity_scan as scan_popularity_func

            singles_progress_file = os.path.join(os.path.dirname(DB_PATH), "singles_scan_progress.json")
            _write_progress_file(singles_progress_file, "singles_scan", True, {"status": "starting"})

            def run_singles_scan_bg():
                _singles_cycle = 0
                try:
                    while True:
                        _singles_cycle += 1

                        cfg = get_config()
                        perpetual_enabled = bool((cfg.get("features") or {}).get("perpetual", False))

                        completed = scan_popularity_func(
                            verbose=False,
                            force=False,
                            singles_only=True,
                            stop_progress_file=singles_progress_file,
                        )
                        if completed is False:
                            _write_progress_with_current_artist(singles_progress_file, "singles_scan", False, {"status": "stopped", "exit_code": 0})
                            logging.info("Singles scan stopped by user request")
                            break

                        logging.info("Singles scan cycle %d completed successfully", _singles_cycle)
                        _log_scan_session_complete("singles")

                        if not perpetual_enabled:
                            _write_progress_with_current_artist(singles_progress_file, "singles_scan", False, {"status": "complete", "exit_code": 0})
                            break

                        # Perpetual: check for stop before looping.
                        with scan_lock:
                            if scan_process_singles is None or _is_stop_requested_from_progress(singles_progress_file):
                                _write_progress_with_current_artist(singles_progress_file, "singles_scan", False, {"status": "stopped", "exit_code": 0})
                                logging.info("Singles scan perpetual loop: stop requested after cycle %d", _singles_cycle)
                                break

                        logging.info(
                            "[SINGLES_PERPETUAL] Cycle %d complete; perpetual mode enabled – restarting from beginning",
                            _singles_cycle,
                        )

                except Exception as e:
                    logging.error(f"Error in singles scan: {e}", exc_info=True)
                    _write_progress_with_current_artist(singles_progress_file, "singles_scan", False, {"status": "error", "error": str(e), "exit_code": 1})

            scan_thread = threading.Thread(target=run_singles_scan_bg, daemon=False)
            scan_thread.start()
            scan_process_singles = {'thread': scan_thread, 'type': 'singles'}

            flash("✅ Singles detection scan started (single detection only)", "success")
        except Exception as e:
            logging.error(f"Error starting singles scan: {e}", exc_info=True)
            flash(f"❌ Error starting single detection scan: {str(e)}", "danger")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/mood", methods=["POST"])
def scan_mood():
    """Deprecated AcousticBrainz route: forward to Essentia scan."""
    flash("AcousticBrainz mood scan has been retired. Starting Essentia mood scan instead.", "info")
    return scan_essentia_mood()


@app.route("/scan/essentia-mood", methods=["POST"])
def scan_essentia_mood():
    """Run Essentia local-ML mood/genre enrichment scan.

    Query parameters
    ----------------
    mode       – ``force`` to re-scan tracks that already have tags; default ``all``
    artist     – restrict scan to this artist (optional)
    album      – restrict scan to this album (requires artist)
    track_id   – restrict scan to a single track by ID (optional)
    """
    global scan_process_essentia_mood

    mode = request.args.get('mode', 'all')
    force_scan = (mode == 'force' or mode == 'resume_force')

    # Scoped-scan filters (from form or query string)
    artist_filter = (request.form.get('artist') or request.args.get('artist') or '').strip()
    album_filter = (request.form.get('album') or request.args.get('album') or '').strip()
    track_id_filter = (request.form.get('track_id') or request.args.get('track_id') or '').strip()

    # Resume from checkpoint artist when requested.
    resume_from_artist = ""
    if mode in ('resume', 'resume_force'):
        try:
            from scan_resume import get_last_scanned_artist
            resume_from_artist = (get_last_scanned_artist(scan_type="essentia_mood", db_path=DB_PATH) or "").strip()
            if resume_from_artist and not artist_filter and not album_filter and not track_id_filter:
                logging.info(f"Essentia resume mode: continuing from artist '{resume_from_artist}'")
        except Exception as resume_err:
            logging.warning(f"Essentia resume mode: failed to resolve checkpoint artist: {resume_err}")

    # When scanning a specific artist, album, or track the user is explicitly
    # targeting those items, so force a rescan even if they already have tags.
    if artist_filter or album_filter or track_id_filter:
        force_scan = True

    # Determine redirect target after launch
    if track_id_filter:
        redirect_target = url_for("track_detail", track_id=track_id_filter)
    elif artist_filter and album_filter:
        redirect_target = url_for("album_detail", artist=artist_filter, album=album_filter)
    elif artist_filter:
        redirect_target = url_for("artist_detail", name=artist_filter)
    else:
        redirect_target = url_for("dashboard")

    with scan_lock:
        if scan_process_essentia_mood is not None:
            if isinstance(scan_process_essentia_mood, dict):
                thread = scan_process_essentia_mood.get('thread')
                if thread and thread.is_alive():
                    flash("Essentia mood scan is already running", "warning")
                    return redirect(redirect_target)
            elif hasattr(scan_process_essentia_mood, 'is_alive') and scan_process_essentia_mood.is_alive():
                flash("Essentia mood scan is already running", "warning")
                return redirect(redirect_target)

        try:
            db_dir = os.path.dirname(DB_PATH)
            essentia_progress_file = os.path.join(db_dir, "essentia_mood_scan_progress.json")
            # Preserve any existing resume checkpoint so the scan can recover if
            # this worker is killed before it writes its first "running" checkpoint.
            _starting_payload: dict = {"status": "starting"}
            try:
                with open(essentia_progress_file, "r", encoding="utf-8") as _ef:
                    _ep = json.load(_ef)
                    _checkpoint = (_ep.get("resume_from_artist") or "").strip()
                    if _checkpoint:
                        _starting_payload["resume_from_artist"] = _checkpoint
            except Exception:
                pass
            _write_progress_file(essentia_progress_file, "essentia_mood_scan", True, _starting_payload)

            # Capture filter values for the closure
            _artist_filter = artist_filter
            _album_filter = album_filter
            _track_id_filter = track_id_filter
            _force_scan = force_scan

            def run_essentia_mood_scan_bg():
                try:
                    from essentia_mood_scan import run_essentia_mood_scan
                    from helpers.config_helpers import get_config

                    _essentia_cycle = 0
                    # On first cycle honour the caller's resume_from_artist; subsequent
                    # perpetual cycles always scan from the beginning.
                    _cycle_resume_from_artist = resume_from_artist

                    while True:
                        _essentia_cycle += 1

                        # Re-read config on every cycle so live changes to essentia
                        # settings (and perpetual on/off) take effect immediately.
                        cfg = get_config()
                        essentia_cfg = cfg.get("essentia", {}) if isinstance(cfg, dict) else {}
                        script_path = essentia_cfg.get("script_path", "")
                        models_dir = essentia_cfg.get("models_dir", "")
                        mood_threshold = float(essentia_cfg.get("mood_threshold", 0.005))
                        per_file_timeout = int(essentia_cfg.get("per_file_timeout", 300))
                        tag_genres = bool(essentia_cfg.get("tag_genres", False))
                        num_genres = int(essentia_cfg.get("num_genres", 3))
                        genre_threshold = float(essentia_cfg.get("genre_threshold", 15.0))
                        genre_format = essentia_cfg.get("genre_format", "parent_child")
                        tag_moods = bool(essentia_cfg.get("tag_moods", True))
                        parse_json_features = bool(essentia_cfg.get("parse_json_features", True))
                        delete_json_after_import = bool(essentia_cfg.get("delete_json_after_import", True))
                        json_output_dir = str(essentia_cfg.get("json_output_dir", "") or "").strip()
                        cpu_nice = int(essentia_cfg.get("cpu_nice", 10))
                        inter_file_delay = float(essentia_cfg.get("inter_file_delay", 0.0))

                        # Scoped scans (artist/album/track filter) are never looped.
                        perpetual_enabled = (
                            bool((cfg.get("features") or {}).get("perpetual", False))
                            and not _artist_filter
                            and not _album_filter
                            and not _track_id_filter
                        )

                        result = run_essentia_mood_scan(
                            script_path=script_path,
                            models_dir=models_dir,
                            mood_threshold=mood_threshold,
                            per_file_timeout=per_file_timeout,
                            force=_force_scan,
                            progress_file=essentia_progress_file,
                            tag_genres=tag_genres,
                            num_genres=num_genres,
                            genre_threshold=genre_threshold,
                            genre_format=genre_format,
                            tag_moods=tag_moods,
                            parse_json_features=parse_json_features,
                            delete_json_after_import=delete_json_after_import,
                            json_output_dir=json_output_dir,
                            artist_filter=_artist_filter,
                            album_filter=_album_filter,
                            track_id_filter=_track_id_filter,
                            resume_from_artist=_cycle_resume_from_artist,
                            cpu_nice=cpu_nice,
                            inter_file_delay=inter_file_delay,
                        )

                        if result.get("stopped"):
                            _write_progress_with_current_artist(
                                essentia_progress_file,
                                "essentia_mood_scan",
                                False,
                                {
                                    "status": "stopped",
                                    "exit_code": 0,
                                    "processed_artists": result.get("processed_artists", 0),
                                    "total_artists": result.get("total_artists", 0),
                                    "scanned_tracks": result.get("scanned_tracks", 0),
                                    "updated_tracks": result.get("updated_tracks", 0),
                                    "synced_files": result.get("synced_files", 0),
                                },
                            )
                            logging.info("Essentia mood scan stopped by user request")
                            log_unified("Essentia Scan - Stopped by user request")
                            break

                        if result.get("error"):
                            _write_progress_with_current_artist(
                                essentia_progress_file,
                                "essentia_mood_scan",
                                False,
                                {"status": "error", "error": result["error"], "exit_code": 1},
                            )
                            logging.error("Essentia mood scan error: %s", result["error"])
                            log_unified(f"Essentia Scan - Error: {result['error']}", level=logging.ERROR)
                            break

                        # Successful cycle.
                        logging.info(
                            "Essentia mood scan cycle %d completed: %s tracks scanned, %s updated, %s file tags synced",
                            _essentia_cycle,
                            result.get("scanned_tracks", 0),
                            result.get("updated_tracks", 0),
                            result.get("synced_files", 0),
                        )

                        if not perpetual_enabled:
                            # Non-perpetual: write completion and exit.
                            _write_progress_with_current_artist(
                                essentia_progress_file,
                                "essentia_mood_scan",
                                False,
                                {
                                    "status": "complete",
                                    "exit_code": 0,
                                    "processed_artists": result.get("processed_artists", 0),
                                    "total_artists": result.get("total_artists", 0),
                                    "scanned_tracks": result.get("scanned_tracks", 0),
                                    "updated_tracks": result.get("updated_tracks", 0),
                                    "synced_files": result.get("synced_files", 0),
                                },
                            )
                            _log_scan_session_complete("essentia_mood")
                            break

                        # Perpetual mode: check for a stop request before looping.
                        with scan_lock:
                            if scan_process_essentia_mood is None or _is_stop_requested_from_progress(essentia_progress_file):
                                _write_progress_with_current_artist(
                                    essentia_progress_file,
                                    "essentia_mood_scan",
                                    False,
                                    {"status": "stopped", "exit_code": 0},
                                )
                                logging.info("Essentia mood scan perpetual loop: stop requested after cycle %d", _essentia_cycle)
                                log_unified("Essentia Scan - Stopped by user request")
                                break

                        logging.info(
                            "[ESSENTIA_PERPETUAL] Cycle %d complete; perpetual mode enabled – restarting from beginning",
                            _essentia_cycle,
                        )
                        log_unified(
                            f"Essentia Scan - Cycle {_essentia_cycle} complete, perpetual mode – restarting"
                        )

                        # If nothing was scanned this cycle (all tracks already tagged),
                        # wait briefly before polling again to avoid a tight spin loop.
                        if result.get("scanned_tracks", 0) == 0:
                            time.sleep(60)

                        # Subsequent perpetual cycles always start from the beginning.
                        _cycle_resume_from_artist = ""

                except Exception as e:
                    logging.error(f"Error in Essentia mood scan: {e}", exc_info=True)
                    log_unified(f"Essentia Scan - Error: {e}", level=logging.ERROR)
                    _write_progress_with_current_artist(
                        essentia_progress_file,
                        "essentia_mood_scan",
                        False,
                        {"status": "error", "error": str(e), "exit_code": 1},
                    )

            scan_thread = threading.Thread(target=run_essentia_mood_scan_bg, daemon=False)
            scan_thread.start()
            scan_process_essentia_mood = {'thread': scan_thread, 'type': 'essentia_mood'}

            scope_label = ""
            if _track_id_filter:
                scope_label = f" (track {_track_id_filter})"
            elif _artist_filter and _album_filter:
                scope_label = f" ({_artist_filter} – {_album_filter})"
            elif _artist_filter:
                scope_label = f" ({_artist_filter})"
            flash(
                f"✅ Essentia scan started ({'Forced' if _force_scan else 'Incremental'} mode{scope_label})",
                "success",
            )
        except Exception as e:
            logging.error(f"Error starting Essentia mood scan: {e}", exc_info=True)
            flash(f"❌ Error starting Essentia mood scan: {str(e)}", "danger")

    return redirect(redirect_target)


@app.route("/scan/mp3-import", methods=["POST"])
def scan_mp3_import():
    """Run MP3 metadata import scan"""
    global scan_process_mp3_import
    
    with scan_lock:
        # Check if scan is already running
        if scan_process_mp3_import is not None:
            is_running = False
            try:
                if hasattr(scan_process_mp3_import, "is_alive"):
                    is_running = scan_process_mp3_import.is_alive()
                elif hasattr(scan_process_mp3_import, "poll"):
                    is_running = scan_process_mp3_import.poll() is None
            except Exception:
                is_running = False

            if is_running:
                flash("MP3 metadata import scan is already running", "warning")
                return redirect(url_for("dashboard"))
        
        try:
            # Import MP3ImportScanner here to avoid issues if file isn't ready
            from scan_mp3_import import MP3ImportScanner
            
            # Get parameters from request
            directory = request.form.get('directory', None)
            dry_run = request.form.get('dry_run', '').lower() == 'on'
            
            # Use database mode by default (reads from tracks table)
            # If directory is specified, use directory mode instead
            mode = 'directory' if directory else 'database'
            
            # Create scanner instance
            scanner = MP3ImportScanner(directory=directory, dry_run=dry_run, verbose=True, mode=mode)
            
            # Start scanner in a background thread
            def run_scan():
                try:
                    results = scanner.scan()
                    logging.info(f"MP3 import scan completed: {results}")
                except Exception as e:
                    logging.error(f"MP3 import scan failed: {e}", exc_info=True)
            
            import threading
            scan_thread = threading.Thread(target=run_scan, daemon=True)
            scan_thread.start()
            scan_process_mp3_import = scan_thread
            
            flash("MP3 metadata import scan started. Check progress below.", "success")
            
        except ImportError as e:
            logging.error(f"Failed to import MP3ImportScanner: {e}")
            flash(f"❌ Failed to start MP3 import scan: {str(e)}", "error")
        except Exception as e:
            logging.error(f"Error starting MP3 import scan: {e}", exc_info=True)
            flash(f"❌ Error starting MP3 import scan: {str(e)}", "error")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/stop", methods=["POST"])
def scan_stop():
    """Stop the running scan (main scan process)"""
    global scan_process
    
    with scan_lock:
        if scan_process and scan_process.poll() is None:
            scan_process.terminate()
            scan_process.wait(timeout=10)
            flash("Main scan stopped", "info")
        else:
            flash("No main scan is currently running", "warning")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/stop-navidrome", methods=["POST"])
def scan_stop_navidrome():
    """Stop the Navidrome sync scan"""
    global scan_process_navidrome
    
