@app.route("/api/slskd/search", methods=["POST"])
def slskd_search():
    """Proxy endpoint for slskd search API - returns search ID for polling"""
    cfg = get_config()
    slskd_config = cfg.get("slskd", {})
    
    if not slskd_config.get("enabled"):
        return jsonify({"error": "slskd integration not enabled"}), 400
    
    query = _normalize_slskd_query(request.json.get("query", ""))
    if not query:
        return jsonify({"error": "Query parameter required"}), 400
    
    web_url = slskd_config.get("web_url", "http://localhost:5030")
    api_key = slskd_config.get("api_key", "")
    
    try:
        # Use a plain session with no automatic retries for interactive searches.
        # The shared api_clients session retries 429 responses up to 3 times with
        # exponential backoff (1s+2s+4s per attempt), which turns a fast 429 into
        # a ~31s wait per start_search attempt.  With max_attempts=3 that can exceed
        # the 60s browser timeout.  A plain session returns 429 immediately so the
        # manual retry loop in start_search() controls the cadence instead.
        plain_session = requests.Session()
        client = SlskdClient(web_url, api_key, http_session=plain_session, enabled=True)

        # Optimistic fast path: attempt the search without pre-emptive cleanup.
        # When slskd has no active searches (the common interactive case), this
        # returns immediately (<1s).  Pre-emptively calling _clear_stale_slskd_searches
        # before every search issues a DELETE for every accumulated completed search
        # (each with a 4s timeout); with even 15 stale background-search entries that
        # path can exceed the 60s browser timeout *before* the POST to slskd is sent —
        # which is why users observe "Request timed out" even when slskd appears idle.
        search_id = client.start_search(query, timeout=6, max_attempts=1)

        if search_id is None:
            # First attempt failed (likely 429 due to a stale/blocking search).
            # Run the stale-search cleanup once and retry with a few more attempts.
            _clear_stale_slskd_searches(client, context="manual search")
            search_id = client.start_search(query, timeout=6, max_attempts=3)

        if not search_id:
            # Start attempts exhausted — check whether an active (non-terminal)
            # search is genuinely holding the slot.  If so, let the client queue
            # the request and auto-retry rather than surfacing a hard error.
            _ACTIVE_STATES = {"InProgress", "Requested", "Initializing"}
            try:
                active_searches = [
                    s for s in client.list_searches(timeout=4)
                    if (s.get("state") or s.get("State") or "") in _ACTIVE_STATES
                ]
            except Exception:
                active_searches = []

            if active_searches:
                a = active_searches[0]
                active_id = a.get("id") or a.get("searchId") or a.get("Id") or ""
                active_query = a.get("searchText") or a.get("query") or ""
                active_state = a.get("state") or a.get("State") or ""
                logging.info(
                    f"[SLSKD] Manual search slot busy — active search "
                    f"{active_id!r} ({active_state!r}) for '{active_query}'; "
                    f"returning slotBusy so client can queue and auto-retry"
                )
                return jsonify({
                    "slotBusy": True,
                    "activeSearchId": active_id,
                    "activeSearchQuery": active_query,
                    "activeSearchState": active_state,
                }), 202

            return jsonify({"error": "Failed to start search — slskd search slot may be busy. Try again in a moment."}), 500

        return jsonify({"searchId": search_id, "status": "searching"})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/slskd/search-slot", methods=["GET"])
def slskd_search_slot():
    """Return whether the slskd search slot is free.

    Used by the manual-search modal to poll while waiting for an active
    background search to finish before auto-starting the queued manual query.

    Response (200):
        {"slotFree": true}
      or
        {"slotFree": false, "activeSearchId": "...", "activeSearchQuery": "...",
         "activeSearchState": "..."}
    """
    cfg = get_config()
    slskd_config = cfg.get("slskd", {})

    if not slskd_config.get("enabled"):
        return jsonify({"error": "slskd integration not enabled"}), 400

    web_url = slskd_config.get("web_url", "http://localhost:5030")
    api_key = slskd_config.get("api_key", "")

    try:
        plain_session = requests.Session()
        client = SlskdClient(web_url, api_key, http_session=plain_session, enabled=True)
        searches = client.list_searches(timeout=4)
        _ACTIVE_STATES = {"InProgress", "Requested", "Initializing"}
        active = [
            s for s in searches
            if (s.get("state") or s.get("State") or "") in _ACTIVE_STATES
        ]
        if active:
            a = active[0]
            return jsonify({
                "slotFree": False,
                "activeSearchId": a.get("id") or a.get("searchId") or a.get("Id") or "",
                "activeSearchQuery": a.get("searchText") or a.get("query") or "",
                "activeSearchState": a.get("state") or a.get("State") or "",
            })
        return jsonify({"slotFree": True})
    except Exception as e:
        logging.error(f"[SLSKD] Error checking search slot: {e}")
        return jsonify({"error": "Failed to check search slot status"}), 500


@app.route("/api/slskd/search/<search_id>", methods=["GET"])
def slskd_search_results(search_id):
    """Poll for Soulseek search results"""
    cfg = get_config()
    slskd_config = cfg.get("slskd", {})
    
    if not slskd_config.get("enabled"):
        return jsonify({"error": "slskd integration not enabled"}), 400
    
    web_url = slskd_config.get("web_url", "http://localhost:5030")
    api_key = slskd_config.get("api_key", "")
    
    try:
        client = SlskdClient(web_url, api_key, enabled=True)
        responses, state, is_complete = client.get_search_results(search_id)
        
        results = []
        for resp in responses:
            if hasattr(resp, 'files'):
                for file in resp.files:
                    results.append({
                        "username": resp.username,
                        "filename": file.filename,
                        "size": file.size,
                        "size_mb": f"{file.size_mb:.2f}",
                        "bitrate": file.bitrate,
                        "sample_rate": file.sample_rate,
                        "length": file.length,
                        "duration": file.duration_formatted,
                    })
        
        response_count = len(responses) if responses else 0
        logging.info(f"[SLSKD] search_id={search_id}, responses={response_count}, files={len(results)}, state={state}, complete={is_complete}")
        
        if is_complete and response_count == 0:
            logging.warning(f"[SLSKD] Search {search_id} completed with 0 responses - check if slskd service is reachable at {web_url}")
        elif is_complete and len(results) == 0:
            logging.warning(f"[SLSKD] Search {search_id} got {response_count} responses but 0 files - peers may not have matching files")
        
        return jsonify({
            "results": results,
            "state": state,
            "responseCount": response_count,
            "fileCount": len(results),
            "isComplete": is_complete
        })
    except Exception as e:
        logging.error(f"[SLSKD] Error getting search results for {search_id}: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({"error": str(e)}), 500


@app.route("/scan/navidrome", methods=["POST"])
def scan_navidrome():
    """Run Navidrome import-only scan (no popularity/singles)."""
    global scan_process_navidrome
    
    # Get scan mode from query parameters (default: "all")
    mode = request.args.get('mode', 'all')  # all, force, missing, resume, resume_force
    restart_requested = str(request.args.get('restart', '0')).strip().lower() in ('1', 'true', 'yes', 'on')
    force_start = str(request.args.get('force_start', '0')).strip().lower() in ('1', 'true', 'yes', 'on')

    with scan_lock:
        if scan_process_navidrome is not None:
            scan_already_running = False
            if isinstance(scan_process_navidrome, dict):
                thread = scan_process_navidrome.get('thread')
                if thread and thread.is_alive():
                    scan_already_running = True
            elif hasattr(scan_process_navidrome, 'is_alive') and scan_process_navidrome.is_alive():
                scan_already_running = True

            if scan_already_running and not force_start:
                return jsonify({"scan_running": True, "message": "A Navidrome scan is already running. Do you want to start a new scan anyway?"}), 409
        
        try:
            db_dir = os.path.dirname(DB_PATH)
            nav_progress_file = os.path.join(db_dir, "navidrome_scan_progress.json")
            # For resume modes, preserve current_artist so get_last_scanned_artist()
            # can read it directly from the file instead of falling back to the DB.
            if mode in ('resume', 'resume_force'):
                _write_progress_with_current_artist(nav_progress_file, "navidrome_scan", True, {"status": "starting"})
            else:
                _write_progress_file(nav_progress_file, "navidrome_scan", True, {"status": "starting"})
            
            def run_navidrome_import_bg():
                global scan_process_navidrome
                _nav_cycle = 0
                _cycle_is_first = True
                try:
                    # Ensure singles/rating pipeline stays off during Navidrome metadata-only import
                    os.environ["SPTNR_SKIP_SINGLES"] = "1"

                    checkpoint_path = os.path.join(os.path.dirname(DB_PATH), "navidrome_scan_checkpoint.json")

                    while True:
                        _nav_cycle += 1

                        cfg = get_config()
                        perpetual_enabled = bool((cfg.get("features") or {}).get("perpetual", False))

                        logging.info(f"Starting Navidrome import-only scan (mode={mode}, cycle={_nav_cycle})")
                        log_debug(f"[NAVIDROME_SCAN] Background thread cycle {_nav_cycle} started (mode={mode}, restart_requested={restart_requested}, force_start={force_start})")

                        if _cycle_is_first and restart_requested and os.path.exists(checkpoint_path):
                            try:
                                os.remove(checkpoint_path)
                                logging.info("Restart requested: cleared Navidrome checkpoint to start from beginning")
                            except Exception as checkpoint_err:
                                logging.warning(f"Restart requested but failed to clear checkpoint: {checkpoint_err}")

                        log_debug("[NAVIDROME_SCAN] Calling build_artist_index()")
                        artist_map = build_artist_index()
                        artists = list(artist_map.items())
                        total = len(artists)
                        log_debug(f"[NAVIDROME_SCAN] build_artist_index() returned {total} artists")

                        if total == 0:
                            logging.warning("[NAVIDROME_SCAN] No artists returned by build_artist_index() — scan will not process any artists")

                        # Check if we have a checkpoint from a previous scan or if resume mode is active
                        start_idx = 0
                        last_scanned_artist = None

                        # For resume mode (first cycle only), get last scanned artist
                        if _cycle_is_first and (mode == 'resume' or mode == 'resume_force'):
                            from scan_resume import get_last_scanned_artist
                            last_scanned_artist = get_last_scanned_artist(scan_type="navidrome", db_path=DB_PATH)
                            if last_scanned_artist:
                                logging.info(f"Resume mode: Found last scanned artist '{last_scanned_artist}'")
                            else:
                                log_debug("[NAVIDROME_SCAN] Resume mode active but no last scanned artist found; starting from beginning")
                        # Otherwise check checkpoint file (first cycle only)
                        elif _cycle_is_first and (not restart_requested) and os.path.exists(checkpoint_path):
                            try:
                                with open(checkpoint_path, 'r') as f:
                                    checkpoint = json.load(f)
                                    last_scanned_artist = checkpoint.get("last_scanned_artist")
                                log_debug(f"[NAVIDROME_SCAN] Checkpoint found: last_scanned_artist='{last_scanned_artist}'")
                            except Exception as e:
                                logging.warning(f"Error reading checkpoint: {e}, starting from beginning")

                        # Find the index of the last scanned artist
                        if last_scanned_artist:
                            for idx, (artist_name, _) in enumerate(artists):
                                if artist_name == last_scanned_artist:
                                    start_idx = idx  # Start from this artist (rescan it completely)
                                    logging.info(f"Resuming Navidrome scan from artist index {start_idx} ('{last_scanned_artist}')")
                                    break
                            else:
                                log_debug(f"[NAVIDROME_SCAN] Last scanned artist '{last_scanned_artist}' not found in artist list; starting from beginning")

                        # Determine force and filter logic based on mode
                        force_rescan = (mode == 'force' or mode == 'resume_force')
                        filter_missing = (mode == 'missing')
                        log_debug(f"[NAVIDROME_SCAN] Starting artist loop from index {start_idx}/{total} (force_rescan={force_rescan}, filter_missing={filter_missing})")

                        _nav_stopped = False

                        # Scan artists starting from checkpoint or beginning
                        for idx, (artist_name, info) in enumerate(artists[start_idx:], start=start_idx):
                            # Check if scan should stop
                            with scan_lock:
                                stop_requested = scan_process_navidrome is None or _is_stop_requested_from_progress(nav_progress_file)
                                if stop_requested:
                                    logging.info("Navidrome scan stop signal received, exiting gracefully")
                                    log_debug(f"[NAVIDROME_SCAN] Stop signal at artist index {idx} ('{artist_name}')")
                                    _write_progress_with_current_artist(nav_progress_file, "navidrome_scan", False, {"status": "stopped", "exit_code": 0})
                                    _nav_stopped = True
                                    break

                            log_debug(f"[NAVIDROME_SCAN] scan_artist_to_db: idx={idx}/{total} artist='{artist_name}' id={info.get('id')}")
                            scan_artist_to_db(
                                artist_name,
                                info.get("id"),
                                verbose=False,
                                force=force_rescan,
                                filter_missing=filter_missing,
                                processed_artists=idx,
                                total_artists=total
                            )

                            # Update checkpoint with the last scanned artist
                            try:
                                with open(checkpoint_path, 'w') as f:
                                    json.dump({"last_scanned_artist": artist_name}, f)
                            except Exception as e:
                                logging.warning(f"Error saving checkpoint: {e}")

                        if _nav_stopped:
                            break

                        # Clear checkpoint when scan completes successfully
                        if os.path.exists(checkpoint_path):
                            os.remove(checkpoint_path)

                        logging.info("Navidrome import-only scan completed")
                        log_debug(f"[NAVIDROME_SCAN] Scan cycle {_nav_cycle} complete: processed {total} artists")
                        _mark_navidrome_first_full_import_complete(scan_source="manual")
                        _sync_new_navidrome_album_artists_fast(trigger_source="manual_post_import")
                        _maybe_start_post_navidrome_mp3_import(trigger_source="manual_post_import")
                        _log_scan_session_complete("navidrome", total)

                        if not perpetual_enabled:
                            _write_progress_with_current_artist(nav_progress_file, "navidrome_scan", False, {"status": "complete", "exit_code": 0})
                            break

                        # Perpetual: check for stop before looping.
                        with scan_lock:
                            if scan_process_navidrome is None or _is_stop_requested_from_progress(nav_progress_file):
                                _write_progress_with_current_artist(nav_progress_file, "navidrome_scan", False, {"status": "stopped", "exit_code": 0})
                                logging.info("Navidrome scan perpetual loop: stop requested after cycle %d", _nav_cycle)
                                break

                        logging.info(
                            "[NAVIDROME_PERPETUAL] Cycle %d complete; perpetual mode enabled – restarting from beginning",
                            _nav_cycle,
                        )

                        # Subsequent perpetual cycles always scan from the beginning.
                        _cycle_is_first = False

                except Exception as e:
                    logging.error(f"Error in Navidrome import-only scan: {e}", exc_info=True)
                    log_debug(f"[NAVIDROME_SCAN] Unhandled exception in background thread: {e}", exc_info=True)
                    _write_progress_with_current_artist(nav_progress_file, "navidrome_scan", False, {"status": "error", "error": str(e), "exit_code": 1})
                finally:
                    # Clear skip flag so popularity/singles scans run normally elsewhere
                    os.environ.pop("SPTNR_SKIP_SINGLES", None)
            
            scan_thread = threading.Thread(target=run_navidrome_import_bg, daemon=False)
            scan_thread.start()
            scan_process_navidrome = {'thread': scan_thread, 'type': 'navidrome'}
            mode_desc = {
                'all': 'Full', 
                'force': 'Full (Forced)', 
                'missing': 'Missing Only',
                'resume': 'Resume from Last',
                'resume_force': 'Resume (Forced)'
            }.get(mode, 'Full')
            flash(f"✅ Navidrome import started ({mode_desc} scan)", "success")
        except Exception as e:
            logging.error(f"Error starting Navidrome import: {e}", exc_info=True)
            flash(f"❌ Error starting Navidrome import: {str(e)}", "danger")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/combined", methods=["POST"])
def scan_combined():
    """Run combined scan per artist: Navidrome -> Metadata -> Popularity -> Singles -> Mood."""
    global scan_process_combined
    
    # Get scan mode from query parameters (default: "all")
    mode = request.args.get('mode', 'all')  # all, force, resume, resume_force
    restart_requested = str(request.args.get('restart', '0')).strip().lower() in ('1', 'true', 'yes', 'on')
    force_start = str(request.args.get('force_start', '0')).strip().lower() in ('1', 'true', 'yes', 'on')

    with scan_lock:
        if scan_process_combined is not None:
            scan_already_running = False
            if isinstance(scan_process_combined, dict):
                thread = scan_process_combined.get('thread')
                if thread and thread.is_alive():
                    scan_already_running = True
            elif hasattr(scan_process_combined, 'is_alive') and scan_process_combined.is_alive():
                scan_already_running = True

            if scan_already_running and not force_start:
                return jsonify({"scan_running": True, "message": "A combined scan is already running. Do you want to start a new scan anyway?"}), 409

        # Cross-process guard: another gunicorn worker may have already started the
        # scan (the in-memory scan_process_combined is per-worker).  Check the shared
        # progress file to detect a recent start so duplicate workers back off.
        if not force_start:
            try:
                db_dir = os.path.dirname(DB_PATH)
                combined_progress_file = os.path.join(db_dir, "combined_scan_progress.json")
                if os.path.exists(combined_progress_file):
                    with open(combined_progress_file, "r", encoding="utf-8") as _pf:
                        _pdata = json.load(_pf)
                    if _pdata.get("is_running"):
                        _last = _pdata.get("last_updated", "")
                        if _last:
                            _age = (datetime.now() - datetime.fromisoformat(_last)).total_seconds()
                            if _age < 60:
                                logging.info(
                                    "[SCAN] Cross-process guard: combined scan progress file shows "
                                    f"is_running=True (age={_age:.1f}s); skipping duplicate start"
                                )
                                return jsonify({"scan_running": True, "message": "A combined scan was just started by another process."}), 409
            except Exception as _guard_err:
                logging.debug(f"[SCAN] Cross-process guard check failed (non-fatal): {_guard_err}")

        try:
            db_dir = os.path.dirname(DB_PATH)
            combined_progress_file = os.path.join(db_dir, "combined_scan_progress.json")
            _write_progress_file(combined_progress_file, "combined_scan", True, {"status": "starting"})
            
            def run_combined_scan_bg():
                global scan_process_combined
                # Define checkpoint_path early so it's available in exception handlers
                checkpoint_path = os.path.join(os.path.dirname(DB_PATH), "combined_scan_checkpoint.json")
                try:
                    logging.info(f"Starting combined scan (mode={mode})")
                    from popularity import popularity_scan as scan_popularity_func
                    from essentia_mood_scan import run_essentia_mood_scan
                    from helpers.config_helpers import get_config

                    if restart_requested and os.path.exists(checkpoint_path):
                        try:
                            os.remove(checkpoint_path)
                            logging.info("Restart requested: cleared combined checkpoint to start from beginning")
                        except Exception as checkpoint_err:
                            logging.warning(f"Restart requested but failed to clear combined checkpoint: {checkpoint_err}")

                    # Sort helper defined once; reused across perpetual cycles.
                    def _combined_scan_sort_key(item):
                        name = item[0] if item[0] else ''
                        if not name:
                            return ('~', '')
                        first_char = name[0].upper()
                        if first_char in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
                            return (first_char, name.lower())
                        return ('#', name.lower())

                    _perpetual_cycle = 0
                    while True:
                        _perpetual_cycle += 1

                        # Build (or refresh) the artist index at the start of each cycle so
                        # newly-added artists are picked up in perpetual runs.
                        try:
                            artist_map = build_artist_index()
                            artists = list(artist_map.items())
                            artists.sort(key=_combined_scan_sort_key)
                            total = len(artists)
                        except Exception as _idx_err:
                            logging.error(
                                f"[COMBINED_PERPETUAL] Error building artist index in cycle "
                                f"{_perpetual_cycle}: {_idx_err}",
                                exc_info=True,
                            )
                            # Check for a stop request before sleeping and retrying.
                            with scan_lock:
                                if scan_process_combined is None or _is_stop_requested_from_progress(combined_progress_file):
                                    _write_progress_with_current_artist(combined_progress_file, "combined_scan", False, {"status": "stopped", "exit_code": 0})
                                    break
                            time.sleep(60)
                            continue

                        # First cycle honours the original mode (resume/force/all).
                        # Subsequent perpetual cycles always do a non-forced full pass.
                        if _perpetual_cycle == 1:
                            force_rescan = (mode == 'force' or mode == 'resume_force')
                        else:
                            force_rescan = False

                        # Determine start index: only apply resume logic on the first cycle.
                        start_idx = 0
                        if _perpetual_cycle == 1 and (mode == 'resume' or mode == 'resume_force'):
                            last_scanned_artist = None
                            if os.path.exists(checkpoint_path):
                                try:
                                    with open(checkpoint_path, 'r') as f:
                                        checkpoint = json.load(f)
                                        last_scanned_artist = checkpoint.get("last_scanned_artist")
                                    if last_scanned_artist:
                                        logging.info(f"Resume mode: Found last scanned artist '{last_scanned_artist}' in checkpoint")
                                    else:
                                        logging.warning("Resume mode: Checkpoint exists but has no last_scanned_artist")
                                except Exception as e:
                                    logging.warning(f"Resume mode: Error reading checkpoint: {e}")

                            if not last_scanned_artist:
                                try:
                                    from scan_resume import get_last_scanned_artist
                                    last_scanned_artist = get_last_scanned_artist(scan_type="combined", db_path=DB_PATH)
                                    if last_scanned_artist:
                                        logging.info(f"Resume mode: Using progress fallback artist '{last_scanned_artist}'")
                                    else:
                                        logging.warning("Resume mode: No fallback artist found in progress metadata")
                                except Exception as resume_err:
                                    logging.warning(f"Resume mode: Could not read fallback progress metadata: {resume_err}")

                            if last_scanned_artist:
                                for idx, (artist_name, _) in enumerate(artists):
                                    if artist_name == last_scanned_artist:
                                        start_idx = idx  # Start from this artist (rescan it completely)
                                        logging.info(f"Resuming combined scan from artist index {start_idx} ('{last_scanned_artist}')")
                                        break
                                else:
                                    logging.warning(f"Resume mode: Artist '{last_scanned_artist}' not found in current artist index; starting from beginning")
                            else:
                                logging.warning("Resume mode: No checkpoint/progress artist found, starting from beginning")

                        # Process each artist sequentially
                        for idx, (artist_name, info) in enumerate(artists[start_idx:], start=start_idx+1):
                            # Check if scan should stop
                            with scan_lock:
                                stop_requested = scan_process_combined is None or _is_stop_requested_from_progress(combined_progress_file)
                                if stop_requested:
                                    logging.info("Combined scan stop signal received, exiting gracefully")
                                    # Preserve checkpoint for potential resume
                                    _write_progress_with_current_artist(combined_progress_file, "combined_scan", False, {"status": "stopped", "exit_code": 0})
                                    return
                        
                            artist_id = info.get("id")
                        
                            logging.info(f"[{idx}/{total}] Processing artist: {artist_name}")
                        
                            # Update combined progress immediately so the dashboard shows the
                            # current artist before the (potentially slow) Navidrome import runs.
                            # This also ensures the combined_scan progress file stays current
                            # throughout the navidrome step (scan_artist_to_db is told to write
                            # here instead of navidrome_scan_progress.json).
                            _write_progress_file(combined_progress_file, "combined_scan", True, {
                                "status": "running",
                                "current_artist": artist_name,
                                "processed_artists": idx,
                                "total_artists": total,
                                "percent_complete": int((idx / total) * 100),
                                "last_updated": datetime.now().isoformat(),
                            })

                            # Step 1: Navidrome import for this artist
                            # Note: filter_missing is always False because we process each artist explicitly
                            # The combined scan handles all artists in sequence, unlike bulk scans
                            logging.info(f"  → Navidrome import for {artist_name}")
                            try:
                                scan_artist_to_db(
                                    artist_name, 
                                    artist_id, 
                                    verbose=False, 
                                    force=force_rescan,
                                    filter_missing=False,  # Combined scan processes all artists explicitly
                                    processed_artists=idx, 
                                    total_artists=total,
                                    progress_file=combined_progress_file,
                                    progress_scan_type="combined_scan",
                                )
                            except Exception as e:
                                logging.error(f"Error in Navidrome import for {artist_name}: {e}")
                                # Continue with next steps even if Navidrome import fails
                        
                            # Step 2: Metadata lookup stage for this artist
                            logging.info(f"  → Metadata lookup scan for {artist_name}")
                            try:
                                completed = scan_popularity_func(
                                    verbose=False, 
                                    force=force_rescan,
                                    artist_filter=artist_name,
                                    metadata_only=True,
                                    stop_progress_file=combined_progress_file,
                                    caller_scan_type="combined_scan",
                                )
                                if completed is False:
                                    logging.info(f"Combined scan stop detected during metadata step for {artist_name}")
                                    _write_progress_with_current_artist(combined_progress_file, "combined_scan", False, {"status": "stopped", "exit_code": 0})
                                    return
                            except Exception as e:
                                logging.error(f"Error in metadata lookup scan for {artist_name}: {e}")

                            # Step 3: Popularity-only scan for this artist
                            logging.info(f"  → Popularity scan for {artist_name}")
                            try:
                                completed = scan_popularity_func(
                                    verbose=False,
                                    force=force_rescan,
                                    artist_filter=artist_name,
                                    popularity_only=True,
                                    stop_progress_file=combined_progress_file,
                                    caller_scan_type="combined_scan",
                                )
                                if completed is False:
                                    logging.info(f"Combined scan stop detected during popularity stage for {artist_name}")
                                    _write_progress_with_current_artist(combined_progress_file, "combined_scan", False, {"status": "stopped", "exit_code": 0})
                                    return
                            except Exception as e:
                                logging.error(f"Error in popularity-only scan for {artist_name}: {e}")

                            # Step 4: Singles-only scan for this artist
                            logging.info(f"  → Singles scan for {artist_name}")
                            try:
                                completed = scan_popularity_func(
                                    verbose=False,
                                    force=force_rescan,
                                    artist_filter=artist_name,
                                    singles_only=True,
                                    stop_progress_file=combined_progress_file,
                                    caller_scan_type="combined_scan",
                                )
                                if completed is False:
                                    logging.info(f"Combined scan stop detected during singles stage for {artist_name}")
                                    _write_progress_with_current_artist(combined_progress_file, "combined_scan", False, {"status": "stopped", "exit_code": 0})
                                    return
                            except Exception as e:
                                logging.error(f"Error in singles-only scan for {artist_name}: {e}")

                            # Step 5: Mood scan for this artist
                            logging.info(f"  → Mood scan for {artist_name}")
                            try:
                                cfg = get_config()
                                essentia_cfg = cfg.get("essentia", {}) if isinstance(cfg, dict) else {}
                                mood_result = run_essentia_mood_scan(
                                    script_path=essentia_cfg.get("script_path", ""),
                                    models_dir=essentia_cfg.get("models_dir", ""),
                                    mood_threshold=float(essentia_cfg.get("mood_threshold", 0.005)),
                                    per_file_timeout=int(essentia_cfg.get("per_file_timeout", 300)),
                                    force=force_rescan,
                                    progress_file="",  # Don't share the standalone essentia progress file –
                                                       # a user stop of the standalone scan must not abort
                                                       # the combined scan's per-artist essentia step.
                                    tag_genres=bool(essentia_cfg.get("tag_genres", False)),
                                    num_genres=int(essentia_cfg.get("num_genres", 3)),
                                    genre_threshold=float(essentia_cfg.get("genre_threshold", 15.0)),
                                    genre_format=essentia_cfg.get("genre_format", "parent_child"),
                                    tag_moods=bool(essentia_cfg.get("tag_moods", True)),
                                    parse_json_features=bool(essentia_cfg.get("parse_json_features", True)),
                                    delete_json_after_import=bool(essentia_cfg.get("delete_json_after_import", True)),
                                    json_output_dir=str(essentia_cfg.get("json_output_dir", "") or "").strip(),
                                    artist_filter=artist_name,
                                    cpu_nice=int(essentia_cfg.get("cpu_nice", 10)),
                                    inter_file_delay=float(essentia_cfg.get("inter_file_delay", 0.0)),
                                )
                                if mood_result.get("stopped"):
                                    logging.info(f"Combined scan stop detected during mood stage for {artist_name}")
                                    _write_progress_with_current_artist(combined_progress_file, "combined_scan", False, {"status": "stopped", "exit_code": 0})
                                    return
                                if mood_result.get("error"):
                                    logging.error(f"Error in mood scan for {artist_name}: {mood_result.get('error')}")
                            except Exception as e:
                                logging.error(f"Error in mood scan for {artist_name}: {e}")
                        
                            # Update checkpoint with the last scanned artist
                            try:
                                with open(checkpoint_path, 'w') as f:
                                    json.dump({"last_scanned_artist": artist_name}, f)
                            except Exception as e:
                                logging.warning(f"Error saving combined scan checkpoint: {e}")
                    
                        # Cycle complete: clear checkpoint.
                        try:
                            if os.path.exists(checkpoint_path):
                                os.remove(checkpoint_path)
                        except Exception as _ck_err:
                            logging.warning(f"Error clearing combined scan checkpoint: {_ck_err}")

                        # Check whether perpetual mode is still enabled before looping.
                        try:
                            _cfg_perp = get_config()
                            _perpetual_enabled = bool((_cfg_perp.get("features") or {}).get("perpetual", False))
                        except Exception as _cfg_err:
                            logging.warning(
                                f"[COMBINED_PERPETUAL] Error reading config for perpetual check: {_cfg_err}; "
                                "assuming perpetual mode is still enabled"
                            )
                            _perpetual_enabled = True

                        if _perpetual_enabled:
                            logging.info(
                                f"[COMBINED_PERPETUAL] Cycle {_perpetual_cycle} complete; "
                                "perpetual mode enabled – restarting from beginning"
                            )
                            # Check for a stop request before starting the next cycle.
                            with scan_lock:
                                if scan_process_combined is None or _is_stop_requested_from_progress(combined_progress_file):
                                    _write_progress_with_current_artist(combined_progress_file, "combined_scan", False, {"status": "stopped", "exit_code": 0})
                                    break
                            # Don't write "complete" – keep the scan visible as running so
                            # a server restart will resume it rather than skip it.
                            continue

                        # Non-perpetual mode: write completion and exit the loop.
                        _write_progress_with_current_artist(combined_progress_file, "combined_scan", False, {"status": "complete", "exit_code": 0})
                        logging.info("Combined scan completed successfully")
                        break
                except Exception as e:
                    logging.error(f"Error in combined scan: {e}", exc_info=True)
                    # Keep checkpoint on error so reboot resume can continue from the last saved artist.
                    _write_progress_with_current_artist(combined_progress_file, "combined_scan", False, {"status": "error", "error": str(e), "exit_code": 1})
                finally:
                    # Ensure the combined scan progress file is never left with is_running=True
                    # after the thread exits. This covers crash scenarios where neither the success
                    # nor error path wrote a clean final state (e.g. double exception in handlers).
                    try:
                        try:
                            with open(combined_progress_file, 'r', encoding='utf-8') as _f:
                                _final_state = json.load(_f)
                        except Exception:
                            _final_state = {}
                        if _final_state.get('is_running', False):
                            _final_state['is_running'] = False
                            if not _final_state.get('status'):
                                _final_state['status'] = 'error'
                            with open(combined_progress_file, 'w', encoding='utf-8') as _f:
                                json.dump(_final_state, _f)
                    except Exception as _fe:
                        logging.error(f"Error in combined scan finally cleanup of progress file: {_fe}")
                    # Clean up thread reference when done
                    with scan_lock:
                        scan_process_combined = None
            
            # daemon=False matches other scan threads - allows scan to complete even during shutdown
            scan_thread = threading.Thread(target=run_combined_scan_bg, daemon=False)
            scan_thread.start()
            scan_process_combined = {'thread': scan_thread, 'type': 'combined'}
            mode_desc = {
                'all': 'Full', 
                'force': 'Full (Forced)',
                'resume': 'Resume from Last',
                'resume_force': 'Resume (Forced)'
            }.get(mode, 'Full')
            restart_desc = " with restart" if restart_requested else ""
            flash(f"✅ Combined scan started ({mode_desc}{restart_desc} - Navidrome → Metadata → Popularity → Singles → Mood per artist)", "success")
        except Exception as e:
            logging.error(f"Error starting combined scan: {e}", exc_info=True)
            flash(f"❌ Error starting combined scan: {str(e)}", "danger")
    
    return redirect(url_for("dashboard"))


@app.route("/api/slsk/banned-words", methods=["GET"])
def api_get_banned_words():
    """Get banned words and suggested words (high zero-result count)."""
    try:
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS slsk_banned_words (
                word TEXT PRIMARY KEY,
                is_banned BOOLEAN NOT NULL DEFAULT FALSE,
                zero_result_count INTEGER NOT NULL DEFAULT 0,
                added_at TIMESTAMP DEFAULT NOW(),
                updated_at TIMESTAMP DEFAULT NOW()
            )
        """)
        conn.commit()
        cursor.execute("""
            SELECT word, is_banned, zero_result_count, added_at, updated_at
            FROM slsk_banned_words
            ORDER BY is_banned DESC, zero_result_count DESC, word ASC
        """)
        rows = cursor.fetchall()
        conn.close()
        result = []
        for r in rows:
            if isinstance(r, dict):
                result.append(r)
            else:
                result.append({
                    'word': r[0], 'is_banned': r[1], 'zero_result_count': r[2],
                    'added_at': str(r[3]) if r[3] else None, 'updated_at': str(r[4]) if r[4] else None
                })
        return jsonify({'success': True, 'words': result}), 200
    except Exception as e:
        logging.error(f"[banned_words] GET error: {e}")
        return jsonify({'error': 'Internal server error'}), 500


@app.route("/api/slsk/banned-words", methods=["POST"])
def api_add_banned_word():
    """Add or update a banned word."""
    try:
        data = request.get_json(force=True, silent=True) or {}
        word = (data.get('word') or '').strip().lower()
        is_banned = bool(data.get('is_banned', True))
        if not word or len(word) < 2:
            return jsonify({'error': 'word must be at least 2 characters'}), 400
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS slsk_banned_words (
                word TEXT PRIMARY KEY,
                is_banned BOOLEAN NOT NULL DEFAULT FALSE,
                zero_result_count INTEGER NOT NULL DEFAULT 0,
                added_at TIMESTAMP DEFAULT NOW(),
                updated_at TIMESTAMP DEFAULT NOW()
            )
        """)
        cursor.execute("""
            INSERT INTO slsk_banned_words (word, is_banned, zero_result_count, updated_at)
            VALUES (%s, %s, 0, NOW())
            ON CONFLICT (word) DO UPDATE SET
                is_banned = EXCLUDED.is_banned,
                updated_at = NOW()
        """, (word, is_banned))
        conn.commit()
        conn.close()
        return jsonify({'success': True, 'word': word, 'is_banned': is_banned}), 200
    except Exception as e:
        logging.error(f"[banned_words] POST error: {e}")
        return jsonify({'error': 'Internal server error'}), 500


