@app.route("/api/slskd/download", methods=["POST"])
def slskd_download():
    """Proxy endpoint to download from slskd"""
    cfg = get_config()
    slskd_config = cfg.get("slskd", {})
    
    if not slskd_config.get("enabled"):
        return jsonify({"error": "slskd integration not enabled"}), 400
    
    payload = request.json or {}
    files_payload = payload.get("files")
    username = payload.get("username", "")
    filename = payload.get("filename", "")
    size = payload.get("size", 0)

    # Batch mode: expect list of files
    if files_payload:
        if not isinstance(files_payload, list):
            return jsonify({"error": "files must be a list"}), 400
        normalized_files = []
        for entry in files_payload:
            u = entry.get("username")
            f = entry.get("filename")
            if not u or not f:
                return jsonify({"error": "Each file requires username and filename"}), 400
            normalized_files.append({
                "username": u,
                "filename": f,
                "size": int(entry.get("size") or 0)
            })

        web_url = slskd_config.get("web_url", "http://localhost:5030")
        api_key = slskd_config.get("api_key", "")
        try:
            client = SlskdClient(web_url, api_key, enabled=True)
            results = client.download_files(normalized_files)
            requested = sum(item.get("requested", 0) for item in results)
            successful_users = sum(1 for item in results if item.get("success"))
            overall_success = requested > 0 and successful_users > 0
            return jsonify({
                "success": overall_success,
                "requested": requested,
                "userBatches": results
            })
        except Exception as e:
            logging.error(f"[SLSKD] Batch download error: {str(e)}")
            return jsonify({"error": str(e)}), 500
    
    if not username or not filename:
        return jsonify({"error": "Username and filename required"}), 400
    
    web_url = slskd_config.get("web_url", "http://localhost:5030")
    api_key = slskd_config.get("api_key", "")
    
    try:
        client = SlskdClient(web_url, api_key, enabled=True)
        success = client.download_file(username, filename, size)
        
        if success:
            return jsonify({"success": True, "message": "Download enqueued"})
        else:
            return jsonify({"error": "Failed to enqueue download"}), 500
            
    except Exception as e:
        logging.error(f"[SLSKD] Download error: {str(e)}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/slskd/queue-download", methods=["POST"])
def slskd_queue_download():
    """Initiate a Soulseek download that is linked to a specific download-queue item.

    Validates the request synchronously then fires the slskd enqueue and DB
    update in a background thread so the response is returned immediately,
    avoiding browser-side timeout errors when slskd is slow to respond.

    Request JSON::

        {
          "queue_id": 883,
          "username": "some_user",
          "filename": "path/to/file.flac",
          "size": 12345678
        }
    """
    cfg = get_config()
    slskd_config = cfg.get("slskd", {})

    if not slskd_config.get("enabled"):
        return jsonify({"error": "slskd integration not enabled"}), 400

    payload = request.json or {}
    queue_id_raw = payload.get("queue_id")
    queue_id = _coerce_optional_int(queue_id_raw)
    username = (payload.get("username") or "").strip()
    filename = (payload.get("filename") or "").strip()
    size = int(payload.get("size") or 0)

    if queue_id is None:
        return jsonify({"error": "queue_id is required"}), 400
    if not username or not filename:
        return jsonify({"error": "username and filename are required"}), 400

    # Quick existence check so we can return 404 synchronously.
    try:
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute(
            f"SELECT id FROM download_queue WHERE id = %s",
            (queue_id,),
        )
        if not cursor.fetchone():
            conn.close()
            return jsonify({"error": f"Queue item {queue_id} not found"}), 404
        conn.close()
    except Exception as e:
        logging.error(f"[SLSKD_QUEUE_DOWNLOAD] DB check error: {e}")
        return jsonify({"error": "Database error checking queue item"}), 500

    web_url = slskd_config.get("web_url", "http://localhost:5030")
    api_key = slskd_config.get("api_key", "")

    # Immediately mark the item as 'downloading' (with the chosen filename)
    # BEFORE starting the background thread.  This closes the race window
    # where the queue processor could still see the item as 'queued',
    # pick it up, and start a competing slskd search.  The background thread
    # then updates slskd_state to 'Requested' once slskd confirms the
    # download has been enqueued.  If slskd rejects the download the
    # background thread resets the item to 'failed' so it can be retried.
    try:
        conn_pre = get_db()
        try:
            cur_pre = conn_pre.cursor()
            cur_pre.execute(
                """
                UPDATE download_queue
                SET status = %s,
                    found_filename = %s,
                    slskd_username = %s,
                    slskd_state = %s,
                    is_manual_download = 1,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
                """,
                ("downloading", filename, username, "Pending", queue_id),
            )
            conn_pre.commit()
        finally:
            conn_pre.close()
    except Exception as pre_err:
        logging.error(f"[SLSKD_QUEUE_DOWNLOAD] Could not pre-set downloading status for queue {queue_id}: {pre_err}")
        # Continue anyway — the background thread will still try to start the download.

    def _background(q_id, uname, fname, sz, w_url, a_key):
        try:
            client = SlskdClient(w_url, a_key, enabled=True)
            success = client.download_file(username=uname, filename=fname, size=sz)
            if not success:
                logging.error(f"[SLSKD_QUEUE_DOWNLOAD] slskd rejected download for queue {q_id}: {fname!r}")
                # Reset status so the item can be retried via the normal queue flow.
                try:
                    conn_fail = get_db()
                    try:
                        cur_fail = conn_fail.cursor()
                        cur_fail.execute(
                            """
                            UPDATE download_queue
                            SET status = %s,
                                slskd_state = %s,
                                failure_reason = %s,
                                updated_at = CURRENT_TIMESTAMP
                            WHERE id = %s AND status = 'downloading'
                            """,
                            ("queued", None, "slskd rejected manual download — will retry", q_id),
                        )
                        conn_fail.commit()
                    finally:
                        conn_fail.close()
                except Exception as reset_err:
                    logging.error(f"[SLSKD_QUEUE_DOWNLOAD] Could not reset status after rejection for queue {q_id}: {reset_err}")
                return
            conn2 = get_db()
            try:
                cur2 = conn2.cursor()
                cur2.execute(
                    """
                    UPDATE download_queue
                    SET slskd_state = %s,
                        slskd_last_sync_at = %s,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = %s
                    """,
                    ("Requested", datetime.now().isoformat(), q_id),
                )
                conn2.commit()
                logging.info(f"[SLSKD_QUEUE_DOWNLOAD] Queue {q_id}: download started for {fname!r}")
            finally:
                conn2.close()
        except Exception as bg_err:
            logging.error(f"[SLSKD_QUEUE_DOWNLOAD] Background error for queue {q_id}: {bg_err}")

    t = threading.Thread(
        target=_background,
        args=(queue_id, username, filename, size, web_url, api_key),
        daemon=True,
    )
    t.start()

    return jsonify({
        "success": True,
        "message": f"Download queued for {os.path.basename(filename)}",
    })


def _normalize_slskd_filename(value):
    return str(value or '').strip().replace('\\', '/').lower()


def _resolve_slskd_transfer(client, username, transfer_id=None, filename=None, timeout=10):
    """Resolve a slskd transfer deterministically and avoid basename-collision mistakes."""
    username_norm = str(username or '').strip()
    transfer_id_norm = str(transfer_id or '').strip()
    target_name = _normalize_slskd_filename(filename)

    try:
        transfers = client.get_active_downloads(timeout=timeout) or []
    except Exception as fetch_err:
        return None, f"Could not query active transfers: {fetch_err}"

    by_id = None
    if transfer_id_norm:
        for transfer in transfers:
            tid = str(transfer.get('id') or '').strip()
            tuser = str(transfer.get('username') or '').strip()
            if tid == transfer_id_norm and (not username_norm or tuser == username_norm):
                by_id = transfer
                break
        if by_id:
            return by_id, None

    if not target_name:
        return None, "Could not resolve transfer: missing filename"

    exact = []
    basename_matches = []
    target_base = os.path.basename(target_name)

    for transfer in transfers:
        tuser = str(transfer.get('username') or '').strip()
        if username_norm and tuser != username_norm:
            continue
        transfer_name = _normalize_slskd_filename(transfer.get('filename'))
        if not transfer_name:
            continue
        if transfer_name == target_name:
            exact.append(transfer)
            continue
        if os.path.basename(transfer_name) == target_base:
            basename_matches.append(transfer)

    if len(exact) == 1:
        return exact[0], None
    if len(exact) > 1:
        return None, "Ambiguous transfer match for exact filename"

    if len(basename_matches) == 1:
        return basename_matches[0], None
    if len(basename_matches) > 1:
        return None, "Ambiguous transfer match for basename; provide transfer_id"

    return None, "Could not resolve transfer_id for this download"


@app.route("/api/slskd/cancel", methods=["POST"])
def slskd_cancel():
    """Cancel a Soulseek download"""
    cfg = get_config()
    slskd_config = cfg.get("slskd", {})

    if not slskd_config.get("enabled"):
        return jsonify({"error": "slskd integration not enabled"}), 400

    payload = request.json or {}
    queue_id_raw = payload.get("queue_id")
    queue_id = _coerce_optional_int(queue_id_raw)
    username = payload.get("username", "")
    filename = payload.get("filename", "")
    transfer_id = payload.get("transfer_id") or payload.get("remoteToken") or payload.get("id")

    # If this is queue-linked, prefer persisted transfer identity for deterministic cancel.
    if queue_id_raw is not None and str(queue_id_raw).strip() and queue_id is None:
        return jsonify({"error": "queue_id must be a valid integer"}), 400

    if queue_id is not None:
        try:
            conn = get_db()
            cursor = conn.cursor()
            cursor.execute("SELECT slskd_username, slskd_transfer_id, found_filename FROM download_queue WHERE id = %s", (queue_id,))
            row = cursor.fetchone()
            conn.close()
            if row:
                rowd = dict(row) if hasattr(row, 'keys') else {
                    'slskd_username': row[0], 'slskd_transfer_id': row[1], 'found_filename': row[2]
                }
                username = (rowd.get('slskd_username') or username or "").strip()
                transfer_id = rowd.get('slskd_transfer_id') or transfer_id
                filename = rowd.get('found_filename') or filename
        except Exception as queue_lookup_err:
            logging.debug(f"[SLSKD] queue cancel lookup failed: {queue_lookup_err}")

    if not username:
        return jsonify({"error": "Username required"}), 400
    if not transfer_id and not filename:
        return jsonify({"error": "Either transfer_id (or remoteToken) or filename is required"}), 400

    web_url = slskd_config.get("web_url", "http://localhost:5030")
    api_key = slskd_config.get("api_key", "")

    try:
        client = SlskdClient(web_url, api_key, enabled=True)
        transfer, resolve_err = _resolve_slskd_transfer(
            client,
            username=username,
            transfer_id=transfer_id,
            filename=filename,
            timeout=10,
        )

        if not transfer:
            status_code = 409 if resolve_err and "Ambiguous" in resolve_err else 404
            return jsonify({"error": resolve_err or "Could not resolve transfer_id for this download"}), status_code

        resolved_transfer_id = str(transfer.get("id") or "").strip()
        resolved_username = str(transfer.get("username") or username).strip()
        if not resolved_transfer_id or not resolved_username:
            return jsonify({"error": "Resolved transfer is missing username/id"}), 404

        success = client.cancel_download(resolved_username, resolved_transfer_id, remove=True, timeout=10)

        if success:
            if queue_id is not None:
                try:
                    from download_queue_manager import update_queue_item
                    update_queue_item(
                        queue_id,
                        slskd_transfer_id=None,
                        slskd_state='Completed, Cancelled',
                        slskd_queue_position=None,
                        slskd_last_sync_at=datetime.now().isoformat(),
                    )
                except Exception as queue_sync_err:
                    logging.debug(f"[SLSKD] queue cancel sync warning: {queue_sync_err}")
            return jsonify({"success": True, "message": "Download cancelled successfully", "transfer_id": resolved_transfer_id})
        return jsonify({"error": "Failed to cancel download in slskd"}), 500

    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/slskd/retry", methods=["POST"])
def slskd_retry():
    """Retry a failed Soulseek download"""
    cfg = get_config()
    slskd_config = cfg.get("slskd", {})

    if not slskd_config.get("enabled"):
        return jsonify({"error": "slskd integration not enabled"}), 400

    payload = request.json or {}
    queue_id_raw = payload.get("queue_id")
    queue_id = _coerce_optional_int(queue_id_raw)
    username = payload.get("username", "")
    filename = payload.get("filename", "")
    size = payload.get("size", 0)
    transfer_id = payload.get("transfer_id") or payload.get("remoteToken") or payload.get("id")

    # Queue-linked retries should use stored transfer identity/filename first.
    if queue_id_raw is not None and str(queue_id_raw).strip() and queue_id is None:
        return jsonify({"error": "queue_id must be a valid integer"}), 400

    if queue_id is not None:
        try:
            conn = get_db()
            cursor = conn.cursor()
            cursor.execute("SELECT slskd_username, slskd_transfer_id, found_filename FROM download_queue WHERE id = %s", (queue_id,))
            row = cursor.fetchone()
            conn.close()
            if row:
                rowd = dict(row) if hasattr(row, 'keys') else {
                    'slskd_username': row[0], 'slskd_transfer_id': row[1], 'found_filename': row[2]
                }
                username = (rowd.get('slskd_username') or username or "").strip()
                transfer_id = rowd.get('slskd_transfer_id') or transfer_id
                filename = rowd.get('found_filename') or filename
        except Exception as queue_lookup_err:
            logging.debug(f"[SLSKD] queue retry lookup failed: {queue_lookup_err}")

    if not username or not filename:
        return jsonify({"error": "Username and filename required"}), 400

    web_url = slskd_config.get("web_url", "http://localhost:5030")
    api_key = slskd_config.get("api_key", "")

    try:
        client = SlskdClient(web_url, api_key, enabled=True)

        # First cancel any stale/failed transfer deterministically (best-effort).
        transfer, resolve_err = _resolve_slskd_transfer(
            client,
            username=username,
            transfer_id=transfer_id,
            filename=filename,
            timeout=10,
        )
        if transfer:
            try:
                resolved_transfer_id = str(transfer.get("id") or "").strip()
                resolved_username = str(transfer.get("username") or username).strip()
                if resolved_transfer_id and resolved_username:
                    client.cancel_download(resolved_username, resolved_transfer_id, remove=True, timeout=10)
                    transfer_id = resolved_transfer_id
            except Exception as cancel_err:
                logging.debug(f"[SLSKD] Retry cancel step warning: {cancel_err}")
        elif resolve_err and "Ambiguous" in resolve_err:
            return jsonify({"error": resolve_err}), 409

        # Then re-queue it and refresh tracked transfer identity.
        enqueue_result = client.enqueue_download_with_tracking(username=username, filename=filename, size=int(size), timeout=10)
        success = bool(enqueue_result.get('success'))

        if success:
            new_transfer_id = (enqueue_result.get('transfer_id') or '').strip() or str(transfer_id or "")
            if queue_id is not None:
                try:
                    from download_queue_manager import update_queue_item
                    update_queue_item(
                        queue_id,
                        status='downloading',
                        slskd_transfer_id=(enqueue_result.get('transfer_id') or '').strip() or None,
                        slskd_username=(enqueue_result.get('username') or username).strip() or None,
                        slskd_state=(enqueue_result.get('state') or 'Requested').strip(),
                        slskd_queue_position=enqueue_result.get('queue_position'),
                        slskd_last_sync_at=datetime.now().isoformat(),
                    )
                except Exception as queue_sync_err:
                    logging.debug(f"[SLSKD] queue retry sync warning: {queue_sync_err}")
            return jsonify({"success": True, "message": f"Download retry queued for {filename}", "transfer_id": new_transfer_id})
        else:
            return jsonify({"error": "Failed to re-queue download"}), 500

    except Exception as e:
        logging.error(f"[SLSKD] Retry download error: {str(e)}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/slskd/search-again", methods=["POST"])
def slskd_search_again():
    """Search for a file again to find alternative sources"""
    cfg = get_config()
    slskd_config = cfg.get("slskd", {})
    
    if not slskd_config.get("enabled"):
        return jsonify({"error": "slskd integration not enabled"}), 400
    
    filename = request.json.get("filename", "")
    
    if not filename:
        return jsonify({"error": "Filename required"}), 400
    
    web_url = slskd_config.get("web_url", "http://localhost:5030")
    api_key = slskd_config.get("api_key", "")
    
    try:
        # Use a plain session (no automatic retry backoff) so the optimistic
        # fast path returns immediately when slskd is idle.
        plain_session = requests.Session()
        client = SlskdClient(web_url, api_key, http_session=plain_session, enabled=True)

        # Optimistic fast path: attempt without pre-emptive cleanup.
        # Pre-emptively calling _clear_stale_slskd_searches issues one DELETE
        # per accumulated completed search (each with a 4 s timeout); with many
        # stale entries that can exceed the 60 s browser timeout before the POST
        # to slskd is even sent.
        search_id = client.start_search(filename, timeout=6, max_attempts=1)

        if search_id is None:
            # First attempt failed (likely 429 — stale search blocking the slot).
            # Run stale-search cleanup once, then retry.
            _clear_stale_slskd_searches(client, context="search-again")
            search_id = client.start_search(filename, timeout=6, max_attempts=3)
        
        if search_id:
            return jsonify({
                "success": True,
                "message": f"Searching for '{filename}'",
                "search_id": search_id
            })
        if not search_id:
            return jsonify({"error": "Failed to start search — slskd search slot may be busy. Try again in a moment."}), 500
            
    except Exception as e:
        logging.error(f"[SLSKD] Search again error: {str(e)}")
        return jsonify({"error": str(e)}), 500


