@app.route("/api/musicbrainz/search", methods=["POST"])
def api_musicbrainz_search():
    """Search MusicBrainz for releases + local cached missing releases"""
    payload = request.get_json(silent=True) or {}
    query = str(payload.get("query", "")).strip()
    artist_only = bool(payload.get("artist_only", False))
    if not query:
        return jsonify({"error": "Query parameter required"}), 400
    
    try:
        releases = []
        seen_ids = set()  # Track IDs to avoid duplicates
        
        # First, search local database for matching artists with missing releases
        try:
            conn = get_db()
            cursor = conn.cursor()
            placeholder = "%s"
            
            # Search local missing releases with either broad term mode or artist-only mode.
            if artist_only:
                cursor.execute(f"""
                    SELECT DISTINCT artist, release_id, title, primary_type, first_release_date, cover_art_url, category
                    FROM missing_releases
                    WHERE LOWER(artist) = LOWER({placeholder})
                    ORDER BY first_release_date DESC
                    LIMIT 250
                """, (query,))
            else:
                query_pattern = f"%{query}%"
                cursor.execute(f"""
                    SELECT DISTINCT artist, release_id, title, primary_type, first_release_date, cover_art_url, category
                    FROM missing_releases
                    WHERE artist LIKE {placeholder} OR title LIKE {placeholder}
                    ORDER BY artist, first_release_date DESC
                    LIMIT 50
                """, (query_pattern, query_pattern))
            
            local_results = cursor.fetchall()
            conn.close()
            
            # Add local results
            for row in local_results:
                artist_name = row['artist']
                release_id = row['release_id']
                title = row['title']
                primary_type = row['primary_type']
                first_release_date = row['first_release_date']
                cover_art_url = row['cover_art_url']
                category = row['category']
                
                # Create unique ID to check for duplicates
                result_id = f"{artist_name}_{release_id}"
                if result_id not in seen_ids:
                    seen_ids.add(result_id)
                    releases.append({
                        "id": release_id,
                        "title": title,
                        "artist": artist_name,
                        "artist-credit": [{"name": artist_name}],
                        "primary_type": primary_type,
                        "first_release_date": first_release_date,
                        "cover_art_url": cover_art_url,
                        "category": category,
                        "source": "local"
                    })
        except Exception as e:
            logging.warning(f"[MB_SEARCH] Error searching local database: {e}")
        
        # Then search MusicBrainz
        try:
            headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
            
            # Search for release groups
            url = "https://musicbrainz.org/ws/2/release-group"
            mb_query = f'artist:"{query}"' if artist_only else query
            params = {
                "fmt": "json",
                "limit": 250 if artist_only else 50,
                "query": mb_query
            }
            
            resp = requests.get(url, headers=headers, params=params, timeout=10)
            resp.raise_for_status()
            data = resp.json()
            
            for rg in data.get("release-groups", []) or []:
                rg_id = rg.get("id", "")
                primary_type = rg.get("primary-type", "")
                artist_credit = rg.get("artist-credit", [])
                artist_name = artist_credit[0].get("name", "Unknown") if artist_credit else "Unknown"
                
                # Check if we already have this from local DB
                result_id = f"{artist_name}_{rg_id}"
                if result_id in seen_ids:
                    continue
                
                seen_ids.add(result_id)
                
                # Determine category
                category = primary_type
                if primary_type.lower() == "ep":
                    category = "EP"
                elif primary_type.lower() == "single":
                    category = "Single"
                elif primary_type.lower() == "album":
                    category = "Album"
                
                releases.append({
                    "id": rg_id,
                    "title": rg.get("title", ""),
                    "artist": artist_name,
                    "artist-credit": artist_credit,
                    "primary_type": primary_type,
                    "first_release_date": rg.get("first-release-date", ""),
                    "cover_art_url": f"https://coverartarchive.org/release-group/{rg_id}/front-500" if rg_id else "",
                    "category": category,
                    "source": "musicbrainz"
                })
        except requests.exceptions.Timeout:
            logging.warning("[MB_SEARCH] MusicBrainz request timed out")
        except Exception as e:
            logging.error(f"[MB_SEARCH] MusicBrainz search error: {e}")
        
        # Sort by artist and release date
        if artist_only:
            releases.sort(key=lambda x: x.get("first_release_date", ""), reverse=True)
        else:
            releases.sort(key=lambda x: (x.get("artist", "").lower(), x.get("first_release_date", "")), reverse=True)
        
        return jsonify({"releases": releases, "total": len(releases)})
        
    except Exception as e:
        logging.error(f"[MB_SEARCH] Error: {e}")
        return jsonify({"error": str(e)}), 500
def _normalize_download_method(requested_method, *, default_method="slskd", context="download request"):
    """Resolve the effective download transport based on enabled integrations."""
    method = str(requested_method or default_method).strip().lower()
    if method == "soulseek":
        method = "slskd"

    if method not in {"slskd", "qbittorrent"}:
        return None, "Invalid method. Use 'slskd' or 'qbittorrent'"

    cfg = get_config() or {}
    slskd_enabled = bool((cfg.get("slskd") or {}).get("enabled", False))
    qbit_enabled = bool((cfg.get("qbittorrent") or {}).get("enabled", False))

    if method == "qbittorrent" and not qbit_enabled:
        if slskd_enabled:
            logging.info(
                "[QUEUE_ROUTE] qBittorrent requested for %s but disabled; routing through Soulseek",
                context,
            )
            return "slskd", None
        return None, "qBittorrent is disabled and Soulseek is not enabled"

    if method == "slskd" and not slskd_enabled:
        if qbit_enabled:
            logging.info(
                "[QUEUE_ROUTE] Soulseek requested for %s but disabled; routing through qBittorrent",
                context,
            )
            return "qbittorrent", None
        return None, "Soulseek is disabled and qBittorrent is not enabled"

    return method, None


def _normalize_queue_source(requested_source, *, default_source="soulseek", context="queue request"):
    """Resolve download_queue source using the transport availability rules."""
    source = str(requested_source or default_source).strip().lower()
    if source == "slskd":
        source = "soulseek"

    method = "slskd" if source == "soulseek" else source
    normalized_method, error_message = _normalize_download_method(
        method,
        default_method="slskd",
        context=context,
    )
    if error_message:
        return None, error_message

    return ("soulseek" if normalized_method == "slskd" else "qbittorrent"), None


@app.route("/api/musicbrainz/download", methods=["POST"])
def api_musicbrainz_download():
    """Initiate a managed download from MusicBrainz release with full track integration"""
    data = request.json or {}
    release_id = data.get("release_id", "").strip()
    release_title = data.get("release_title", "").strip()
    artist = data.get("artist", "").strip()
    method = data.get("method", "").strip().lower()
    persistent_search = data.get("persistent_search", False)
    max_retries = data.get("max_retries", 3)
    session_id = data.get("session_id", None)
    
    if not all([release_id, release_title, artist]):
        return jsonify({"error": "Missing required parameters"}), 400

    method, method_error = _normalize_download_method(
        method,
        default_method="slskd",
        context=f"MusicBrainz release {release_id}",
    )
    if method_error:
        return jsonify({"error": method_error}), 400
    
    try:
        # Fetch MusicBrainz release data to get all tracks
        from musicbrainz_release_manager import get_manager
        manager = get_manager()
        mb_data = manager.fetch_release_from_musicbrainz(release_id)
        
        if not mb_data or 'releases' not in mb_data or not mb_data['releases']:
            logging.warning(f"[MB_DOWNLOAD] No release data found for {release_id}, proceeding with simple download")
            # Fall back to simple download if no MB data available
            return _simple_mb_download(release_id, release_title, artist, method, persistent_search, max_retries, session_id)
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Verify session exists if provided
        if session_id:
            cursor.execute(f"SELECT id FROM playlist_download_sessions WHERE id = {placeholder}", (session_id,))
            if not cursor.fetchone():
                conn.close()
                return jsonify({"error": f"Session {session_id} not found"}), 404
        
        # Extract release year
        release_year = None
        if mb_data['releases']:
            date_str = mb_data['releases'][0].get('first-release-date', '')
            release_year = int(date_str.split('-')[0]) if date_str else None
        if not release_year:
            from datetime import datetime as dt
            release_year = dt.now().year
        
        # Count total tracks
        total_tracks = 0
        if 'releases' in mb_data:
            for release in mb_data['releases']:
                for medium in release.get('media', []):
                    total_tracks += len(medium.get('tracks', []))
        
        # Create managed_downloads entry
        download_query = f"{artist} - {release_title}"
        cursor.execute(f"""
            INSERT INTO managed_downloads 
            (release_id, release_title, artist, method, status, download_query, persistent_search, max_retries, session_id, created_at, updated_at)
            VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, 'queued', {placeholder}, {placeholder}, {placeholder}, {placeholder}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            RETURNING id
        """, (release_id, release_title, artist, method, download_query, 1 if persistent_search else 0, max_retries, session_id))
        tracking_row = cursor.fetchone()
        tracking_id = _row_get(tracking_row, 'id', 0)
        # Add all tracks to download_queue to ensure they're tracked
        # under a single import_group (queue folder) for this release request.
        # Use mbid_ prefix so _resolve_canonical_release_mbid extracts the MBID directly.
        import_group = f"mbid_{release_id}"
        # Build a release-specific cover art URL so the correct artwork is fetched
        # even for compilations that lack art at the release-group level.
        cover_art_url = f"https://coverartarchive.org/release/{release_id}/front-500"
        queue_source = 'soulseek' if method == 'slskd' else 'qbittorrent'
        queue_ids = []
        track_count = 0
        if 'releases' in mb_data:
            for release in mb_data['releases']:
                for medium in release.get('media', []):
                    for track in medium.get('tracks', []):
                        track_count += 1
                        track_title = track.get('title', f'Track {track_count}')
                        track_number = track.get('position', track_count)
                        duration = track.get('length', 0)
                        isrc = track.get('isrc', None)
                        
                        # Use provided artist or extract from track/recording data.
                        # With inc=recordings+artist-credits the per-track artist
                        # is available on the recording object; fall back to the
                        # album artist for non-VA releases where artist-credit is
                        # absent.
                        recording = track.get('recording', {})
                        rec_credits = (
                            recording.get('artist-credit')
                            or track.get('artist-credit')
                            or []
                        )
                        if rec_credits:
                            track_artist = _build_artist_credit_string(rec_credits) or artist
                        else:
                            track_artist = artist
                        recording_mbid = recording.get('id') or None
                        
                        # Create search query for individual track (artist - title format, no album)
                        search_query = f"{track_artist} - {track_title}".strip()
                        
                        # Add to download_queue
                        cursor.execute(f"""
                            INSERT INTO download_queue
                            (artist, album, title, search_query, source, status,
                             import_group, import_type,
                             release_id, release_mbid, release_source,
                             track_number, album_artist, year, recording_mbid, cover_art_url,
                             created_at, updated_at)
                            VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, 'queued',
                                    {placeholder}, 'album',
                                    {placeholder}, {placeholder}, 'musicbrainz',
                                    {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder},
                                   CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
                            RETURNING id
                        """, (track_artist, release_title, track_title, search_query, queue_source,
                              import_group,
                              release_id, release_id,
                              track_number, artist, release_year, recording_mbid, cover_art_url))
                        queue_row = cursor.fetchone()
                        queue_id = queue_row[0] if queue_row else None
                        if queue_id is not None:
                            queue_ids.append(queue_id)
        
        conn.commit()
        conn.close()
        
        logging.info(f"[MB_DOWNLOAD] Release {release_id}: Created tracking ID {tracking_id}, added {len(queue_ids)} tracks to queue")
        
        # Initiate search in background thread
        if method == "slskd":
            thread = threading.Thread(target=_initiate_slskd_download_bg, args=(tracking_id, download_query), daemon=True)
            thread.start()
        elif method == "qbittorrent":
            thread = threading.Thread(target=_initiate_qbit_download_bg, args=(tracking_id, download_query), daemon=True)
            thread.start()
        
        return jsonify({
            "success": True,
            "tracking_id": tracking_id,
            "message": f"Download queued for {release_title} ({len(queue_ids)} tracks)",
            "total_tracks": total_tracks,
            "queued_tracks": len(queue_ids),
            "persistent_search": persistent_search,
            "session_id": session_id
        }), 201
        
    except Exception as e:
        logging.error(f"[MB_DOWNLOAD] Error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"error": str(e)}), 500


def _simple_mb_download(release_id, release_title, artist, method, persistent_search, max_retries, session_id):
    """Fallback simple download when MusicBrainz data not available"""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        download_query = f"{artist} - {release_title}"
        
        cursor.execute(f"""
            INSERT INTO managed_downloads 
            (release_id, release_title, artist, method, status, download_query, persistent_search, max_retries, session_id, created_at, updated_at)
            VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, 'queued', {placeholder}, {placeholder}, {placeholder}, {placeholder}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            RETURNING id
        """, (release_id, release_title, artist, method, download_query, 1 if persistent_search else 0, max_retries, session_id))
        tracking_row = cursor.fetchone()
        tracking_id = _row_get(tracking_row, 'id', 0)
        conn.commit()
        conn.close()
        
        if method == "slskd":
            thread = threading.Thread(target=_initiate_slskd_download_bg, args=(tracking_id, download_query), daemon=True)
            thread.start()
        elif method == "qbittorrent":
            thread = threading.Thread(target=_initiate_qbit_download_bg, args=(tracking_id, download_query), daemon=True)
            thread.start()
        
        return jsonify({
            "success": True,
            "tracking_id": tracking_id,
            "message": f"Download queued for {release_title} (MusicBrainz data not available, using simple search)",
            "persistent_search": persistent_search,
            "session_id": session_id
        }), 201
        
    except Exception as e:
        logging.error(f"[MB_DOWNLOAD_SIMPLE] Error: {e}")
        return jsonify({"error": str(e)}), 500


def _initiate_slskd_download_bg(tracking_id, query):
    """Background thread worker to initiate a Soulseek search and wait for user selection"""
    try:
        cfg = get_config()
        slskd_config = cfg.get("slskd", {})
        
        if not slskd_config.get("enabled"):
            conn = get_db()
            cursor = conn.cursor()
            placeholder = "%s"
            cursor.execute(f"""
                UPDATE managed_downloads 
                SET status = 'error', error_message = 'Soulseek not enabled', updated_at = CURRENT_TIMESTAMP
                WHERE id = {placeholder}
            """, (tracking_id,))
            conn.commit()
            conn.close()
            return
        
        web_url = slskd_config.get("web_url", "http://localhost:5030")
        api_key = slskd_config.get("api_key", "")
        
        client = SlskdClient(web_url, api_key, enabled=True)
        _clear_stale_slskd_searches(client, context="background search")
        search_id = client.start_search(query)
        
        if not search_id:
            conn = get_db()
            cursor = conn.cursor()
            placeholder = "%s"
            cursor.execute(f"""
                UPDATE managed_downloads 
                SET status = 'error', error_message = 'Failed to start search', updated_at = CURRENT_TIMESTAMP
                WHERE id = {placeholder}
            """, (tracking_id,))
            conn.commit()
            conn.close()
            return
        
        # Store search_id and update status
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        cursor.execute(f"""
            UPDATE managed_downloads 
            SET status = 'searching', external_id = {placeholder}, updated_at = CURRENT_TIMESTAMP
            WHERE id = {placeholder}
        """, (search_id, tracking_id))
        conn.commit()
        conn.close()
        
        # Start monitoring in a sub-thread
        def monitor_slskd_search():
            import time
            from difflib import SequenceMatcher

            max_wait = 60  # Wait up to 60 seconds for results (raised from 30 s)
            start_time = time.time()
            all_files = []  # Collect all results, not just the best

            # Parse query into artist/title so we can use SequenceMatcher-based
            # scoring that matches what the queue processor uses.
            parts = query.split(' - ', 1)
            if len(parts) == 2:
                _q_artist = parts[0].strip().lower()
                _q_title = parts[1].strip().lower()
            else:
                _q_artist = ""
                _q_title = query.strip().lower()

            def _sim(a, b):
                if not a or not b:
                    return 0.0
                return SequenceMatcher(None, a, b).ratio()

            def _score_file(raw_filename):
                """Return a relevance score [0, 1] for a candidate filename."""
                fn = str(raw_filename or "").replace('\\', '/').lower()
                basename = fn.rsplit('/', 1)[-1] if '/' in fn else fn
                # Strip extension for text matching
                stem = basename.rsplit('.', 1)[0] if '.' in basename else basename
                # Artist similarity
                artist_score = _sim(_q_artist, stem) if _q_artist else 0.5
                # Title similarity
                title_score = _sim(_q_title, stem)
                # Boost for preferred audio extensions
                ext_boost = 0.0
                if any(fn.endswith(ext) for ext in ('.mp3', '.flac', '.m4a', '.aac', '.ogg')):
                    ext_boost = 0.05
                return (artist_score * 0.4 + title_score * 0.6) + ext_boost

            while time.time() - start_time < max_wait:
                try:
                    responses, state, is_complete = client.get_search_results(search_id)

                    if responses:
                        # Collect all matching files with scores
                        for response in responses:
                            if hasattr(response, 'files') and response.files:
                                for file_info in response.files:
                                    raw_filename = file_info.filename if hasattr(file_info, 'filename') else file_info.get('filename', '')
                                    raw_size = file_info.size if hasattr(file_info, 'size') else file_info.get('size', 0)

                                    match_score = _score_file(raw_filename)

                                    if match_score >= 0.3:  # Only include files with at least 30% match
                                        all_files.append({
                                            'username': response.username if hasattr(response, 'username') else 'Unknown',
                                            'filename': raw_filename,
                                            'size': raw_size,
                                            'match_score': match_score
                                        })

                    if is_complete:
                        break

                    time.sleep(1)

                except Exception as e:
                    logging.error(f"[SLSKD_MONITOR] Error monitoring search {search_id}: {e}")
                    break
            
            # Save results and wait for user selection
            if all_files:
                try:
                    conn2 = get_db()
                    cursor2 = conn2.cursor()
                    placeholder = "%s"

                    # Sort by match score (descending)
                    all_files.sort(key=lambda x: x['match_score'], reverse=True)

                    # Insert all results into database
                    for file_result in all_files:
                        cursor2.execute(f"""
                            INSERT INTO slskd_search_results
                            (download_id, username, filename, size, match_score)
                            VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder})
                        """, (tracking_id, file_result['username'], file_result['filename'],
                              file_result['size'], file_result['match_score']))

                    # Update status to awaiting_selection
                    cursor2.execute(f"""
                        UPDATE managed_downloads 
                        SET status = 'awaiting_selection', updated_at = CURRENT_TIMESTAMP
                        WHERE id = {placeholder}
                    """, (tracking_id,))

                    conn2.commit()
                    conn2.close()

                    logging.info(f"[SLSKD_MONITOR] Found {len(all_files)} results for download {tracking_id}, awaiting user selection")

                except Exception as e:
                    logging.error(f"[SLSKD_MONITOR] Error saving results: {e}")
                    try:
                        conn2 = get_db()
                        cursor2 = conn2.cursor()
                        placeholder = "%s"
                        cursor2.execute(f"""
                            UPDATE managed_downloads 
                            SET status = 'error', error_message = {placeholder}, updated_at = CURRENT_TIMESTAMP
                            WHERE id = {placeholder}
                        """, (str(e), tracking_id))
                        conn2.commit()
                        conn2.close()
                    except:
                        pass
            else:
                # No good matches found
                try:
                    conn2 = get_db()
                    cursor2 = conn2.cursor()
                    placeholder = "%s"
                    cursor2.execute(f"""
                        UPDATE managed_downloads 
                        SET status = 'error', error_message = 'No matching files found', updated_at = CURRENT_TIMESTAMP
                        WHERE id = {placeholder}
                    """, (tracking_id,))
                    conn2.commit()
                    conn2.close()
                except:
                    pass
        
        # Start monitoring thread
        thread = threading.Thread(target=monitor_slskd_search, daemon=True)
        thread.start()
            
    except Exception as e:
        logging.error(f"[SLSKD_INIT] Error for tracking {tracking_id}: {e}")
        try:
            conn = get_db()
            cursor = conn.cursor()
            placeholder = "%s"
            cursor.execute(f"""
                UPDATE managed_downloads 
                SET status = 'error', error_message = {placeholder}, updated_at = CURRENT_TIMESTAMP
                WHERE id = {placeholder}
            """, (str(e), tracking_id))
            conn.commit()
            conn.close()
        except:
            pass


def _initiate_slskd_download(tracking_id, query, cursor, conn):
    """Helper to initiate a Soulseek download"""
    placeholder = "%s"
    try:
        cfg = get_config()
        slskd_config = cfg.get("slskd", {})
        
        if not slskd_config.get("enabled"):
            cursor.execute(f"""
                UPDATE managed_downloads 
                SET status = 'error', error_message = 'Soulseek not enabled', updated_at = CURRENT_TIMESTAMP
                WHERE id = {placeholder}
            """, (tracking_id,))
            conn.commit()
            return
        
        web_url = slskd_config.get("web_url", "http://localhost:5030")
        api_key = slskd_config.get("api_key", "")
        
        client = SlskdClient(web_url, api_key, enabled=True)
        _clear_stale_slskd_searches(client, context="background search")
        search_id = client.start_search(query)
        
        if not search_id:
            cursor.execute(f"""
                UPDATE managed_downloads 
                SET status = 'error', error_message = 'Failed to start search', updated_at = CURRENT_TIMESTAMP
                WHERE id = {placeholder}
            """, (tracking_id,))
            conn.commit()
            return
        
        # Store search_id and update status
        cursor.execute(f"""
            UPDATE managed_downloads 
            SET status = 'searching', external_id = {placeholder}, updated_at = CURRENT_TIMESTAMP
            WHERE id = {placeholder}
        """, (search_id, tracking_id))
        conn.commit()
        
        # Start a thread to monitor the search and download when results are available
        def monitor_slskd_search():
            import time
            # Increased timeout to 60 seconds to handle slow Soulseek peer responses
            # Each peer has a 5-second timeout; many timeouts need more time to collect results
            max_wait = 60
            start_time = time.time()
            best_file = None
            best_match_score = 0
            
            while time.time() - start_time < max_wait:
                try:
                    responses, state, is_complete = client.get_search_results(search_id)
                    
                    if responses:
                        # Look through responses for best matching files
                        for response in responses:
                            if hasattr(response, 'files') and response.files and len(response.files) > 0:
                                for file_info in response.files:
                                    # Get filename - handle both dict and object formats
                                    filename = file_info.get('filename', '') if isinstance(file_info, dict) else getattr(file_info, 'filename', '')
                                    filename_lower = str(filename).lower()
                                    query_lower = query.lower()
                                    
                                    # Simple scoring: count matching words
                                    query_words = query_lower.split()
                                    matches = sum(1 for word in query_words if word in filename_lower)
                                    match_score = matches / len(query_words) if query_words else 0
                                    
                                    # Prefer files with audio extensions
                                    if any(filename_lower.endswith(ext) for ext in ['.mp3', '.flac', '.m4a', '.aac', '.ogg']):
                                        match_score *= 1.2
                                    else:
                                        match_score *= 0.5  # Lower score for non-audio
                                    
                                    if match_score > best_match_score:
                                        best_match_score = match_score
                                        best_file = {
                                            'username': response.username if hasattr(response, 'username') else 'Unknown',
                                            'filename': filename,
                                            'size': file_info.get('size', 0) if isinstance(file_info, dict) else getattr(file_info, 'size', 0),
                                            'match_score': match_score
                                        }
                    
                    if is_complete and best_file and best_match_score >= 0.3:
                        # Stop early if search is complete and we have a good match
                        logging.debug(f"[SLSKD_MONITOR] Search complete with good match score {best_match_score}")
                        break
                    
                    if is_complete and not best_file:
                        # Stop if search is complete but no files found
                        logging.debug(f"[SLSKD_MONITOR] Search complete but no files found")
                        break
                    
                    time.sleep(1)
                    
                except Exception as e:
                    logging.error(f"[SLSKD_MONITOR] Error monitoring search {search_id}: {e}")
                    break
            
            # Download the best file found
            if best_file and best_match_score >= 0.3:  # Minimum 30% match
                try:
                    conn2 = get_db()
                    cursor2 = conn2.cursor()
                    placeholder = "%s"
                    
                    logging.info(f"[SLSKD_MONITOR] Downloading best match with score {best_match_score}: {best_file['filename'][:80]}")
                    
                    # Start the download
                    success = client.download_file(
                        best_file['username'],
                        best_file['filename'],
                        best_file['size']
                    )
                    
                    if success:
                        cursor2.execute(f"""
                            UPDATE managed_downloads 
                            SET status = 'downloading', updated_at = CURRENT_TIMESTAMP
                            WHERE id = {placeholder}
                        """, (tracking_id,))
                        logging.info(f"[SLSKD_MONITOR] Started download: {best_file['filename']} from {best_file['username']}")
                    else:
                        cursor2.execute(f"""
                            UPDATE managed_downloads 
                            SET status = 'error', error_message = 'Failed to start file download', updated_at = CURRENT_TIMESTAMP
                            WHERE id = {placeholder}
                        """, (tracking_id,))
                    
                    conn2.commit()
                    conn2.close()
                    
                except Exception as e:
                    logging.error(f"[SLSKD_MONITOR] Error downloading file: {e}")
                    try:
                        conn2 = get_db()
                        cursor2 = conn2.cursor()
                        placeholder = "%s"
                        cursor2.execute(f"""
                            UPDATE managed_downloads 
                            SET status = 'error', error_message = {placeholder}, updated_at = CURRENT_TIMESTAMP
                            WHERE id = {placeholder}
                        """, (str(e), tracking_id))
                        conn2.commit()
                        conn2.close()
                    except:
                        pass
            else:
                # No good matches found
                try:
                    conn2 = get_db()
                    cursor2 = conn2.cursor()
                    placeholder = "%s"
                    match_score_msg = f"match score {best_match_score}" if best_file else "no responses with files"
                    cursor2.execute(f"""
                        UPDATE managed_downloads 
                        SET status = 'error', error_message = {placeholder}, updated_at = CURRENT_TIMESTAMP
                        WHERE id = {placeholder}
                    """, (f"No matching files found ({match_score_msg})", tracking_id))
                    conn2.commit()
                    conn2.close()
                except:
                    pass
        
        # Start monitoring thread
        import threading
        thread = threading.Thread(target=monitor_slskd_search, daemon=True)
        thread.start()
            
    except Exception as e:
        logging.error(f"[SLSKD_INIT] Error for tracking {tracking_id}: {e}")
        cursor.execute(f"""
            UPDATE managed_downloads 
            SET status = 'error', error_message = {placeholder}, updated_at = CURRENT_TIMESTAMP
            WHERE id = {placeholder}
        """, (str(e), tracking_id))
        conn.commit()


def _initiate_qbit_download_bg(tracking_id, query):
    """Background thread worker to initiate a qBittorrent download with fresh DB connection"""
    try:
        cfg = get_config()
        qbit_config = cfg.get("qbittorrent", {})
        
        if not qbit_config.get("enabled"):
            conn = get_db()
            cursor = conn.cursor()
            placeholder = "%s"
            cursor.execute(f"""
                UPDATE managed_downloads 
                SET status = 'error', error_message = 'qBittorrent not enabled', updated_at = CURRENT_TIMESTAMP
                WHERE id = {placeholder}
            """, (tracking_id,))
            conn.commit()
            conn.close()
            return
        
        web_url = qbit_config.get("web_url", "http://localhost:8080")
        username = qbit_config.get("username", "")
        password = qbit_config.get("password", "")
        
        # Update status to searching
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        cursor.execute(f"""
            UPDATE managed_downloads 
            SET status = 'searching', updated_at = CURRENT_TIMESTAMP
            WHERE id = {placeholder}
        """, (tracking_id,))
        conn.commit()
        conn.close()
        
        # Start search in qBittorrent in a background thread
        def search_and_add_qbit():
            try:
                import requests as req
                import time
                
                session = req.Session()
                
                # Login if credentials provided
                if username and password:
                    login_url = f"{web_url}/api/v2/auth/login"
                    try:
                        session.post(login_url, data={"username": username, "password": password}, timeout=5)
                    except:
                        pass  # May not require login
                
                # Start search
                search_url = f"{web_url}/api/v2/search/start"
                resp = session.post(search_url, data={"pattern": query, "plugins": "all", "category": "Music"}, timeout=10)
                
                if resp.status_code not in [200, 201]:
                    raise Exception(f"Search failed: {resp.status_code}")
                
                search_data = resp.json()
                search_id = search_data.get("id")
                
                if not search_id:
                    raise Exception("No search ID returned from qBittorrent")
                
                # Poll for results
                best_result = None
                for i in range(60):  # Poll for up to 30 seconds
                    time.sleep(0.5)
                    
                    status_url = f"{web_url}/api/v2/search/status"
                    status_resp = session.get(status_url, params={"id": search_id}, timeout=5)
                    
                    if status_resp.status_code == 200:
                        status_data = status_resp.json()
                        
                        if status_data and len(status_data) > 0:
                            # Get results
                            results_url = f"{web_url}/api/v2/search/results"
                            results_resp = session.get(results_url, params={"id": search_id, "limit": 100}, timeout=5)
                            
                            if results_resp.status_code == 200:
                                data = results_resp.json()
                                results = data.get("results", [])
                                
                                if results:
                                    # Pick the result with best seeders
                                    best_result = max(results, key=lambda x: x.get('nb_seeders', 0))
                            
                            # Check if search is done
                            search_status = status_data[0]
                            if search_status.get("status") == "Stopped":
                                break
                
                # Stop search
                try:
                    stop_url = f"{web_url}/api/v2/search/stop"
                    session.post(stop_url, data={"id": search_id}, timeout=5)
                except:
                    pass
                
                # Add the best torrent found
                if best_result:
                    conn2 = get_db()
                    cursor2 = conn2.cursor()
                    placeholder = "%s"
                    
                    try:
                        # Add magnet link if available
                        add_url = f"{web_url}/api/v2/torrents/add"
                        magnet = best_result.get('magnet_uri') or best_result.get('magnet')
                        torrent_url = best_result.get('torrent_url') or best_result.get('link')
                        
                        add_payload = {"category": "Music", "tags": "Music"}
                        if magnet:
                            add_payload["urls"] = magnet
                            resp = session.post(add_url, data=add_payload, timeout=10)
                        elif torrent_url:
                            add_payload["urls"] = torrent_url
                            resp = session.post(add_url, data=add_payload, timeout=10)
                        else:
                            raise Exception("No magnet link or torrent URL found")
                        
                        if resp.status_code in [200, 403]:  # 403 might mean already added
                            cursor2.execute(f"""
                                UPDATE managed_downloads 
                                SET status = 'downloading', updated_at = CURRENT_TIMESTAMP
                                WHERE id = {placeholder}
                            """, (tracking_id,))
                            logging.info(f"[QBIT_MONITOR] Added torrent: {best_result.get('name', 'Unknown')}")
                        else:
                            logging.warning(f"[QBIT_MONITOR] qBittorrent add failed ({resp.status_code}), falling back to Soulseek")
                            _initiate_slskd_download_bg(tracking_id, query)
                            conn2.close()
                            return
                    except Exception as e:
                        logging.warning(f"[QBIT_MONITOR] qBittorrent add error ({e}), falling back to Soulseek")
                        _initiate_slskd_download_bg(tracking_id, query)
                        conn2.close()
                        return
                    
                    conn2.commit()
                    conn2.close()
                else:
                    logging.info(f"[QBIT_MONITOR] No qBittorrent results for '{query}', falling back to Soulseek")
                    _initiate_slskd_download_bg(tracking_id, query)
                    return
                    
            except Exception as e:
                logging.error(f"[QBIT_MONITOR] Error: {e}")
                try:
                    conn2 = get_db()
                    cursor2 = conn2.cursor()
                    placeholder = "%s"
                    cursor2.execute(f"""
                        UPDATE managed_downloads 
                        SET status = 'error', error_message = {placeholder}, updated_at = CURRENT_TIMESTAMP
                        WHERE id = {placeholder}
                    """, (str(e), tracking_id))
                    conn2.commit()
                    conn2.close()
                except:
                    pass
        
        # Start qBit search in a background thread
        thread = threading.Thread(target=search_and_add_qbit, daemon=True)
        thread.start()
        
    except Exception as e:
        logging.error(f"[QBIT_INIT] Error for tracking {tracking_id}: {e}")
        try:
            conn = get_db()
            cursor = conn.cursor()
            placeholder = "%s"
            cursor.execute(f"""
                UPDATE managed_downloads 
                SET status = 'error', error_message = {placeholder}, updated_at = CURRENT_TIMESTAMP
                WHERE id = {placeholder}
            """, (str(e), tracking_id))
            conn.commit()
            conn.close()
        except:
            pass


