@app.route("/api/downloads/folder/<path:folder_path>/match-musicbrainz", methods=["POST"])
def api_downloads_folder_match_musicbrainz(folder_path):
    """
    Match a folder group with MusicBrainz and return candidate releases.
    Supports manual search queries and Discogs fallback.
    
    Args:
        folder_path: URL-encoded relative folder path
        artist: Artist name (in request JSON, optional if manual_query provided)
        album: Album name (in request JSON, optional if manual_query provided)
        manual_query: Manual search string (in request JSON, optional)
    
    Returns:
        JSON with MusicBrainz/Discogs candidates for selection
    """
    try:
        from download_folder_grouping import match_folder_group_with_musicbrainz
        
        data = request.get_json() or {}
        artist = data.get('artist', '').strip()
        album = data.get('album', '').strip()
        manual_query = data.get('manual_query', '').strip()
        tracks = data.get('tracks', [])
        
        # Extract track titles for the track-title fallback search
        track_titles = []
        if isinstance(tracks, list):
            for t in tracks:
                title = str(t.get('title', '') if isinstance(t, dict) else '').strip()
                if title:
                    track_titles.append(title)
        
        # Require either manual query or artist+album
        if not manual_query and (not artist or not album):
            return jsonify({
                "success": False,
                "error": "Either manual_query or both artist and album are required"
            }), 400
        
        result = match_folder_group_with_musicbrainz(
            folder_path, 
            artist, 
            album,
            manual_query=manual_query if manual_query else None,
            track_titles=track_titles if track_titles else None
        )
        
        return jsonify({
            "success": result.get('success', False),
            **result
        })
    except Exception as e:
        logging.error(f"Error matching folder with MusicBrainz: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({
            "success": False,
            "error": str(e),
            "candidates": []
        }), 500


@app.route("/api/downloads/folder/<path:folder_path>/auto-match", methods=["POST"])
def api_downloads_folder_auto_match(folder_path):
    """
    Attempt to automatically match a folder group with high confidence.
    Returns either a single suggested match or empty result if confidence too low.
    
    Args:
        folder_path: URL-encoded relative folder path
        artist: Detected artist name (in request JSON)
        album: Detected album name (in request JSON)
        tracks: List of track dicts (in request JSON)
    
    Returns:
        JSON with auto_match (if found) or empty candidates array
    """
    try:
        from folder_matching_enhancements import suggest_auto_match, get_musicbrainz_release_tracks
        from download_folder_grouping import match_folder_group_with_musicbrainz
        
        data = request.get_json() or {}
        artist = data.get('artist', '').strip()
        album = data.get('album', '').strip()
        tracks = data.get('tracks', [])
        
        if not artist or not album or not tracks:
            return jsonify({
                "success": False,
                "error": "artist, album, and tracks are required",
                "candidates": []
            }), 400
        
        # Get candidate releases from MusicBrainz
        candidates_result = match_folder_group_with_musicbrainz(
            folder_path,
            artist,
            album
        )
        
        if not candidates_result.get('success') or not candidates_result.get('candidates'):
            return jsonify({
                "success": False,
                "candidates": [],
                "auto_match": None
            })
        
        candidates = candidates_result['candidates']
        
        # Try to auto-suggest best match
        auto_match = suggest_auto_match(artist, album, candidates, tracks)
        
        return jsonify({
            "success": True,
            "candidates": candidates,
            "auto_match": auto_match,
            "auto_match_confidence": auto_match.get('auto_match_confidence') if auto_match else 0.0
        })
        
    except Exception as e:
        logging.error(f"Error auto-matching folder: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({
            "success": False,
            "error": str(e),
            "candidates": []
        }), 500


