@app.route("/api/playlist/import", methods=["POST"])
def api_playlist_import():
    """API endpoint to import a Spotify playlist and match to Navidrome database using enhanced ISRC + fuzzy + strict matching"""
    try:
        data = request.get_json()
        spotify_url = data.get("spotify_url", "").strip()
        playlist_name = data.get("playlist_name", "").strip()
        playlist_description = data.get("playlist_description", "").strip()
        target_user = (data.get("target_user") or data.get("user") or "").strip()
        
        if not spotify_url or not playlist_name:
            return jsonify({"error": "Missing required fields"}), 400
        
        # Extract playlist ID from various URL formats
        playlist_id = extract_spotify_playlist_id(spotify_url)
        if not playlist_id:
            return jsonify({"error": "Invalid Spotify playlist URL or ID"}), 400
        
        # Get Spotify client and fetch playlist tracks
        try:
            spotify_tracks = get_spotify_playlist_tracks(playlist_id)
        except Exception as e:
            return jsonify({"error": f"Failed to fetch Spotify playlist: {str(e)}"}), 500
        
        if not spotify_tracks:
            return jsonify({"error": "Playlist is empty or could not be fetched"}), 400
        
        # Match tracks using enhanced 3-tier strategy: ISRC → Fuzzy → Strict
        matched_tracks = []
        missing_tracks = []
        
        # Statistics for matching strategies
        match_stats = {
            "isrc": 0,
            "fuzzy": 0,
            "strict": 0,
            "unmatched": 0
        }
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        for spotify_track in spotify_tracks:
            # Use enhanced matching from playlist_matcher
            matched_track, confidence, strategy = enhanced_match_track(
                spotify_track,
                cursor,
                enable_isrc=True,
                enable_fuzzy=True,
                enable_strict=True,
                fuzzy_threshold=0.80,  # Based on navispot's threshold
                logger=logging
            )
            
            if matched_track:
                matched_tracks.append({
                    "id": matched_track["id"],
                    "title": matched_track["title"],
                    "artist": matched_track["artist"],
                    "album": matched_track["album"],
                    "stars": matched_track["stars"],
                    "confidence": confidence,
                    "strategy": strategy
                })
                match_stats[strategy] += 1
            else:
                missing_tracks.append({
                    "title": spotify_track.get("title", ""),
                    "artist": spotify_track.get("artist", ""),
                    "album": spotify_track.get("album", ""),
                    "spotify_id": spotify_track.get("spotify_id", ""),
                    "isrc": spotify_track.get("isrc", ""),
                    "best_score": confidence
                })
                match_stats["unmatched"] += 1
        
        conn.close()
        
        # Check if slskd is enabled
        config_data, _ = _read_yaml(CONFIG_PATH)
        slskd_enabled = config_data.get("slskd", {}).get("enabled", False)
        
        # Log matching statistics
        logging.info(f"Playlist import '{playlist_name}': Matched {len(matched_tracks)}/{len(spotify_tracks)} tracks")
        logging.info(f"  Strategy breakdown: ISRC={match_stats['isrc']}, Fuzzy={match_stats['fuzzy']}, Strict={match_stats['strict']}, Unmatched={match_stats['unmatched']}")
        
        return jsonify({
            "success": True,
            "playlist_name": playlist_name,
            "playlist_description": playlist_description,
            "target_user": target_user,
            "matched_tracks": matched_tracks,
            "missing_tracks": missing_tracks,
            "slskd_enabled": slskd_enabled,
            "spotify_playlist_id": playlist_id,
            "message": f"Matched {len(matched_tracks)}/{len(spotify_tracks)} tracks",
            "match_stats": match_stats
        })
    
    except Exception as e:
        logging.error(f"Playlist import error: {str(e)}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/playlist/import/csv", methods=["POST"])
def api_playlist_import_csv():
    """Import a playlist from an Exportify-exported CSV file.

    Accepts multipart/form-data with:
        file             – CSV file (required)
        playlist_name    – desired playlist name (required)
        playlist_description – optional description
        target_user      – Navidrome user to assign the playlist to

    Exportify CSV columns used for matching:
        Track Name, Artist Name(s), Album Name, ISRC, Spotify URI
    """
    try:
        # --- Validate uploaded file ---
        if "file" not in request.files:
            return jsonify({"error": "No file uploaded"}), 400

        uploaded_file = request.files["file"]
        if not uploaded_file.filename:
            return jsonify({"error": "No file selected"}), 400
        if not uploaded_file.filename.lower().endswith(".csv"):
            return jsonify({"error": "Only .csv files are supported"}), 400

        playlist_name = (request.form.get("playlist_name") or "").strip()
        playlist_description = (request.form.get("playlist_description") or "").strip()
        target_user = (request.form.get("target_user") or "").strip()

        if not playlist_name:
            return jsonify({"error": "playlist_name is required"}), 400

        # --- Parse CSV ---
        content = uploaded_file.read().decode("utf-8-sig")  # strip BOM if present
        reader = csv.DictReader(io.StringIO(content))

        # Normalise header names: lowercase + strip whitespace
        raw_fieldnames = reader.fieldnames or []
        normalised = {h.lower().strip(): h for h in raw_fieldnames}

        def col(aliases):
            """Return the actual header name for the first alias that exists."""
            for alias in aliases:
                if alias in normalised:
                    return normalised[alias]
            return None

        title_col    = col(["track name", "name", "title"])
        artist_col   = col(["artist name(s)", "artist names", "artist name", "artist", "artists"])
        album_col    = col(["album name", "album"])
        album_artist_col = col(["album artist", "album_artist", "albumartist"])
        isrc_col     = col(["isrc"])
        uri_col      = col(["spotify uri", "track uri", "uri"])
        duration_col = col(["duration (ms)", "duration_ms", "duration"])
        date_col     = col(["release date", "release_date", "date"])
        genres_col   = col(["genres", "genre"])
        label_col    = col(["record label", "label"])
        popularity_col = col(["popularity"])
        explicit_col   = col(["explicit"])

        if not title_col or not artist_col:
            return jsonify({
                "error": "CSV must contain at least 'Track Name' and 'Artist Name(s)' columns. "
                         "Please export using Exportify (exportify.net)."
            }), 400

        def _extract_year(date_str):
            """Extract a 4-digit year from a date string (e.g. '24/04/2026' or '2026-04-24')."""
            if not date_str:
                return None
            # Try ISO format first (YYYY-MM-DD or YYYY-…)
            import re
            m = re.search(r'\b(\d{4})\b', str(date_str))
            return m.group(1) if m else None

        tracks_from_csv = []
        for row in reader:
            title  = (row.get(title_col) or "").strip()
            artist = (row.get(artist_col) or "").strip()
            if not title and not artist:
                continue  # skip blank rows

            # Album artist from CSV.  When absent, fall back to the first artist
            # from the (possibly semicolon-joined) track artist field so that
            # single-artist releases are handled correctly without hardcoding
            # "Various Artists" here — that decision is left to the caller.
            raw_album_artist = (row.get(album_artist_col) or "").strip() if album_artist_col else ""
            album_artist = raw_album_artist or artist.split(';')[0].strip()

            # Duration: CSV stores milliseconds; convert to whole seconds for queue
            duration_s = None
            if duration_col:
                raw_dur = (row.get(duration_col) or "").strip()
                try:
                    duration_s = int(round(float(raw_dur) / 1000)) if raw_dur else None
                except (ValueError, TypeError):
                    duration_s = None

            # Year from release date
            year = _extract_year(row.get(date_col)) if date_col else None

            tracks_from_csv.append({
                "title":        title,
                "artist":       artist,
                "album_artist": album_artist,
                "album":        (row.get(album_col) or "").strip() if album_col else "",
                "isrc":         (row.get(isrc_col) or "").strip() if isrc_col else "",
                "spotify_id":   (row.get(uri_col) or "").strip().split(":")[-1] if uri_col else "",
                "duration_s":   duration_s,
                "year":         year,
                "genres":       (row.get(genres_col) or "").strip() if genres_col else "",
                "record_label": (row.get(label_col) or "").strip() if label_col else "",
                "popularity":   (row.get(popularity_col) or "").strip() if popularity_col else "",
                "explicit":     (row.get(explicit_col) or "").strip().upper() if explicit_col else "",
            })

        if not tracks_from_csv:
            return jsonify({"error": "No tracks found in CSV"}), 400

        # --- Skip matching if caller only wants parsed track metadata ---
        skip_matching = request.form.get("skip_matching", "").lower() in ("true", "1", "yes")
        if skip_matching:
            logging.info(
                f"CSV parse-only (skip_matching) for '{playlist_name}': "
                f"{len(tracks_from_csv)} tracks parsed"
            )
            return jsonify({
                "success":    True,
                "all_tracks": tracks_from_csv,
                "total":      len(tracks_from_csv),
            })

        # --- Match tracks using same 3-tier strategy as Spotify URL import ---
        matched_tracks = []
        missing_tracks = []
        match_stats = {"isrc": 0, "fuzzy": 0, "strict": 0, "unmatched": 0}

        conn = get_db()
        cursor = conn.cursor()

        for track in tracks_from_csv:
            matched_track, confidence, strategy = enhanced_match_track(
                track,
                cursor,
                enable_isrc=True,
                enable_fuzzy=True,
                enable_strict=True,
                fuzzy_threshold=0.80,
                logger=logging,
            )

            if matched_track:
                matched_tracks.append({
                    "id":         matched_track["id"],
                    "title":      matched_track["title"],
                    "artist":     matched_track["artist"],
                    "album":      matched_track["album"],
                    "stars":      matched_track["stars"],
                    "confidence": confidence,
                    "strategy":   strategy,
                })
                match_stats[strategy] += 1
            else:
                missing_tracks.append({
                    "title":        track["title"],
                    "artist":       track["artist"],
                    "album_artist": track.get("album_artist", ""),
                    "album":        track["album"],
                    "spotify_id":   track["spotify_id"],
                    "isrc":         track["isrc"],
                    "best_score":   confidence,
                    "duration_s":   track.get("duration_s"),
                    "year":         track.get("year"),
                    "genres":       track.get("genres"),
                    "record_label": track.get("record_label"),
                    "popularity":   track.get("popularity"),
                    "explicit":     track.get("explicit"),
                })
                match_stats["unmatched"] += 1

        conn.close()

        # Check if slskd is enabled
        config_data, _ = _read_yaml(CONFIG_PATH)
        slskd_enabled = config_data.get("slskd", {}).get("enabled", False)

        logging.info(
            f"CSV playlist import '{playlist_name}': "
            f"Matched {len(matched_tracks)}/{len(tracks_from_csv)} tracks"
        )
        logging.info(
            f"  Strategy breakdown: ISRC={match_stats['isrc']}, "
            f"Fuzzy={match_stats['fuzzy']}, Strict={match_stats['strict']}, "
            f"Unmatched={match_stats['unmatched']}"
        )

        return jsonify({
            "success":              True,
            "playlist_name":        playlist_name,
            "playlist_description": playlist_description,
            "target_user":          target_user,
            "matched_tracks":       matched_tracks,
            "missing_tracks":       missing_tracks,
            "slskd_enabled":        slskd_enabled,
            "message":              f"Matched {len(matched_tracks)}/{len(tracks_from_csv)} tracks",
            "match_stats":          match_stats,
        })

    except UnicodeDecodeError:
        return jsonify({"error": "Could not decode CSV file. Please save it as UTF-8."}), 400
    except Exception as e:
        logging.error(f"CSV playlist import error: {str(e)}")
        return jsonify({"error": "An error occurred while processing the CSV file"}), 500


@app.route("/api/playlist/create", methods=["POST"])
def api_playlist_create():
    """
    Create a Navidrome playlist from matched tracks.
    
    Request body:
        {
            "playlist_name": "My Playlist",
            "playlist_description": "Optional description",
            "matched_tracks": [
                {"id": "track-123", "title": "Song", "artist": "Artist"},
                ...
            ]
        }
    
    Returns:
        201 Created: {"success": true, "data": {...}, ...}
        400 Bad Request: {"success": false, "error": {...}, ...}
        500 Server Error: {"success": false, "error": {...}, ...}
    """
    try:
        from helpers.api_response import api_success, api_error
        
        # Parse request
        try:
            data = request.get_json(force=True, silent=True) or {}
        except Exception as json_err:
            logging.error(f"Invalid JSON in playlist/create request: {json_err}")
            return api_error(
                "invalid_json",
                "Request body must be valid JSON",
                status=400
            )
        
        playlist_name = (data.get("playlist_name") or "").strip()
        playlist_description = (data.get("playlist_description") or "").strip()
        matched_tracks = data.get("matched_tracks", [])
        
        # Validate required fields
        if not playlist_name:
            return api_error(
                "missing_field",
                "playlist_name is required",
                status=400,
                field="playlist_name"
            )
        
        if not matched_tracks or not isinstance(matched_tracks, list):
            return api_error(
                "missing_field",
                "matched_tracks is required and must be a list",
                status=400,
                field="matched_tracks"
            )
        
        # Extract track IDs
        track_ids = [
            str(track.get("id")).strip()
            for track in matched_tracks
            if track.get("id")
        ]
        
        if not track_ids:
            return api_error(
                "no_valid_tracks",
                f"No valid track IDs found in {len(matched_tracks)} provided tracks",
                status=400,
                tracks_provided=len(matched_tracks),
                valid_tracks=0
            )
        
        # Build NSP playlist data structure
        playlist_data = {
            "name": playlist_name,
            "comment": playlist_description or "Created via SPTNR",
            "trackIds": track_ids
        }
        
        # Determine file system path
        music_folder = os.environ.get("MUSIC_FOLDER", "/music")
        playlists_dir = os.path.join(music_folder, "Playlists")
        
        # Sanitize filename
        safe_name = "".join(
            c for c in playlist_name 
            if c.isalnum() or c in ('-', '_', ' ')
        ).strip()
        
        if not safe_name:
            return api_error(
                "invalid_name",
                f"Playlist name '{playlist_name}' contains no valid filename characters",
                status=400
            )
        
        file_path = os.path.join(playlists_dir, f"{safe_name}.nsp")
        
        # Check if file already exists
        if os.path.exists(file_path):
            return api_error(
                "playlist_exists",
                f"Playlist file '{safe_name}.nsp' already exists",
                status=409,
                file_path=file_path
            )
        
        # Create directory
        try:
            os.makedirs(playlists_dir, exist_ok=True)
        except OSError as dir_err:
            logging.error(f"Failed to create playlists directory '{playlists_dir}': {dir_err}")
            return api_error(
                "directory_error",
                f"Could not create playlists directory: {str(dir_err)}",
                status=500,
                directory=playlists_dir
            )
        
        # Write playlist file
        try:
            with open(file_path, 'w', encoding='utf-8') as f:
                json.dump(playlist_data, f, indent=2)
            
            logging.info(
                f"Created playlist: {playlist_name} with {len(track_ids)} tracks at {file_path}"
            )
            
            return api_success(
                {
                    "playlist_name": playlist_name,
                    "file_name": f"{safe_name}.nsp",
                    "file_path": file_path,
                    "track_count": len(track_ids),
                    "track_ids": track_ids
                },
                message=f"Playlist '{playlist_name}' created successfully",
                status=201
            )
        
        except IOError as io_err:
            logging.error(f"Failed to write playlist file '{file_path}': {io_err}")
            return api_error(
                "file_write_error",
                f"Failed to write playlist file: {str(io_err)}",
                status=500,
                file_path=file_path
            )
        except UnicodeEncodeError as encode_err:
            logging.error(f"Unicode encoding error writing playlist: {encode_err}")
            return api_error(
                "encoding_error",
                f"Encoding error: {str(encode_err)}",
                status=500
            )
    
    except Exception as e:
        logging.error(
            f"Unexpected error in /api/playlist/create: {type(e).__name__}: {e}",
            exc_info=True
        )
        return api_error(
            "internal_error",
            "An unexpected error occurred while creating the playlist",
            status=500,
            error_type=type(e).__name__,
            error_message=str(e)
        )


def extract_spotify_playlist_id(url_or_id):
    """Extract Spotify playlist ID from URL or return the ID if already in correct format"""
    import re
    
    # If it's just an ID (32 characters of alphanumeric)
    if re.match(r"^[a-zA-Z0-9]{22}$", url_or_id):
        return url_or_id
    
    # Extract from various URL formats
    patterns = [
        r"spotify\.com/playlist/([a-zA-Z0-9]+)",  # https://open.spotify.com/playlist/...
        r"spotify:playlist:([a-zA-Z0-9]+)",       # spotify:playlist:...
    ]
    
    for pattern in patterns:
        match = re.search(pattern, url_or_id)
        if match:
            return match.group(1)
    
    return None


def get_spotify_playlist_tracks(playlist_id):
    """Fetch tracks from a Spotify playlist"""
    try:
        from popularity_helpers import get_spotify_client
        spotify_client = get_spotify_client()
        if not spotify_client:
            raise Exception("Spotify client not configured")
        
        # Use SpotifyClient's get_playlist_tracks method
        tracks = spotify_client.get_playlist_tracks(playlist_id)
        return tracks
    
    except Exception as e:
        logging.error(f"Error fetching Spotify playlist: {str(e)}")
        raise


@app.route("/api/track/discogs", methods=["POST"])
def api_track_discogs_lookup():
    """Lookup track on Discogs for better metadata and genres"""
    try:
        from api_clients.discogs import DiscogsClient
        
        data = request.get_json()
        title = data.get("title", "")
        artist = data.get("artist", "")
        album = data.get("album", "")
        
        if not title or not artist:
            return jsonify({"error": "Missing title or artist"}), 400
        
        # Get Discogs token from config
        cfg = get_config()
        # Check both api_integrations.discogs and root discogs for backwards compatibility
        discogs_config = cfg.get("api_integrations", {}).get("discogs", {}) or cfg.get("discogs", {})
        token = discogs_config.get("token", "")
        
        if not token:
            return jsonify({"error": "Discogs token not configured. Please add your Discogs token in config.yaml under api_integrations.discogs.token"}), 400
        
        # Use DiscogsClient with proper session and retry logic
        client = DiscogsClient(token=token)
        
        # Prepare search query
        from api_clients import session
        query = f"{artist} {album or title}"
        
        # Search Discogs API using the shared session with retry logic
        headers = {
            "Authorization": f"Discogs token={token}",
            "User-Agent": "popularr-cli/1.0 +https://github.com/M0VENTURA/popularr"
        }
        
        import time
        response = session.get(
            "https://api.discogs.com/database/search",
            params={"q": query, "type": "release", "per_page": 5},
            headers=headers,
            timeout=(5, 10)
        )
        
        # Handle rate limiting
        if response.status_code == 429:
            retry_after = int(response.headers.get("Retry-After", 60))
            time.sleep(min(retry_after, 5))  # Cap at 5 seconds
            response = session.get(
                "https://api.discogs.com/database/search",
                params={"q": query, "type": "release", "per_page": 5},
                headers=headers,
                timeout=(5, 10)
            )
        
        # Check for auth errors
        if response.status_code == 401:
            return jsonify({"error": "Discogs API authentication failed: invalid or expired token"}), 401
        elif response.status_code == 403:
            return jsonify({"error": "Discogs API access forbidden: check token permissions"}), 403
        
        if not response.ok:
            return jsonify({"error": f"Discogs API error: {response.status_code}"}), 500
        
        results_data = response.json().get("results", [])
        
        if not results_data:
            return jsonify({"results": [], "message": "No Discogs matches found"}), 200
        
        # Format results with track-level enrichment when possible
        import difflib
        import re
        formatted_results = []
        for result in results_data[:5]:
            # Check if format includes "Single" to detect singles
            formats = result.get("format", [])
            is_single_release = "Single" in formats if formats else False

            release_title = result.get("title", "Unknown")
            parsed_artist = artist
            parsed_album = album or title
            if " - " in release_title:
                parts = release_title.split(" - ", 1)
                if parts[0].strip():
                    parsed_artist = parts[0].strip()
                if parts[1].strip():
                    parsed_album = parts[1].strip()

            matched_track = None
            discogs_genres = []

            resource_url = result.get("resource_url", "")
            if resource_url:
                try:
                    rel_resp = session.get(resource_url, headers=headers, timeout=(5, 10))
                    if rel_resp.ok:
                        rel_data = rel_resp.json() or {}

                        # Merge release-level genres/styles for easy field application.
                        discogs_genres = list(dict.fromkeys((rel_data.get("genres") or []) + (rel_data.get("styles") or [])))

                        best_score = 0.0
                        best_track = None
                        for trk in rel_data.get("tracklist", []) or []:
                            trk_title = (trk.get("title") or "").strip()
                            if not trk_title:
                                continue
                            score = difflib.SequenceMatcher(None, title.lower(), trk_title.lower()).ratio()
                            if score > best_score:
                                best_score = score
                                best_track = trk

                        if best_track and best_score >= 0.55:
                            position = (best_track.get("position") or "").strip()
                            track_number = None
                            match_num = re.search(r"(\d+)$", position)
                            if match_num:
                                track_number = match_num.group(1)

                            writer_names = []
                            for ea in best_track.get("extraartists", []) or []:
                                role = str(ea.get("role") or "").lower()
                                if any(keyword in role for keyword in ["writer", "lyric", "composer", "written"]):
                                    name = (ea.get("name") or "").strip()
                                    if name and name not in writer_names:
                                        writer_names.append(name)

                            matched_track = {
                                "title": best_track.get("title", ""),
                                "position": position,
                                "track_number": track_number,
                                "duration": best_track.get("duration", ""),
                                "writers": writer_names,
                                "confidence": round(best_score, 3),
                            }
                except Exception as enrich_error:
                    logging.debug(f"Discogs release enrichment failed for {resource_url}: {enrich_error}")

            if not discogs_genres:
                discogs_genres = list(dict.fromkeys((result.get("genre", []) or []) + (result.get("style", []) or [])))
            
            formatted_results.append({
                "title": release_title,
                "artist": parsed_artist,
                "album": parsed_album,
                "year": result.get("year", ""),
                "genre": result.get("genre", []),
                "style": result.get("style", []),
                "genres": discogs_genres,
                "format": formats,
                "is_single": is_single_release,
                "url": resource_url,
                "source": "discogs",
                "discogs_id": result.get("id", ""),
                "matched_track": matched_track,
            })
        
        return jsonify({"results": formatted_results}), 200
    except Exception as e:
        logger = logging.getLogger('sptnr')
        logger.error(f"Discogs lookup error: {e}")
        import traceback
        logger.debug(f"Traceback: {traceback.format_exc()}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/track/<track_id>", methods=["GET"])
def api_get_track(track_id):
    """Get track metadata by ID"""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        cursor.execute(f"""
            SELECT *
            FROM tracks
            WHERE id = {placeholder}
        """, (track_id,))
        
        row = cursor.fetchone()
        conn.close()
        
        if not row:
            return jsonify({"error": "Track not found"}), 404
        
        # Safely convert row to dict
        try:
            track = dict(row) if hasattr(row, 'keys') else convert_row_to_json_serializable(row)
            track = convert_row_to_json_serializable(track)
        except (IndexError, TypeError) as e:
            logging.error(f"[API] Error converting track row to dict: {e}")
            return jsonify({"error": "Failed to process track data"}), 500
            
        return jsonify(track)
    except Exception as e:
        logging.error(f"[API] Error fetching track {track_id}: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({"error": str(e)}), 500


@app.route("/api/track/<track_id>/audio")
@login_required
def api_track_audio(track_id):
    """Stream an audio file for in-browser playback.

    Looks up the track's file_path in the database, verifies the path falls
    under the configured music folder (security boundary), then serves the
    file with HTTP range-request support so browsers can seek freely.
    """
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = get_placeholder(conn)
        cursor.execute(
            f"SELECT file_path FROM tracks WHERE id = {placeholder}",
            (track_id,),
        )
        row = cursor.fetchone()
        conn.close()
    except Exception as e:
        logging.error(f"[audio] DB error for track {track_id}: {e}")
        return jsonify({"error": "Database error"}), 500

    if not row or not row.get("file_path"):
        return jsonify({"error": "Track not found or has no file"}), 404

    file_path = row["file_path"]

    # Reject placeholder paths used for queued-but-not-yet-downloaded tracks
    if "__queued_for_download__" in file_path:
        return jsonify({"error": "Track is not yet downloaded"}), 404

    # Resolve to absolute path and confirm it exists on disk
    resolved = os.path.realpath(file_path)
    if not os.path.isfile(resolved):
        return jsonify({"error": "File not found on disk"}), 404

    # Security: ensure the file lives inside the configured music folder
    cfg = get_config()
    music_folder = os.path.realpath(
        cfg.get("navidrome", {}).get("music_folder", "")
        or os.environ.get("MUSIC_FOLDER", "")
        or os.environ.get("MUSIC_DIR", "/music")
    )
    if not resolved.startswith(music_folder + os.sep) and resolved != music_folder:
        logging.warning(f"[audio] Path traversal attempt blocked: {resolved}")
        abort(403)

    # Determine MIME type from extension
    ext = os.path.splitext(resolved)[1].lower()
    mime_map = {
        ".mp3": "audio/mpeg",
        ".flac": "audio/flac",
        ".ogg": "audio/ogg",
        ".opus": "audio/ogg; codecs=opus",
        ".m4a": "audio/mp4",
        ".aac": "audio/aac",
        ".wav": "audio/wav",
    }
    mimetype = mime_map.get(ext, "application/octet-stream")

    return send_file(resolved, mimetype=mimetype, conditional=True)


@app.route("/api/track/genre-recommendations", methods=["GET"])
def track_genre_recommendations():
    """Get genre recommendations for a track from various sources"""
    track_id = request.args.get("track_id", "").strip()
    
    if not track_id:
        return jsonify({"error": "Track ID is required"}), 400
    
    try:
        # Get track info
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        cursor.execute(f"""
            SELECT artist, album, title, 
                   spotify_genres, lastfm_tags, discogs_genres, 
                   musicbrainz_genres, navidrome_genres
            FROM tracks 
            WHERE id = {placeholder}
        """, (track_id,))
        
        track = cursor.fetchone()
        conn.close()
        
        if not track:
            return jsonify({"error": "Track not found"}), 404
        
        # Collect all genres from various sources
        genres_set = set()
        
        # Parse genres from all available sources
        for genre_field in [track["spotify_genres"], track["lastfm_tags"], 
                           track["discogs_genres"], track["musicbrainz_genres"], 
                           track["navidrome_genres"]]:
            if genre_field:
                # Handle both comma-separated strings and JSON arrays
                try:
                    genre_list = json.loads(genre_field)
                    if isinstance(genre_list, list):
                        genres_set.update(g.strip() for g in genre_list if g and g.strip())
                except:
                    # Handle backslash-separated (from Navidrome) and comma-separated
                    delimiter = '\\' if '\\' in str(genre_field) else ','
                    genres_set.update(g.strip() for g in str(genre_field).split(delimiter) if g and g.strip())
        
        # Get artist-level genres
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        cursor.execute(f"""
            SELECT DISTINCT spotify_genres, lastfm_tags, discogs_genres, 
                   musicbrainz_genres, navidrome_genres
            FROM tracks 
            WHERE artist = {placeholder}
            LIMIT 50
        """, (track["artist"],))
        
        artist_tracks = cursor.fetchall()
        conn.close()
        
        # Aggregate artist genres
        artist_genres_count = {}
        for t in artist_tracks:
            for genre_field in [t["spotify_genres"], t["lastfm_tags"], 
                               t["discogs_genres"], t["musicbrainz_genres"], 
                               t["navidrome_genres"]]:
                if genre_field:
                    try:
                        genre_list = json.loads(genre_field)
                        if isinstance(genre_list, list):
                            for g in genre_list:
                                if g and g.strip():
                                    artist_genres_count[g.strip()] = artist_genres_count.get(g.strip(), 0) + 1
                    except:
                        # Handle backslash-separated (from Navidrome) and comma-separated
                        delimiter = '\\' if '\\' in str(genre_field) else ','
                        for g in str(genre_field).split(delimiter):
                            if g and g.strip():
                                artist_genres_count[g.strip()] = artist_genres_count.get(g.strip(), 0) + 1
        
        # Sort by frequency and add top artist genres
        sorted_artist_genres = sorted(artist_genres_count.items(), key=lambda x: x[1], reverse=True)
        genres_set.update(g[0] for g in sorted_artist_genres[:10])
        
        # Clean up and format genres
        recommendations = []
        for genre in sorted(genres_set):
            # Skip empty, very short, or malformed genres
            if genre and len(genre) > 2 and not genre.isdigit():
                # Capitalize properly
                formatted = ' '.join(word.capitalize() for word in genre.split())
                if formatted not in recommendations:
                    recommendations.append(formatted)
        
        return jsonify({
            "track_id": track_id,
            "artist": track["artist"],
            "title": track["title"],
            "recommendations": recommendations[:20]  # Limit to top 20
        })
        
    except Exception as e:
        logging.error(f"Error fetching genre recommendations: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/api/album/<path:artist>/<path:album>/track-recommendations", methods=["GET"])
def api_album_track_recommendations(artist, album):
    """Get genre recommendations for all tracks in an album
    
    Returns recommendations from Spotify, MusicBrainz, Discogs, LastFM, and Navidrome sources.
    """
    logger = logging.getLogger('sptnr')
    try:
        from urllib.parse import unquote
        artist = unquote(artist)
        album = unquote(album)
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get all tracks in the album with their metadata and genres
        placeholder = "%s"
        collate_nocase = ""
        cursor.execute(f"""
            SELECT 
                id, title, artist, track_number,
                spotify_genres,
                lastfm_tags,
                discogs_genres,
                musicbrainz_genres,
                navidrome_genres
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}
            ORDER BY COALESCE(disc_number, 1), COALESCE(track_number, 999), title{collate_nocase}
        """, (artist, album))
        
        tracks_data = cursor.fetchall()
        conn.close()
        
        if not tracks_data:
            return jsonify({"error": "Album not found"}), 404
        
        # Build recommendations for each track
        recommendations_by_track = {}
        
        for track in tracks_data:
            track_id = track['id'] if isinstance(track, dict) else track[0]
            track_title = track['title'] if isinstance(track, dict) else track[1]
            
            # Collect genres from all sources
            genres_set = set()
            
            # Parse each genre field
            genre_fields = {
                'spotify_genres': track['spotify_genres'] if isinstance(track, dict) else track[4],
                'lastfm_tags': track['lastfm_tags'] if isinstance(track, dict) else track[5],
                'discogs_genres': track['discogs_genres'] if isinstance(track, dict) else track[6],
                'musicbrainz_genres': track['musicbrainz_genres'] if isinstance(track, dict) else track[7],
                'navidrome_genres': track['navidrome_genres'] if isinstance(track, dict) else track[8],
            }
            
            # Extract genres from all fields
            for field_name, field_value in genre_fields.items():
                if field_value:
                    try:
                        # Ensure field_value is a string
                        if isinstance(field_value, dict):
                            # If it's already a dict (unlikely), skip it
                            continue
                        if not isinstance(field_value, str):
                            field_value = str(field_value)
                        
                        # Try to parse as JSON array
                        try:
                            genre_list = json.loads(field_value)
                            if isinstance(genre_list, list):
                                for g in genre_list:
                                    genre_str = None
                                    if isinstance(g, str):
                                        genre_str = g
                                    elif isinstance(g, dict):
                                        # Try to extract from dict (could be {"name": "Rock"} or {"genre": "Rock"})
                                        genre_str = g.get('name') or g.get('genre') or g.get('title') or str(g)
                                    else:
                                        genre_str = str(g)
                                    
                                    if genre_str and isinstance(genre_str, str) and len(genre_str.strip()) > 2:
                                        genres_set.add(genre_str.strip())
                            elif isinstance(genre_list, dict):
                                # If parsed JSON is a dict, try to extract 'genres' key
                                if 'genres' in genre_list and isinstance(genre_list['genres'], list):
                                    for g in genre_list['genres']:
                                        genre_str = g if isinstance(g, str) else str(g)
                                        if genre_str and len(genre_str.strip()) > 2:
                                            genres_set.add(genre_str.strip())
                        except (json.JSONDecodeError, TypeError):
                            # Handle comma or backslash-separated genres
                            delimiter = '\\' if '\\' in field_value else ','
                            for g in field_value.split(delimiter):
                                if g and isinstance(g, str) and len(g.strip()) > 2:
                                    genres_set.add(g.strip())
                    except Exception as e:
                        logger.debug(f"Error processing genre field {field_name}: {e}")
                        continue
            
            # Format and deduplicate genres
            recommendations = []
            for genre in sorted(genres_set):
                # Capitalize properly
                formatted = ' '.join(word.capitalize() for word in genre.split())
                if formatted not in recommendations:
                    recommendations.append(formatted)
            
            recommendations_by_track[str(track_id)] = {
                'title': track_title,
                'recommendations': recommendations[:15]  # Limit to top 15
            }
        
        return jsonify({
            "success": True,
            "album": album,
            "artist": artist,
            "recommendations": recommendations_by_track
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching track recommendations: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/api/album/musicbrainz", methods=["POST"])
def api_album_musicbrainz_lookup():
    """Lookup album on MusicBrainz for multiple matches (Picard-style) with retry logic"""
    logger = logging.getLogger('sptnr')
    try:
        data = request.get_json(force=True, silent=True)
        if not data:
            return jsonify({"error": "Invalid JSON in request body"}), 400
        album = data.get("album", "")
        artist = data.get("artist", "")
        existing_mbid = (data.get("existing_mbid") or "").strip()
        
        if not album or not artist:
            return jsonify({"error": "Missing album or artist"}), 400
        
        import difflib
        headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
        results = []

        # ------------------------------------------------------------------
        # Step 1: If the album has an existing stored MBID, do a direct lookup
        # for it so the user can see their currently stored release/release-group
        # and compare it against the text search results.
        # musicbrainz_album_mbid stores a release MBID (specific pressing), so
        # try a release lookup first, then fall back to release-group lookup.
        # ------------------------------------------------------------------
        if existing_mbid:
            try:
                stored_result = None
                mbid_type = None

                # Try as release MBID first
                time.sleep(1)
                rel_resp = requests.get(
                    f"https://musicbrainz.org/ws/2/release/{existing_mbid}",
                    params={"fmt": "json", "inc": "artist-credits+release-groups"},
                    headers=headers,
                    timeout=10,
                )
                if rel_resp.status_code == 200:
                    rel_data = rel_resp.json()
                    rel_artist_credits = rel_data.get("artist-credit", [])
                    rel_artist = _build_artist_credit_string(rel_artist_credits) if rel_artist_credits else artist
                    rel_date = rel_data.get("date", "")
                    rg = rel_data.get("release-group") or {}
                    primary_type = rg.get("primary-type", "Album")
                    rg_id = rg.get("id", "")
                    # Prefer release-group cover art (more reliably available in CAA
                    # than art for a specific pressing/reissue MBID)
                    cover_art_url = (
                        f"https://coverartarchive.org/release-group/{rg_id}/front-250"
                        if rg_id
                        else f"https://coverartarchive.org/release/{existing_mbid}/front-250"
                    )
                    # Use the release-group's original first-release-date so that
                    # a remaster/reissue shows the original album year, not the
                    # reissue year.
                    display_date = rg.get("first-release-date", "") or rel_date
                    stored_result = {
                        "mbid": existing_mbid,
                        "title": rel_data.get("title", album),
                        "artist": rel_artist,
                        "primary_type": primary_type,
                        "first_release_date": display_date,
                        "cover_art_url": cover_art_url,
                        "confidence": 1.0,
                        "source": "musicbrainz",
                        "is_stored_mbid": True,
                        "mbid_type": "release",
                    }
                    mbid_type = "release"
                elif rel_resp.status_code == 404:
                    # Try as release-group MBID
                    time.sleep(1)
                    rg_resp = requests.get(
                        f"https://musicbrainz.org/ws/2/release-group/{existing_mbid}",
                        params={"fmt": "json", "inc": "artist-credits"},
                        headers=headers,
                        timeout=10,
                    )
                    if rg_resp.status_code == 200:
                        rg_data = rg_resp.json()
                        rg_artist_credits = rg_data.get("artist-credit", [])
                        rg_artist = _build_artist_credit_string(rg_artist_credits) if rg_artist_credits else artist
                        cover_art_url = f"https://coverartarchive.org/release-group/{existing_mbid}/front-250"
                        stored_result = {
                            "mbid": existing_mbid,
                            "title": rg_data.get("title", album),
                            "artist": rg_artist,
                            "primary_type": rg_data.get("primary-type", "Album"),
                            "first_release_date": rg_data.get("first-release-date", ""),
                            "cover_art_url": cover_art_url,
                            "confidence": 1.0,
                            "source": "musicbrainz",
                            "is_stored_mbid": True,
                            "mbid_type": "release-group",
                        }
                        mbid_type = "release-group"

                if stored_result:
                    results.append(stored_result)
                    logging.info(
                        f"[MB_LOOKUP] Found existing {mbid_type} MBID {existing_mbid}: "
                        f"{stored_result['title']} by {stored_result['artist']}"
                    )
            except Exception as mbid_err:
                logging.warning(f"[MB_LOOKUP] Could not look up existing MBID {existing_mbid}: {mbid_err}")

        # ------------------------------------------------------------------
        # Step 2: Text search for release groups
        # ------------------------------------------------------------------
        # Search MusicBrainz for release groups using shared retry session
        query = f'release:"{album}" AND artist:"{artist}"'
        
        with create_retry_session(
            retries=3,
            backoff=1.0,
            status_forcelist=(429, 500, 502, 503, 504)
        ) as session:
            try:
                resp = session.get(
                    "https://musicbrainz.org/ws/2/release-group",
                    params={"query": query, "fmt": "json", "limit": 10},
                    headers=headers,
                    timeout=(5, 10)  # (connect_timeout, read_timeout)
                )
                resp.raise_for_status()
                search_data = resp.json()
                release_groups = search_data.get("release-groups", []) or []
            except requests.exceptions.RequestException as e:
                logger.warning(f"MusicBrainz album lookup unavailable after retries: {e}")
                if results:
                    # Return stored MBID result even if text search failed
                    return jsonify({"results": results}), 200
                return jsonify({
                    "error": f"MusicBrainz connection failed. Try Discogs instead.",
                    "results": []
                }), 503
        
        if not release_groups and not results:
            return jsonify({"results": [], "message": "No MusicBrainz album matches found"}), 200
        
        # Collect existing MBID values to avoid duplicating the stored result
        seen_mbids = {r["mbid"] for r in results}

        for rg in release_groups:
            rg_id = rg.get("id", "")
            if rg_id in seen_mbids:
                continue
            rg_title = rg.get("title", "")
            primary_type = rg.get("primary-type", "Album")
            first_release = rg.get("first-release-date", "")
            
            # Get artist credit
            artist_credit = rg.get("artist-credit", [])
            rg_artist = artist_credit[0].get("name", "") if artist_credit else ""
            
            # Calculate similarity scores
            title_similarity = difflib.SequenceMatcher(None, album.lower(), rg_title.lower()).ratio()
            artist_similarity = difflib.SequenceMatcher(None, artist.lower(), rg_artist.lower()).ratio()
            overall_confidence = (title_similarity * 0.7 + artist_similarity * 0.3)
            
            # Get cover art URL
            cover_art_url = f"https://coverartarchive.org/release-group/{rg_id}/front-250" if rg_id else ""
            
            results.append({
                "mbid": rg_id,
                "title": rg_title,
                "artist": rg_artist,
                "primary_type": primary_type,
                "first_release_date": first_release,
                "cover_art_url": cover_art_url,
                "confidence": round(overall_confidence, 3),
                "title_similarity": round(title_similarity, 3),
                "artist_similarity": round(artist_similarity, 3),
                "source": "musicbrainz",
                "is_stored_mbid": False,
            })
        
        # Sort by confidence; keep stored MBID always first
        stored = [r for r in results if r.get("is_stored_mbid")]
        others = sorted([r for r in results if not r.get("is_stored_mbid")], key=lambda x: x["confidence"], reverse=True)
        results = stored + others
        
        return jsonify({"results": results[:11]}), 200
            
    except Exception as e:
        logger = logging.getLogger('sptnr')
        logger.error(f"MusicBrainz album lookup error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/album/musicbrainz/release-group/releases", methods=["POST"])
def api_release_group_releases():
    """Fetch all specific releases in a MusicBrainz release group."""
    try:
        data = request.get_json(force=True, silent=True) or {}
        rg_mbid = (data.get("release_group_mbid") or "").strip()
        if not rg_mbid:
            return jsonify({"error": "release_group_mbid is required"}), 400

        headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
        time.sleep(1)
        resp = requests.get(
            "https://musicbrainz.org/ws/2/release",
            params={
                "release-group": rg_mbid,
                "fmt": "json",
                "inc": "media",
                "limit": 50,
            },
            headers=headers,
            timeout=10,
        )
        resp.raise_for_status()
        releases_data = resp.json().get("releases", []) or []

        releases = []
        for r in releases_data:
            media = r.get("media", [])
            total_tracks = sum(m.get("track-count", 0) for m in media)
            disc_count = len(media)
            formats = list({m.get("format", "") for m in media if m.get("format")})
            releases.append({
                "id": r.get("id", ""),
                "title": r.get("title", ""),
                "date": r.get("date", ""),
                "country": r.get("country", ""),
                "status": r.get("status", ""),
                "disambiguation": r.get("disambiguation", ""),
                "track_count": total_tracks,
                "disc_count": disc_count,
                "formats": formats,
                "cover_art_url": f"https://coverartarchive.org/release/{r.get('id')}/front-250" if r.get("id") else "",
            })

        releases.sort(key=lambda x: (x["date"] == "", x["date"]))

        return jsonify({"success": True, "releases": releases}), 200

    except Exception as e:
        logging.error(f"[release_group_releases] Error: {e}")
        return jsonify({"error": "Failed to fetch releases"}), 500


@app.route("/api/album/musicbrainz/compare", methods=["POST"])
def api_album_musicbrainz_compare():
    """Compare MusicBrainz release tracks with library tracks to identify metadata that needs updating.

    Accepts a release-group or release MBID alongside the library artist/album names.
    Returns a per-track comparison showing which fields differ so the UI can offer
    selective or bulk updates.
    """
    try:
        import difflib as _difflib
        data = request.get_json(force=True, silent=True) or {}
        release_group_mbid = (data.get("release_group_mbid") or "").strip()
        artist = (data.get("artist") or "").strip()
        album = (data.get("album") or "").strip()

        if not release_group_mbid or not artist or not album:
            return jsonify({"error": "release_group_mbid, artist, and album are required"}), 400

        # Fetch MusicBrainz release data from cache first (handles release and release-group MBIDs).
        from folder_matching_enhancements import get_musicbrainz_release_metadata
        mb_release = get_musicbrainz_release_metadata(release_group_mbid)
        if not mb_release:
            return jsonify({"error": "Could not fetch MusicBrainz release data"}), 404

        mb_tracks = mb_release.get("tracks", [])
        mb_year = mb_release.get("release_year", "")
        mb_release_title = mb_release.get("release_title", "")

        # Fetch library tracks for this album
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(f"""
            SELECT id, title, track_number, disc_number, artist, year, mbid, file_path, duration, mb_ignored_fields
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
              AND album = {placeholder}
            ORDER BY COALESCE(disc_number, 1), COALESCE(track_number, 999)
        """, (artist, album))
        library_tracks = [dict(r) for r in cursor.fetchall()]
        conn.close()

        if not library_tracks:
            return jsonify({
                "success": False,
                "error": "No library tracks found for this album",
                "comparison": [],
            }), 404

        # Build lookup maps: (disc, track_num) -> track  and  (disc, norm_title) -> track
        lib_by_tracknum = {}
        lib_by_title = {}
        for t in library_tracks:
            disc = int(t.get("disc_number") or 1)
            num = t.get("track_number")
            if num is not None:
                try:
                    lib_by_tracknum[(disc, int(num))] = t
                except (TypeError, ValueError):
                    pass
            norm = re.sub(r"\s+", " ", (t.get("title") or "").lower().strip())
            lib_by_title[(disc, norm)] = t

        # Compare each MB track with the library.
        # matched_lib_ids tracks every library track that has already been claimed by a
        # previous MB-track match.  Fuzzy fallbacks (steps 3 & 4) skip claimed tracks so
        # that e.g. a disc-3 "Song (Instrumental)" cannot steal the disc-1 "Song" that
        # was already correctly matched by the disc-1 MB entry.
        matched_lib_ids: set = set()
        comparison = []
        for mb_track in mb_tracks:
            disc = int(mb_track.get("disc_number") or 1)
            mb_num = mb_track.get("track_number")
            mb_track_title = mb_track.get("title", "")
            mb_track_artist = mb_track.get("artist", "")
            mb_recording_id = mb_track.get("recording_mbid", "")

            # 1. Match by track number — only accepted when titles are reasonably similar,
            #    to avoid false matches on albums where track ordering differs between
            #    the library and MusicBrainz (e.g. library track 5 is "Intro" but MB
            #    track 5 is "Symphony No. 5").
            _TRACK_NUM_TITLE_SIM_MIN = 0.30  # minimum similarity to trust a track-number match
            lib_track = None
            if mb_num is not None:
                try:
                    candidate = lib_by_tracknum.get((disc, int(mb_num)))
                    if candidate is not None:
                        # Accept the track-number match only if the titles are similar
                        # enough to reduce false positives.
                        if mb_track_title:
                            norm_mb_title = re.sub(r"\s+", " ", mb_track_title.lower().strip())
                            norm_lib_title = re.sub(r"\s+", " ", (candidate.get("title") or "").lower().strip())
                            sim = _difflib.SequenceMatcher(None, norm_mb_title, norm_lib_title).ratio()
                            if sim >= _TRACK_NUM_TITLE_SIM_MIN or not norm_lib_title:
                                lib_track = candidate
                            # else: fall through to title-based matching below
                        else:
                            lib_track = candidate
                except (TypeError, ValueError):
                    pass

            # 2. Match by exact normalised title
            if lib_track is None:
                norm_mb = re.sub(r"\s+", " ", mb_track_title.lower().strip())
                lib_track = lib_by_title.get((disc, norm_mb))

                # 3. Fuzzy title match (≥80% similarity) — restricted to the same disc
                #    so that instrumental/bonus tracks on a higher-numbered MB disc are
                #    never matched against regular tracks on a lower library disc (e.g.
                #    MB disc 3 "Song (Instrumental)" must not match library disc 1 "Song").
                #    Also skips library tracks already claimed by an earlier MB track.
                if lib_track is None:
                    best_ratio = 0.0
                    best_t = None
                    for t in library_tracks:
                        if int(t.get("disc_number") or 1) != disc:
                            continue
                        if t.get("id") in matched_lib_ids:
                            continue
                        lib_norm = re.sub(r"\s+", " ", (t.get("title") or "").lower().strip())
                        ratio = _difflib.SequenceMatcher(None, norm_mb, lib_norm).ratio()
                        if ratio > best_ratio and ratio >= 0.80:
                            best_ratio = ratio
                            best_t = t
                    lib_track = best_t

                # 4. Core-title match: strip parenthetical/bracketed suffixes from the
                #    MB title (e.g. "World So Cold (live at …)" → "World So Cold") and
                #    retry exact then fuzzy matching against library titles.  This
                #    handles recordings where MusicBrainz adds venue/year/version info
                #    in parentheses that the local library title omits.
                #    The regex strips greedily from the first ( or [ to end-of-string.
                #    e.g. "Song (feat. X) (Remix)" → "Song", which correctly matches
                #    a library entry titled simply "Song".
                #    Like step 3, matching is restricted to the same disc and to
                #    unclaimed library tracks.
                if lib_track is None:
                    norm_mb_core = re.sub(r"\s*[\(\[].+$", "", norm_mb).strip()
                    if norm_mb_core and norm_mb_core != norm_mb:
                        candidate_exact = lib_by_title.get((disc, norm_mb_core))
                        if candidate_exact is not None and candidate_exact.get("id") not in matched_lib_ids:
                            lib_track = candidate_exact
                        if lib_track is None:
                            best_ratio = 0.0
                            best_t = None
                            for t in library_tracks:
                                if int(t.get("disc_number") or 1) != disc:
                                    continue
                                if t.get("id") in matched_lib_ids:
                                    continue
                                lib_norm = re.sub(r"\s+", " ", (t.get("title") or "").lower().strip())
                                ratio = _difflib.SequenceMatcher(None, norm_mb_core, lib_norm).ratio()
                                if ratio > best_ratio and ratio >= 0.80:
                                    best_ratio = ratio
                                    best_t = t
                            lib_track = best_t

            mb_duration_ms_raw = mb_track.get("duration")
            mb_duration_sec_raw = int(mb_duration_ms_raw // 1000) if mb_duration_ms_raw else None

            entry = {
                "mb_track_number": mb_num,
                "mb_disc_number": disc,
                "mb_title": mb_track_title,
                "mb_artist": mb_track_artist,
                "mb_recording_id": mb_recording_id,
                "mb_year": mb_year,
                "library_track_id": None,
                "library_title": None,
                "library_track_number": None,
                "library_artist": None,
                "library_year": None,
                "mb_duration": None,
                "mb_duration_sec": mb_duration_sec_raw,
                "library_duration": None,
                "needs_update": False,
                "diff_fields": [],
                "matched": False,
            }

            if lib_track:
                matched_lib_ids.add(lib_track["id"])
                entry["matched"] = True
                entry["library_track_id"] = lib_track.get("id")
                entry["library_title"] = lib_track.get("title", "")
                entry["library_track_number"] = lib_track.get("track_number")
                entry["library_artist"] = lib_track.get("artist", "")
                entry["library_year"] = str(lib_track.get("year") or "")

                diff_fields = []
                # Title differs? — skip if the only difference is a "(Artist Cover)" suffix
                # in the library title, e.g. "Song (Bob Dylan Cover)" vs MB "Song".
                if mb_track_title and mb_track_title != lib_track.get("title", ""):
                    lib_title = lib_track.get("title", "")
                    if re.search(r'\([^)]*\bcover\b[^)]*\)', lib_title, re.IGNORECASE):
                        # Strip the cover notation and compare again; if they now match,
                        # this is an expected cover-version annotation — don't flag it.
                        stripped = re.sub(r'\s*\([^)]*\bcover\b[^)]*\)', '', lib_title, flags=re.IGNORECASE).strip()
                        if stripped.lower() != mb_track_title.lower():
                            diff_fields.append("title")
                    else:
                        diff_fields.append("title")
                # Track number differs?
                if mb_num is not None and str(mb_num) != str(lib_track.get("track_number") or ""):
                    diff_fields.append("track_number")
                # Year differs?
                if mb_year and str(mb_year) != str(lib_track.get("year") or ""):
                    diff_fields.append("year")
                # MBID: flag if library is missing recording MBID but MB has one
                lib_mbid = (lib_track.get("mbid") or "").strip()
                if mb_recording_id and not lib_mbid:
                    diff_fields.append("mbid")
                # Duration: flag if they differ by more than 5 seconds
                _DURATION_TOLERANCE_SEC = 5
                mb_duration_ms = mb_track.get("duration")
                mb_duration_sec = (mb_duration_ms / 1000.0) if mb_duration_ms else None
                raw_lib_dur = lib_track.get("duration")
                if raw_lib_dur not in (None, "", 0, "0"):
                    try:
                        lib_dur_val = float(raw_lib_dur)
                        lib_duration_sec = (lib_dur_val / 1000.0) if lib_dur_val > 10000 else lib_dur_val
                        lib_duration_sec = lib_duration_sec if lib_duration_sec > 0 else None
                    except (TypeError, ValueError):
                        lib_duration_sec = None
                else:
                    lib_duration_sec = None

                def _fmt_dur(sec):
                    if sec is None:
                        return None
                    s = int(round(sec))
                    return f"{s // 60}:{s % 60:02d}"

                entry["mb_duration"] = _fmt_dur(mb_duration_sec)
                entry["library_duration"] = _fmt_dur(lib_duration_sec)

                if mb_duration_sec is not None and lib_duration_sec is not None:
                    if abs(mb_duration_sec - lib_duration_sec) > _DURATION_TOLERANCE_SEC:
                        diff_fields.append("duration")

                # Disc number: flag if library disc_number differs from MB disc_number
                lib_disc_val = int(lib_track.get("disc_number") or 1)
                entry["library_disc_number"] = lib_disc_val
                if lib_disc_val != disc:
                    diff_fields.append("disc_number")

                # Remove any fields the user has permanently ignored for this track
                import json as _json_cmp
                _raw_ignored = lib_track.get("mb_ignored_fields") or "[]"
                try:
                    _ignored_set = set(_json_cmp.loads(_raw_ignored))
                except Exception:
                    _ignored_set = set()
                diff_fields = [f for f in diff_fields if f not in _ignored_set]

                entry["diff_fields"] = diff_fields
                entry["needs_update"] = len(diff_fields) > 0

            comparison.append(entry)

        tracks_needing_update = sum(1 for c in comparison if c["needs_update"])

        # ── Cross-disc matching pass ──────────────────────────────────────────
        # After the same-disc pass, some MB tracks may remain unmatched because
        # the library stores them under a different disc number (e.g. library has
        # tracks 23–37 on disc 1 but MusicBrainz places them on disc 2).
        # For each still-unmatched MB track, try a fuzzy title match against
        # still-unmatched library tracks on *any* disc.  When a cross-disc match
        # is found the track is promoted to a regular comparison entry with
        # "disc_number" in diff_fields so the UI can suggest the corrective move.
        matched_mb_recording_ids: set = {
            e.get("mb_recording_id", "") for e in comparison if e.get("matched")
        }
        for mb_track in mb_tracks:
            mb_recording_id = mb_track.get("recording_mbid", "")
            if mb_recording_id and mb_recording_id in matched_mb_recording_ids:
                continue
            mb_track_title = mb_track.get("title", "")
            mb_num = mb_track.get("track_number")
            disc = int(mb_track.get("disc_number") or 1)

            # Check whether this MB track was already matched in the main pass.
            already_matched = any(
                e.get("matched") and e.get("mb_title") == mb_track_title
                and int(e.get("mb_disc_number") or 1) == disc
                and e.get("mb_track_number") == mb_num
                for e in comparison
            )
            if already_matched:
                continue

            # Fuzzy title search across all discs (excluding already-matched library tracks)
            norm_mb = re.sub(r"\s+", " ", mb_track_title.lower().strip())
            # Derive a "core" title by truncating at the first parenthetical/bracket.
            # Use str.find to avoid catastrophic backtracking on user-supplied text.
            _paren = norm_mb.find('(')
            _brack = norm_mb.find('[')
            _cut = min(x for x in (_paren, _brack, len(norm_mb)) if x >= 0)
            norm_mb_core = norm_mb[:_cut].rstrip()

            best_ratio = 0.0
            best_lib = None
            for t in library_tracks:
                if t.get("id") in matched_lib_ids:
                    continue
                # Must be on a different disc to be a cross-disc candidate
                lib_disc = int(t.get("disc_number") or 1)
                if lib_disc == disc:
                    continue
                lib_norm = re.sub(r"\s+", " ", (t.get("title") or "").lower().strip())
                ratio = _difflib.SequenceMatcher(None, norm_mb, lib_norm).ratio()
                if ratio < 0.80 and norm_mb_core and norm_mb_core != norm_mb:
                    ratio = max(ratio, _difflib.SequenceMatcher(None, norm_mb_core, lib_norm).ratio())
                if ratio > best_ratio and ratio >= 0.80:
                    best_ratio = ratio
                    best_lib = t

            if best_lib is None:
                continue

            # We have a cross-disc match — build a comparison entry identical to
            # the same-disc path but with disc_number guaranteed in diff_fields.
            lib_track = best_lib
            matched_lib_ids.add(lib_track["id"])
            if mb_recording_id:
                matched_mb_recording_ids.add(mb_recording_id)

            mb_year = mb_release.get("release_year", "")
            mb_duration_ms_raw = mb_track.get("duration")
            mb_duration_sec_raw = int(mb_duration_ms_raw // 1000) if mb_duration_ms_raw else None

            entry = {
                "mb_track_number": mb_num,
                "mb_disc_number": disc,
                "mb_title": mb_track_title,
                "mb_artist": mb_track.get("artist", ""),
                "mb_recording_id": mb_recording_id,
                "mb_year": mb_year,
                "library_track_id": lib_track["id"],
                "library_title": lib_track.get("title", ""),
                "library_track_number": lib_track.get("track_number"),
                "library_disc_number": int(lib_track.get("disc_number") or 1),
                "library_artist": lib_track.get("artist", ""),
                "library_year": str(lib_track.get("year") or ""),
                "mb_duration": None,
                "mb_duration_sec": mb_duration_sec_raw,
                "library_duration": None,
                "matched": True,
                "cross_disc_match": True,
            }

            diff_fields = []
            if mb_track_title and mb_track_title != lib_track.get("title", ""):
                lib_title = lib_track.get("title", "")
                if re.search(r'\([^)]*\bcover\b[^)]*\)', lib_title, re.IGNORECASE):
                    stripped = re.sub(r'\s*\([^)]*\bcover\b[^)]*\)', '', lib_title, flags=re.IGNORECASE).strip()
                    if stripped.lower() != mb_track_title.lower():
                        diff_fields.append("title")
                else:
                    diff_fields.append("title")
            if mb_num is not None and str(mb_num) != str(lib_track.get("track_number") or ""):
                diff_fields.append("track_number")
            if mb_year and str(mb_year) != str(lib_track.get("year") or ""):
                diff_fields.append("year")
            lib_mbid = (lib_track.get("mbid") or "").strip()
            if mb_recording_id and not lib_mbid:
                diff_fields.append("mbid")

            mb_duration_sec = (mb_duration_ms_raw / 1000.0) if mb_duration_ms_raw else None
            raw_lib_dur = lib_track.get("duration")
            if raw_lib_dur not in (None, "", 0, "0"):
                try:
                    lib_dur_val = float(raw_lib_dur)
                    lib_duration_sec = (lib_dur_val / 1000.0) if lib_dur_val > 10000 else lib_dur_val
                    lib_duration_sec = lib_duration_sec if lib_duration_sec > 0 else None
                except (TypeError, ValueError):
                    lib_duration_sec = None
            else:
                lib_duration_sec = None

            def _fmt_dur2(sec):
                if sec is None:
                    return None
                s = int(round(sec))
                return f"{s // 60}:{s % 60:02d}"

            entry["mb_duration"] = _fmt_dur2(mb_duration_sec)
            entry["library_duration"] = _fmt_dur2(lib_duration_sec)
            if mb_duration_sec is not None and lib_duration_sec is not None:
                if abs(mb_duration_sec - lib_duration_sec) > 5:
                    diff_fields.append("duration")

            # disc_number mismatch is the whole point of this match
            diff_fields.append("disc_number")

            import json as _json_xdisc
            _raw_ignored = lib_track.get("mb_ignored_fields") or "[]"
            try:
                _ignored_set = set(_json_xdisc.loads(_raw_ignored))
            except Exception:
                _ignored_set = set()
            diff_fields = [f for f in diff_fields if f not in _ignored_set]
            diff_fields = list(dict.fromkeys(diff_fields))  # deduplicate, preserve order

            entry["diff_fields"] = diff_fields
            entry["needs_update"] = len(diff_fields) > 0
            comparison.append(entry)

        # Recount after cross-disc pass
        tracks_needing_update = sum(1 for c in comparison if c["needs_update"])

        # Identify library tracks that were never matched by any MB track —
        # these are "extra" tracks that exist locally but are not part of the
        # official release according to MusicBrainz.
        extra_tracks = []
        for t in library_tracks:
            if t["id"] not in matched_lib_ids:
                extra_tracks.append({
                    "library_track_id": t["id"],
                    "library_title": t.get("title", ""),
                    "library_track_number": t.get("track_number"),
                    "library_disc_number": int(t.get("disc_number") or 1),
                    "library_artist": t.get("artist", ""),
                })

        # Persist comparison results to the database so that the "MusicBrainz
        # update available" banners survive page refreshes.
        try:
            import json as _json
            conn_p = get_db()
            cursor_p = conn_p.cursor()
            ph_p = "%s"
            # Clear any stale pending updates for all tracks in this album so
            # that tracks which are now up-to-date no longer show a banner.
            cursor_p.execute(
                f"UPDATE tracks SET pending_mb_updates = NULL "
                f"WHERE COALESCE(NULLIF(album_artist, ''), artist) = {ph_p} AND album = {ph_p}",
                (artist, album),
            )
            # Store fresh pending update data for tracks that still need it.
            for entry in comparison:
                if entry.get("needs_update") and entry.get("library_track_id"):
                    cursor_p.execute(
                        f"UPDATE tracks SET pending_mb_updates = {ph_p} WHERE id = {ph_p}",
                        (_json.dumps(entry), entry["library_track_id"]),
                    )
            # Mark extra tracks (not in MB metadata) so the badge persists on page refresh.
            for extra in extra_tracks:
                cursor_p.execute(
                    f"UPDATE tracks SET pending_mb_updates = {ph_p} WHERE id = {ph_p}",
                    (_json.dumps({"is_extra": True}), extra["library_track_id"]),
                )
            conn_p.commit()
            conn_p.close()
        except Exception as _save_err:
            logging.warning(f"[MB_COMPARE] Could not persist comparison results: {_save_err}")

        # Persist unmatched (missing) tracks so they survive page refreshes.
        # Only non-ignored entries from a previous comparison are replaced; ignored
        # entries remain untouched so the user's "Ignore" choice is preserved.
        try:
            conn_m = get_db()
            cursor_m = conn_m.cursor()
            ph_m = "%s"
            _ensure_missing_album_tracks_table(cursor_m)
            # Remove only non-ignored entries for this album so we get a fresh set
            cursor_m.execute(
                f"DELETE FROM missing_album_tracks "
                f"WHERE artist_name = {ph_m} AND album_name = {ph_m} AND ignored = FALSE",
                (artist, album),
            )
            for entry in comparison:
                if not entry.get("matched"):
                    cursor_m.execute(
                        f"INSERT INTO missing_album_tracks "
                        f"(artist_name, album_name, title, track_number, disc_number, track_artist, year, release_id, recording_mbid, duration) "
                        f"VALUES ({ph_m},{ph_m},{ph_m},{ph_m},{ph_m},{ph_m},{ph_m},{ph_m},{ph_m},{ph_m})",
                        (
                            artist, album,
                            entry.get("mb_title", ""),
                            str(entry.get("mb_track_number") or ""),
                            int(entry.get("mb_disc_number") or 1),
                            entry.get("mb_artist") or artist,
                            str(mb_year or ""),
                            release_group_mbid,
                            entry.get("mb_recording_id") or "",
                            entry.get("mb_duration_sec"),
                        ),
                    )
            conn_m.commit()
            conn_m.close()
        except Exception as _miss_err:
            logging.warning(f"[MB_COMPARE] Could not persist missing tracks: {_miss_err}")

        return jsonify({
            "success": True,
            "mb_title": mb_release_title,
            "mb_year": mb_year,
            "mb_artist": mb_release.get("artist", ""),
            "release_group_mbid": release_group_mbid,
            "comparison": comparison,
            "extra_tracks": extra_tracks,
            "tracks_needing_update": tracks_needing_update,
            "total_tracks": len(comparison),
        }), 200

    except Exception as e:
        logging.error(f"MusicBrainz compare error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/album/discogs", methods=["POST"])
def api_album_discogs_lookup():
    """Lookup album on Discogs for better metadata and genres"""
    try:
        from popularity import _discogs_search, _get_discogs_session
        import difflib
        
        data = request.get_json(force=True, silent=True)
        if not data:
            return jsonify({"error": "Invalid JSON in request body"}), 400
        album = data.get("album", "")
        artist = data.get("artist", "")
        
        if not album or not artist:
            return jsonify({"error": "Missing album or artist"}), 400
        
        # Get Discogs config for token
        config_data, _ = _read_yaml(CONFIG_PATH)
        discogs_config = config_data.get("api_integrations", {}).get("discogs", {})
        discogs_token = discogs_config.get("token", "")
        
        # Search Discogs with multiple query strategies
        session = _get_discogs_session()
        headers = {"User-Agent": "Popularr/1.0"}
        if discogs_token:
            headers["Authorization"] = f"Discogs token={discogs_token}"
        
        # Try different query formats to improve match rate
        queries = [
            f"{artist} {album}",  # Full query
            f'artist:"{artist}" release:"{album}"',  # Structured query
            f'{artist} "{album}"',  # Quoted album
        ]
        
        results = []
        for query in queries:
            logger = logging.getLogger('sptnr')
            logger.debug(f"Discogs search attempt: {query}")
            results = _discogs_search(session, headers, query, kind="release", per_page=10)
            if results:
                logger.debug(f"Discogs search found {len(results)} results")
                break
            logger.debug(f"Discogs search with query '{query}' returned no results")
        
        if not results:
            return jsonify({"results": [], "message": "No Discogs album matches found"}), 200
        
        # Format results with similarity scoring
        formatted_results = []
        for result in results[:10]:
            result_title = result.get("title", "Unknown")
            # Calculate similarity to improve ordering
            title_sim = difflib.SequenceMatcher(None, album.lower(), result_title.lower()).ratio()
            artist_part = result_title.split("-")[0] if "-" in result_title else result_title
            artist_sim = difflib.SequenceMatcher(None, artist.lower(), artist_part.lower()).ratio()
            overall_conf = (title_sim * 0.7 + artist_sim * 0.3)
            
            formatted_results.append({
                "title": result_title,
                "year": result.get("year", ""),
                "genre": result.get("genre", []),
                "style": result.get("style", []),
                "format": result.get("format", []),
                "url": result.get("resource_url", ""),
                "discogs_id": result.get("id", ""),
                "confidence": round(overall_conf, 3),
                "source": "discogs"
            })
        
        # Sort by confidence
        formatted_results.sort(key=lambda x: x["confidence"], reverse=True)
        
        return jsonify({"results": formatted_results}), 200
    except Exception as e:
        logger = logging.getLogger('sptnr')
        logger.error(f"Discogs lookup error: {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/album/spotify-genres", methods=["POST"])
def api_album_spotify_genres():
    """Get Spotify genres for an album from database"""
    logger = logging.getLogger('sptnr')
    try:
        data = request.get_json(force=True, silent=True)
        if not data:
            return jsonify({"error": "Invalid JSON in request body"}), 400
        album = data.get("album", "")
        artist = data.get("artist", "")
        
        if not album or not artist:
            return jsonify({"error": "Missing album or artist"}), 400
        
        # Get Spotify artist genres from tracks in this album
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Try to get spotify_artist_genres column, fall back to spotify_genres if column doesn't exist
        try:
            cursor.execute(f"""
                SELECT DISTINCT spotify_artist_genres
                FROM tracks
                WHERE artist = {placeholder} AND album = {placeholder} 
                AND spotify_artist_genres IS NOT NULL 
                AND spotify_artist_genres != ''
            """, (artist, album))
            genre_rows = cursor.fetchall()
        except Exception:
            # Fallback if spotify_artist_genres column doesn't exist
            cursor.execute(f"""
                SELECT DISTINCT spotify_genres
                FROM tracks
                WHERE artist = {placeholder} AND album = {placeholder} 
                AND spotify_genres IS NOT NULL 
                AND spotify_genres != ''
            """, (artist, album))
            genre_rows = cursor.fetchall()
        
        conn.close()
        
        # Aggregate unique genres
        genres = set()
        for row in genre_rows:
            try:
                genre_value = row[0] if row else None
                if genre_value:
                    # Parse JSON array
                    genre_list = json.loads(genre_value)
                    if isinstance(genre_list, list):
                        genres.update(genre_list)
            except (json.JSONDecodeError, IndexError, TypeError) as e:
                logger.debug(f"Error parsing Spotify genres: {e}")
                continue
        
        return jsonify({"genres": sorted(list(genres))}), 200
    except Exception as e:
        logger.error(f"Spotify genres lookup error: {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/album/apply-mbid", methods=["POST"])
def api_album_apply_mbid():
    """Apply MusicBrainz ID and cover art to all tracks in an album"""
    try:
        data = request.get_json() or {}
        artist = data.get("artist", "")
        album = data.get("album", "")
        mbid = str(data.get("mbid", "") or "").strip()
        release_group_mbid = str(data.get("release_group_mbid", "") or "").strip()
        cover_art_url = data.get("cover_art_url", "")
        
        if not artist or not album:
            return jsonify({"error": "Missing artist or album"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # Detect compatible album-level MBID column for mixed schema deployments.
        track_columns = _get_table_columns(cursor, "tracks") or set()
        mb_album_column = None
        if "musicbrainz_album_mbid" in track_columns:
            mb_album_column = "musicbrainz_album_mbid"
        elif "beets_album_mbid" in track_columns:
            mb_album_column = "beets_album_mbid"
        release_group_column = "musicbrainz_releasegroupid" if "musicbrainz_releasegroupid" in track_columns else None

        cursor.execute(
            f"""
            SELECT id, file_path
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
              AND album = {placeholder}
            """,
            (artist, album),
        )
        track_rows = [
            dict(r) if hasattr(r, "keys") else {"id": r[0], "file_path": r[1]}
            for r in cursor.fetchall()
        ]
        
        # Update all tracks in this album with MBID and cover art.
        # Do not overwrite per-track recording MBID (`mbid`) with album/release IDs.
        updates = []
        if mbid and mb_album_column:
            updates.append(f"{mb_album_column} = {placeholder}")
        if release_group_mbid and release_group_column:
            updates.append(f"{release_group_column} = {placeholder}")
        if cover_art_url:
            updates.append(f"cover_art_url = {placeholder}")
        
        if not updates:
            return jsonify({"error": "No data to update"}), 400
        
        query = (
            f"UPDATE tracks SET {', '.join(updates)} "
            f"WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} AND album = {placeholder}"
        )
        params = []
        if mbid and mb_album_column:
            params.append(mbid)
        if release_group_mbid and release_group_column:
            params.append(release_group_mbid)
        if cover_art_url:
            params.append(cover_art_url)
        params.extend([artist, album])
        
        cursor.execute(query, params)
        rows_updated = cursor.rowcount
        conn.commit()
        conn.close()

        files_updated = 0
        if track_rows and (mbid or release_group_mbid):
            try:
                from helpers.tag_manager import write_tags_to_file
            except Exception:
                write_tags_to_file = None

            if write_tags_to_file:
                for row in track_rows:
                    file_path = str(row.get("file_path") or "").strip()
                    if not file_path or not os.path.exists(file_path):
                        continue
                    tag_updates = {}
                    if mbid:
                        tag_updates["musicbrainz_album_mbid"] = mbid
                    if release_group_mbid:
                        tag_updates["musicbrainz_releasegroupid"] = release_group_mbid
                    if not tag_updates:
                        continue
                    try:
                        if write_tags_to_file(file_path, tag_updates):
                            files_updated += 1
                    except Exception as file_err:
                        logging.warning(f"[ALBUM_APPLY_MBID] Failed writing tags to {file_path}: {file_err}")

        logging.info(f"Applied album MBID {mbid} to {rows_updated} tracks in {artist} - {album}")
        
        return jsonify({
            "success": True,
            "message": f"Updated {rows_updated} tracks with MBID and cover art",
            "rows_updated": rows_updated,
            "files_updated": files_updated,
        }), 200
    except Exception as e:
        logger = logging.getLogger('sptnr')
        logger.error(f"Apply MBID error: {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/album/apply-discogs-id", methods=["POST"])
def api_album_apply_discogs_id():
    """Apply Discogs ID to all tracks in an album"""
    import time
    logger = logging.getLogger('sptnr')
    try:
        data = request.get_json()
        artist = data.get("artist", "")
        album = data.get("album", "")
        discogs_id = data.get("discogs_id", "")
        is_single = data.get("is_single", False)  # Check if Discogs marked this as Single
        
        if not artist or not album or not discogs_id:
            return jsonify({"error": "Missing required fields"}), 400
        
        # Retry logic for database lock
        max_retries = 3
        retry_delay = 0.5
        rows_updated = 0
        last_error = None
        
        for attempt in range(max_retries):
            try:
                conn = get_db()
                placeholder = "%s"
                cursor = conn.cursor()
                placeholder = "%s"
                
                # Update all tracks in this album with Discogs ID and is_single flag if detected
                if is_single:
                    # If Discogs detected this as a Single, mark tracks as singles with high confidence and set 5★ rating
                    is_single_true = "TRUE"
                    cursor.execute(
                        f"UPDATE tracks SET discogs_album_id = {placeholder}, is_single = {is_single_true}, single_confidence = 'high', single_sources = CASE WHEN single_sources IS NULL THEN 'discogs' ELSE single_sources || ',discogs' END, stars = 5 WHERE artist = {placeholder} AND album = {placeholder}",
                        (discogs_id, artist, album)
                    )
                else:
                    # Just update the Discogs ID
                    cursor.execute(
                        f"UPDATE tracks SET discogs_album_id = {placeholder} WHERE artist = {placeholder} AND album = {placeholder}",
                        (discogs_id, artist, album)
                    )
                
                rows_updated = cursor.rowcount
                conn.commit()
                conn.close()
                
                if is_single:
                    logger.info(f"Updated {rows_updated} tracks with Discogs ID {discogs_id} and marked as single with 5★ rating for {artist} - {album}")
                else:
                    logger.info(f"Updated {rows_updated} tracks with Discogs ID {discogs_id} for {artist} - {album}")
                
                return jsonify({
                    "success": True,
                    "message": f"Updated {rows_updated} tracks with Discogs ID" + (" and marked as single with 5★ rating" if is_single else ""),
                    "rows_updated": rows_updated
                }), 200
            except Exception as inner_e:
                last_error = inner_e
                raise
        
        # If we get here, all retries failed
        logger.error(f"Apply Discogs ID failed after {max_retries} retries: {last_error}")
        return jsonify({"error": f"Database locked. Please try again."}), 503
    except Exception as e:
        logger = logging.getLogger('sptnr')
        logger.error(f"Apply Discogs ID error: {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/album/majority-artist", methods=["POST"])
def api_album_majority_artist():
    """Get the most common artist from all tracks in an album"""
    from collections import Counter
    try:
        data = request.get_json()
        artist = data.get("artist", "").strip()
        album = data.get("album", "").strip()
        
        if not artist or not album:
            return jsonify({"error": "Missing required fields"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = get_placeholder(conn)
        
        # Get all track artists from this album
        cursor.execute(f"""
            SELECT artist FROM tracks 
            WHERE album = {placeholder} 
            ORDER BY track_number ASC
        """, (album,))
        
        tracks = cursor.fetchall()
        conn.close()
        
        if not tracks:
            # No tracks found, return the album artist as default
            return jsonify({"majority_artist": artist}), 200
        
        # Count occurrences of each artist
        artists = [t['artist'] for t in tracks]
        artist_counts = Counter(artists)
        
        # Get the most common artist
        most_common_artist = artist_counts.most_common(1)[0][0] if artist_counts else artist
        
        # Also return the count and total tracks for reference
        return jsonify({
            "majority_artist": most_common_artist,
            "count": artist_counts[most_common_artist],
            "total_tracks": len(artists)
        }), 200
    except Exception as e:
        logger = logging.getLogger('sptnr')
        logger.error(f"Get majority artist error: {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/album/apply-genres", methods=["POST"])
def api_album_apply_genres():
    """Apply selected genres to all audio files in an album"""
    logger = logging.getLogger('sptnr')
    conn = None
    try:
        data = request.get_json()
        artist = data.get("artist", "").strip()
        album = data.get("album", "").strip()
        genres = data.get("genres", [])
        
        if not artist or not album or not genres:
            return jsonify({"error": "Missing required fields"}), 400
        
        # Get all tracks in the album from database
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        cursor.execute(f"""
            SELECT id, title, file_path
            FROM tracks
            WHERE artist = {placeholder} AND album = {placeholder}
        """, (artist, album))
        tracks = cursor.fetchall()
        
        if not tracks:
            return jsonify({"error": "No tracks found in album"}), 404
        
        # Write genres to audio files using mutagen and update database per-track
        updated_count = 0
        failed_files = []
        genres_str = ','.join(genres)
        
        for track in tracks:
            # Prefer beets_path, fallback to file_path
            file_path = row_get(track, 'file_path')
            
            if not file_path or not os.path.exists(file_path):
                track_id = row_get(track, 'id', 'unknown')
                track_title = row_get(track, 'title', '')
                failed_files.append(track_title if track_title else f"Track ID: {track_id}")
                continue
            
            # Update audio file using helper function
            success, error = update_audio_file_genres(file_path, genres)
            
            if success:
                # Update database only after successful file update
                try:
                    cursor.execute(f"""
                        UPDATE tracks
                        SET genres = {placeholder}
                        WHERE id = {placeholder}
                    """, (genres_str, row_get(track, 'id')))
                    updated_count += 1
                except Exception as db_error:
                    logger.error(f"Failed to update database for {file_path}: {db_error}")
                    track_title = row_get(track, 'title', '')
                    failed_files.append(track_title if track_title else f"Track ID: {row_get(track, 'id')}")
            else:
                # Check if error is due to unsupported format or actual failure
                if error and "Unsupported format" in error:
                    logger.debug(f"Skipped {file_path}: {error}")
                    # Still update database for unsupported formats
                    try:
                        cursor.execute(f"""
                            UPDATE tracks
                            SET genres = {placeholder}
                            WHERE id = {placeholder}
                        """, (genres_str, row_get(track, 'id')))
                        updated_count += 1
                    except Exception as db_error:
                        logger.error(f"Failed to update database for {file_path}: {db_error}")
                        track_title = row_get(track, 'title', '')
                        failed_files.append(track_title if track_title else f"Track ID: {row_get(track, 'id')}")
                else:
                    logger.error(f"Failed to update {file_path}: {error}")
                    track_id = row_get(track, 'id', 'unknown')
                    track_title = row_get(track, 'title', '')
                    failed_files.append(track_title if track_title else f"Track ID: {track_id}")
        
        conn.commit()
        
        message = f"Updated {updated_count} audio file(s) with genres: {', '.join(genres)}"
        if failed_files:
            message += f". Failed to update {len(failed_files)} file(s): {', '.join(failed_files[:5])}"
        
        logger.info(f"Applied genres {genres} to album '{album}' by {artist}: {updated_count} files updated")
        
        return jsonify({
            "success": True,
            "message": message,
            "updated_count": updated_count,
            "failed_count": len(failed_files)
        }), 200
        
    except Exception as e:
        logger.error(f"Apply genres error: {e}")
        import traceback
        logger.error(traceback.format_exc())
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            conn.close()


@app.route("/api/album/add-to-missing-releases", methods=["POST"])
def api_album_add_to_missing_releases():
    """Add an album to the missing releases tracking list"""
    try:
        data = request.get_json()
        artist = data.get("artist", "").strip()
        album = data.get("album", "").strip()
        year = data.get("year", "").strip()
        
        if not artist or not album:
            return jsonify({"error": "Artist and album are required"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        # Check if missing_releases table exists
        cursor.execute("""
            SELECT tablename FROM pg_tables 
            WHERE tablename='missing_releases'
        """)
        if not cursor.fetchone():
            conn.close()
            return jsonify({"error": "Missing releases table not found"}), 500
        
        # Insert or update the album in missing_releases with DB-aware upsert
        generated_release_id = f"{artist}-{album}".lower().replace(" ", "-")
        cursor.execute(
            f"DELETE FROM missing_releases WHERE LOWER(artist) = LOWER({placeholder}) AND release_id = {placeholder}",
            (artist, generated_release_id)
        )
        cursor.execute("SELECT COALESCE(MAX(id), 0) + 1 AS next_id FROM missing_releases")
        next_id_row = cursor.fetchone()
        next_missing_release_id = int(next_id_row.get("next_id", 1)) if isinstance(next_id_row, dict) else int(next_id_row[0] if next_id_row else 1)
        cursor.execute(f"""
            INSERT INTO missing_releases 
            (id, artist, release_id, title, first_release_date, category, last_checked)
            VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, 'Album', CURRENT_TIMESTAMP)
        """, (
            next_missing_release_id,
            artist,
            generated_release_id,
            album,
            year if year else None
        ))
        conn.commit()
        conn.close()
        
        logging.info(f"Added {album} by {artist} to missing releases")
        
        return jsonify({
            "success": True,
            "message": f"Added '{album}' by {artist} to missing releases tracking"
        }), 200
        
    except Exception as e:
        logging.error(f"Error adding album to missing releases: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({"error": str(e)}), 500


