@app.route("/api/artist/genre-recommendations", methods=["GET"])
def api_artist_genre_recommendations():
    """Fetch artist genre recommendations from MusicBrainz via backend proxy."""
    artist_name = (request.args.get("artist", "") or "").strip()
    if not artist_name:
        return jsonify({"error": "Artist name is required"}), 400

    try:
        headers = {
            "User-Agent": MUSICBRAINZ_USER_AGENT,
            "Accept": "application/json"
        }

        # Search first, then fetch artist details with tags/genres for better recommendations.
        search_params = {
            "query": f'artist:"{artist_name}"',
            "fmt": "json",
            "limit": 5,
        }

        with create_retry_session(
            user_agent=MUSICBRAINZ_USER_AGENT,
            retries=2,
            backoff=0.5,
            status_forcelist=(429, 500, 502, 503, 504),
        ) as session:
            search_response = session.get(
                "https://musicbrainz.org/ws/2/artist",
                params=search_params,
                headers=headers,
                timeout=(5, 10),
            )
            search_response.raise_for_status()
            search_data = search_response.json() or {}

            candidates = search_data.get("artists", []) or []
            if not candidates:
                return jsonify({
                    "success": True,
                    "artist": artist_name,
                    "recommendations": [],
                    "message": "No MusicBrainz artist matches found",
                })

            requested_norm = _normalize_artist_name(artist_name)

            def _candidate_rank(candidate):
                candidate_name = candidate.get("name", "")
                candidate_norm = _normalize_artist_name(candidate_name)
                try:
                    mb_score = int(candidate.get("score") or 0)
                except (TypeError, ValueError):
                    mb_score = 0
                exact_bonus = 1000 if candidate_norm == requested_norm else 0
                return exact_bonus + mb_score

            best_candidate = max(candidates, key=_candidate_rank)
            artist_mbid = best_candidate.get("id", "")

            if not artist_mbid:
                return jsonify({
                    "success": True,
                    "artist": artist_name,
                    "recommendations": [],
                    "message": "Matched artist has no MusicBrainz ID",
                })

            details_response = session.get(
                f"https://musicbrainz.org/ws/2/artist/{artist_mbid}",
                params={"fmt": "json", "inc": "genres+tags"},
                headers=headers,
                timeout=(5, 10),
            )
            details_response.raise_for_status()
            details = details_response.json() or {}

        genre_scores = {}
        for entry in (details.get("genres", []) or []):
            name = str(entry.get("name") or "").strip()
            if not name:
                continue
            count = entry.get("count") or 0
            try:
                count_val = int(count)
            except (TypeError, ValueError):
                count_val = 0
            genre_scores[name] = max(genre_scores.get(name, 0), count_val)

        for entry in (details.get("tags", []) or []):
            name = str(entry.get("name") or "").strip()
            if not name:
                continue
            count = entry.get("count") or 0
            try:
                count_val = int(count)
            except (TypeError, ValueError):
                count_val = 0
            genre_scores[name] = max(genre_scores.get(name, 0), count_val)

        recommendations = [
            name for name, _ in sorted(
                genre_scores.items(),
                key=lambda item: (-item[1], item[0].lower()),
            )
        ][:15]

        return jsonify({
            "success": True,
            "artist": artist_name,
            "musicbrainz_artist": best_candidate.get("name", artist_name),
            "musicbrainz_artist_id": artist_mbid,
            "recommendations": recommendations,
            "source": "musicbrainz",
        })

    except requests.exceptions.RequestException as e:
        logging.warning(f"[ARTIST GENRES] MusicBrainz request failed for '{artist_name}': {e}")
        return jsonify({"error": "MusicBrainz request failed"}), 503
    except Exception as e:
        logging.error(f"[ARTIST GENRES] Error fetching genre recommendations for '{artist_name}': {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/track/musicbrainz", methods=["POST"])
def api_track_musicbrainz_lookup():
    """Lookup track on MusicBrainz for multiple matches (Picard-style) with retry logic"""
    logger = logging.getLogger('sptnr')
    try:
        data = request.get_json()
        title = data.get("title", "")
        artist = data.get("artist", "")
        mbid = (data.get("mbid") or "").strip()

        if not title or not artist:
            return jsonify({"error": "Missing title or artist"}), 400

        import difflib
        headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}

        def _format_recording(rec, confidence_override=None):
            rec_id = rec.get("id", "")
            rec_title = rec.get("title", "")
            rec_length = rec.get("length", 0)
            artist_credit = rec.get("artist-credit", [])
            rec_artist = artist_credit[0].get("name", "") if artist_credit else ""
            releases = rec.get("releases", []) or []
            release_list = [{"id": r.get("id", ""), "title": r.get("title", "")} for r in releases[:5]]
            best_album = releases[0].get("title", "") if releases else ""
            best_year = ""
            for rel in releases:
                rel_date = (rel.get("date") or "").strip()
                if len(rel_date) >= 4 and rel_date[:4].isdigit():
                    best_year = rel_date[:4]
                    break
            writer_names = []
            for rel in rec.get("relations", []) or []:
                rel_type = str(rel.get("type") or "").lower()
                if rel_type in ("writer", "lyricist", "composer"):
                    rel_artist = (rel.get("artist") or {}).get("name")
                    if rel_artist and rel_artist not in writer_names:
                        writer_names.append(rel_artist)
                work = rel.get("work") or {}
                for work_rel in work.get("relations", []) or []:
                    work_rel_type = str(work_rel.get("type") or "").lower()
                    if work_rel_type in ("writer", "lyricist", "composer"):
                        work_artist = (work_rel.get("artist") or {}).get("name")
                        if work_artist and work_artist not in writer_names:
                            writer_names.append(work_artist)
            if confidence_override is not None:
                overall_confidence = confidence_override
                title_similarity = confidence_override
                artist_similarity = confidence_override
            else:
                title_similarity = difflib.SequenceMatcher(None, title.lower(), rec_title.lower()).ratio()
                artist_similarity = difflib.SequenceMatcher(None, artist.lower(), rec_artist.lower()).ratio()
                overall_confidence = title_similarity * 0.7 + artist_similarity * 0.3
            return {
                "mbid": rec_id,
                "title": rec_title,
                "artist": rec_artist,
                "album": best_album,
                "year": best_year,
                "length": rec_length,
                "releases": release_list,
                "writers": writer_names,
                "composer": ", ".join(writer_names) if writer_names else "",
                "confidence": round(overall_confidence, 3),
                "title_similarity": round(title_similarity, 3),
                "artist_similarity": round(artist_similarity, 3),
                "source": "musicbrainz",
            }

        # If the track already has an MBID, resolve it directly first so we
        # always return a result even when the text search finds nothing.
        direct_result = None
        if mbid:
            try:
                direct_resp = requests.get(
                    f"https://musicbrainz.org/ws/2/recording/{mbid}",
                    params={"fmt": "json", "inc": "releases+artist-credits+work-rels+work-level-rels"},
                    headers=headers,
                    timeout=8,
                )
                if direct_resp.ok:
                    direct_result = _format_recording(direct_resp.json(), confidence_override=1.0)
                    logger.debug(f"MusicBrainz direct MBID lookup succeeded for {mbid}")
            except Exception as mbid_err:
                logger.debug(f"MusicBrainz direct MBID lookup failed for {mbid}: {mbid_err}")

        # Search MusicBrainz for recordings with retry
        query = f'recording:"{_escape_mb_phrase(title)}" AND artist:"{_escape_mb_phrase(artist)}"'

        max_retries = 2
        for attempt in range(max_retries):
            try:
                resp = requests.get(
                    "https://musicbrainz.org/ws/2/recording",
                    params={"query": query, "fmt": "json", "limit": 10},
                    headers=headers,
                    timeout=5
                )
                resp.raise_for_status()
                data = resp.json()
                recordings = data.get("recordings", []) or []

                if not recordings:
                    if direct_result:
                        return jsonify({"results": [direct_result]}), 200
                    return jsonify({"results": [], "message": "No MusicBrainz track matches found"}), 200
                
                # Format results using the shared helper
                results = [_format_recording(rec) for rec in recordings]

                # Sort by confidence
                results.sort(key=lambda x: x["confidence"], reverse=True)

                # Merge direct MBID result as the definitive top entry when present,
                # de-duplicating if the same MBID already appears in search results.
                if direct_result:
                    results = [r for r in results if r["mbid"] != direct_result["mbid"]]
                    results.insert(0, direct_result)

                return jsonify({"results": results[:10]}), 200
                
            except requests.exceptions.Timeout:
                logging.debug(f"MusicBrainz timeout (attempt {attempt+1}/{max_retries}) for {title} by {artist}")
                if attempt < max_retries - 1:
                    time.sleep(1 * (2 ** attempt))  # Exponential backoff
            except requests.exceptions.ConnectionError as e:
                logging.debug(f"MusicBrainz connection error (attempt {attempt+1}/{max_retries}): {type(e).__name__}")
                if attempt < max_retries - 1:
                    time.sleep(1 * (2 ** attempt))
            except Exception as e:
                logging.debug(f"MusicBrainz lookup error: {e}")
                if attempt == max_retries - 1:
                    return jsonify({"error": f"MusicBrainz lookup failed: {str(e)}"}), 500
                time.sleep(1)
        
        # Log at warning level for transient network issues (not critical errors)
        logger.warning(f"MusicBrainz track lookup unavailable after retries for '{title}' by '{artist}'")
        # If we at least resolved the track via direct MBID lookup, return that.
        if direct_result:
            return jsonify({"results": [direct_result]}), 200
        return jsonify({"error": "MusicBrainz connection failed. Try again later."}), 503
            
    except Exception as e:
        logger.error(f"MusicBrainz track lookup error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/track/<track_id>/mb-releases", methods=["GET"])
def api_track_mb_releases(track_id):
    """Fetch all MusicBrainz releases that contain this track's recording"""
    logger = logging.getLogger('sptnr')
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        cursor.execute(
            f"SELECT musicbrainz_trackid, beets_mbid FROM tracks WHERE CAST(id AS TEXT) = {placeholder}",
            (str(track_id),)
        )
        row = cursor.fetchone()
        conn.close()

        if not row:
            return jsonify({"error": "Track not found"}), 404

        recording_mbid = (row[0] if row[0] else row[1] or "").strip()
        if not recording_mbid:
            return jsonify({"error": "Track has no MusicBrainz recording ID"}), 400

        headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
        resp = requests.get(
            f"https://musicbrainz.org/ws/2/recording/{recording_mbid}",
            params={"fmt": "json", "inc": "releases+release-groups+media"},
            headers=headers,
            timeout=10,
        )
        if not resp.ok:
            return jsonify({"error": f"MusicBrainz returned {resp.status_code}"}), 502

        data = resp.json()
        releases_raw = data.get("releases") or []

        releases = []
        for rel in releases_raw:
            rg = rel.get("release-group") or {}
            primary_type = rg.get("primary-type") or ""
            secondary_types = rg.get("secondary-types") or []
            all_types = [primary_type] + secondary_types
            type_str = "+".join(t for t in all_types if t)
            date = (rel.get("date") or "").strip()
            year = date[:4] if len(date) >= 4 and date[:4].isdigit() else ""
            # Track position on this release
            track_pos = None
            for medium in (rel.get("media") or []):
                for t in (medium.get("tracks") or []):
                    if (t.get("recording") or {}).get("id") == recording_mbid:
                        track_pos = t.get("number") or t.get("position")
                        break
                if track_pos is not None:
                    break
            releases.append({
                "release_mbid": rel.get("id", ""),
                "release_group_mbid": rg.get("id", ""),
                "title": rel.get("title", ""),
                "year": year,
                "date": date,
                "country": rel.get("country") or rel.get("release-events", [{}])[0].get("area", {}).get("iso-3166-1-codes", [""])[0] if rel.get("release-events") else (rel.get("country") or ""),
                "status": rel.get("status") or "",
                "type": type_str,
                "track_position": track_pos,
            })

        # Sort: official releases first, then by date
        def _sort_key(r):
            status_order = 0 if r["status"].lower() == "official" else 1
            return (status_order, r["date"] or "9999")

        releases.sort(key=_sort_key)

        return jsonify({"recording_mbid": recording_mbid, "releases": releases}), 200

    except requests.exceptions.Timeout:
        return jsonify({"error": "MusicBrainz request timed out"}), 504
    except Exception as e:
        logger.error(f"mb-releases error for track {track_id}: {e}")
        return jsonify({"error": "Failed to fetch releases from MusicBrainz"}), 500


@app.route("/api/track/<track_id>/apply-mb-release", methods=["POST"])
def api_track_apply_mb_release(track_id):
    """Apply a chosen MusicBrainz release MBID to a track (updates album MBID fields)"""
    logger = logging.getLogger('sptnr')
    try:
        data = request.get_json() or {}
        release_mbid = str(data.get("release_mbid") or "").strip()
        release_group_mbid = str(data.get("release_group_mbid") or "").strip()

        if not release_mbid:
            return jsonify({"error": "release_mbid required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # Determine which columns exist
        track_columns = _get_table_columns(cursor, "tracks") or set()
        has_mb_album_mbid = "musicbrainz_album_mbid" in track_columns
        has_musicbrainz_albumid = "musicbrainz_albumid" in track_columns
        has_rg = "musicbrainz_releasegroupid" in track_columns

        update_parts = []
        params = []

        if has_mb_album_mbid:
            update_parts.append(f"musicbrainz_album_mbid = {placeholder}")
            params.append(release_mbid)
        if has_musicbrainz_albumid:
            update_parts.append(f"musicbrainz_albumid = {placeholder}")
            params.append(release_mbid)
        if release_group_mbid and has_rg:
            update_parts.append(f"musicbrainz_releasegroupid = {placeholder}")
            params.append(release_group_mbid)

        if not update_parts:
            conn.close()
            return jsonify({"error": "No compatible columns to update"}), 400

        params.append(str(track_id))
        cursor.execute(
            f"UPDATE tracks SET {', '.join(update_parts)} WHERE CAST(id AS TEXT) = {placeholder}",
            params,
        )
        conn.commit()

        # Fetch file path for tag sync
        cursor.execute(f"SELECT file_path FROM tracks WHERE CAST(id AS TEXT) = {placeholder}", (str(track_id),))
        row = cursor.fetchone()
        conn.close()
        file_path = (row[0] if row else None) or ""

        file_synced = False
        if file_path and os.path.exists(file_path):
            try:
                from helpers.tag_manager import write_tags_to_file
                tag_updates = {"musicbrainz_album_mbid": release_mbid}
                if release_group_mbid:
                    tag_updates["musicbrainz_releasegroupid"] = release_group_mbid
                file_synced = bool(write_tags_to_file(file_path, tag_updates))
            except Exception as tag_err:
                logger.warning(f"[APPLY_MB_RELEASE] Tag write failed for {file_path}: {tag_err}")

        return jsonify({"success": True, "release_mbid": release_mbid, "file_synced": file_synced}), 200

    except Exception as e:
        logger.error(f"apply-mb-release error for track {track_id}: {e}")
        return jsonify({"error": "Failed to apply release"}), 500


