@app.route("/api/genres/remove", methods=["POST"])
def api_remove_genres():
    """
    Remove specific genres from artist or album's tracks
    Updates database only
    """
    conn = None
    try:
        data = request.get_json() or {}
        artist_name = data.get("artist_name", "").strip()
        album_name = data.get("album_name", "").strip()
        genres_to_remove = data.get("genres", [])

        if not artist_name and not album_name:
            return jsonify({"error": "artist_name or album_name required"}), 400

        if not genres_to_remove or not isinstance(genres_to_remove, list):
            return jsonify({"error": "genres must be a non-empty list"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # Build WHERE clause
        if album_name:
            cursor.execute(
                f"SELECT id, title, genres FROM tracks WHERE artist = {placeholder} AND album = {placeholder}",
                (artist_name, album_name)
            )
        else:
            cursor.execute(
                f"SELECT id, title, genres FROM tracks WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}",
                (artist_name,)
            )

        rows = cursor.fetchall()
        affected_count = 0

        # Build list of updates in memory first
        for row in rows:
            if isinstance(row, dict):
                track_id = row.get("id")
                genres_str = row.get("genres")
            elif hasattr(row, "keys"):
                track_id = row["id"]
                genres_str = row["genres"]
            else:
                track_id = row[0]
                genres_str = row[2]

            if not genres_str:
                continue

            # Parse genres
            genre_list = [g.strip() for g in re.split(r'[\\,]+', genres_str)]

            # Remove specified genres (case-insensitive)
            genres_to_remove_lower = [g.lower() for g in genres_to_remove]
            filtered_genres = [
                g for g in genre_list
                if g.lower() not in genres_to_remove_lower
            ]

            # Only update if changes were made
            if len(filtered_genres) != len(genre_list):
                new_genres_str = '\\'.join(filtered_genres) if filtered_genres else ''

                # Update database
                cursor.execute(
                    f"UPDATE tracks SET genres = {placeholder} WHERE id = {placeholder}",
                    (new_genres_str, track_id)
                )

                affected_count += 1

        conn.commit()

        # Log bulk change
        if affected_count > 0:
            log_genre_update(
                artist_name=artist_name,
                album_name=album_name,
                track_id=None,
                genres_before='',
                genres_after='',
                action_type='remove_from_album' if album_name else 'remove_from_artist',
                affected_count=affected_count,
                change_summary=f"Removed genres from {affected_count} tracks: {', '.join(genres_to_remove)}"
            )

        # Trigger Navidrome scan in background
        def trigger_scan():
            try:
                from api_clients.navidrome import NavidromeClient
                cfg = get_config()
                navidrome_config = cfg.get("navidrome", {})

                if navidrome_config.get("base_url"):
                    client = NavidromeClient(
                        navidrome_config.get("base_url"),
                        navidrome_config.get("user"),
                        navidrome_config.get("password")
                    )
                    client.start_scan()
            except Exception as e:
                logging.error(f"Failed to trigger Navidrome scan: {e}")

        # Run scan in background thread
        scan_thread = threading.Thread(target=trigger_scan, daemon=True)
        scan_thread.start()

        return jsonify({
            "success": True,
            "affected_tracks": affected_count,
            "message": f"Removed genres from {affected_count} track(s)",
            "scan_triggered": True
        }), 200

    except Exception as e:
        logging.error(f"Error removing genres: {e}")
        return jsonify({"error": str(e)}), 500
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass

@app.route("/api/track/update-metadata", methods=["POST"])
def api_track_update_metadata():
    """
    Update track metadata (comprehensive - all fields)
    
    Request body:
    {
        "track_id": "track_id_from_db",
        "title": "new title (optional)",
        "artist": "new artist (optional)",
        "album": "new album (optional)",
        "album_artist": "(optional)",
        "composer": "(optional)",
        "writer": "(optional)",
        "arranger": "(optional)",
        "mixer": "(optional)",
        "producer": "(optional)",
        "work": "(optional)",
        "genres": "new genres separated by backslash (optional)",
        "stars": 0-5 (optional),
        "is_single": 0 or 1 (optional),
        "single_confidence": "low|medium|high" (optional)",
        "year": "YYYY (optional)",
        "track_number": "(optional)",
        "disc_number": "(optional)",
        "comment": "(optional)",
        "mbid": "(optional)",
        "isrc": "(optional)",
        "bpm": (optional)",
        "bitrate": (optional)",
        "sample_rate": (optional)",
        "is_cover": 0 or 1 (optional)",
        "alternate_take": 0 or 1 (optional)",
        "is_compilation": 0 or 1 (optional)",
        "is_live": 0 or 1 (optional)",
        "is_acoustic": 0 or 1 (optional)"
    }
    """
    conn = None
    try:
        data = request.get_json() or {}
        track_id = data.get("track_id", "").strip()
        sync_to_file = data.get("sync_to_file", True)
        clear_mb_pending = bool(data.get("clear_mb_pending", False))
        
        if not track_id:
            return jsonify({"error": "track_id required"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Build database update with provided fields
        db_updates = {}
        optional_string_fields = [
            'title', 'artist', 'album', 'album_artist', 'genres', 'year',
            'composer', 'writer', 'arranger', 'mixer', 'producer', 'work',
            'track_number', 'comment', 'mbid', 'isrc', 'single_confidence',
            # Sort keys
            'titlesort', 'albumsort', 'artistsort', 'composersort', 'albumartistsort',
            'lyricistsort', 'artistssort', 'albumartistssort',
            # Multi-value artist fields
            'artists', 'albumartists',
            # Credits
            'conductor', 'performer', 'director', 'djmixer', 'engineer', 'remixer', 'lyricist',
            # Release/content fields
            'albumversion', 'recordlabel', 'copyright', 'releasedate', 'releasetype', 'releasestatus',
            'releasecountry', 'media', 'barcode', 'catalognumber', 'asin', 'originalyear', 'originaldate',
            'tracktotal', 'disctotal', 'script', 'discsubtitle', 'lyrics', 'subtitle', 'grouping',
            'movement', 'movementname', 'movementtotal',
            # Technical/legal
            'key', 'language', 'license', 'website', 'encodedby', 'encodersettings', 'explicitstatus',
            # MusicBrainz release identifiers
            'musicbrainz_albumid', 'musicbrainz_artistid', 'musicbrainz_albumartistid',
            'musicbrainz_releasegroupid', 'musicbrainz_releasetrackid', 'musicbrainz_workid',
            # ReplayGain/R128
            'replaygain_track_gain', 'replaygain_track_peak', 'replaygain_album_gain',
            'replaygain_album_peak', 'r128_track_gain', 'r128_album_gain'
        ]
        optional_int_fields = ['stars', 'disc_number', 'bpm', 'bitrate', 'sample_rate']
        optional_bool_fields = ['is_single', 'is_cover', 'alternate_take', 'is_compilation', 'is_live', 'is_acoustic']
        
        for field in optional_string_fields:
            if field in data and data[field] is not None:
                db_updates[field] = data[field].strip() if isinstance(data[field], str) else data[field]
        
        for field in optional_int_fields:
            if field in data and data[field] is not None:
                try:
                    db_updates[field] = int(data[field]) if data[field] != '' else None
                except (ValueError, TypeError):
                    pass

        for field in optional_bool_fields:
            if field in data and data[field] is not None:
                raw_val = data[field]
                if isinstance(raw_val, str):
                    bool_val = raw_val.strip().lower() in {'1', 'true', 'yes', 'on'}
                else:
                    bool_val = bool(raw_val)
                db_updates[field] = bool_val

        # Merge duplicate writer/lyricist semantics so either field updates both when only one is provided.
        writer_val = db_updates.get('writer')
        lyricist_val = db_updates.get('lyricist')
        if writer_val and not lyricist_val:
            db_updates['lyricist'] = writer_val
        elif lyricist_val and not writer_val:
            db_updates['writer'] = lyricist_val

        # Coerce boolean-like flags according to current DB column types.
        present_bool_fields = {field: db_updates[field] for field in optional_bool_fields if field in db_updates}
        if present_bool_fields:
            db_updates.update(_normalize_track_flag_payload(conn, present_bool_fields))
        
        if not db_updates:
            conn.close()
            return jsonify({"error": "At least one field required"}), 400

        # Clear the stored MusicBrainz comparison pending state when the update
        # has been applied (signalled by the caller setting clear_mb_pending=true).
        if clear_mb_pending:
            db_updates["pending_mb_updates"] = None

        # Update database using the correct placeholder for the DB backend
        set_clause = ", ".join([f"{k} = {placeholder}" for k in db_updates.keys()])
        values = list(db_updates.values()) + [track_id]
        cursor.execute(f"UPDATE tracks SET {set_clause} WHERE id = {placeholder}", values)
        conn.commit()
        
        conn.close()
        conn = None

        # Sync tags back to file by default for album/artist/track editing flows.
        file_synced = False
        if sync_to_file:
            try:
                from helpers.tag_manager import sync_track_tags_to_file
                file_synced = sync_track_tags_to_file(track_id)
            except Exception as sync_error:
                logging.warning(f"Track metadata DB update succeeded but file sync failed for {track_id}: {sync_error}")
        
        return jsonify({
            "success": True,
            "track_id": track_id,
            "file_synced": file_synced,
            "changes": db_updates,
            "message": "Track metadata updated successfully"
        }), 200
            
    except Exception as e:
        logging.error(f"Error updating track metadata: {e}")
        return jsonify({"error": str(e)}), 500
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass

@app.route("/api/track/ignore-mb-field", methods=["POST"])
def api_track_ignore_mb_field():
    """Permanently ignore a specific MusicBrainz diff field for a track.

    Accepts ``{track_id, field}`` in the request body.  The field name is
    appended to the ``mb_ignored_fields`` JSON array stored on the track row so
    that future comparisons skip it automatically.
    """
    import json as _json_ignore
    conn = None
    try:
        data = request.get_json(force=True, silent=True) or {}
        track_id = str(data.get("track_id") or "").strip()
        field = str(data.get("field") or "").strip()
        clear_pending = bool(data.get("clear_mb_pending", False))

        valid_fields = {"title", "track_number", "year", "mbid", "duration", "disc_number"}
        if not track_id or field not in valid_fields:
            return jsonify({"error": "track_id and a valid field are required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(f"SELECT mb_ignored_fields FROM tracks WHERE id = {placeholder}", (track_id,))
        row = cursor.fetchone()
        if not row:
            conn.close()
            return jsonify({"error": "Track not found"}), 404

        raw = (row["mb_ignored_fields"] if isinstance(row, dict) else row[0]) or "[]"
        try:
            ignored = _json_ignore.loads(raw)
            if not isinstance(ignored, list):
                ignored = []
        except Exception:
            ignored = []

        if field not in ignored:
            ignored.append(field)

        updates = {"mb_ignored_fields": _json_ignore.dumps(ignored)}
        if clear_pending:
            updates["pending_mb_updates"] = None

        set_clause = ", ".join([f"{k} = {placeholder}" for k in updates])
        cursor.execute(
            f"UPDATE tracks SET {set_clause} WHERE id = {placeholder}",
            list(updates.values()) + [track_id],
        )
        conn.commit()
        conn.close()
        conn = None
        return jsonify({"success": True, "ignored_fields": ignored}), 200

    except Exception as e:
        logging.error(f"[ignore_mb_field] Error: {e}")
        return jsonify({"error": "Failed to ignore field"}), 500
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


