def _build_artist_credit_string(artist_credit):
    """
    Build a display string from a MusicBrainz artist-credit array.

    Uses the ``joinphrase`` field so that multi-artist credits are formatted
    correctly, e.g. "Simon & Garfunkel" rather than "Simon Garfunkel".

    Args:
        artist_credit: list of dicts (MusicBrainz artist-credit array)

    Returns:
        str: Human-readable artist string
    """
    result = ''
    for credit in artist_credit:
        if isinstance(credit, dict):
            result += credit.get('name', '')
            result += credit.get('joinphrase', '')
        else:
            result += str(credit)
    return result.strip()


@app.route("/api/upcoming-releases/search-musicbrainz", methods=["POST"])
def api_search_musicbrainz_release():
    """Search MusicBrainz for a release and return track listings.

    Accepts any combination of artist, album, and track (song title).
    When `track` is provided the MusicBrainz recordings endpoint is queried
    so the user can find releases by song title, optionally filtered by artist
    and/or album.  The release-group search path is used when no track is given.
    """
    try:
        data = request.get_json() or {}
        artist = (data.get("artist", "") or "").strip()
        album = (data.get("album", "") or "").strip()
        track = (data.get("track", "") or "").strip()

        if not artist and not album and not track:
            return jsonify({"error": "At least one of artist, album, or track is required"}), 400

        headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}

        # ------------------------------------------------------------------
        # Track-based search path: search MusicBrainz recordings endpoint
        # and return the releases that contain matching recordings.
        # This path is taken whenever a track/song name is provided.
        # NOTE: The recordings endpoint uses field names that differ from the
        # release-group endpoint:
        #   recording:"<title>"  – matches recording/track title
        #   artist:"<name>"      – matches artist name (same as release-group path)
        #   release:"<title>"    – matches the release (album) title
        # ------------------------------------------------------------------
        if track:
            # Escape special characters so that titles/artists containing
            # '"', '\', '(', ')', '+', etc. don't produce a malformed Lucene
            # phrase query (which would cause MusicBrainz to return HTTP 400).
            query_parts = [f'recording:"{_escape_mb_phrase(track)}"']
            if artist:
                query_parts.append(f'artist:"{_escape_mb_phrase(artist)}"')
            if album:
                query_parts.append(f'release:"{_escape_mb_phrase(album)}"')
            recording_query = " AND ".join(query_parts)

            logging.info(
                f"[MB_SEARCH] Track search: {recording_query}"
            )
            time.sleep(1)
            # NOTE: The MusicBrainz search endpoint does not support the
            # inc= parameter (only lookup/browse requests do).  Omitting it
            # avoids a 400 Bad Request; artist-credit and release data are
            # included in recording search results by default.
            rec_response = requests.get(
                "https://musicbrainz.org/ws/2/recording",
                params={
                    "query": recording_query,
                    "fmt": "json",
                    "limit": 10,
                },
                headers=headers,
                timeout=15,
            )
            rec_response.raise_for_status()
            recordings = rec_response.json().get("recordings", []) or []

            if not recordings:
                return jsonify({
                    "success": True,
                    "results": [],
                    "message": f"No recordings found for '{track}'"
                            + (f" by '{artist}'" if artist else "")
                })

            # Collect unique release IDs preserving order of relevance
            seen_release_ids = {}  # release_id → recording info
            for rec in recordings:
                rec_artist_credits = rec.get("artist-credit", []) or []
                rec_artist_name = (
                    rec_artist_credits[0].get("name", "") if rec_artist_credits else artist
                )
                for rel in rec.get("releases", []) or []:
                    rel_id = rel.get("id")
                    if rel_id and rel_id not in seen_release_ids:
                        seen_release_ids[rel_id] = {
                            "artist": rec_artist_name or artist,
                        }

            results = []
            for release_id, release_meta in list(seen_release_ids.items())[:_MB_SEARCH_MAX_RELEASE_GROUPS]:
                time.sleep(1)
                try:
                    rel_response = requests.get(
                        f"https://musicbrainz.org/ws/2/release/{release_id}",
                        params={"fmt": "json", "inc": "recordings+artist-credits"},
                        headers=headers,
                        timeout=15,
                    )
                    rel_response.raise_for_status()
                    release = rel_response.json()

                    # Artist from release artist-credit (use joinphrase for correct formatting)
                    rel_artist = release_meta["artist"]
                    ac = release.get("artist-credit", []) or []
                    if ac:
                        rel_artist = _build_artist_credit_string(ac) or rel_artist

                    media = release.get("media", [])
                    tracks_list = []
                    for disc_idx, disc in enumerate(media, 1):
                        disc_number = disc.get("position", disc_idx)
                        for t in disc.get("tracks", []):
                            recording = t.get("recording", {})
                            track_entry = {
                                "title": recording.get("title", "Unknown"),
                                "position": t.get("position", ""),
                                "length": t.get("length") or recording.get("length", 0),
                                "disc_number": disc_number,
                                "recording_mbid": recording.get("id", ""),
                            }
                            # Include per-track artist for compilation support
                            rec_credits = recording.get("artist-credit") or []
                            if rec_credits:
                                track_entry["artist"] = _build_artist_credit_string(rec_credits)
                            tracks_list.append(track_entry)

                    rg = release.get("release-group") or {}
                    results.append({
                        "release_group_id": rg.get("id", ""),
                        "release_id": release_id,
                        "title": release.get("title", ""),
                        "artist": rel_artist,
                        "type": rg.get("primary-type", ""),
                        "date": release.get("date", ""),
                        "year": (release.get("date", "") or "")[:4],
                        "track_count": len(tracks_list),
                        "tracks": tracks_list,
                    })
                except Exception as rel_err:
                    logging.warning(f"[MB_SEARCH] Error fetching release {release_id}: {rel_err}")
                    continue

            return jsonify({
                "success": True,
                "results": results,
                "total": len(results),
            })

        # ------------------------------------------------------------------
        # Release-level search path for album lookups.
        # This preserves multiple versions of the same release title (e.g.
        # deluxe/region variants) and improves Various Artists matching.
        # ------------------------------------------------------------------
        if album:
            from difflib import SequenceMatcher

            artist_key = ' '.join((artist or '').lower().replace('-', ' ').replace('_', ' ').split())
            is_various_artist = artist_key in {'various', 'various artist', 'various artists', 'va', 'v/a'}

            escaped_album = _escape_mb_phrase(album)
            search_queries = []
            if artist and not is_various_artist:
                search_queries.append(
                    f'artist:"{_escape_mb_phrase(artist)}" AND release:"{escaped_album}"'
                )
            else:
                search_queries.append(f'release:"{escaped_album}"')
                if artist:
                    search_queries.append(
                        f'artist:"{_escape_mb_phrase(artist)}" AND release:"{escaped_album}"'
                    )

            release_candidates = []
            seen_release_ids = set()
            for query in search_queries:
                time.sleep(1)
                response = requests.get(
                    "https://musicbrainz.org/ws/2/release",
                    headers=headers,
                    params={
                        "fmt": "json",
                        "query": query,
                        "limit": 50,
                    },
                    timeout=15,
                )
                response.raise_for_status()
                data = response.json() or {}
                for rel in data.get("releases", []) or []:
                    rel_id = rel.get("id")
                    if not rel_id or rel_id in seen_release_ids:
                        continue
                    seen_release_ids.add(rel_id)
                    release_candidates.append(rel)

            if not release_candidates:
                return jsonify({
                    "success": True,
                    "results": [],
                    "message": "No releases found"
                            + (f" for '{artist}'" if artist else "")
                            + (f" - '{album}'" if album else "")
                })

            album_norm = album.lower()
            artist_norm = artist.lower()

            def _artist_from_credit(rel):
                credits = rel.get("artist-credit") or []
                return _build_artist_credit_string(credits) if credits else ""

            release_candidates.sort(
                key=lambda rel: (
                    SequenceMatcher(None, album_norm, (rel.get("title") or "").lower()).ratio(),
                    SequenceMatcher(None, artist_norm, _artist_from_credit(rel).lower()).ratio() if artist_norm else 0.0,
                    str(rel.get("date") or ""),
                ),
                reverse=True,
            )

            max_results = max(_MB_SEARCH_MAX_RELEASE_GROUPS * 2, 8)
            selected_candidates = release_candidates[:max_results]

            results = []
            for rel in selected_candidates:
                release_id = rel.get("id", "")
                time.sleep(1)
                try:
                    rel_response = requests.get(
                        f"https://musicbrainz.org/ws/2/release/{release_id}",
                        params={"fmt": "json", "inc": "recordings+artist-credits"},
                        headers=headers,
                        timeout=15,
                    )
                    rel_response.raise_for_status()
                    release = rel_response.json() or {}

                    media = release.get("media", [])
                    tracks = []
                    for disc_idx, disc in enumerate(media, 1):
                        disc_number = disc.get("position", disc_idx)
                        for track_row in disc.get("tracks", []):
                            recording = track_row.get("recording", {})
                            track_entry = {
                                "title": recording.get("title", "Unknown"),
                                "position": track_row.get("position", ""),
                                "length": track_row.get("length") or recording.get("length", 0),
                                "disc_number": disc_number,
                                "recording_mbid": recording.get("id", ""),
                            }
                            rec_credits = recording.get("artist-credit") or []
                            if rec_credits:
                                track_entry["artist"] = _build_artist_credit_string(rec_credits)
                            tracks.append(track_entry)

                    rg = release.get("release-group") or {}
                    release_artist = _artist_from_credit(release) or artist

                    results.append({
                        "release_group_id": rg.get("id", ""),
                        "release_id": release_id,
                        "title": release.get("title", ""),
                        "artist": release_artist,
                        "type": rg.get("primary-type") or rel.get("status") or "",
                        "date": release.get("date", "") or rel.get("date", ""),
                        "year": (release.get("date", "") or rel.get("date", ""))[:4],
                        "track_count": len(tracks),
                        "tracks": tracks,
                    })
                except Exception as e:
                    logging.warning(f"Error fetching tracks for release {release_id}: {e}")
                    continue
        else:
            # ------------------------------------------------------------------
            # Artist-only fallback: keep release-group search behavior.
            # ------------------------------------------------------------------
            search_url = "https://musicbrainz.org/ws/2/release-group"

            requested_artist_norm = _normalize_artist_name(artist) if artist else ""
            artist_mbid = None

            if artist:
                try:
                    conn = get_db()
                    cursor = conn.cursor()
                    placeholder = "%s"
                    cursor.execute(
                        f"""
                        SELECT MAX(musicbrainz_artist_id) AS mbid
                        FROM tracks
                        WHERE LOWER(COALESCE(NULLIF(album_artist, ''), artist)) = LOWER({placeholder})
                          AND musicbrainz_artist_id IS NOT NULL
                        """,
                        (artist,),
                    )
                    row = cursor.fetchone()
                    conn.close()
                    if row and row.get('mbid'):
                        artist_mbid = row.get('mbid')
                except Exception as db_err:
                    logging.debug(f"[MB_SEARCH] Could not load artist MBID from DB for '{artist}': {db_err}")

                if not artist_mbid:
                    try:
                        artist_search_params = {
                            "fmt": "json",
                            "query": f'artist:"{artist}"',
                            "limit": 5,
                        }
                        artist_response = requests.get(
                            "https://musicbrainz.org/ws/2/artist",
                            headers=headers,
                            params=artist_search_params,
                            timeout=15,
                        )
                        artist_response.raise_for_status()
                        artist_data = artist_response.json() or {}
                        for candidate in artist_data.get("artists", []) or []:
                            candidate_name = candidate.get("name", "")
                            candidate_norm = _normalize_artist_name(candidate_name)
                            if candidate_norm == requested_artist_norm:
                                artist_mbid = candidate.get("id")
                                break
                    except Exception as artist_lookup_err:
                        logging.debug(f"[MB_SEARCH] Artist MBID lookup failed for '{artist}': {artist_lookup_err}")

            if artist_mbid:
                query = f'arid:"{artist_mbid}" AND (primarytype:album OR primarytype:ep OR primarytype:single)'
            else:
                query = f'artist:"{artist}" AND (primarytype:album OR primarytype:ep OR primarytype:single)'

            params = {
                "fmt": "json",
                "query": query,
                "limit": 100,
            }

            logging.info(
                f"[MB_SEARCH] Release-group search: artist='{artist}'"
                + (f" [arid={artist_mbid}]" if artist_mbid else "")
            )

            response = requests.get(search_url, headers=headers, params=params, timeout=15)
            response.raise_for_status()
            data = response.json()

            release_groups = data.get("release-groups", [])

            if not release_groups:
                return jsonify({
                    "success": True,
                    "results": [],
                    "message": "No releases found" + (f" for '{artist}'" if artist else "")
                })

            results = []
            for rg in release_groups[:_MB_SEARCH_MAX_RELEASE_GROUPS]:
                rg_id = rg.get("id", "")
                rg_title = rg.get("title", "")
                rg_type = rg.get("primary-type", "")
                first_release_date = rg.get("first-release-date", "")

                if artist and not artist_mbid:
                    credits = rg.get("artist-credit", []) or []
                    credit_name = " ".join(c.get("name", "") for c in credits if isinstance(c, dict)).strip()
                    if credit_name:
                        credit_norm = _normalize_artist_name(credit_name)
                        if (
                            credit_norm != requested_artist_norm
                            and requested_artist_norm not in credit_norm
                            and credit_norm not in requested_artist_norm
                        ):
                            continue

                rg_credits = rg.get("artist-credit", []) or []
                result_artist = _build_artist_credit_string(rg_credits) or artist

                # Return release-group metadata without fetching tracks upfront.
                # The frontend will lazy-load tracks via /api/upcoming-releases/release-group-tracks
                # when the user expands the accordion item, avoiding N×1-sec serial HTTP requests
                # that previously caused gunicorn worker timeouts for prolific artists.
                results.append({
                    "release_group_id": rg_id,
                    "release_id": None,
                    "title": rg_title,
                    "artist": result_artist,
                    "type": rg_type,
                    "date": first_release_date,
                    "year": first_release_date[:4] if first_release_date else "",
                    "track_count": 0,
                    "tracks": [],
                    "tracks_deferred": True,
                })
        
        return jsonify({
            "success": True,
            "results": results,
            "total": len(results)
        })
        
    except requests.exceptions.HTTPError as e:
        logging.error(f"MusicBrainz API error: {e}")
        return jsonify({"error": f"MusicBrainz API error: {e.response.status_code if hasattr(e, 'response') else str(e)}"}), 500
    except Exception as e:
        logging.error(f"Error searching MusicBrainz: {str(e)}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/upcoming-releases/release-group-tracks", methods=["GET"])
def api_get_release_group_tracks():
    """Fetch the track listing for the first release in a MusicBrainz release group.

    Used by the frontend to lazy-load tracks when a user expands an accordion
    item returned by the artist-only search path (which returns release-group
    metadata without tracks to avoid N×1-sec serial HTTP requests that would
    cause gunicorn worker timeouts for prolific artists).
    """
    try:
        rg_id = request.args.get("rg_id", "").strip()
        if not rg_id:
            return jsonify({"error": "rg_id is required"}), 400

        headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
        response = requests.get(
            "https://musicbrainz.org/ws/2/release",
            params={
                "fmt": "json",
                "release-group": rg_id,
                "inc": "recordings+artist-credits",
                "limit": 1,
            },
            headers=headers,
            timeout=15,
        )
        response.raise_for_status()
        browse_data = response.json() or {}

        releases = browse_data.get("releases", [])
        if not releases:
            return jsonify({"success": True, "tracks": [], "track_count": 0, "release_id": None})

        release = releases[0]
        release_id = release.get("id", "")

        media = release.get("media", [])
        tracks = []
        for disc_idx, disc in enumerate(media, 1):
            disc_number = disc.get("position", disc_idx)
            for track_row in disc.get("tracks", []):
                recording = track_row.get("recording", {})
                track_entry = {
                    "title": recording.get("title", "Unknown"),
                    "position": track_row.get("position", ""),
                    "length": track_row.get("length") or recording.get("length", 0),
                    "disc_number": disc_number,
                    "recording_mbid": recording.get("id", ""),
                }
                rec_credits = recording.get("artist-credit") or []
                if rec_credits:
                    track_entry["artist"] = _build_artist_credit_string(rec_credits)
                tracks.append(track_entry)

        return jsonify({
            "success": True,
            "tracks": tracks,
            "track_count": len(tracks),
            "release_id": release_id,
        })

    except requests.exceptions.HTTPError as e:
        logging.error(f"[MB_TRACKS] HTTP error fetching release group {request.args.get('rg_id')}: {e}")
        status = e.response.status_code if hasattr(e, 'response') and e.response is not None else 0
        return jsonify({"error": f"MusicBrainz API error: {status or 'unknown'}"}), 500
    except Exception as e:
        logging.error(f"[MB_TRACKS] Error fetching release group tracks: {e}")
        return jsonify({"error": "Failed to fetch tracks"}), 500


@app.route("/api/upcoming-releases/search-discogs", methods=["POST"])
def api_search_discogs_release():
    """Search Discogs for a release and return track listings as fallback"""
    try:
        data = request.get_json() or {}
        artist = (data.get("artist", "") or "").strip()
        album = (data.get("album", "") or "").strip()
        
        if not artist:
            return jsonify({"error": "Artist name required"}), 400
        
        # Get Discogs configuration
        cfg = get_config()
        discogs_config = cfg.get("discogs", {})
        discogs_token = discogs_config.get("token", "")
        discogs_enabled = discogs_config.get("enabled", False)
        
        if not discogs_enabled or not discogs_token:
            return jsonify({
                "success": False,
                "error": "Discogs is not configured. Please add your Discogs token in config."
            }), 400
        
        from api_clients.discogs import DiscogsClient
        
        discogs_client = DiscogsClient(token=discogs_token, enabled=discogs_enabled)
        
        # Search Discogs for releases
        search_url = f"{discogs_client.base_url}/database/search"
        search_query = f"{artist} {album}".strip()
        search_params = {
            "q": search_query,
            "type": "release",
            "per_page": 20
        }
        
        logging.info(f"Searching Discogs for: {artist}" + (f" - {album}" if album else ""))
        
        time.sleep(DISCOGS_RATE_LIMIT_DELAY)  # Discogs rate limiting
        
        response = requests.get(search_url, headers=discogs_client.headers, params=search_params, timeout=15)
        response.raise_for_status()
        search_data = response.json()
        
        search_results = search_data.get("results", [])
        
        if not search_results:
            return jsonify({
                "success": True,
                "results": [],
                "message": f"No releases found on Discogs for {artist}" + (f" - {album}" if album else "")
            })
        
        # Fetch details for top matches
        results = []
        for result in search_results[:10]:  # Limit to 10 results
            release_id = result.get('id')
            if not release_id:
                continue
            
            try:
                time.sleep(DISCOGS_RATE_LIMIT_DELAY)  # Rate limiting
                
                # Fetch full release data
                release_url = f"{discogs_client.base_url}/releases/{release_id}"
                release_response = requests.get(release_url, headers=discogs_client.headers, timeout=15)
                release_response.raise_for_status()
                release_data = release_response.json()
                
                # Extract track listing
                tracklist = release_data.get("tracklist", [])
                tracks = []
                for track in tracklist:
                    if track.get("type_") == "track":
                        tracks.append({
                            "title": track.get("title", "Unknown"),
                            "position": track.get("position", ""),
                            "duration": track.get("duration", "")
                        })
                
                # Get release info
                release_title = release_data.get("title", "")
                release_year = release_data.get("year")
                release_formats = release_data.get("formats", [])
                format_names = [fmt.get("name", "") for fmt in release_formats]
                
                results.append({
                    "release_id": release_id,
                    "title": release_title,
                    "artist": artist,
                    "year": release_year,
                    "formats": format_names,
                    "track_count": len(tracks),
                    "tracks": tracks,
                    "source": "discogs"
                })
                
            except Exception as e:
                logging.warning(f"Error fetching Discogs release {release_id}: {e}")
                continue
        
        return jsonify({
            "success": True,
            "results": results,
            "total": len(results),
            "source": "discogs"
        })
        
    except requests.exceptions.HTTPError as e:
        logging.error(f"Discogs API error: {e}")
        return jsonify({"error": f"Discogs API error: {e.response.status_code if hasattr(e, 'response') else str(e)}"}), 500
    except Exception as e:
        logging.error(f"Error searching Discogs: {str(e)}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/upcoming-releases/search", methods=["POST"])
def api_search_upcoming_release():
    """Search for downloads of an upcoming release"""
    try:
        data = request.get_json() or {}
        artist = data.get("artist", "")
        album = data.get("album", "")
        
        if not artist or not album:
            return jsonify({"error": "Artist and album name required"}), 400
        
        # Redirect to downloads with search query
        search_query = f"{artist} {album}"
        
        return jsonify({
            "success": True,
            "search_query": search_query,
            "message": f"Ready to search for: {search_query}"
        })
    except Exception as e:
        logging.error(f"Error processing release search: {str(e)}")
        return jsonify({"error": str(e)}), 500


if __name__ == "__main__":
    # Check if background scanner should auto-start on app launch
    try:
        cfg = get_config()
        features = cfg.get('features', {})
        
        # Only show auto-start status if perpetual mode is enabled
        if features.get('perpetual'):
            logging.info("Background scanner auto-start: ENABLED")
            logging.info("Starting Navidrome sync and popularity scan in background...")
            
            # Start the beets auto-import and scanner in background thread
            def start_scanner():
                import time as time_module
                time_module.sleep(2)  # Give Flask time to start
                try:
                    _log = logging.getLogger('sptnr')
                    _log.info("Auto-starting scanner with perpetual mode...")
                    
                    # Run the standard scanner
                    _log.info("Step 1: Running Navidrome sync and popularity scan...")
                    from start import run_scan
                    run_scan(scan_type='full')
                except Exception as e:
                    import traceback
                    _log = logging.getLogger('sptnr')
                    _log.error(f"Error in background scanner: {e}")
                    _log.error(traceback.format_exc())
            
            scanner_thread = threading.Thread(target=start_scanner, daemon=True)
            scanner_thread.start()
        else:
            # Perpetual mode disabled - scans will be triggered manually
            logging.info("Background scanner auto-start: DISABLED (trigger scans manually via web UI)")
    except Exception as e:
        import traceback
        logging.error(f"Error checking auto-start configuration: {e}")
        logging.error(traceback.format_exc())
    
    # Start Download Retry Manager (for persistent downloads)
    try:
        def start_retry_manager():
            """Background thread to manage download retries"""
            import time as time_module
            from download_retry_manager import run_retry_manager
            
            # Wait for Flask to start
            time_module.sleep(5)
            
            try:
                cfg = get_config()
                # Get scheduler config
                scheduler_config = cfg.get("features", {}).get("retry_scheduler", {})
                interval = scheduler_config.get("interval_seconds", 60)
                
                navidrome_config = cfg.get("navidrome", {})
                navidrome_url = navidrome_config.get("url", "http://localhost:4533")
                navidrome_token = navidrome_config.get("token", "")
                
                logging.info(f"[RETRY_SCHEDULER] Started with interval: {interval}s")
                
                while not retry_scheduler.get("stop_event", threading.Event()).is_set():
                    try:
                        stats = run_retry_manager(DB_PATH, navidrome_url, navidrome_token)
                        if stats["retried"] > 0 or stats["completed"] > 0:
                            logging.info(f"[RETRY_SCHEDULER] Retried: {stats['retried']}, Completed: {stats['completed']}, Failed: {stats['failed']}")
                    except Exception as e:
                        logging.error(f"[RETRY_SCHEDULER] Error: {e}")
                    
                    # Wait with stop event check
                    if retry_scheduler.get("stop_event", threading.Event()).wait(timeout=interval):
                        # Stop event was set
                        break
                
                logging.info("[RETRY_SCHEDULER] Stopped")
            except Exception as e:
                logging.error(f"[RETRY_SCHEDULER] Worker error: {e}")
            finally:
                with retry_scheduler_lock:
                    retry_scheduler["running"] = False
        
        logging.info("Starting Download Retry Manager...")
        retry_scheduler["stop_event"] = threading.Event()
        retry_thread = threading.Thread(target=start_retry_manager, daemon=True)
        retry_thread.start()
        
        with retry_scheduler_lock:
            retry_scheduler["thread"] = retry_thread
            retry_scheduler["running"] = True
    except Exception as e:
        logging.warning(f"Could not start Download Retry Manager: {e}")

    # Start automatic queue cleanup scheduler (duplicates + fully completed album groups)
    try:
        _start_download_queue_cleanup_scheduler()
    except Exception as e:
        logging.warning(f"Could not start Download Queue Cleanup Scheduler: {e}")

    # Start persistent auto-discovery watcher so queue updates even when UI is closed.
    try:
        def start_downloads_auto_discovery():
            """Background thread that periodically scans downloads folder into queue."""
            import time as time_module
            from download_queue_manager import auto_discover_and_queue_files

            # Wait for app bootstrap to settle before first scan.
            time_module.sleep(8)

            while True:
                try:
                    cfg = get_config() or {}
                    feature_cfg = cfg.get("features", {}) if isinstance(cfg, dict) else {}
                    discover_cfg = feature_cfg.get("downloads_auto_discover", {}) if isinstance(feature_cfg, dict) else {}

                    enabled = discover_cfg.get("enabled", True)
                    interval = int(discover_cfg.get("interval_seconds", 60))
                    if interval < 15:
                        interval = 15

                    if enabled:
                        stats = auto_discover_and_queue_files()
                        if stats.get("queued", 0) > 0:
                            logging.info(
                                "[AUTO_DISCOVERY] Added %s new file(s) to queue (scanned=%s)",
                                stats.get("queued", 0),
                                stats.get("scanned", 0),
                            )

                    time_module.sleep(interval)
                except Exception as watcher_error:
                    logging.error(f"[AUTO_DISCOVERY] Background watcher error: {watcher_error}")
                    time_module.sleep(30)

        logging.info("Starting persistent Downloads auto-discovery watcher...")
        auto_discovery_thread = threading.Thread(target=start_downloads_auto_discovery, daemon=True)
        auto_discovery_thread.start()
    except Exception as e:
        logging.warning(f"Could not start Downloads auto-discovery watcher: {e}")
    
    # Start Flask application
    app.run(debug=False, host="0.0.0.0", port=5000)


